--
-- Name: p2_package_current_conditions(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p2_package_current_conditions(p_tenant uuid, p_site uuid, p_package uuid) RETURNS TABLE(kind text, rule_type text, tier_order integer, value jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  WITH cur AS (
    -- THE WHOLE AUTHORISATION DECISION, and it is not the caller's to make. The revision is resolved from the
    -- package's own current pointer, and only for a package that is in this tenant and site and is not a
    -- system package. A caller naming another site's package, a system package, or a package with nothing
    -- published gets no rows — the same answer as a package that genuinely has no conditions, which is the
    -- correct amount of information to give something that asked out of scope.
    SELECT p.current_revision_id AS rev
      FROM iam_v2.internet_packages p
     WHERE p.id = p_package
       AND p.tenant_id = p_tenant
       AND p.site_id = p_site
       AND p.is_system = false
       AND p.current_revision_id IS NOT NULL
  )
  SELECT 'RULE'::text, r.rule_type, NULL::int, COALESCE(r.rule_value, '{}'::jsonb)
    FROM iam_v2.package_eligibility_rules r
    JOIN cur ON r.package_revision_id = cur.rev
   WHERE r.tenant_id = p_tenant AND r.site_id = p_site
  UNION ALL
  SELECT 'TIER'::text, NULL::text, t.tier_order, COALESCE(t.grant_value, '{}'::jsonb)
    FROM iam_v2.package_grant_tiers t
    JOIN cur ON t.package_revision_id = cur.rev
   WHERE t.tenant_id = p_tenant AND t.site_id = p_site
   ORDER BY 1, 3, 2
$$;


--
-- Name: FUNCTION p2_package_current_conditions(p_tenant uuid, p_site uuid, p_package uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p2_package_current_conditions(p_tenant uuid, p_site uuid, p_package uuid) IS 'The eligibility rules and grant tiers of the CURRENT revision of one non-system Internet package, scoped to the caller-supplied tenant and site and resolved from the package''s own current-revision pointer. Exists so the Hotel-Admin service can load a package''s specification before republishing it without holding SELECT on iam_v2.package_eligibility_rules or iam_v2.package_grant_tiers. Returns package policy only: no row ids, no tenant/site, and no guest, Stay, reservation, folio, payment or PMS data.';


--
-- Name: p3_accounting_needs_binding(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_accounting_needs_binding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF iam_v2.p3_entitlement_at(NEW.session_id, NEW.sampled_at) IS NULL THEN
    RAISE EXCEPTION 'ACCT_NO_BINDING: no entitlement was bound to session % at %', NEW.session_id, NEW.sampled_at;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p3_alert_action_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_alert_action_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE prev_seq bigint; prev_action text;
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'checkout_grace_alert_actions is append-only (% rejected)', TG_OP; END IF;
  SELECT seq, action INTO prev_seq, prev_action FROM iam_v2.checkout_grace_alert_actions
    WHERE audit_id=NEW.audit_id ORDER BY seq DESC LIMIT 1;
  IF prev_seq IS NULL THEN
    IF NEW.seq <> 1 OR NEW.action <> 'OPEN' THEN RAISE EXCEPTION 'first alert action must be seq=1 OPEN'; END IF;
  ELSE
    IF NEW.seq <> prev_seq + 1 THEN RAISE EXCEPTION 'alert action seq must be contiguous'; END IF;
    -- (item 10) legal edges only: OPEN->ACKNOWLEDGED|RESOLVED, ACKNOWLEDGED->RESOLVED, RESOLVED terminal.
    -- Rejects OPEN->OPEN, ACKNOWLEDGED->OPEN, repeated ACKNOWLEDGED, and any action after RESOLVED.
    IF NOT ( (prev_action='OPEN'         AND NEW.action IN ('ACKNOWLEDGED','RESOLVED'))
          OR (prev_action='ACKNOWLEDGED' AND NEW.action='RESOLVED') ) THEN
      RAISE EXCEPTION 'illegal alert action edge % -> %', prev_action, NEW.action;
    END IF;
  END IF;
  IF NEW.action IN ('ACKNOWLEDGED','RESOLVED') AND NEW.actor IS NULL THEN
    RAISE EXCEPTION 'ACKNOWLEDGED/RESOLVED alert action requires an actor';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p3_alert_open_on_audit(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_alert_open_on_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  -- This operation writes a capability-scoped family, so it declares its own scope. Doing it here
  -- rather than relying on ownership is what lets Gate-P give every function its own owner without
  -- any of them losing the right to perform its own writes.
  PERFORM iam_v2.begin_controlled_operation('alert');
  IF NEW.alert_code IS NOT NULL THEN
    INSERT INTO iam_v2.checkout_grace_alert_actions(tenant_id, site_id, audit_id, seq, action, reason_code)
      VALUES (NEW.tenant_id, NEW.site_id, NEW.id, 1, 'OPEN', NEW.reason_code);
  END IF;
  RETURN NULL;
END $$;


--
-- Name: p3_cfg_secs(jsonb, text, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_cfg_secs(p_config jsonb, p_key text, p_default integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT CASE
           WHEN (p_config->>p_key) ~ '^[1-9][0-9]{0,10}$'
            AND (p_config->>p_key)::bigint BETWEEN 1000 AND 604800000
             THEN ((p_config->>p_key)::bigint / 1000)::int
           ELSE p_default
         END;
$_$;


--
-- Name: FUNCTION p3_cfg_secs(p_config jsonb, p_key text, p_default integer); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p3_cfg_secs(p_config jsonb, p_key text, p_default integer) IS 'Fail-closed millisecond-to-seconds reader for operator-authored Revision config. Any missing, malformed, out-of-range or non-integer value yields the supplied default. Cannot raise: callers are on the authentication path, where an exception would be an outage.';


--
-- Name: p3_checkout_audit_provenance(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_checkout_audit_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE ev RECORD; ent RECORD; pur_episode int;
BEGIN
  IF NEW.boundary_event_id IS NOT NULL THEN
    SELECT tenant_id, site_id, pms_interface_id, stay_id, event_type, processing_status, sequence_version, normalization_version
      INTO ev FROM iam_v2.stay_events WHERE id = NEW.boundary_event_id;
    IF ev.tenant_id IS NULL THEN RAISE EXCEPTION 'boundary_event_id does not reference a stay_event'; END IF;
    IF ev.tenant_id <> NEW.tenant_id OR ev.site_id <> NEW.site_id OR ev.pms_interface_id <> NEW.pms_interface_id
       OR ev.stay_id IS DISTINCT FROM NEW.stay_id THEN
      RAISE EXCEPTION 'boundary event scope must match the audit (tenant/site/interface/stay)';
    END IF;
    IF ev.event_type <> 'GO' THEN RAISE EXCEPTION 'boundary event must be the typed checkout (GO) event'; END IF;
    IF ev.processing_status <> 'APPLIED' THEN RAISE EXCEPTION 'boundary event must be APPLIED'; END IF;
    IF NEW.boundary_event_seq IS DISTINCT FROM ev.sequence_version
       OR NEW.boundary_normalization_version IS DISTINCT FROM ev.normalization_version THEN
      RAISE EXCEPTION 'audit boundary seq/normalization must match the source event';
    END IF;
  END IF;
  IF NEW.grace_entitlement_id IS NOT NULL THEN
    SELECT e.tenant_id, e.site_id, e.pms_interface_id, e.stay_id, e.purchase_id
      INTO ent FROM iam_v2.entitlements e WHERE e.id = NEW.grace_entitlement_id;
    IF ent.tenant_id IS NULL THEN RAISE EXCEPTION 'grace_entitlement_id does not reference an entitlement'; END IF;
    IF ent.tenant_id <> NEW.tenant_id OR ent.site_id <> NEW.site_id OR ent.pms_interface_id IS DISTINCT FROM NEW.pms_interface_id
       OR ent.stay_id IS DISTINCT FROM NEW.stay_id THEN
      RAISE EXCEPTION 'grace entitlement scope must match the audit (tenant/site/interface/stay)';
    END IF;
    SELECT checkout_episode INTO pur_episode FROM iam_v2.purchases WHERE id = ent.purchase_id;
    IF pur_episode IS DISTINCT FROM NEW.lifecycle_version THEN
      RAISE EXCEPTION 'grace purchase checkout_episode % must equal audit lifecycle_version %', pur_episode, NEW.lifecycle_version;
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p3_checkout_grace_audit_appendonly(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_checkout_grace_audit_appendonly() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION 'iam_v2.checkout_grace_audit is append-only (% rejected)', TG_OP;
END $$;


--
-- Name: p3_controlled_operation_open(text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_controlled_operation_open(p_family text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_tok text;
BEGIN
  v_tok := current_setting('iam_v2.op_' || p_family, true);   -- missing_ok: NULL when never set
  IF v_tok IS NULL OR v_tok = '' THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM iam_v2.controlled_operation_scope s
     WHERE s.txid = txid_current() AND s.family = p_family AND s.token::text = v_tok);
END $$;


--
-- Name: p3_controlled_writer_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_controlled_writer_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE owner_role text; changed boolean := true; v_sig text; v_oid oid; v_cap text;
BEGIN
  -- CAPABILITY-SCOPED FAMILIES (see 4t). The write is allowed when a scope for the family is open in this
  -- transaction, or when the caller is already the opener's owner — the latter so that the operations
  -- themselves, and a database whose roles have not yet been separated, behave identically.
  v_cap := CASE
    WHEN TG_TABLE_NAME IN ('stays','stay_events')                                   THEN 'stay'
    WHEN TG_TABLE_NAME = 'auth_resolutions'                                          THEN 'auth_resolution'
    WHEN TG_TABLE_NAME IN ('offer_quotes','purchases')                               THEN 'commerce_intent'
    WHEN TG_TABLE_NAME IN ('checkout_grace_audit','entitlement_boundary_watermarks') THEN 'checkout_conversion'
    WHEN TG_TABLE_NAME = 'pms_source_conflicts'                                      THEN 'source_conflict'
    WHEN TG_TABLE_NAME = 'auth_contexts'                                             THEN 'auth_context'
    WHEN TG_TABLE_NAME = 'entitlement_device_authorizations'                          THEN 'device_auth'
    WHEN TG_TABLE_NAME = 'session_entitlement_bindings'                               THEN 'session_binding'
    WHEN TG_TABLE_NAME = 'checkout_grace_policy_publications'                         THEN 'grace_publication'
    WHEN TG_TABLE_NAME = 'checkout_grace_alert_actions'                               THEN 'alert'
    ELSE NULL END;
  -- resolve the family's approved function owner INLINE (catalog-only). Deliberately NOT a call to the
  -- introspection helper: this trigger fires as whichever role is writing, and a cross-function EXECUTE
  -- dependency would break exactly the dedicated-owner separation Gate-P needs.
  v_sig := CASE
    WHEN TG_TABLE_NAME = 'site_checkout_grace_config'
      THEN 'iam_v2.publish_checkout_grace_config(uuid,uuid,uuid,int,int,int,bigint,int,text,int)'
    WHEN TG_TABLE_NAME = 'appliance_class_generation'
      THEN 'iam_v2.allocate_class_generation(uuid,uuid,uuid)'
    WHEN TG_TABLE_NAME = 'auth_context_offers'
      THEN 'iam_v2.record_auth_context_offer(uuid,uuid,uuid,uuid,int,bigint,timestamptz)'
    WHEN TG_TABLE_NAME IN ('accounting_records','accounting_checkpoints','delayed_accounting_records','sessions')
      THEN 'iam_v2.ingest_absolute_counters(uuid,uuid,uuid,uuid,text,int,bigint,bigint,bigint,timestamptz)'
    -- Capability-scoped families resolve their owner through the operation-scope opener (see 4t), as does the
    -- scope table itself: a token nobody but the opener can write is what makes the scope unforgeable.
    WHEN TG_TABLE_NAME IN ('stays','stay_events','auth_resolutions','offer_quotes','purchases',
                           'checkout_grace_audit','entitlement_boundary_watermarks','pms_source_conflicts',
                           'auth_contexts','entitlement_device_authorizations','session_entitlement_bindings',
                           'checkout_grace_policy_publications','checkout_grace_alert_actions',
                           'controlled_operation_scope')
      THEN 'iam_v2.begin_controlled_operation(text)'
    ELSE 'iam_v2.apply_entitlement_transition(uuid,text,timestamptz,text)' END;
  v_oid := to_regprocedure(v_sig);
  IF v_oid IS NULL THEN
    RAISE EXCEPTION 'controlled-writer function % is not resolvable (fail closed)', v_sig;
  END IF;
  SELECT pg_get_userbyid(proowner) INTO owner_role FROM pg_proc WHERE oid = v_oid;
  IF owner_role IS NULL OR owner_role = '' THEN
    RAISE EXCEPTION 'controlled-writer owner for % is not resolvable (fail closed)', v_sig;
  END IF;

  IF v_cap IS NOT NULL THEN
    -- EVERY write to a capability-scoped family is checked, including DELETE: an authoritative record that
    -- can be removed outside a declared operation is a record that can be made to have never happened.
    IF current_user <> owner_role AND NOT iam_v2.p3_controlled_operation_open(v_cap) THEN
      -- RAISE takes only '%' substitutions; '%L' is format()'s syntax and would print a literal L.
      RAISE EXCEPTION
        '%: writes to the % family require an open controlled operation (caller %) — call iam_v2.begin_controlled_operation(''%'') in the transaction that performs them',
        TG_TABLE_NAME, v_cap, current_user, v_cap;
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- (item 1) DELETE of the authoritative site grace config is ALWAYS a controlled-writer-only operation. There
  -- is no approved ordinary DELETE for this row; a future reset/disable must be its own audited, PO-approved API
  -- with explicit semantics (this guard deliberately does NOT silently convert DELETE into "disable").
  IF TG_OP = 'DELETE' THEN
    IF current_user <> owner_role THEN
      RAISE EXCEPTION '%: DELETE goes through an approved controlled iam_v2 writer (caller %)',
        TG_TABLE_NAME, current_user;
    END IF;
    RETURN OLD;
  END IF;
  IF TG_TABLE_NAME IN ('accounting_records','accounting_checkpoints','delayed_accounting_records',
                       'appliance_class_generation','auth_context_offers') THEN
    -- EVERY write is controlled. A physical measurement has exactly one legitimate author: the operation that
    -- computed it from a locked checkpoint. A raw INSERT here is invented usage; a raw UPDATE is rewritten
    -- history; and a raw checkpoint write is worse than either, because it silently changes what every FUTURE
    -- observation will be measured against.
    changed := true;
  ELSIF TG_TABLE_NAME = 'sessions' AND TG_OP = 'UPDATE' THEN
    -- A Session row is written by several legitimate paths (it is created, bound, rebound and ended), but two
    -- groups of columns are accounting state:
    --   * the USAGE TOTALS, advanced only by the ingestion operation in the same transaction as the record
    --     that justifies them — anything else moves a total with no row behind it;
    --   * the ACCOUNTING IDENTITY (address and ingress interface), which the operation re-derives the
    --     counter source from. Rewriting either retroactively changes which physical counters a Session is
    --     measured against, which is a silent way to make one guest's traffic land on another's checkpoint.
    -- ...and the ENFORCEMENT LIFECYCLE. A Session that says 'active' is a claim that the kernel is
    -- authorizing and metering this guest right now. Only the enforcement owner can know that, so promoting
    -- a Phase-3 session out of PENDING_ENFORCEMENT goes through activate_session_enforcement. Legacy
    -- transitions between the pre-existing values are untouched: this only guards the new state.
    changed := (NEW.bytes_up IS DISTINCT FROM OLD.bytes_up OR NEW.bytes_down IS DISTINCT FROM OLD.bytes_down
      OR NEW.ip IS DISTINCT FROM OLD.ip OR NEW.ingress_interface IS DISTINCT FROM OLD.ingress_interface
      OR (OLD.state = 'PENDING_ENFORCEMENT' AND NEW.state IS DISTINCT FROM OLD.state)
      OR NEW.state = 'PENDING_ENFORCEMENT');
  ELSIF TG_TABLE_NAME = 'entitlements' THEN
    changed := (NEW.status IS DISTINCT FROM OLD.status);   -- only status is controlled-writer-only
  ELSIF TG_TABLE_NAME = 'site_checkout_grace_config' AND TG_OP = 'UPDATE' THEN
    changed := (NEW.grace_package_revision_id IS DISTINCT FROM OLD.grace_package_revision_id
      OR NEW.grace_duration_seconds IS DISTINCT FROM OLD.grace_duration_seconds
      OR NEW.grace_down_kbps IS DISTINCT FROM OLD.grace_down_kbps
      OR NEW.grace_up_kbps IS DISTINCT FROM OLD.grace_up_kbps
      OR NEW.grace_data_quota_bytes IS DISTINCT FROM OLD.grace_data_quota_bytes
      OR NEW.grace_device_limit IS DISTINCT FROM OLD.grace_device_limit
      OR NEW.grace_device_limit_policy IS DISTINCT FROM OLD.grace_device_limit_policy
      OR NEW.eligibility_window_seconds IS DISTINCT FROM OLD.eligibility_window_seconds
      OR NEW.config_version IS DISTINCT FROM OLD.config_version);
  END IF;
  IF changed AND current_user <> owner_role THEN
    RAISE EXCEPTION '%: authoritative writes go through the controlled iam_v2 writer functions (caller %)',
      TG_TABLE_NAME, current_user;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p3_controlled_writer_owner(text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_controlled_writer_owner(p_family text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_sig text; v_oid oid; v_owner text;
BEGIN
  v_sig := CASE p_family
    WHEN 'entitlement' THEN 'iam_v2.apply_entitlement_transition(uuid,text,timestamptz,text)'
    WHEN 'grace_config' THEN 'iam_v2.publish_checkout_grace_config(uuid,uuid,uuid,int,int,int,bigint,int,text,int)'
    WHEN 'accounting' THEN 'iam_v2.ingest_absolute_counters(uuid,uuid,uuid,uuid,text,int,bigint,bigint,bigint,timestamptz)'
    WHEN 'accounting_origin' THEN 'iam_v2.register_class_origin(uuid,uuid,uuid,uuid,text,int,bigint,bigint,bigint,timestamptz)'
    WHEN 'class_generation' THEN 'iam_v2.allocate_class_generation(uuid,uuid,uuid)'
    WHEN 'auth_offers' THEN 'iam_v2.record_auth_context_offer(uuid,uuid,uuid,uuid,int,bigint,timestamptz)'
    ELSE NULL END;
  IF v_sig IS NULL THEN
    RAISE EXCEPTION 'no approved controlled-writer family %', p_family;
  END IF;
  v_oid := to_regprocedure(v_sig);            -- NULL (not an error) when unresolvable
  IF v_oid IS NULL THEN
    RAISE EXCEPTION 'controlled-writer function % is not resolvable (fail closed)', v_sig;
  END IF;
  SELECT pg_get_userbyid(proowner) INTO v_owner FROM pg_proc WHERE oid = v_oid;
  IF v_owner IS NULL OR v_owner = '' THEN
    RAISE EXCEPTION 'controlled-writer owner for % is not resolvable (fail closed)', v_sig;
  END IF;
  RETURN v_owner;
END $$;


--
-- Name: p3_detect_delayed_accounting(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_detect_delayed_accounting() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_ent uuid; v_t uuid; v_s uuid; v_wm uuid;
BEGIN
  -- The SAME binding answer the ingestion operation used — no second opinion, and no fallback to the
  -- session's current pointer. The BEFORE INSERT guard has already refused any row without one, so a NULL
  -- here would mean the guard was bypassed; fail closed rather than attribute it to whatever is current.
  v_ent := iam_v2.p3_entitlement_at(NEW.session_id, NEW.sampled_at);
  IF v_ent IS NULL THEN
    RAISE EXCEPTION 'ACCT_NO_BINDING: no entitlement was bound to session % at %', NEW.session_id, NEW.sampled_at;
  END IF;
  SELECT id INTO v_wm FROM iam_v2.entitlement_boundary_watermarks
    WHERE entitlement_id = v_ent AND boundary_at >= NEW.sampled_at ORDER BY boundary_at ASC LIMIT 1;
  IF v_wm IS NULL THEN RETURN NEW; END IF;   -- nothing frozen for this period
  SELECT tenant_id, site_id INTO v_t, v_s FROM iam_v2.sessions WHERE id = NEW.session_id;
  INSERT INTO iam_v2.delayed_accounting_records
    (tenant_id,site_id,accounting_record_id,session_id,entitlement_id,watermark_id,sampled_at,bytes_up,bytes_down)
    VALUES (v_t,v_s,NEW.id,NEW.session_id,v_ent,v_wm,NEW.sampled_at,NEW.bytes_up,NEW.bytes_down)
    ON CONFLICT (accounting_record_id) DO NOTHING;
  RETURN NEW;
END $$;


--
-- Name: p3_eda_insert_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_eda_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE prev_seq bigint; prev_deauth timestamptz; prev_open int;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM iam_v2.entitlement_devices ed
                 WHERE ed.entitlement_id=NEW.entitlement_id AND ed.device_id=NEW.device_id) THEN
    RAISE EXCEPTION 'device authorization requires an entitlement_devices binding';
  END IF;
  SELECT seq, deauthorized_at INTO prev_seq, prev_deauth
    FROM iam_v2.entitlement_device_authorizations
    WHERE entitlement_id=NEW.entitlement_id AND device_id=NEW.device_id ORDER BY seq DESC LIMIT 1;
  SELECT count(*) INTO prev_open FROM iam_v2.entitlement_device_authorizations
    WHERE entitlement_id=NEW.entitlement_id AND device_id=NEW.device_id AND deauthorized_at IS NULL;
  IF prev_seq IS NULL THEN
    IF NEW.seq <> 1 THEN RAISE EXCEPTION 'first device authorization must have seq=1'; END IF;
  ELSE
    IF NEW.seq <> prev_seq + 1 THEN RAISE EXCEPTION 'device authorization seq must be contiguous'; END IF;
    IF prev_open > 0 THEN RAISE EXCEPTION 'a device may not have two open authorization intervals'; END IF;
    IF NEW.authorized_at < prev_deauth THEN RAISE EXCEPTION 'new authorization cannot begin before the prior interval closed'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p3_entitlement_at(uuid, timestamp with time zone); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_entitlement_at(p_session uuid, p_at timestamp with time zone) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT b.entitlement_id FROM iam_v2.session_entitlement_bindings b
   WHERE b.session_id = p_session AND b.bound_from <= p_at
     AND (b.bound_until IS NULL OR b.bound_until > p_at)
   ORDER BY b.seq DESC LIMIT 1;
$$;


--
-- Name: p3_entitlement_data_usage(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_entitlement_data_usage(p_entitlement uuid) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT COALESCE(sum(ar.bytes_up + ar.bytes_down), 0)::bigint
    FROM iam_v2.accounting_records ar
    JOIN iam_v2.session_entitlement_bindings b
      ON b.session_id = ar.session_id
     AND b.entitlement_id = p_entitlement
     AND b.bound_from <= ar.sampled_at
     AND (
           -- the ordinary half-open interval, unchanged
           b.bound_until IS NULL
        OR b.bound_until > ar.sampled_at
           -- ...and the closing instant, ONLY when nothing else owns the sample. At most one binding per
           -- session can close at a given instant, and this arm is unreachable whenever a successor binding
           -- covers it, so a sample is still attributed EXACTLY ONCE.
        OR ( b.bound_until = ar.sampled_at
             AND NOT EXISTS (
                   SELECT 1
                     FROM iam_v2.session_entitlement_bindings b2
                    WHERE b2.session_id = ar.session_id
                      AND b2.bound_from <= ar.sampled_at
                      AND (b2.bound_until IS NULL OR b2.bound_until > ar.sampled_at)) )
         )
$$;


--
-- Name: FUNCTION p3_entitlement_data_usage(p_entitlement uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p3_entitlement_data_usage(p_entitlement uuid) IS 'Authoritative bytes attributed to an Entitlement across every Session and Device bound to it. Attribution follows the half-open binding interval, plus the closing instant itself when no other binding for that session covers it - which is the terminal case, where the sample that exhausted the quota would otherwise be attributed to nothing. A Phase-5 rebinding always has a successor covering the boundary, so that arm cannot fire there and no sample is counted twice. entitlements.consumed_data_bytes must equal this.';


--
-- Name: p3_entitlement_status_coherent(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_entitlement_status_coherent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE latest text; cur text;
BEGIN
  -- re-read the CURRENT (final, at-commit) row status rather than trusting the deferred trigger's captured NEW:
  -- a row updated several times in one tx queues several deferred events, each carrying a stale intermediate
  -- NEW — only the final committed status must agree with the latest transition.
  SELECT status INTO cur FROM iam_v2.entitlements WHERE id = NEW.id;
  IF cur IS NULL THEN RETURN NULL; END IF; -- row removed within the tx; nothing to check
  SELECT to_state INTO latest FROM iam_v2.entitlement_state_transitions
    WHERE entitlement_id = NEW.id AND superseded_by IS NULL ORDER BY seq DESC LIMIT 1;
  IF latest IS DISTINCT FROM cur THEN
    RAISE EXCEPTION 'entitlement % status % is not backed by its latest transition % (use apply_entitlement_transition)',
      NEW.id, cur, COALESCE(latest, 'NONE');
  END IF;
  RETURN NULL;
END $$;


--
-- Name: p3_est_insert_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_est_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE prev_seq bigint; prev_to text; prev_at timestamptz; cur_status text;
        max_seq bigint; max_rec timestamptz; tgt_ent uuid; tgt_by uuid;
BEGIN
  -- seq/recorded_at monotonicity is measured over the WHOLE table (knowledge only grows); the STATE CHAIN is
  -- measured over the LIVE (non-superseded) history, because an invalidated fact is no longer part of the chain.
  SELECT COALESCE(max(seq),0), max(recorded_at) INTO max_seq, max_rec
    FROM iam_v2.entitlement_state_transitions WHERE entitlement_id = NEW.entitlement_id;
  IF max_seq > 0 AND NEW.seq <> max_seq + 1 THEN
    RAISE EXCEPTION 'entitlement transition seq must be contiguous (% -> %)', max_seq, NEW.seq;
  END IF;
  IF max_seq = 0 AND NEW.seq <> 1 THEN
    RAISE EXCEPTION 'first entitlement transition must have seq=1 (got %)', NEW.seq;
  END IF;
  -- recorded_at (SYSTEM time) is the axis that can never move backwards. effective_at (BUSINESS time) is stored
  -- verbatim and may legitimately be earlier than an already-recorded fact, but only as an explicit correction
  -- that first INVALIDATES (supersedes) the facts it replaces.
  IF max_rec IS NOT NULL AND NEW.recorded_at < max_rec THEN
    RAISE EXCEPTION 'transition recorded_at cannot move backwards (% < %)', NEW.recorded_at, max_rec;
  END IF;
  IF NEW.supersedes IS NOT NULL THEN
    SELECT entitlement_id, superseded_by INTO tgt_ent, tgt_by
      FROM iam_v2.entitlement_state_transitions WHERE id = NEW.supersedes;
    IF tgt_ent IS NULL OR tgt_ent <> NEW.entitlement_id THEN
      RAISE EXCEPTION 'superseded transition % does not belong to entitlement %', NEW.supersedes, NEW.entitlement_id;
    END IF;
    -- the correction must ALREADY own the fact it claims to correct: the invalidated rows are marked with THIS
    -- row's id before it is inserted, so a caller cannot append a row that merely points at someone else's fact.
    IF tgt_by IS DISTINCT FROM NEW.id THEN
      RAISE EXCEPTION 'superseded transition % is not marked as corrected by this transition', NEW.supersedes;
    END IF;
  END IF;
  -- chain continuity is evaluated against what REMAINS live (post-invalidation)
  SELECT seq, to_state, effective_at INTO prev_seq, prev_to, prev_at
    FROM iam_v2.entitlement_state_transitions
    WHERE entitlement_id = NEW.entitlement_id AND superseded_by IS NULL ORDER BY seq DESC LIMIT 1;
  IF prev_seq IS NULL THEN
    IF NEW.from_state IS NOT NULL THEN RAISE EXCEPTION 'transition with no live predecessor must have from_state NULL'; END IF;
  ELSE
    IF NEW.from_state IS DISTINCT FROM prev_to THEN RAISE EXCEPTION 'from_state % must equal previous to_state %', NEW.from_state, prev_to; END IF;
    -- an append may not be back-dated behind the live chain: silently accepting an earlier effective_at would
    -- rewrite the state-at-boundary answer with no record. Corrections invalidate what they replace, first.
    IF NEW.effective_at < prev_at THEN
      RAISE EXCEPTION 'transition effective_at % precedes the live head % - record a correction (supersede_entitlement_transition / terminate_entitlement_at_boundary)', NEW.effective_at, prev_at;
    END IF;
  END IF;
  IF NEW.from_state IS NOT NULL AND NOT (
       (NEW.from_state='PENDING'   AND NEW.to_state IN ('ACTIVE','SUSPENDED','TERMINATED'))
    OR (NEW.from_state='ACTIVE'    AND NEW.to_state IN ('SUSPENDED','TERMINATED'))
    OR (NEW.from_state='SUSPENDED' AND NEW.to_state IN ('ACTIVE','TERMINATED'))) THEN
    RAISE EXCEPTION 'illegal entitlement transition % -> % (TERMINATED is terminal)', NEW.from_state, NEW.to_state;
  END IF;
  SELECT status INTO cur_status FROM iam_v2.entitlements WHERE id = NEW.entitlement_id;
  IF NEW.to_state IS DISTINCT FROM cur_status THEN
    RAISE EXCEPTION 'transition to_state % must equal entitlement current status % (use apply_entitlement_transition)', NEW.to_state, cur_status;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p3_expected_class_minor(inet); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_expected_class_minor(p_ip inet) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_ip IS NULL OR family(p_ip) <> 4 THEN NULL
    ELSE 4096 + (((split_part(host(p_ip), '.', 3)::int & 15) << 8) | split_part(host(p_ip), '.', 4)::int)
  END;
$$;


--
-- Name: p3_feed_authorizes(uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_feed_authorizes(p_tenant uuid, p_site uuid, p_interface uuid, p_revision uuid, p_evidence_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
  SELECT EXISTS (
    SELECT 1
      FROM iam_v2.pms_interfaces pi
      JOIN iam_v2.pms_interface_revisions pr
        ON pr.tenant_id=pi.tenant_id AND pr.site_id=pi.site_id
       AND pr.pms_interface_id=pi.id AND pr.id=p_revision
      JOIN iam_v2.pms_interface_runtime rt
        ON rt.tenant_id=pi.tenant_id AND rt.site_id=pi.site_id AND rt.pms_interface_id=pi.id
     WHERE pi.tenant_id=p_tenant AND pi.site_id=p_site AND pi.id=p_interface
       AND pi.lifecycle_state='ACTIVE'
       AND p_evidence_at IS NOT NULL
       -- (1) EITHER the feed is live, OR the last published roster stands on its own (D39).
       AND (
             (    rt.transport_status = 'CONNECTED'
              AND rt.sync_status      = 'IN_SYNC'
              AND COALESCE(rt.last_heartbeat_at, rt.last_connected_at) IS NOT NULL
              AND COALESCE(rt.last_heartbeat_at, rt.last_connected_at)
                    > now() - make_interval(secs => iam_v2.p3_cfg_secs(pr.config,'heartbeat_timeout_ms',300)))
             OR
             -- THE LAST GOOD ROSTER. A resync that is in flight, or that began and failed, says nothing about
             -- the roster already published: that roster is untouched until a replacement completes, so it
             -- remains exactly as trustworthy as it was a moment before the attempt started. Only its AGE may
             -- retire it, and term (3) is what does that.
             (    rt.transport_status <> 'CONNECTED'
              AND rt.last_complete_sync_at IS NOT NULL)
           )
       AND rt.continuity_status = 'CONTINUOUS'
       AND rt.pinned_revision_id = p_revision
       -- (2) MATERIALIZATION READINESS, unchanged — and the reason the partial generation cannot leak in.
       AND NOT EXISTS (
             SELECT 1 FROM iam_v2.stay_events se
              WHERE se.tenant_id = rt.tenant_id
                AND se.site_id = rt.site_id
                AND se.pms_interface_id = rt.pms_interface_id
                AND se.processing_status = 'PENDING'
                AND (se.admission_kind = 'LIVE'
                     OR se.resync_generation <= rt.published_resync_generation))
       -- (3) the absolute freshness ceiling. For the offline branch this IS the seventy-two hours: the last
       --     good roster is usable until it ages out, and then nothing is.
       AND p_evidence_at > now() - make_interval(secs =>
             CASE
               WHEN (pr.config->>'max_auth_cache_age_seconds') ~ '^[1-9][0-9]{0,5}$'
                AND (pr.config->>'max_auth_cache_age_seconds')::int <= 604800
                 THEN (pr.config->>'max_auth_cache_age_seconds')::int
               ELSE iam_v2.p3_cfg_secs(pr.config, 'complete_sync_ms', 86400)
                  + iam_v2.p3_cfg_secs(pr.config, 'heartbeat_timeout_ms', 300)
             END)
  );
$_$;


--
-- Name: FUNCTION p3_feed_authorizes(p_tenant uuid, p_site uuid, p_interface uuid, p_revision uuid, p_evidence_at timestamp with time zone); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p3_feed_authorizes(p_tenant uuid, p_site uuid, p_interface uuid, p_revision uuid, p_evidence_at timestamp with time zone) IS 'Single source of truth for the feed half of PMS Room sign-in eligibility. Authorises on EITHER a live feed OR the LAST SUCCESSFULLY PUBLISHED roster (D39), in both cases only when the materialized roster has caught up: no CLAIMABLE PENDING stay_event may exist, where claimable mirrors the applier''s own predicate (LIVE, or a generation at or below the published one). A resync that is in flight or that began and failed does NOT invalidate the published roster — the applier cannot consume an unpublished generation, so the live roster is whole until a replacement completes, and only max_auth_cache_age_seconds retires it. STABLE and therefore NOT sufficient on its own: callers take the interface runtime row lock first.';


--
-- Name: p3_grace_config_version_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_grace_config_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE policy_changed boolean;
BEGIN
  policy_changed := (NEW.grace_package_revision_id IS DISTINCT FROM OLD.grace_package_revision_id
    OR NEW.grace_duration_seconds IS DISTINCT FROM OLD.grace_duration_seconds
    OR NEW.grace_down_kbps IS DISTINCT FROM OLD.grace_down_kbps OR NEW.grace_up_kbps IS DISTINCT FROM OLD.grace_up_kbps
    OR NEW.grace_data_quota_bytes IS DISTINCT FROM OLD.grace_data_quota_bytes
    OR NEW.grace_device_limit IS DISTINCT FROM OLD.grace_device_limit
    OR NEW.grace_device_limit_policy IS DISTINCT FROM OLD.grace_device_limit_policy
    OR NEW.eligibility_window_seconds IS DISTINCT FROM OLD.eligibility_window_seconds);
  IF NEW.config_version < OLD.config_version THEN
    RAISE EXCEPTION 'site grace config_version cannot decrease (% -> %)', OLD.config_version, NEW.config_version;
  END IF;
  IF policy_changed AND NEW.config_version <> OLD.config_version + 1 THEN
    RAISE EXCEPTION 'a grace policy change must increment config_version by exactly 1 (use publish_checkout_grace_config)';
  END IF;
  IF NOT policy_changed AND NEW.config_version <> OLD.config_version THEN
    RAISE EXCEPTION 'config_version may not change without a policy change';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p3_guest_network_mirror_state(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_guest_network_mirror_state(p_tenant uuid, p_site uuid, p_guest_network uuid) RETURNS TABLE(transport_status text, last_complete_sync_at timestamp with time zone, can_authorise boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT COALESCE(max(rt.transport_status), ''),
         max(rt.last_complete_sync_at),
         COALESCE(bool_or(iam_v2.p3_feed_authorizes(
             pi.tenant_id, pi.site_id, pi.id, pi.current_revision_id, now())), false)
    FROM iam_v2.guest_network_pms_map m
    JOIN iam_v2.pms_interfaces pi
      ON pi.tenant_id = m.tenant_id AND pi.site_id = m.site_id AND pi.id = m.pms_interface_id
     AND pi.lifecycle_state = 'ACTIVE'
    LEFT JOIN iam_v2.pms_interface_runtime rt
      ON rt.tenant_id = pi.tenant_id AND rt.site_id = pi.site_id AND rt.pms_interface_id = pi.id
   WHERE m.tenant_id = p_tenant AND m.site_id = p_site AND m.guest_network_id = p_guest_network;
$$;


--
-- Name: FUNCTION p3_guest_network_mirror_state(p_tenant uuid, p_site uuid, p_guest_network uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p3_guest_network_mirror_state(p_tenant uuid, p_site uuid, p_guest_network uuid) IS 'Transport status, last complete sync and "could the mirror authorise anybody" for the interfaces mapped to one guest network. Exists so svc_scd never needs privilege on iam_v2.pms_interface_runtime: the role being authorised must not read or rewrite the feed health it is authorised against. Exposes no guest, Stay, reservation or PMS credential.';


--
-- Name: p3_history_appendonly(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_history_appendonly() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION '%: append-only history (DELETE rejected)', TG_TABLE_NAME;
  END IF;
  -- UPDATE: only entitlement_device_authorizations.deauthorized_at may go NULL->a value once; nothing else.
  IF TG_TABLE_NAME = 'entitlement_device_authorizations' THEN
    IF OLD.deauthorized_at IS NOT NULL THEN
      RAISE EXCEPTION 'entitlement_device_authorizations interval is immutable once closed';
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.entitlement_id IS DISTINCT FROM OLD.entitlement_id
       OR NEW.device_id IS DISTINCT FROM OLD.device_id OR NEW.seq IS DISTINCT FROM OLD.seq
       OR NEW.authorized_at IS DISTINCT FROM OLD.authorized_at THEN
      RAISE EXCEPTION 'entitlement_device_authorizations identity/interval-start immutable';
    END IF;
    IF NEW.deauthorized_at IS NULL THEN
      RAISE EXCEPTION 'entitlement_device_authorizations UPDATE must close the interval (set deauthorized_at)';
    END IF;
    RETURN NEW;
  END IF;
  -- entitlement_state_transitions: the ONLY permitted mutation is marking a row superseded (NULL -> the id of the
  -- correcting transition), exactly once. Every other column, including effective_at, stays immutable forever.
  IF TG_TABLE_NAME = 'entitlement_state_transitions' THEN
    IF OLD.superseded_by IS NOT NULL THEN
      RAISE EXCEPTION 'entitlement_state_transitions row % is already superseded', OLD.id;
    END IF;
    IF NEW.superseded_by IS NULL THEN
      RAISE EXCEPTION 'entitlement_state_transitions UPDATE must record a supersession';
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.entitlement_id IS DISTINCT FROM OLD.entitlement_id
       OR NEW.seq IS DISTINCT FROM OLD.seq OR NEW.from_state IS DISTINCT FROM OLD.from_state
       OR NEW.to_state IS DISTINCT FROM OLD.to_state OR NEW.effective_at IS DISTINCT FROM OLD.effective_at
       OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at OR NEW.supersedes IS DISTINCT FROM OLD.supersedes
       OR NEW.reason IS DISTINCT FROM OLD.reason THEN
      RAISE EXCEPTION 'entitlement_state_transitions is immutable except for the supersession mark';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION '%: append-only history (UPDATE rejected)', TG_TABLE_NAME;
END $$;


--
-- Name: p3_lock_grace_config(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_lock_grace_config(p_tenant uuid, p_site uuid) RETURNS TABLE(grace_duration_seconds integer, grace_down_kbps integer, grace_up_kbps integer, grace_data_quota_bytes bigint, grace_device_limit integer, grace_device_limit_policy text, grace_package_revision_id uuid, config_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
    SELECT g.grace_duration_seconds, g.grace_down_kbps, g.grace_up_kbps, g.grace_data_quota_bytes,
           g.grace_device_limit, g.grace_device_limit_policy, g.grace_package_revision_id, g.config_version
      FROM iam_v2.site_checkout_grace_config g
     WHERE g.tenant_id = p_tenant AND g.site_id = p_site
     FOR UPDATE;
  -- No row is not an error: an unconfigured site takes the Emergency Grace path, and the caller distinguishes
  -- "no row" from "row present but incomplete". Returning zero rows preserves that exactly.
END
$$;


--
-- Name: FUNCTION p3_lock_grace_config(p_tenant uuid, p_site uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p3_lock_grace_config(p_tenant uuid, p_site uuid) IS 'Locks one site grace-config row FOR UPDATE inside the caller''s transaction and returns the eight fields the Checkout Converter reads. Exists so a caller needs EXECUTE on a non-mutating function rather than UPDATE on the table: PostgreSQL requires UPDATE privilege to take a row lock, and granting it to a runtime role collided with the D32 no-direct-grace-mutation invariant. Mutates nothing; the audited publication boundary remains the only way grace policy changes.';


--
-- Name: p3_rederive_entitlement_times(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_rederive_entitlement_times(p_ent uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  UPDATE iam_v2.entitlements e SET
    activated_at = (SELECT min(t.effective_at) FROM iam_v2.entitlement_state_transitions t
                    WHERE t.entitlement_id = e.id AND t.superseded_by IS NULL AND t.to_state='ACTIVE'),
    terminated_at = (SELECT t.effective_at FROM iam_v2.entitlement_state_transitions t
                     WHERE t.entitlement_id = e.id AND t.superseded_by IS NULL AND t.to_state='TERMINATED'
                     ORDER BY t.seq DESC LIMIT 1)
  WHERE e.id = p_ent;
END $$;


--
-- Name: p3_reserved_grace_codes(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_reserved_grace_codes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE reserved text[] := ARRAY['__sys_emergency_grace_plan__','__sys_emergency_grace_pkg__'];
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.code = ANY(reserved) THEN
      RAISE EXCEPTION 'reserved system grace object % cannot be deleted', OLD.code;
    END IF;
    RETURN OLD;
  END IF;
  -- protect BOTH the old and the new code: a reserved object cannot be renamed AWAY (OLD reserved -> NEW not),
  -- nor can a non-reserved row be renamed INTO the reserved namespace as a non-system object.
  IF TG_OP = 'UPDATE' AND OLD.code = ANY(reserved) AND NEW.code IS DISTINCT FROM OLD.code THEN
    RAISE EXCEPTION 'reserved system grace object code is immutable (cannot rename away from %)', OLD.code;
  END IF;
  IF NEW.code = ANY(reserved) THEN
    IF TG_TABLE_NAME = 'internet_packages' THEN
      IF NEW.is_system IS NOT TRUE THEN
        RAISE EXCEPTION 'reserved grace code % requires a system-owned package', NEW.code;
      END IF;
      IF NEW.active IS NOT TRUE THEN
        RAISE EXCEPTION 'reserved system grace package cannot be disabled';
      END IF;
      IF TG_OP = 'UPDATE' THEN
        IF NEW.is_system IS DISTINCT FROM OLD.is_system THEN
          RAISE EXCEPTION 'reserved system grace package is_system is immutable';
        END IF;
        -- current_revision_id may be SET once by bootstrap, never re-pointed afterwards.
        IF OLD.current_revision_id IS NOT NULL AND NEW.current_revision_id IS DISTINCT FROM OLD.current_revision_id THEN
          RAISE EXCEPTION 'reserved system grace package current revision cannot be re-pointed';
        END IF;
      END IF;
    ELSIF TG_TABLE_NAME = 'service_plans' THEN
      IF NEW.enabled IS NOT TRUE THEN
        RAISE EXCEPTION 'reserved system grace plan cannot be disabled';
      END IF;
      IF TG_OP = 'UPDATE' AND OLD.current_revision_id IS NOT NULL
         AND NEW.current_revision_id IS DISTINCT FROM OLD.current_revision_id THEN
        RAISE EXCEPTION 'reserved system grace plan current revision cannot be re-pointed';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p3_seb_appendonly(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_seb_appendonly() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'session_entitlement_bindings: append-only (DELETE rejected)'; END IF;
  IF OLD.bound_until IS NOT NULL THEN RAISE EXCEPTION 'session binding interval is immutable once closed'; END IF;
  IF NEW.bound_until IS NULL THEN RAISE EXCEPTION 'session binding UPDATE must close the interval'; END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.session_id IS DISTINCT FROM OLD.session_id
     OR NEW.entitlement_id IS DISTINCT FROM OLD.entitlement_id OR NEW.seq IS DISTINCT FROM OLD.seq
     OR NEW.bound_from IS DISTINCT FROM OLD.bound_from THEN
    RAISE EXCEPTION 'session binding identity/interval-start immutable';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p3_seb_insert_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_seb_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE prev_seq bigint; prev_until timestamptz; prev_open boolean;
BEGIN
  SELECT seq, bound_until, bound_until IS NULL INTO prev_seq, prev_until, prev_open
    FROM iam_v2.session_entitlement_bindings WHERE session_id = NEW.session_id ORDER BY seq DESC LIMIT 1;
  IF prev_seq IS NULL THEN
    IF NEW.seq <> 1 THEN RAISE EXCEPTION 'first session binding must have seq=1 (got %)', NEW.seq; END IF;
  ELSE
    IF NEW.seq <> prev_seq + 1 THEN RAISE EXCEPTION 'session binding seq must be contiguous (% -> %)', prev_seq, NEW.seq; END IF;
    IF prev_open THEN RAISE EXCEPTION 'session % already has an OPEN binding interval', NEW.session_id; END IF;
    IF NEW.bound_from < prev_until THEN RAISE EXCEPTION 'session binding % cannot begin before the previous closed at %', NEW.bound_from, prev_until; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p3_session_close_binding(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_session_close_binding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  -- This operation writes a capability-scoped family, so it declares its own scope. Doing it here
  -- rather than relying on ownership is what lets Gate-P give every function its own owner without
  -- any of them losing the right to perform its own writes.
  PERFORM iam_v2.begin_controlled_operation('session_binding');
  IF NEW.ended IS NOT NULL AND OLD.ended IS NULL THEN
    UPDATE iam_v2.session_entitlement_bindings b SET bound_until = GREATEST(NEW.ended, b.bound_from)
      WHERE b.session_id = NEW.id AND b.bound_until IS NULL;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: p3_session_open_binding(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_session_open_binding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  -- This operation writes a capability-scoped family, so it declares its own scope. Doing it here
  -- rather than relying on ownership is what lets Gate-P give every function its own owner without
  -- any of them losing the right to perform its own writes.
  PERFORM iam_v2.begin_controlled_operation('session_binding');
  INSERT INTO iam_v2.session_entitlement_bindings(tenant_id,site_id,session_id,entitlement_id,seq,bound_from)
    VALUES (NEW.tenant_id,NEW.site_id,NEW.id,NEW.entitlement_id,1,NEW.started);
  RETURN NULL;
END $$;


--
-- Name: p3_stay_event_appendonly(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_stay_event_appendonly() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE ok_stay int;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'stay_events is append-only (DELETE rejected)';
  END IF;

  -- RETENTION ANONYMISATION (0127). The table owner, inside a retention run, may replace the payload and the
  -- event fingerprint of a processed event -- and nothing else. The new payload is the blank marker or a part
  -- of the old one (0144): anonymisation removes, it never writes something new.
  --
  -- GIVING UP A WAITING EVENT (0139; GDPR audit B2, D-B2). An event still PENDING long after any real PMS would
  -- have been processed may, in the same run, be closed as FAILED with review code RETENTION_GIVEN_UP, its
  -- payload blanked and its fingerprint replaced, in ONE move. No other column may change, so the processor can
  -- never act on a blanked payload: the event is terminal before anyone sees it empty.
  IF TG_OP = 'UPDATE'
     AND current_setting('iam_v2.anonymise', true) = 'retention'
     AND current_user = (SELECT pg_get_userbyid(c.relowner) FROM pg_class c WHERE c.oid = TG_RELID) THEN
    IF OLD.processing_status = 'PENDING' THEN
      IF NEW.processing_status = 'FAILED' AND NEW.review_code = 'RETENTION_GIVEN_UP' AND NEW.processed_at IS NOT NULL
         AND NEW.payload = '{"anonymised": true}'::jsonb AND NEW.stay_id IS NOT DISTINCT FROM OLD.stay_id
         AND (to_jsonb(NEW) - 'payload' - 'external_event_identity' - 'processing_status' - 'review_code' - 'processed_at')
             = (to_jsonb(OLD) - 'payload' - 'external_event_identity' - 'processing_status' - 'review_code' - 'processed_at') THEN
        RETURN NEW;
      END IF;
      RAISE EXCEPTION 'a waiting stay_events row may only be given up whole (FAILED, RETENTION_GIVEN_UP, payload blanked)';
    END IF;
    IF (to_jsonb(NEW) - 'payload' - 'external_event_identity')
       IS DISTINCT FROM (to_jsonb(OLD) - 'payload' - 'external_event_identity') THEN
      RAISE EXCEPTION 'stay_events anonymisation may replace only payload and external_event_identity of a processed event';
    END IF;
    IF NEW.payload IS DISTINCT FROM OLD.payload
       AND NEW.payload IS DISTINCT FROM '{"anonymised": true}'::jsonb
       AND NOT (OLD.payload @> NEW.payload) THEN
      RAISE EXCEPTION 'stay_events anonymisation may only remove from a payload or blank it';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.processing_status <> 'PENDING' THEN
      RAISE EXCEPTION 'stay_events must be inserted as PENDING (no terminal event inserted directly)';
    END IF;
    IF NEW.stay_id IS NOT NULL THEN
      RAISE EXCEPTION 'stay_events cannot be inserted with a pre-resolved stay_id';
    END IF;
    IF NEW.processed_at IS NOT NULL THEN
      RAISE EXCEPTION 'stay_events.processed_at must be NULL on insert';
    END IF;
    IF NEW.review_code IS NOT NULL THEN
      RAISE EXCEPTION 'stay_events.review_code must be NULL on insert';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE: immutable identity / normalization / admission columns
  IF   NEW.id                    IS DISTINCT FROM OLD.id
    OR NEW.tenant_id             IS DISTINCT FROM OLD.tenant_id
    OR NEW.site_id               IS DISTINCT FROM OLD.site_id
    OR NEW.pms_interface_id      IS DISTINCT FROM OLD.pms_interface_id
    OR NEW.external_event_identity IS DISTINCT FROM OLD.external_event_identity
    OR NEW.event_type            IS DISTINCT FROM OLD.event_type
    OR NEW.pms_timestamp_raw     IS DISTINCT FROM OLD.pms_timestamp_raw
    OR NEW.pms_timestamp_utc     IS DISTINCT FROM OLD.pms_timestamp_utc
    OR NEW.source_timezone       IS DISTINCT FROM OLD.source_timezone
    OR NEW.received_at           IS DISTINCT FROM OLD.received_at
    OR NEW.sequence_version      IS DISTINCT FROM OLD.sequence_version
    OR NEW.normalization_version IS DISTINCT FROM OLD.normalization_version
    OR NEW.clock_suspect         IS DISTINCT FROM OLD.clock_suspect
    OR NEW.payload               IS DISTINCT FROM OLD.payload
    OR NEW.admission_kind              IS DISTINCT FROM OLD.admission_kind
    OR NEW.admission_runtime_generation IS DISTINCT FROM OLD.admission_runtime_generation
    OR NEW.resync_generation           IS DISTINCT FROM OLD.resync_generation
    OR NEW.fingerprint_key_version     IS DISTINCT FROM OLD.fingerprint_key_version
  THEN
    RAISE EXCEPTION 'stay_events identity/normalization/admission columns are immutable (append-only)';
  END IF;

  -- Once terminal, the only permitted update is a no-op (no result/lineage field may change).
  IF OLD.processing_status <> 'PENDING' THEN
    IF NEW.processing_status IS DISTINCT FROM OLD.processing_status
       OR NEW.stay_id      IS DISTINCT FROM OLD.stay_id
       OR NEW.processed_at IS DISTINCT FROM OLD.processed_at
       OR NEW.review_code  IS DISTINCT FROM OLD.review_code THEN
      RAISE EXCEPTION 'terminal stay_events row is immutable (status/stay_id/processed_at/review_code frozen)';
    END IF;
    RETURN NEW;
  END IF;

  -- OLD is PENDING and staying PENDING: no result/lineage field may be set yet.
  IF NEW.processing_status = 'PENDING' THEN
    IF NEW.stay_id IS NOT NULL OR NEW.processed_at IS NOT NULL OR NEW.review_code IS NOT NULL THEN
      RAISE EXCEPTION 'stay_events result fields (stay_id/processed_at/review_code) may only be set on PENDING->terminal';
    END IF;
    RETURN NEW;
  END IF;

  -- PENDING -> terminal (one move). A RESYNC row's PUBLICATION is enforced by the consumer against the
  -- interface's published_resync_generation boundary; the row itself stays immutable append-first evidence.
  IF NEW.processing_status NOT IN ('APPLIED','SKIPPED_DUPLICATE','MANUAL_REVIEW','FAILED') THEN
    RAISE EXCEPTION 'invalid stay_events terminal processing_status %', NEW.processing_status;
  END IF;
  IF NEW.processed_at IS NULL THEN
    RAISE EXCEPTION 'stay_events.processed_at is required on PENDING->%', NEW.processing_status;
  END IF;
  -- stay_id lineage: NULL -> a same-interface Stay only
  IF NEW.stay_id IS NOT NULL THEN
    IF OLD.stay_id IS NOT NULL THEN
      RAISE EXCEPTION 'stay_events.stay_id may only go from NULL to a resolved Stay';
    END IF;
    SELECT count(*) INTO ok_stay FROM iam_v2.stays s
      WHERE s.id = NEW.stay_id AND s.tenant_id = NEW.tenant_id
        AND s.site_id = NEW.site_id AND s.pms_interface_id = NEW.pms_interface_id;
    IF ok_stay <> 1 THEN
      RAISE EXCEPTION 'stay_events.stay_id must reference a Stay in the same tenant/site/pms_interface';
    END IF;
  END IF;
  -- review_code vocabulary: bounded machine code only (no PII / payload / stack traces)
  IF NEW.review_code IS NOT NULL AND NEW.review_code !~ '^[A-Z][A-Z0-9_]{0,63}$' THEN
    RAISE EXCEPTION 'stay_events.review_code must match ^[A-Z][A-Z0-9_]{0,63}$ (bounded machine code)';
  END IF;
  -- result-specific invariants
  IF NEW.processing_status = 'APPLIED' THEN
    IF NEW.stay_id IS NULL THEN RAISE EXCEPTION 'APPLIED requires a resolved same-interface stay_id'; END IF;
    IF NEW.review_code IS NOT NULL THEN RAISE EXCEPTION 'APPLIED must not carry a review_code'; END IF;
  ELSIF NEW.processing_status = 'MANUAL_REVIEW' THEN
    IF NEW.review_code IS NULL THEN RAISE EXCEPTION 'MANUAL_REVIEW requires a bounded review_code'; END IF;
  ELSIF NEW.processing_status = 'FAILED' THEN
    IF NEW.review_code IS NULL THEN RAISE EXCEPTION 'FAILED requires a bounded review_code'; END IF;
  END IF;
  -- SKIPPED_DUPLICATE: processed_at required (checked); stay_id/review_code optional (validated above).
  RETURN NEW;
END $_$;


--
-- Name: p3_stay_lifecycle_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p3_stay_lifecycle_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE allowed boolean; is_reinstate boolean; evidence_changed boolean;
BEGIN
  -- ANONYMISING A FINISHED STAY (0147) may coarsen the checkout boundary and the occupancy evidence time to the day, and
  -- nothing else about the lifecycle: the boundary stays inside its day, the status, versions and evidence identity do not
  -- move. Only the table's owner, inside the anonymising definer functions (the flag is transaction-local).
  IF current_setting('iam_v2.anonymise', true) = 'retention'
     AND current_user = (SELECT pg_get_userbyid(c.relowner) FROM pg_class c WHERE c.oid = TG_RELID)
     AND OLD.status IN ('CHECKED_OUT', 'POST_STAY_ACTIVE', 'CANCELLED', 'NO_SHOW')
     AND NEW.status = OLD.status AND NEW.lifecycle_version = OLD.lifecycle_version
     AND NEW.last_applied_event_version = OLD.last_applied_event_version
     AND NEW.occupancy_evidence_version = OLD.occupancy_evidence_version
     AND NEW.occupancy_revision_id IS NOT DISTINCT FROM OLD.occupancy_revision_id
     AND NEW.occupancy_normalization_version IS NOT DISTINCT FROM OLD.occupancy_normalization_version
     AND NEW.occupancy_clock_suspect IS NOT DISTINCT FROM OLD.occupancy_clock_suspect
     AND (NEW.effective_checkout_at IS NOT DISTINCT FROM OLD.effective_checkout_at
          OR NEW.effective_checkout_at = date_trunc('day', OLD.effective_checkout_at))
     AND (NEW.occupancy_evidence_at IS NOT DISTINCT FROM OLD.occupancy_evidence_at
          OR NEW.occupancy_evidence_at = date_trunc('day', OLD.occupancy_evidence_at)) THEN
    RETURN NEW;
  END IF;
  IF NEW.last_applied_event_version < OLD.last_applied_event_version THEN
    RAISE EXCEPTION 'stays.last_applied_event_version cannot decrease (% -> %)',
      OLD.last_applied_event_version, NEW.last_applied_event_version;
  END IF;

  IF NEW.occupancy_evidence_version < OLD.occupancy_evidence_version THEN
    RAISE EXCEPTION 'stays.occupancy_evidence_version cannot decrease (% -> %)',
      OLD.occupancy_evidence_version, NEW.occupancy_evidence_version;
  END IF;
  evidence_changed := (
       NEW.occupancy_evidence_at          IS DISTINCT FROM OLD.occupancy_evidence_at
    OR NEW.occupancy_revision_id          IS DISTINCT FROM OLD.occupancy_revision_id
    OR NEW.occupancy_normalization_version IS DISTINCT FROM OLD.occupancy_normalization_version
    OR NEW.occupancy_clock_suspect        IS DISTINCT FROM OLD.occupancy_clock_suspect);
  IF evidence_changed THEN
    IF NEW.occupancy_evidence_version <> OLD.occupancy_evidence_version + 1 THEN
      RAISE EXCEPTION 'a material occupancy-evidence change must increment occupancy_evidence_version by exactly 1 (% -> %)',
        OLD.occupancy_evidence_version, NEW.occupancy_evidence_version;
    END IF;
  ELSE
    IF NEW.occupancy_evidence_version <> OLD.occupancy_evidence_version THEN
      RAISE EXCEPTION 'stays.occupancy_evidence_version may not change without a material occupancy-evidence change (% -> %)',
        OLD.occupancy_evidence_version, NEW.occupancy_evidence_version;
    END IF;
  END IF;

  is_reinstate := (OLD.status = 'CHECKED_OUT' AND NEW.status = 'IN_HOUSE');

  IF NEW.effective_checkout_at IS DISTINCT FROM OLD.effective_checkout_at THEN
    IF is_reinstate THEN
      IF NEW.effective_checkout_at IS NOT NULL THEN
        RAISE EXCEPTION 'reinstatement must CLEAR effective_checkout_at (starts a new episode)';
      END IF;
    ELSIF OLD.status = 'IN_HOUSE' AND NEW.status = 'CHECKED_OUT' THEN
      IF NEW.effective_checkout_at IS NULL THEN
        RAISE EXCEPTION 'checkout must SET effective_checkout_at';
      END IF;
    ELSE
      RAISE EXCEPTION 'effective_checkout_at is immutable within an episode (% -> %, status % -> %)',
        OLD.effective_checkout_at, NEW.effective_checkout_at, OLD.status, NEW.status;
    END IF;
  END IF;

  IF NEW.lifecycle_version <> OLD.lifecycle_version THEN
    IF NOT (NEW.lifecycle_version = OLD.lifecycle_version + 1 AND is_reinstate) THEN
      RAISE EXCEPTION 'stays.lifecycle_version may increment by exactly 1 ONLY during a CHECKED_OUT->IN_HOUSE reinstatement (% -> %, % -> %)',
        OLD.lifecycle_version, NEW.lifecycle_version, OLD.status, NEW.status;
    END IF;
  END IF;

  IF NEW.status <> OLD.status THEN
    allowed := CASE
      WHEN OLD.status='RESERVED'    AND NEW.status IN ('IN_HOUSE','CANCELLED','NO_SHOW') THEN true
      WHEN OLD.status='IN_HOUSE'    AND NEW.status IN ('CHECKED_OUT')                    THEN true
      WHEN OLD.status='CHECKED_OUT' AND NEW.status IN ('IN_HOUSE')                       THEN true  -- reinstatement
      -- PHASE 5: the post-stay conversion, and the only arm this migration adds. It stays within the episode
      -- (lifecycle_version unchanged, enforced above) and keeps the immutable checkout boundary (unchanged,
      -- enforced above), so a post-stay Stay is still the same episode that checked out.
      WHEN OLD.status='CHECKED_OUT' AND NEW.status IN ('POST_STAY_ACTIVE')               THEN true
      ELSE false END;
    IF NOT allowed THEN
      RAISE EXCEPTION 'illegal stays.status transition % -> %', OLD.status, NEW.status;
    END IF;
    IF is_reinstate AND NEW.lifecycle_version <> OLD.lifecycle_version + 1 THEN
      RAISE EXCEPTION 'reinstatement (CHECKED_OUT->IN_HOUSE) must increment lifecycle_version exactly once';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_admin_posting_block(uuid, uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_admin_posting_block(p_tenant uuid, p_site uuid, p_stay uuid, p_action text, p_reason text, p_operator uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'public', 'pg_temp'
    AS $$
DECLARE st record; v_status text; n integer;
BEGIN
  IF p_action NOT IN ('SET','CLEAR') THEN
    RAISE EXCEPTION 'ADMIN_BLOCK_ACTION: SET or CLEAR' USING ERRCODE = 'check_violation';
  END IF;
  IF length(btrim(coalesce(p_reason,''))) < 4 THEN
    RAISE EXCEPTION 'ADMIN_BLOCK_REASON: a reason is required' USING ERRCODE = 'check_violation';
  END IF;
  SELECT status INTO v_status FROM public.operators WHERE id = p_operator AND tenant_id = p_tenant;
  IF v_status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'ADMIN_BLOCK_ACTOR: an active operator of this tenant is required' USING ERRCODE = 'check_violation';
  END IF;
  SELECT id INTO st FROM iam_v2.stays WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_stay FOR UPDATE;
  IF st.id IS NULL THEN RAISE EXCEPTION 'ADMIN_BLOCK_STAY: no such stay' USING ERRCODE = 'no_data_found'; END IF;
  IF p_action = 'SET' THEN
    PERFORM iam_v2.p4_place_stay_posting_block(p_stay, 'ADMIN_BLOCK', 'OPERATOR', NULL, NULL, p_operator, btrim(p_reason));
    RETURN 'SET';
  END IF;
  UPDATE iam_v2.stay_posting_blocks
     SET cleared_at = now(), cleared_by_source = 'OPERATOR', cleared_by = p_operator, cleared_reason = btrim(p_reason)
   WHERE stay_id = p_stay AND reason = 'ADMIN_BLOCK' AND cleared_at IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM iam_v2.p4_refresh_stay_posting_permission(p_stay);
  RETURN CASE WHEN n > 0 THEN 'CLEARED' ELSE 'NOT_BLOCKED' END;
END $$;


--
-- Name: p4_answer_effect(uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_answer_effect(p_iface uuid, p_as text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_action text;
BEGIN
  IF p_as = 'OK' THEN RETURN 'POSTED'; END IF;
  IF p_as IS NULL OR p_as NOT IN ('NP','NG','NR','NA','RY') THEN RETURN 'UNPROVEN'; END IF;
  SELECT action INTO v_action FROM iam_v2.pms_answer_confirmations
   WHERE pms_interface_id = p_iface AND as_status = p_as ORDER BY recorded_at DESC, id DESC LIMIT 1;
  IF v_action IS DISTINCT FROM 'CONFIRM' THEN RETURN 'UNPROVEN'; END IF;
  RETURN CASE p_as WHEN 'NP' THEN 'NOT_POSTED_NO_POST'
                   WHEN 'NG' THEN 'NOT_POSTED_TARGET_INVALID'
                   WHEN 'NR' THEN 'NOT_POSTED_TARGET_INVALID'
                   ELSE 'NOT_POSTED_NO_STAY_EFFECT' END;
END $$;


--
-- Name: p4_append_only_refuse(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_append_only_refuse() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION '% is append-only: % refused', TG_TABLE_NAME, TG_OP USING ERRCODE = 'restrict_violation';
END $$;


--
-- Name: p4_apply_provider_outcome(text, text, text, text, text, jsonb); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_apply_provider_outcome(p_client_ref text, p_provider_event_id text, p_event_type text, p_outcome text, p_provider_txn_ref text, p_evidence jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE tx record;
BEGIN
  IF p_outcome NOT IN ('CAPTURED','FAILED','UNKNOWN') THEN
    RAISE EXCEPTION 'PAYMENT_OUTCOME_INVALID: % is not a provider outcome this operation may apply',
      p_outcome USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO tx FROM iam_v2.payment_transactions WHERE provider_ref = p_client_ref;
  IF tx.id IS NULL THEN
    RAISE EXCEPTION 'CALLBACK_UNCORRELATED: no payment intent matches this client reference'
      USING ERRCODE = 'no_data_found';
  END IF;
  -- THE NARROWING THAT MATTERS. An outcome may only be applied to a payment that is actually executing --
  -- so this cannot be used to conjure a result for an intent nobody started.
  --
  -- The one exception is a delivery that REPEATS the outcome already recorded, which is what every provider
  -- does when it retries a webhook. That is not a status change and it is not a manufacture; it is a fact
  -- about a delivery, and it still goes through to the callback ledger below so the retry is RECORDED
  -- rather than silently dropped. The ledger's unique index makes it a no-op, and the reference-conflict
  -- check still runs -- which is why this delegates instead of returning early.
  IF tx.status <> 'PENDING' AND tx.status IS DISTINCT FROM p_outcome THEN
    RAISE EXCEPTION 'PAYMENT_NOT_EXECUTING: the intent is %; an outcome may only be applied to a payment '
                    'that crossed the execution boundary', tx.status USING ERRCODE = 'check_violation';
  END IF;
  RETURN iam_v2.apply_payment_callback_v2(
    tx.tenant_id, tx.provider, tx.merchant_account_id, p_client_ref,
    p_provider_event_id, p_event_type, p_outcome, nullif(p_provider_txn_ref,''), p_evidence);
END $$;


--
-- Name: p4_apply_refund_policy(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_apply_refund_policy(p_tenant uuid, p_site uuid, p_charge uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  ch record; se record; v_captured bigint; v_refunded bigint; v_charged_back bigint; v_ent uuid; v_status text; v_tr uuid;
BEGIN
  SELECT * INTO ch FROM iam_v2.payment_transactions
   WHERE id = p_charge AND tenant_id = p_tenant AND site_id = p_site AND transaction_type = 'CHARGE';
  IF NOT FOUND OR ch.status <> 'CAPTURED' THEN
    RETURN 'NOT_A_CAPTURED_CHARGE';
  END IF;
  SELECT * INTO se FROM iam_v2.settlements WHERE id = ch.settlement_id FOR UPDATE;
  v_captured := ch.amount_minor;
  SELECT COALESCE(sum(amount_minor) FILTER (WHERE transaction_type = 'REFUND'), 0),
         COALESCE(sum(amount_minor) FILTER (WHERE transaction_type = 'CHARGEBACK'), 0)
    INTO v_refunded, v_charged_back
    FROM iam_v2.payment_transactions WHERE parent_transaction_id = p_charge AND status = 'CAPTURED';

  IF v_charged_back > 0 THEN
    INSERT INTO iam_v2.card_reversal_reviews (tenant_id, site_id, settlement_id, charge_transaction_id, kind, provider_ref)
    VALUES (p_tenant, p_site, se.id, p_charge, 'CHARGEBACK', 'ledger')
    ON CONFLICT (charge_transaction_id, kind, provider_ref) DO NOTHING;
    RETURN 'CHARGEBACK_REVIEW';
  END IF;
  IF v_refunded <= 0 THEN
    RETURN 'NO_REFUND';
  END IF;
  IF v_refunded < v_captured THEN
    RETURN 'PARTIAL_NO_ACTION';
  END IF;

  SELECT id, status INTO v_ent, v_status FROM iam_v2.entitlements
   WHERE tenant_id = p_tenant AND site_id = p_site AND purchase_id = se.purchase_id;
  IF v_ent IS NULL THEN
    RETURN 'NO_ENTITLEMENT';
  END IF;
  IF EXISTS (SELECT 1 FROM iam_v2.refund_access_terminations WHERE entitlement_id = v_ent) THEN
    RETURN 'ALREADY_ENDED';
  END IF;
  IF v_status = 'TERMINATED' THEN
    RETURN 'ALREADY_TERMINATED'; -- ended for another reason before the refund; nothing to record
  END IF;
  v_tr := iam_v2.p4_end_access_funded_by(v_ent, 'REVOKED');
  INSERT INTO iam_v2.refund_access_terminations
    (entitlement_id, tenant_id, site_id, settlement_id, charge_transaction_id, captured_minor, refunded_minor, transition_id)
  VALUES (v_ent, p_tenant, p_site, se.id, p_charge, v_captured, v_refunded, v_tr);
  RETURN 'ACCESS_ENDED';
END $$;


--
-- Name: p4_assert_compliance_archived(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_assert_compliance_archived(p_tenant uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_any int; v_verified int;
BEGIN
  SELECT count(*) INTO v_any FROM iam_v2.compliance_archives
   WHERE tenant_id = p_tenant AND purpose = 'CROSS_CUSTOMER_PURGE';
  IF v_any = 0 THEN
    RAISE EXCEPTION 'COMPLIANCE_ARCHIVE_MISSING: tenant % has no compliance archive; its data may not be '
                    'purged until one has been produced and its custody acknowledged', p_tenant
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*) INTO v_verified FROM iam_v2.compliance_archives
   WHERE tenant_id = p_tenant AND purpose = 'CROSS_CUSTOMER_PURGE' AND receipt_verified;
  IF v_verified = 0 THEN
    RAISE EXCEPTION 'COMPLIANCE_RECEIPT_UNVERIFIED: tenant % has an archive but no EXTERNAL authority has '
                    'acknowledged custody of it. A local copy attested only by the appliance that is about '
                    'to delete the data is self-certification, not a compliance archive. No archival '
                    'receipt authority exists in this product, so this purge cannot proceed', p_tenant
      USING ERRCODE = 'check_violation';
  END IF;
END $$;


--
-- Name: p4_assert_financial_actor(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_assert_financial_actor(p_tenant uuid, p_actor uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'public', 'pg_temp'
    AS $$
DECLARE ok boolean;
BEGIN
  IF p_actor IS NULL THEN
    RAISE EXCEPTION 'FINANCIAL_ACTOR_REQUIRED: an audited financial decision has an author'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.operators o
                  WHERE o.id = p_actor AND o.tenant_id = p_tenant AND o.status = 'active')
    INTO ok;
  IF NOT ok THEN
    RAISE EXCEPTION 'FINANCIAL_ACTOR_UNKNOWN: the recorded author is not an active operator of this '
                    'tenant' USING ERRCODE = 'check_violation';
  END IF;
END $$;


--
-- Name: p4_attempt_freshness_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_attempt_freshness_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_block text; v_rev uuid;
BEGIN
  SELECT posting_interface_revision_id INTO v_rev FROM iam_v2.pms_postings WHERE id = NEW.internal_posting_id;
  v_block := iam_v2.p4_interface_freshness_block(NEW.tenant_id, NEW.site_id, NEW.pms_interface_id, v_rev, now());
  IF v_block IS NOT NULL THEN
    RAISE EXCEPTION 'INTERFACE_NOT_FRESH: %', v_block USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_attempt_lifecycle_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_attempt_lifecycle_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_state text;
BEGIN
  SELECT lifecycle_state INTO v_state FROM iam_v2.pms_interfaces
   WHERE tenant_id = NEW.tenant_id AND site_id = NEW.site_id AND id = NEW.pms_interface_id;
  IF v_state = 'DECOMMISSIONED' THEN
    RAISE EXCEPTION 'INTERFACE_DECOMMISSIONED: interface % may not transmit', NEW.pms_interface_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_attempt_not_sent_reason(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_attempt_not_sent_reason(p_attempt uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT e.detail->>'reason' FROM iam_v2.posting_attempt_events e
   WHERE e.posting_attempt_id = p_attempt AND e.event_type = 'NOT_SENT' ORDER BY e.created_at LIMIT 1;
$$;


--
-- Name: p4_attempt_retry_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_attempt_retry_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_last record; v_auth int; v_term text;
BEGIN
  SELECT attempt_no, outcome INTO v_last
    FROM iam_v2.posting_attempts
   WHERE internal_posting_id = NEW.internal_posting_id
   ORDER BY attempt_no DESC LIMIT 1;

  IF v_last IS NULL THEN
    IF NEW.attempt_no <> 1 THEN
      RAISE EXCEPTION 'ATTEMPT_SEQUENCE: first attempt for posting % must be attempt_no 1, got %',
        NEW.internal_posting_id, NEW.attempt_no USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.attempt_no <> v_last.attempt_no + 1 THEN
    RAISE EXCEPTION 'ATTEMPT_SEQUENCE: next attempt for posting % must be %, got %',
      NEW.internal_posting_id, v_last.attempt_no + 1, NEW.attempt_no USING ERRCODE = 'check_violation';
  END IF;

  IF v_last.outcome = 'SENDING' THEN
    RAISE EXCEPTION 'ATTEMPT_IN_FLIGHT: attempt % for posting % is still SENDING; a second concurrent '
                    'attempt would risk a duplicate charge', v_last.attempt_no, NEW.internal_posting_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_last.outcome IN ('UNKNOWN','ACKED') THEN
    SELECT terminal_action, retry_authorized_attempt_no INTO v_term, v_auth
      FROM iam_v2.posting_review_state WHERE posting_id = NEW.internal_posting_id;
    IF v_term IS DISTINCT FROM 'CONFIRM_NOT_POSTED_RETRY' OR v_auth IS DISTINCT FROM NEW.attempt_no THEN
      RAISE EXCEPTION 'RETRY_REQUIRES_REVIEW: posting % last attempt is %; attempt % is not authorized by '
                      'an audited CONFIRM_NOT_POSTED_RETRY', NEW.internal_posting_id, v_last.outcome, NEW.attempt_no
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: p4_attempt_targets_posting_reservation(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_attempt_targets_posting_reservation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_g text;
BEGIN
  SELECT g_number INTO v_g FROM iam_v2.pms_postings WHERE id = NEW.internal_posting_id;
  IF v_g IS NULL OR NEW.g_number IS DISTINCT FROM v_g THEN
    RAISE EXCEPTION 'ATTEMPT_RESERVATION_MISMATCH: an attempt carries its posting''s reservation number and no other'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_authorize_zero_attempt_retry(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_authorize_zero_attempt_retry(p_posting uuid, p_actor uuid, p_reason text, p_evidence jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE po record; ob record; h record; v_action uuid; v_attempts int; v_bad text;
BEGIN
  SELECT * INTO po FROM iam_v2.pms_postings WHERE id = p_posting;
  IF po.id IS NULL THEN
    RAISE EXCEPTION 'REVIEW_POSTING_UNKNOWN: %', p_posting USING ERRCODE = 'no_data_found';
  END IF;
  PERFORM iam_v2.p4_assert_financial_actor(po.tenant_id, p_actor);
  IF p_reason IS NULL OR length(btrim(p_reason)) < 10 THEN
    RAISE EXCEPTION 'REVIEW_REASON_REQUIRED: a retry authorization records WHY, in at least 10 characters'
      USING ERRCODE = 'check_violation';
  END IF;
  -- Evidence screening. p4_callback_evidence_safe is deliberately NOT reused here: it enforces the
  -- PROVIDER-CALLBACK key allowlist (provider_status, provider_reason_code, ...), which is the wrong
  -- contract for a review decision and would reject the operator evidence the review surface actually
  -- collects. What matters in both places is the same, though -- the ledger is immutable, so nothing that
  -- looks like a secret may enter it -- so the screening is done here against the same shapes.
  IF p_evidence IS NOT NULL THEN
    IF jsonb_typeof(p_evidence) <> 'object' THEN
      RAISE EXCEPTION 'REVIEW_EVIDENCE_UNSAFE: evidence must be a bounded object'
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT string_agg(k, ',') INTO v_bad FROM jsonb_object_keys(p_evidence) k
     WHERE k IN ('raw_body','raw','payload','body','token','secret','password','api_key','card',
                 'pan','cvv','authorization');
    IF v_bad IS NOT NULL THEN
      RAISE EXCEPTION 'REVIEW_EVIDENCE_UNSAFE: key(s) % may not enter an immutable audit record; record a '
                      'REFERENCE to the artefact, never its contents', v_bad
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT string_agg(k, ',') INTO v_bad FROM jsonb_each_text(p_evidence) e(k, v)
     WHERE length(v) > 256 OR v ~ '[[:cntrl:]]'
        OR v ~ '(?i)(sk_live|pk_live|-----BEGIN|bearer [A-Za-z0-9._-]{20,}|[0-9]{13,19})';
    IF v_bad IS NOT NULL THEN
      RAISE EXCEPTION 'REVIEW_EVIDENCE_UNSAFE: value(s) under % look like a secret, a card number or an '
                      'unbounded blob', v_bad USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  SELECT count(*) INTO v_attempts FROM iam_v2.posting_attempts WHERE internal_posting_id = p_posting;
  IF v_attempts > 0 THEN
    RAISE EXCEPTION 'RETRY_HAS_ATTEMPTS: this posting has % attempt(s); use the ordinary audited review '
                    'path, which is the one that knows how to read them', v_attempts
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO ob FROM iam_v2.posting_outbox WHERE posting_id = p_posting FOR UPDATE;
  IF ob.id IS NULL OR ob.state <> 'HELD_RECOVERY' THEN
    RAISE EXCEPTION 'RETRY_NOT_HELD: this posting is not held by recovery (%); there is nothing to release',
      coalesce(ob.state,'no outbox row') USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO h FROM iam_v2.financial_recovery_holds
   WHERE work_kind = 'POSTING_OUTBOX' AND work_id = ob.id
   ORDER BY held_at DESC LIMIT 1;
  IF h.id IS NULL OR h.resolution IS DISTINCT FROM 'CONFIRMED_NOT_COMPLETED' THEN
    RAISE EXCEPTION 'RETRY_NOT_ESTABLISHED: this posting has no reconciliation establishing that it was '
                    'NOT completed (%). A retry is only safe once someone has checked the folio',
      coalesce(h.resolution, 'unreconciled') USING ERRCODE = 'check_violation';
  END IF;

  -- The audited record. It goes into the SAME append-only review ledger every other financial decision
  -- goes into, so a reader auditing this posting sees one history rather than two.
  --
  -- 0011 guards that ledger with a writer token so it has exactly one writer. Setting the token here makes
  -- this function a SECOND sanctioned writer, which is a deliberate and narrow addition: it is the only way
  -- to record the zero-attempt case, it is a definer function no runtime role can call except the operator
  -- role, and every other path into the table remains closed. The alternative -- writing the decision
  -- somewhere else -- would give this posting two histories.
  PERFORM set_config('iam_v2.p4_review_writer', txid_current()::text, true);
  INSERT INTO iam_v2.posting_review_actions
    (tenant_id, site_id, posting_id, action, actor, reason, evidence)
  VALUES (po.tenant_id, po.site_id, p_posting, 'CONFIRM_NOT_POSTED_RETRY', p_actor, p_reason,
          coalesce(p_evidence, '{}'::jsonb))
  RETURNING id INTO v_action;

  INSERT INTO iam_v2.posting_review_state
    (posting_id, tenant_id, site_id, review_version, retry_authorized_attempt_no, updated_at)
  VALUES (p_posting, po.tenant_id, po.site_id, 1, 1, now())
  ON CONFLICT (posting_id) DO UPDATE
     SET review_version = iam_v2.posting_review_state.review_version + 1,
         retry_authorized_attempt_no = 1,
         updated_at = now();

  -- Only NOW does it become sendable, and only because an operator established it never was.
  UPDATE iam_v2.posting_outbox SET state = 'QUEUED' WHERE id = ob.id;
  RETURN v_action;
END $$;


--
-- Name: p4_callback_evidence_safe(jsonb); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_callback_evidence_safe(p jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE k text; v text; allowed text[] := ARRAY['provider_status','provider_reason_code','provider_message',
                                                'provider_received_at','settled_currency','settled_amount_minor'];
BEGIN
  IF p IS NULL OR p = '{}'::jsonb THEN RETURN NULL; END IF;
  IF jsonb_typeof(p) <> 'object' THEN RETURN 'callback evidence must be a flat object'; END IF;
  FOR k, v IN SELECT key, value::text FROM jsonb_each_text(p) LOOP
    IF NOT (k = ANY(allowed)) THEN
      RETURN 'callback evidence key ' || k || ' is not in the allowed set: ' || array_to_string(allowed, ', ');
    END IF;
    IF length(v) > 200 THEN RETURN 'callback evidence value for ' || k || ' exceeds 200 characters'; END IF;
    IF v ~ '[\x00-\x1f\x7f]' THEN RETURN 'callback evidence value for ' || k || ' contains control characters'; END IF;
    IF v ~* '\m(pass(word|phrase)?|secret|api[-_ ]?key|token|bearer|authorization|credential|cvv|cvc|pan)\M'
       OR v ~ '(-----BEGIN|eyJ[A-Za-z0-9_-]{10,}|sk_live_|whsec_)'
       OR v ~ '\m(?:\d[ -]?){13,19}\M' THEN
      RETURN 'callback evidence value for ' || k || ' looks like a secret, card number or credential';
    END IF;
  END LOOP;
  -- nesting is refused wholesale: a nested value is a payload
  IF EXISTS (SELECT 1 FROM jsonb_each(p) WHERE jsonb_typeof(value) IN ('object','array')) THEN
    RETURN 'callback evidence must be flat; nested objects and arrays are payloads';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: p4_clear_posting_unresolved(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_clear_posting_unresolved(p_posting uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_stay uuid;
BEGIN
  SELECT stay_id INTO v_stay FROM iam_v2.pms_postings WHERE id = p_posting;
  UPDATE iam_v2.stay_posting_blocks SET cleared_at = now(), cleared_by_source = 'POSTING_LEDGER'
   WHERE posting_id = p_posting AND reason = 'POSTING_UNRESOLVED' AND cleared_at IS NULL;
  IF v_stay IS NOT NULL THEN PERFORM iam_v2.p4_refresh_stay_posting_permission(v_stay); END IF;
END $$;


--
-- Name: p4_consume_retry_authorization(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_consume_retry_authorization() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  UPDATE iam_v2.posting_review_state
     SET retry_authorized_attempt_no = NULL,
         retry_authorization_consumed_at = now(),
         review_version = review_version + 1,
         updated_at = now()
   WHERE posting_id = NEW.internal_posting_id
     AND terminal_action = 'CONFIRM_NOT_POSTED_RETRY'
     AND retry_authorized_attempt_no = NEW.attempt_no;
  RETURN NULL;
END $$;


--
-- Name: p4_create_room_charge_posting(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_create_room_charge_posting(p_tenant uuid, p_site uuid, p_settlement uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE se record; pu record; ac record; i record; rdy record; st record; v_posting uuid;
BEGIN
  SELECT * INTO se FROM iam_v2.settlements WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_settlement FOR UPDATE;
  IF se.id IS NULL OR se.method <> 'PMS_POSTING' OR se.status <> 'REQUIRED' THEN
    RAISE EXCEPTION 'ROOM_CHARGE_SETTLEMENT: not a REQUIRED room-charge settlement' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO pu FROM iam_v2.purchases WHERE id = se.purchase_id FOR UPDATE;
  IF pu.state <> 'AWAITING_SETTLEMENT' OR pu.stay_id IS NULL OR pu.pms_interface_id IS NULL OR pu.settlement_mapping_id IS NULL THEN
    RAISE EXCEPTION 'ROOM_CHARGE_PURCHASE: the purchase does not pin a stay, interface and mapping' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO ac FROM iam_v2.auth_contexts WHERE id = pu.auth_context_id;
  IF ac.method <> 'PMS' OR ac.stay_id IS DISTINCT FROM pu.stay_id THEN
    RAISE EXCEPTION 'ROOM_CHARGE_AUTHENTICATION: a room charge needs a verified Room sign-in for the same stay' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO rdy FROM iam_v2.pms_interface_financially_ready(p_tenant, p_site, pu.pms_interface_id);
  IF NOT rdy.ready THEN
    RAISE EXCEPTION 'ROOM_CHARGE_NOT_READY: %', rdy.reason USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO i FROM iam_v2.pms_interfaces WHERE id = pu.pms_interface_id;
  SELECT external_reservation_id INTO st FROM iam_v2.stays
   WHERE tenant_id = p_tenant AND site_id = p_site AND pms_interface_id = pu.pms_interface_id AND id = pu.stay_id;
  IF st.external_reservation_id IS NULL OR btrim(st.external_reservation_id) = '' THEN
    RAISE EXCEPTION 'ROOM_CHARGE_NO_RESERVATION: the stay has no reservation number' USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO iam_v2.pms_postings
    (tenant_id, site_id, pms_interface_id, settlement_id, purchase_id, stay_id, g_number,
     posting_interface_revision_id, posting_type, amount_minor, currency, currency_exponent, idempotency_key)
  VALUES (p_tenant, p_site, pu.pms_interface_id, se.id, pu.id, pu.stay_id, st.external_reservation_id,
          i.current_revision_id, 'CHARGE', pu.amount_minor, pu.currency, pu.currency_exponent,
          'room-charge:' || se.id::text)
  RETURNING id INTO v_posting;
  INSERT INTO iam_v2.posting_outbox (tenant_id, site_id, pms_interface_id, posting_id, state)
  VALUES (p_tenant, p_site, pu.pms_interface_id, v_posting, 'QUEUED');
  UPDATE iam_v2.settlements SET status = 'IN_PROGRESS' WHERE id = se.id;
  RETURN v_posting;
END $$;


--
-- Name: p4_current_restore_generation(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_current_restore_generation(p_tenant uuid, p_site uuid) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT coalesce(max(restore_generation), 0) FROM iam_v2.financial_epochs
   WHERE tenant_id = p_tenant AND site_id = p_site;
$$;


--
-- Name: p4_declare_financial_recovery(uuid, uuid, uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_declare_financial_recovery(p_tenant uuid, p_site uuid, p_actor uuid, p_reason text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE cur record; v_epoch bigint;
BEGIN
  PERFORM iam_v2.p4_assert_financial_actor(p_tenant, p_actor);
  IF p_reason IS NULL OR length(btrim(p_reason)) < 10 THEN
    RAISE EXCEPTION 'RECOVERY_REASON_REQUIRED: declaring recovery needs a reason of at least 10 characters'
      USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('p4.epoch:' || p_tenant::text || ':' || p_site::text));
  SELECT * INTO cur FROM iam_v2.financial_epochs
   WHERE tenant_id = p_tenant AND site_id = p_site ORDER BY epoch DESC LIMIT 1;
  IF cur.epoch IS NOT NULL AND cur.released_at IS NULL THEN
    RETURN cur.epoch;
  END IF;
  v_epoch := coalesce(cur.epoch, 0) + 1;
  INSERT INTO iam_v2.financial_epochs (tenant_id, site_id, epoch, system_identity, reason)
  VALUES (p_tenant, p_site, v_epoch, coalesce(cur.system_identity, 'operator-declared'), 'OPERATOR_DECLARED');
  -- The SAME full-rail hold a detected restore performs. An operator declaring recovery is making the same
  -- statement a restore detector makes, so it must have the same consequence.
  PERFORM iam_v2.p4_hold_financial_rails(p_tenant, p_site, v_epoch);
  RETURN v_epoch;
END $$;


--
-- Name: p4_end_access_funded_by(uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_end_access_funded_by(p_entitlement uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_tr uuid; v_status text;
BEGIN
  SELECT status INTO v_status FROM iam_v2.entitlements WHERE id = p_entitlement FOR UPDATE;
  IF v_status IS NULL OR v_status = 'TERMINATED' THEN
    RETURN NULL;
  END IF;
  v_tr := iam_v2.terminate_entitlement_at_boundary(p_entitlement, now(), p_reason);
  PERFORM iam_v2.begin_controlled_operation('device_auth');
  WITH closed AS (
    UPDATE iam_v2.entitlement_device_authorizations a
       SET deauthorized_at = GREATEST(now(), a.authorized_at)
     WHERE a.entitlement_id = p_entitlement AND a.deauthorized_at IS NULL
     RETURNING a.entitlement_id, a.device_id)
  UPDATE iam_v2.entitlement_devices ed
     SET status = 'DISCONNECTED', disconnected_reason = 'ENTITLEMENT_ENDED'
    FROM closed
   WHERE ed.entitlement_id = closed.entitlement_id AND ed.device_id = closed.device_id;
  UPDATE iam_v2.sessions
     SET state = 'ended', ended = GREATEST(now(), started), end_reason = 'ENTITLEMENT_ENDED'
   WHERE entitlement_id = p_entitlement AND state IN ('active', 'PENDING_ENFORCEMENT');
  RETURN v_tr;
END $$;


--
-- Name: p4_entitlement_grant_kernel(uuid, uuid, uuid, uuid, uuid, uuid, jsonb, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_entitlement_grant_kernel(p_tenant uuid, p_site uuid, p_purchase uuid, p_voucher uuid, p_account uuid, p_principal uuid, p_snapshot jsonb, p_plan_rev uuid, p_pkg_rev uuid) RETURNS TABLE(entitlement_id uuid, already_granted boolean, superseded uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT * FROM iam_v2.p4_entitlement_grant_kernel_v2(p_tenant, p_site, p_purchase,
    p_voucher, p_account, p_principal, NULL, NULL, NULL, p_snapshot, p_plan_rev, p_pkg_rev);
$$;


--
-- Name: p4_entitlement_grant_kernel_v2(uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, jsonb, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_entitlement_grant_kernel_v2(p_tenant uuid, p_site uuid, p_purchase uuid, p_voucher uuid, p_account uuid, p_principal uuid, p_anon uuid, p_stay uuid, p_iface uuid, p_snapshot jsonb, p_plan_rev uuid, p_pkg_rev uuid) RETURNS TABLE(entitlement_id uuid, already_granted boolean, superseded uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  v_subject_key text; v_existing uuid; v_superseded uuid; v_new uuid;
  v_time_mode text; v_end_mode text; v_window timestamptz; v_state text;
  v_burned int; v_voucher_pkg uuid; v_quota bigint;
BEGIN
  IF num_nonnulls(p_voucher, p_account, p_principal, p_anon, p_stay) <> 1 THEN
    RAISE EXCEPTION 'GRANT_SUBJECT_UNRESOLVED: an entitlement always belongs to exactly one subject'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_stay IS NOT NULL AND p_iface IS NULL THEN
    RAISE EXCEPTION 'GRANT_STAY_UNPINNED: a stay entitlement names its PMS interface' USING ERRCODE = 'check_violation';
  END IF;
  IF p_snapshot IS NULL OR p_snapshot->>'service_plan_revision_id' IS NULL THEN
    RAISE EXCEPTION 'GRANT_SNAPSHOT_UNREADABLE' USING ERRCODE = 'check_violation';
  END IF;

  -- A voucher grants what it was printed for, and nothing else (0088).
  IF p_voucher IS NOT NULL THEN
    IF p_pkg_rev IS NULL THEN
      RAISE EXCEPTION 'VOUCHER_PACKAGE_UNPINNED: a voucher grant must name the package revision it grants'
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT package_revision_id INTO v_voucher_pkg FROM iam_v2.vouchers
     WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_voucher;
    IF v_voucher_pkg IS NULL THEN
      RAISE EXCEPTION 'VOUCHER_NOT_FOUND: voucher % does not belong to this owner', p_voucher
        USING ERRCODE = 'check_violation';
    END IF;
    IF v_voucher_pkg <> p_pkg_rev THEN
      RAISE EXCEPTION 'VOUCHER_PACKAGE_MISMATCH: voucher % was printed against package revision %, and this '
                      'grant is for %; a card grants what it was printed for', p_voucher, v_voucher_pkg, p_pkg_rev
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  v_time_mode := coalesce(p_snapshot->>'time_accounting_mode', 'VALIDITY_WINDOW');
  v_end_mode  := coalesce(nullif(p_snapshot->>'end_mode',''), 'MANUAL_END');
  v_window    := CASE WHEN p_snapshot->>'window_ends_at' IS NOT NULL
                      THEN (p_snapshot->>'window_ends_at')::timestamptz ELSE NULL END;
  -- A PER_STAY_NIGHT allowance resolved ONCE at quote time from the pinned stay and frozen here. Only this
  -- explicit key is read: the snapshot's plan data_quota_bytes is the plan's own number and the entitlement
  -- keeps reading its plan revision for it, exactly as before.
  v_quota     := CASE WHEN (p_snapshot->>'frozen_data_quota_bytes') IS NOT NULL
                       AND (p_snapshot->>'frozen_data_quota_bytes')::bigint > 0
                      THEN (p_snapshot->>'frozen_data_quota_bytes')::bigint ELSE NULL END;

  v_subject_key := 'phase2.subject|' || p_tenant::text || '|' || p_site::text || '|' ||
                   coalesce(p_voucher::text, p_account::text, p_principal::text, p_anon::text, p_stay::text);
  PERFORM pg_advisory_xact_lock(hashtext(v_subject_key));

  SELECT id INTO v_existing FROM iam_v2.entitlements WHERE purchase_id = p_purchase LIMIT 1;
  IF v_existing IS NOT NULL THEN
    entitlement_id := v_existing; already_granted := true; superseded := NULL; RETURN NEXT; RETURN;
  END IF;

  SELECT id INTO v_superseded FROM iam_v2.entitlements
   WHERE tenant_id = p_tenant AND site_id = p_site AND status IN ('PENDING','ACTIVE','SUSPENDED')
     AND ( (p_voucher   IS NOT NULL AND voucher_id           = p_voucher)
        OR (p_account   IS NOT NULL AND guest_account_id     = p_account)
        OR (p_principal IS NOT NULL AND guest_principal_id   = p_principal)
        OR (p_anon      IS NOT NULL AND anonymous_subject_id = p_anon)
        OR (p_stay      IS NOT NULL AND stay_id              = p_stay) )
   ORDER BY activated_at DESC NULLS LAST, id LIMIT 1 FOR UPDATE;
  IF v_superseded IS NOT NULL THEN
    PERFORM iam_v2.apply_entitlement_transition(v_superseded, 'TERMINATED', now(), 'SUPERSEDED');
  END IF;

  INSERT INTO iam_v2.entitlements
    (tenant_id, site_id, voucher_id, guest_account_id, guest_principal_id, anonymous_subject_id,
     stay_id, pms_interface_id, purchase_id,
     policy_snapshot, service_plan_revision_id, package_revision_id, time_accounting_mode,
     end_mode, window_ends_at, status, supersedes_entitlement_id, activated_at, data_quota_bytes)
  VALUES (p_tenant, p_site, p_voucher, p_account, p_principal, p_anon,
          p_stay, CASE WHEN p_stay IS NOT NULL THEN p_iface END, p_purchase,
          p_snapshot, p_plan_rev, p_pkg_rev, v_time_mode, v_end_mode, v_window,
          'ACTIVE', v_superseded, now(), v_quota)
  RETURNING id INTO v_new;
  PERFORM iam_v2.apply_entitlement_transition(v_new, 'ACTIVE', now(), 'GRANTED');

  -- SINGLE-USE: the voucher is spent here, inside the grant, or the grant does not happen (0084).
  IF p_voucher IS NOT NULL THEN
    UPDATE iam_v2.vouchers
       SET state = 'REDEEMED'
     WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_voucher
       AND state = 'UNUSED'
       AND (redemption_valid_from  IS NULL OR redemption_valid_from  <= now())
       AND (redemption_valid_until IS NULL OR redemption_valid_until >  now());
    GET DIAGNOSTICS v_burned = ROW_COUNT;
    IF v_burned <> 1 THEN
      RAISE EXCEPTION 'VOUCHER_NOT_REDEEMABLE: voucher % is not UNUSED and inside its window for this owner',
        p_voucher USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  SELECT state INTO v_state FROM iam_v2.purchases WHERE id = p_purchase FOR UPDATE;
  IF v_state NOT IN ('PENDING','AWAITING_SETTLEMENT','MANUAL_REVIEW') THEN
    RAISE EXCEPTION 'PURCHASE_STATE_TRANSITION: % -> GRANTED is not an approved transition', v_state
      USING ERRCODE = 'check_violation';
  END IF;
  UPDATE iam_v2.purchases SET state = 'GRANTED' WHERE id = p_purchase;

  entitlement_id := v_new; already_granted := false; superseded := v_superseded; RETURN NEXT;
END $$;


--
-- Name: p4_fail_unstarted_card_purchases(uuid, uuid, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_fail_unstarted_card_purchases(p_tenant uuid, p_site uuid, p_older_than_seconds integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE r record; v_n integer := 0;
BEGIN
  IF p_tenant IS NULL OR p_site IS NULL THEN
    RAISE EXCEPTION 'CARD_SWEEP_SCOPE: tenant and site are required' USING ERRCODE = 'check_violation';
  END IF;
  IF p_older_than_seconds IS NULL OR p_older_than_seconds < 600 OR p_older_than_seconds > 7 * 86400 THEN
    RAISE EXCEPTION 'CARD_SWEEP_AGE: % s is outside 600 s .. 7 days', p_older_than_seconds
      USING ERRCODE = 'check_violation';
  END IF;
  FOR r IN
    SELECT se.id AS settlement_id, pu.id AS purchase_id,
           GREATEST(1, extract(epoch FROM now() - q.consumed_at)::integer) AS waited
      FROM iam_v2.settlements se
      JOIN iam_v2.purchases pu
        ON pu.tenant_id = se.tenant_id AND pu.site_id = se.site_id AND pu.id = se.purchase_id
      JOIN iam_v2.offer_quotes q ON q.id = pu.offer_quote_id
     WHERE se.tenant_id = p_tenant AND se.site_id = p_site
       AND se.method = 'ONLINE_PAYMENT' AND se.status = 'REQUIRED'
       AND pu.state = 'AWAITING_SETTLEMENT'
       AND q.consumed_at IS NOT NULL
       AND q.consumed_at < now() - make_interval(secs => p_older_than_seconds)
       AND NOT EXISTS (SELECT 1 FROM iam_v2.payment_transactions pt WHERE pt.settlement_id = se.id)
     ORDER BY q.consumed_at
     LIMIT 200
     FOR UPDATE OF se SKIP LOCKED
  LOOP
    -- Re-checked under the row lock: a transaction created between the scan and the lock wins.
    IF EXISTS (SELECT 1 FROM iam_v2.payment_transactions pt WHERE pt.settlement_id = r.settlement_id) THEN
      CONTINUE;
    END IF;
    UPDATE iam_v2.settlements SET status = 'IN_PROGRESS' WHERE id = r.settlement_id AND status = 'REQUIRED';
    UPDATE iam_v2.settlements SET status = 'FAILED' WHERE id = r.settlement_id AND status = 'IN_PROGRESS';
    INSERT INTO iam_v2.card_purchase_sweeps (tenant_id, site_id, purchase_id, settlement_id, reason, waited_seconds)
    VALUES (p_tenant, p_site, r.purchase_id, r.settlement_id, 'NO_PAYMENT_TRANSACTION', r.waited);
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END $$;


--
-- Name: p4_fias_exponent_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_fias_exponent_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_kind text;
BEGIN
  IF NEW.posting_type = 'REVERSAL' THEN
    RETURN NEW;
  END IF;
  SELECT connector_kind INTO v_kind FROM iam_v2.pms_interfaces
   WHERE tenant_id = NEW.tenant_id AND site_id = NEW.site_id AND id = NEW.pms_interface_id;
  IF v_kind = 'protel-fias' AND NEW.currency_exponent IS NOT NULL AND NEW.currency_exponent <> 2 THEN
    RAISE EXCEPTION 'FIAS_EXPONENT_UNSUPPORTED: the protel-fias posting path is exponent 2 by contract '
                    '(section 9a); posting exponent is %', NEW.currency_exponent
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_financial_mirror_max_age_seconds(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_financial_mirror_max_age_seconds(p_tenant uuid, p_site uuid, p_iface uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT COALESCE((SELECT s.mirror_max_age_seconds FROM iam_v2.pms_interface_financial_settings s
                    WHERE s.tenant_id = p_tenant AND s.site_id = p_site AND s.pms_interface_id = p_iface), 14400);
$$;


--
-- Name: p4_financial_recovery_active(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_financial_recovery_active(p_tenant uuid, p_site uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM iam_v2.financial_epochs
                  WHERE tenant_id = p_tenant AND site_id = p_site AND released_at IS NULL
                    AND reason IN ('RESTORE_DETECTED','OPERATOR_DECLARED'));
$$;


--
-- Name: p4_financial_resync_due(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_financial_resync_due(p_tenant uuid, p_site uuid, p_iface uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT COALESCE((
    SELECT rt.transport_status = 'CONNECTED'
       AND rt.sync_status = 'IN_SYNC'
       AND rt.resync_started_at IS NULL
       AND rt.published_resync_generation = rt.resync_generation_seq
       AND rt.last_complete_sync_at IS NOT NULL
       AND rt.last_complete_sync_at < now() - make_interval(secs =>
             iam_v2.p4_financial_mirror_max_age_seconds(p_tenant, p_site, p_iface) / 2.0)
       AND COALESCE((SELECT r.ready FROM iam_v2.pms_interface_financially_ready(p_tenant, p_site, p_iface) r), false)
      FROM iam_v2.pms_interface_runtime rt
     WHERE rt.tenant_id = p_tenant AND rt.site_id = p_site AND rt.pms_interface_id = p_iface), false);
$$;


--
-- Name: p4_grant_paid_entitlement(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_grant_paid_entitlement(p_tenant uuid, p_site uuid, p_settlement uuid) RETURNS TABLE(entitlement_id uuid, already_granted boolean, superseded uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE se record; pu record; q record; ac record;
BEGIN
  SELECT * INTO se FROM iam_v2.settlements
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_settlement FOR UPDATE;
  IF se.id IS NULL THEN
    RAISE EXCEPTION 'GRANT_SETTLEMENT_UNKNOWN: no such settlement in this tenant and site'
      USING ERRCODE = 'no_data_found';
  END IF;
  IF se.method NOT IN ('ONLINE_PAYMENT','PMS_POSTING') THEN
    RAISE EXCEPTION 'GRANT_WRONG_RAIL: settlement method is %; this operation grants only against a card '
                    'payment or a room charge', se.method USING ERRCODE = 'check_violation';
  END IF;
  IF se.status <> 'SETTLED' THEN
    RAISE EXCEPTION 'GRANT_NOT_SETTLED: settlement is %; money is the authorization and nothing short of '
                    'SETTLED is money', se.status USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO pu FROM iam_v2.purchases
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = se.purchase_id FOR UPDATE;
  IF pu.id IS NULL THEN RAISE EXCEPTION 'GRANT_PURCHASE_UNKNOWN' USING ERRCODE = 'no_data_found'; END IF;
  IF EXISTS (SELECT 1 FROM iam_v2.entitlements WHERE purchase_id = pu.id) THEN
    RETURN QUERY SELECT e.id, true, NULL::uuid FROM iam_v2.entitlements e WHERE e.purchase_id = pu.id LIMIT 1;
    RETURN;
  END IF;
  IF pu.state NOT IN ('AWAITING_SETTLEMENT','MANUAL_REVIEW') THEN
    RAISE EXCEPTION 'GRANT_PURCHASE_STATE: a paid grant requires the purchase to be AWAITING_SETTLEMENT, '
                    'not %', pu.state USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO q  FROM iam_v2.offer_quotes
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = pu.offer_quote_id;
  SELECT * INTO ac FROM iam_v2.auth_contexts
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = pu.auth_context_id;
  IF q.id IS NULL OR ac.id IS NULL THEN
    RAISE EXCEPTION 'GRANT_EVIDENCE_MISSING: the purchase has no pinned quote or auth context'
      USING ERRCODE = 'no_data_found';
  END IF;
  IF se.method = 'PMS_POSTING' AND (pu.stay_id IS NULL OR pu.pms_interface_id IS NULL) THEN
    RAISE EXCEPTION 'GRANT_EVIDENCE_MISSING: a room charge grant needs the pinned stay and interface'
      USING ERRCODE = 'no_data_found';
  END IF;
  RETURN QUERY SELECT * FROM iam_v2.p4_entitlement_grant_kernel_v2(
    p_tenant, p_site, pu.id,
    ac.voucher_id, ac.guest_account_id, ac.guest_principal_id, ac.anonymous_subject_id,
    CASE WHEN ac.stay_id IS NOT NULL THEN pu.stay_id END,
    CASE WHEN ac.stay_id IS NOT NULL THEN pu.pms_interface_id END,
    q.grant_snapshot, (q.grant_snapshot->>'service_plan_revision_id')::uuid, pu.package_revision_id);
END $$;


--
-- Name: p4_grant_quoted_entitlement(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_grant_quoted_entitlement(p_tenant uuid, p_site uuid, p_purchase uuid) RETURNS TABLE(entitlement_id uuid, already_granted boolean, superseded uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE pu record; se record; q record; ac record;
BEGIN
  SELECT * INTO pu FROM iam_v2.purchases
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_purchase FOR UPDATE;
  IF pu.id IS NULL THEN RAISE EXCEPTION 'GRANT_PURCHASE_UNKNOWN' USING ERRCODE = 'no_data_found'; END IF;
  SELECT * INTO se FROM iam_v2.settlements
   WHERE tenant_id = p_tenant AND site_id = p_site AND purchase_id = pu.id;
  IF se.id IS NULL OR se.method <> 'NOT_REQUIRED' OR se.status <> 'NOT_REQUIRED' THEN
    RAISE EXCEPTION 'GRANT_NOT_FREE: this purchase requires settlement (% / %); a free grant is not the '
                    'right authorization for it', coalesce(se.method,'none'), coalesce(se.status,'none')
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO q  FROM iam_v2.offer_quotes
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = pu.offer_quote_id;
  SELECT * INTO ac FROM iam_v2.auth_contexts
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = pu.auth_context_id;
  IF q.id IS NULL OR ac.id IS NULL THEN
    RAISE EXCEPTION 'GRANT_EVIDENCE_MISSING: the purchase has no pinned quote or auth context'
      USING ERRCODE = 'no_data_found';
  END IF;
  IF coalesce(q.price_minor, 0) <> 0 THEN
    RAISE EXCEPTION 'GRANT_NOT_FREE: the pinned quote is priced at %; money has to arrive first',
      q.price_minor USING ERRCODE = 'check_violation';
  END IF;
  RETURN QUERY SELECT * FROM iam_v2.p4_entitlement_grant_kernel_v2(
    p_tenant, p_site, pu.id, ac.voucher_id, ac.guest_account_id, ac.guest_principal_id,
    ac.anonymous_subject_id, NULL, NULL,
    q.grant_snapshot, (q.grant_snapshot->>'service_plan_revision_id')::uuid, pu.package_revision_id);
END $$;


--
-- Name: p4_grant_voucher_entitlement(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_grant_voucher_entitlement(p_tenant uuid, p_site uuid, p_purchase uuid) RETURNS TABLE(entitlement_id uuid, already_granted boolean, superseded uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE pu record; se record; q record; ac record;
BEGIN
  SELECT * INTO pu FROM iam_v2.purchases
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_purchase FOR UPDATE;
  IF pu.id IS NULL THEN RAISE EXCEPTION 'GRANT_PURCHASE_UNKNOWN' USING ERRCODE = 'no_data_found'; END IF;
  IF pu.trigger <> 'VOUCHER_REDEMPTION' THEN
    RAISE EXCEPTION 'GRANT_WRONG_RAIL: a voucher grant needs a VOUCHER_REDEMPTION purchase, not %', pu.trigger
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO se FROM iam_v2.settlements
   WHERE tenant_id = p_tenant AND site_id = p_site AND purchase_id = pu.id;
  IF se.id IS NULL OR se.method <> 'PREPAID' OR se.status <> 'SETTLED' THEN
    RAISE EXCEPTION 'GRANT_NOT_PREPAID: settlement is % / %', coalesce(se.method,'none'), coalesce(se.status,'none')
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO q  FROM iam_v2.offer_quotes
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = pu.offer_quote_id;
  SELECT * INTO ac FROM iam_v2.auth_contexts
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = pu.auth_context_id;
  IF q.id IS NULL OR ac.id IS NULL OR ac.voucher_id IS NULL THEN
    RAISE EXCEPTION 'GRANT_EVIDENCE_MISSING: a voucher grant needs a pinned quote and a voucher auth context'
      USING ERRCODE = 'no_data_found';
  END IF;
  RETURN QUERY SELECT * FROM iam_v2.p4_entitlement_grant_kernel_v2(
    p_tenant, p_site, pu.id, ac.voucher_id, NULL, NULL, NULL, NULL, NULL,
    q.grant_snapshot, (q.grant_snapshot->>'service_plan_revision_id')::uuid, pu.package_revision_id);
END $$;


--
-- Name: p4_hold_financial_rails(uuid, uuid, bigint); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_hold_financial_rails(p_tenant uuid, p_site uuid, p_epoch bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_held int := 0; v_n int;
BEGIN
  -- THE POSTING RAIL. This is the correction: the underlying outbox rows are moved to HELD_RECOVERY, so the
  -- worker's claim predicate (state = 'QUEUED') no longer matches them. Copying them into a ledger, as 0019
  -- did, left them exactly as claimable as before.
  --
  -- FOR UPDATE serializes against a worker claiming concurrently. Whichever transaction takes the row lock
  -- first wins: if the worker wins, its IN_FLIGHT row is then held here; if recovery wins, the worker's
  -- UPDATE finds HELD_RECOVERY and the gate below refuses it. There is no interleaving in which a claim
  -- escapes.
  PERFORM 1 FROM iam_v2.posting_outbox
   WHERE tenant_id = p_tenant AND site_id = p_site AND state IN ('QUEUED','IN_FLIGHT')
   FOR UPDATE;

  INSERT INTO iam_v2.financial_recovery_holds
    (tenant_id, site_id, epoch, work_kind, work_id, held_status, amount_minor, currency)
  SELECT o.tenant_id, o.site_id, p_epoch, 'POSTING_OUTBOX', o.id, o.state, NULL, NULL
    FROM iam_v2.posting_outbox o
   WHERE o.tenant_id = p_tenant AND o.site_id = p_site AND o.state IN ('QUEUED','IN_FLIGHT')
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_held := v_held + v_n;

  UPDATE iam_v2.posting_outbox SET state = 'HELD_RECOVERY'
   WHERE tenant_id = p_tenant AND site_id = p_site AND state IN ('QUEUED','IN_FLIGHT');

  -- THE PAYMENT RAIL. A payment cannot be "moved to held" -- its status machine is the financial record --
  -- so the hold is enforced by begin_payment_execution and the recovery gate refusing to start anything.
  -- What is recorded here is the ledger entry an operator reconciles.
  INSERT INTO iam_v2.financial_recovery_holds
    (tenant_id, site_id, epoch, work_kind, work_id, held_status, amount_minor, currency)
  SELECT t.tenant_id, t.site_id, p_epoch, 'PAYMENT_TRANSACTION', t.id, t.status, t.amount_minor, t.currency
    FROM iam_v2.payment_transactions t
   WHERE t.tenant_id = p_tenant AND t.site_id = p_site AND t.status IN ('CREATED','PENDING','UNKNOWN')
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_held := v_held + v_n;

  INSERT INTO iam_v2.financial_recovery_holds
    (tenant_id, site_id, epoch, work_kind, work_id, held_status, amount_minor, currency)
  SELECT se.tenant_id, se.site_id, p_epoch, 'SETTLEMENT', se.id, se.status, NULL, NULL
    FROM iam_v2.settlements se
   WHERE se.tenant_id = p_tenant AND se.site_id = p_site
     AND se.status IN ('REQUIRED','IN_PROGRESS','MANUAL_REVIEW')
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_held := v_held + v_n;

  RETURN v_held;
END $$;


--
-- Name: p4_insert_entitlement(uuid, uuid, uuid, uuid, uuid, uuid, jsonb, uuid, uuid, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_insert_entitlement(p_tenant uuid, p_site uuid, p_voucher uuid, p_account uuid, p_principal uuid, p_purchase uuid, p_policy jsonb, p_plan_rev uuid, p_pkg_rev uuid, p_time_mode text, p_end_mode text, p_window_ends timestamp with time zone, p_supersedes uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO iam_v2.entitlements
    (tenant_id, site_id, voucher_id, guest_account_id, guest_principal_id, purchase_id,
     policy_snapshot, service_plan_revision_id, package_revision_id, time_accounting_mode,
     end_mode, window_ends_at, status, supersedes_entitlement_id, activated_at)
  VALUES (p_tenant, p_site, p_voucher, p_account, p_principal, p_purchase,
          p_policy, p_plan_rev, p_pkg_rev, p_time_mode,
          coalesce(nullif(p_end_mode,''), 'MANUAL_END'), p_window_ends, 'ACTIVE', p_supersedes, now())
  RETURNING id INTO v_id;
  PERFORM iam_v2.apply_entitlement_transition(v_id, 'ACTIVE', now(), 'GRANTED');
  RETURN v_id;
END $$;


--
-- Name: p4_interface_decommission_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_interface_decommission_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_open int;
BEGIN
  IF NEW.lifecycle_state = 'DECOMMISSIONED' AND OLD.lifecycle_state IS DISTINCT FROM 'DECOMMISSIONED' THEN
    SELECT count(*) INTO v_open
      FROM iam_v2.posting_outbox o
     WHERE o.pms_interface_id = NEW.id AND o.state IN ('QUEUED','IN_FLIGHT','HELD_RECOVERY');
    IF v_open > 0 THEN
      RAISE EXCEPTION 'DECOMMISSION_BLOCKED: interface % still has % non-terminal posting(s)', NEW.id, v_open
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT count(*) INTO v_open
      FROM iam_v2.posting_attempts a
     WHERE a.pms_interface_id = NEW.id AND a.outcome IN ('SENDING','UNKNOWN');
    IF v_open > 0 THEN
      RAISE EXCEPTION 'DECOMMISSION_BLOCKED: interface % still has % SENDING/UNKNOWN attempt(s)', NEW.id, v_open
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_interface_freshness_block(uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_interface_freshness_block(p_tenant uuid, p_site uuid, p_interface uuid, p_revision uuid, p_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE r record; hb_ms bigint; sync_ms bigint; v_age integer;
BEGIN
  SELECT * INTO r FROM iam_v2.pms_interface_runtime
   WHERE tenant_id = p_tenant AND site_id = p_site AND pms_interface_id = p_interface;
  IF NOT FOUND THEN
    RETURN 'RUNTIME_UNKNOWN';           -- no runtime state at all: fail closed, never assume healthy
  END IF;

  SELECT (config->>'heartbeat_timeout_ms')::bigint, (config->>'complete_sync_ms')::bigint
    INTO hb_ms, sync_ms
    FROM iam_v2.pms_interface_revisions
   WHERE tenant_id = p_tenant AND site_id = p_site AND pms_interface_id = p_interface AND id = p_revision;

  -- axis 1: transport -- connected, and Protel's own link-alive recently observed
  IF r.transport_status <> 'CONNECTED' THEN RETURN 'TRANSPORT_' || r.transport_status; END IF;
  IF r.last_heartbeat_at IS NULL
     OR r.last_heartbeat_at < p_at - make_interval(secs => COALESCE(hb_ms, 300000) / 1000.0) THEN
    RETURN 'TRANSPORT_HEARTBEAT_STALE';
  END IF;

  -- axis 2: continuity -- no detected gap. Silence from a healthy feed is NOT a gap.
  IF r.continuity_status <> 'CONTINUOUS' THEN RETURN 'CONTINUITY_' || r.continuity_status; END IF;

  -- axis 3: complete sync
  IF r.sync_status <> 'IN_SYNC' THEN RETURN 'SYNC_' || r.sync_status; END IF;
  IF sync_ms IS NOT NULL AND (r.last_complete_sync_at IS NULL
       OR r.last_complete_sync_at < p_at - make_interval(secs => sync_ms / 1000.0)) THEN
    RETURN 'SYNC_STALE';
  END IF;

  -- axis 3b: the financial mirror age, proven only by a successful COMPLETE resync (a live event does not reset it)
  v_age := iam_v2.p4_financial_mirror_max_age_seconds(p_tenant, p_site, p_interface);
  IF r.last_complete_sync_at IS NULL OR r.last_complete_sync_at < p_at - make_interval(secs => v_age) THEN
    RETURN 'FINANCIAL_MIRROR_STALE';
  END IF;

  -- axis 4: pin coherence
  IF r.pinned_revision_id IS DISTINCT FROM p_revision THEN RETURN 'PIN_REVISION_MISMATCH'; END IF;
  IF r.published_resync_generation <> r.resync_generation_seq THEN RETURN 'PIN_RESYNC_IN_FLIGHT'; END IF;

  RETURN NULL;
END $$;


--
-- Name: p4_lock_posting_stay(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_lock_posting_stay(p_posting uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  PERFORM 1 FROM iam_v2.stays s JOIN iam_v2.pms_postings p ON p.stay_id = s.id WHERE p.id = p_posting FOR SHARE OF s;
END $$;


--
-- Name: p4_mark_purchase_granted(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_mark_purchase_granted(p_purchase uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_state text;
BEGIN
  SELECT state INTO v_state FROM iam_v2.purchases WHERE id = p_purchase FOR UPDATE;
  IF v_state IS NULL THEN
    RAISE EXCEPTION 'PURCHASE_UNKNOWN: %', p_purchase USING ERRCODE = 'no_data_found';
  END IF;
  IF v_state NOT IN ('PENDING','AWAITING_SETTLEMENT') THEN
    RAISE EXCEPTION 'PURCHASE_STATE_TRANSITION: % -> GRANTED is not an approved transition', v_state
      USING ERRCODE = 'check_violation';
  END IF;
  UPDATE iam_v2.purchases SET state = 'GRANTED' WHERE id = p_purchase;
END $$;


--
-- Name: p4_open_dispute_review(uuid, uuid, uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_open_dispute_review(p_tenant uuid, p_site uuid, p_charge uuid, p_provider_ref text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE ch record; n int;
BEGIN
  IF p_provider_ref IS NULL OR length(p_provider_ref) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'a dispute needs the provider reference' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO ch FROM iam_v2.payment_transactions
   WHERE id = p_charge AND tenant_id = p_tenant AND site_id = p_site AND transaction_type = 'CHARGE' AND status = 'CAPTURED';
  IF NOT FOUND THEN
    RETURN 'NOT_A_CAPTURED_CHARGE';
  END IF;
  INSERT INTO iam_v2.card_reversal_reviews (tenant_id, site_id, settlement_id, charge_transaction_id, kind, provider_ref)
  VALUES (p_tenant, p_site, ch.settlement_id, p_charge, 'DISPUTE', p_provider_ref)
  ON CONFLICT (charge_transaction_id, kind, provider_ref) DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN CASE WHEN n = 1 THEN 'OPENED' ELSE 'ALREADY_OPEN' END;
END $$;


--
-- Name: p4_outbox_recovery_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_outbox_recovery_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF NEW.state = 'IN_FLIGHT' AND OLD.state <> 'IN_FLIGHT'
     AND iam_v2.p4_financial_recovery_active(NEW.tenant_id, NEW.site_id) THEN
    RAISE EXCEPTION 'FINANCIAL_RECOVERY_MODE: this site is in financial recovery; a posting may not be '
                    'claimed or transmitted until an operator has reconciled what already happened'
      USING ERRCODE = 'check_violation';
  END IF;
  -- Leaving HELD_RECOVERY has exactly two sanctioned routes, and an ordinary UPDATE is neither.
  --
  --   1. a recovery reconciliation decision, which sets the session flag below;
  --   2. the EXISTING audited retry authorization -- record_posting_review_action grants exactly one
  --      attempt and records who granted it. That is the path the contract names for making
  --      CONFIRMED_NOT_COMPLETED work retryable, so blocking it here would have replaced one gap with
  --      another: held work that can never be finished at all.
  --
  -- Route 2 is recognised structurally, from the review state, rather than by a second session flag. A flag
  -- proves a code path was taken; the authorization proves a decision was made and by whom.
  IF OLD.state = 'HELD_RECOVERY' AND NEW.state <> 'HELD_RECOVERY'
     AND coalesce(current_setting('iam_v2.p4_recovery_reconciling', true), '') <> 'on'
     AND NOT EXISTS (SELECT 1 FROM iam_v2.posting_review_state rs
                      WHERE rs.posting_id = NEW.posting_id
                        AND rs.retry_authorized_attempt_no IS NOT NULL) THEN
    RAISE EXCEPTION 'RECOVERY_HOLD_RELEASE_UNCONTROLLED: held posting work leaves HELD_RECOVERY only '
                    'through a recovery reconciliation decision or an audited retry authorization'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_payment_admission_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_payment_admission_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_status text;
BEGIN
  SELECT status INTO v_status FROM iam_v2.settlements WHERE id = NEW.settlement_id FOR UPDATE;
  IF v_status IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_SETTLEMENT_UNKNOWN: settlement % does not exist', NEW.settlement_id
      USING ERRCODE = 'no_data_found';
  END IF;
  IF v_status IN ('SETTLED','FAILED','PARTIALLY_REVERSED','REVERSED') AND NEW.transaction_type = 'CHARGE' THEN
    RAISE EXCEPTION 'PAYMENT_SETTLEMENT_CLOSED: settlement is %; it cannot admit another charge. A charge '
                    'admitted here could later be CAPTURED while the settlement stays terminal, leaving '
                    'captured money whose settlement says otherwise', v_status
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_payment_creation_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_payment_creation_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE se record; pu record; par record; v_refunded bigint;
BEGIN
  IF NEW.currency !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'PAYMENT_CURRENCY_INVALID: % is not an ISO-4217 code', NEW.currency
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.currency_exponent < 0 OR NEW.currency_exponent > 4 THEN
    RAISE EXCEPTION 'PAYMENT_EXPONENT_INVALID: %', NEW.currency_exponent USING ERRCODE = 'check_violation';
  END IF;
  -- A new financial intent starts at CREATED. Inserting one already CAPTURED would skip the whole machine.
  IF NEW.status <> 'CREATED' THEN
    RAISE EXCEPTION 'PAYMENT_MUST_START_CREATED: a payment transaction is created as CREATED, not %',
      NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.provider_txn_ref IS NOT NULL THEN
    RAISE EXCEPTION 'PAYMENT_EXTERNAL_REF_TOO_EARLY: provider_txn_ref is assigned by the provider, not at '
                    'creation' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO se FROM iam_v2.settlements
   WHERE tenant_id = NEW.tenant_id AND site_id = NEW.site_id AND id = NEW.settlement_id;
  IF se.id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_SETTLEMENT_UNKNOWN: settlement % is not in this tenant/site', NEW.settlement_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  SELECT * INTO pu FROM iam_v2.purchases
   WHERE tenant_id = NEW.tenant_id AND site_id = NEW.site_id AND id = se.purchase_id;

  IF NEW.transaction_type = 'CHARGE' THEN
    IF se.method <> 'ONLINE_PAYMENT' THEN
      RAISE EXCEPTION 'PAYMENT_WRONG_RAIL: settlement method is %; an online payment charge requires '
                      'ONLINE_PAYMENT', se.method USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.amount_minor IS DISTINCT FROM pu.amount_minor
       OR NEW.currency IS DISTINCT FROM pu.currency
       OR NEW.currency_exponent IS DISTINCT FROM pu.currency_exponent THEN
      RAISE EXCEPTION 'PAYMENT_AMOUNT_NOT_SERVER_PINNED: charge %/%/% <> pinned purchase %/%/%',
        NEW.amount_minor, NEW.currency, NEW.currency_exponent,
        pu.amount_minor, pu.currency, pu.currency_exponent USING ERRCODE = 'check_violation';
    END IF;
    -- the duplicate-charge bound is now ptx_one_live_charge_per_settlement, enforced at COMMIT
    RETURN NEW;
  END IF;

  -- REFUND / CHARGEBACK. Serialize on the parent FIRST, so the sum below cannot miss a concurrent sibling.
  PERFORM pg_advisory_xact_lock(iam_v2.ns_payment_parent(NEW.parent_transaction_id::text));

  SELECT * INTO par FROM iam_v2.payment_transactions WHERE id = NEW.parent_transaction_id;
  IF par.id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_PARENT_UNKNOWN: %', NEW.parent_transaction_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF par.transaction_type <> 'CHARGE' THEN
    RAISE EXCEPTION 'PAYMENT_PARENT_NOT_A_CHARGE: parent is %', par.transaction_type
      USING ERRCODE = 'check_violation';
  END IF;
  IF par.status <> 'CAPTURED' THEN
    RAISE EXCEPTION 'PAYMENT_PARENT_NOT_CAPTURED: parent is %; there is nothing to return', par.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF par.tenant_id <> NEW.tenant_id OR par.site_id <> NEW.site_id
     OR par.settlement_id <> NEW.settlement_id THEN
    RAISE EXCEPTION 'PAYMENT_PARENT_OUT_OF_SCOPE: the parent belongs to a different tenant/site/settlement'
      USING ERRCODE = 'check_violation';
  END IF;
  IF par.merchant_account_id <> NEW.merchant_account_id OR par.provider <> NEW.provider THEN
    RAISE EXCEPTION 'PAYMENT_PARENT_MERCHANT_MISMATCH: money returns to the account it came from'
      USING ERRCODE = 'check_violation';
  END IF;
  IF par.currency <> NEW.currency OR par.currency_exponent <> NEW.currency_exponent THEN
    RAISE EXCEPTION 'PAYMENT_PARENT_CURRENCY_MISMATCH: %/% <> %/% (no implicit FX)',
      NEW.currency, NEW.currency_exponent, par.currency, par.currency_exponent
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum(amount_minor), 0) INTO v_refunded
    FROM iam_v2.payment_transactions
   WHERE parent_transaction_id = NEW.parent_transaction_id
     AND transaction_type IN ('REFUND','CHARGEBACK')
     AND status IN ('CREATED','PENDING','CAPTURED','UNKNOWN');
  IF v_refunded + NEW.amount_minor > par.amount_minor THEN
    RAISE EXCEPTION 'PAYMENT_REFUND_EXCEEDS_CHARGE: % already returned + % requested > % captured',
      v_refunded, NEW.amount_minor, par.amount_minor USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: p4_payment_identity_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_payment_identity_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE acct record; v_converts boolean; v_parent_currency text;
BEGIN
  SELECT * INTO acct FROM iam_v2.payment_provider_accounts
   WHERE tenant_id = NEW.tenant_id AND site_id = NEW.site_id AND id = NEW.merchant_account_id;
  IF acct.id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_ACCOUNT_UNKNOWN: merchant account % is not configured for this site',
      NEW.merchant_account_id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.provider IS DISTINCT FROM acct.provider THEN
    RAISE EXCEPTION 'PAYMENT_PROVIDER_MISMATCH: the transaction says provider %, the configured account '
                    'says %. A payment must name the provider it is actually going to',
      NEW.provider, acct.provider USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.transaction_type = 'CHARGE' AND acct.status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'PAYMENT_ACCOUNT_NOT_ACTIVE: merchant account % is %; a disabled account cannot take '
                    'money', acct.id, acct.status USING ERRCODE = 'check_violation';
  END IF;
  IF acct.currency IS NOT NULL AND acct.currency <> NEW.currency THEN
    IF NEW.parent_transaction_id IS NOT NULL THEN
      -- A reversal is recorded in its charge's currency, whatever the account settles in.
      SELECT currency INTO v_parent_currency FROM iam_v2.payment_transactions WHERE id = NEW.parent_transaction_id;
      IF v_parent_currency IS NOT DISTINCT FROM NEW.currency THEN
        RETURN NEW;
      END IF;
    END IF;
    SELECT provider_converts INTO v_converts FROM iam_v2.payment_account_conversion WHERE account_id = acct.id;
    IF NEW.transaction_type = 'CHARGE' AND coalesce(v_converts, false) AND acct.provider = 'stripe' THEN
      RETURN NEW; -- presented in NEW.currency; the provider converts into acct.currency and reports it
    END IF;
    RAISE EXCEPTION 'PAYMENT_ACCOUNT_CURRENCY: account % settles in %, this payment is in %. No conversion '
                    'is performed', acct.id, acct.currency, NEW.currency USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_payment_status_machine(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_payment_status_machine() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'PAYMENT_IMMUTABLE: payment transactions are never deleted'
      USING ERRCODE = 'feature_not_supported';
  END IF;

  IF ROW(NEW.tenant_id, NEW.site_id, NEW.settlement_id, NEW.merchant_account_id, NEW.transaction_type,
         NEW.parent_transaction_id, NEW.provider, NEW.provider_ref, NEW.idempotency_key,
         NEW.amount_minor, NEW.currency, NEW.currency_exponent, NEW.intent_created_at)
     IS DISTINCT FROM
     ROW(OLD.tenant_id, OLD.site_id, OLD.settlement_id, OLD.merchant_account_id, OLD.transaction_type,
         OLD.parent_transaction_id, OLD.provider, OLD.provider_ref, OLD.idempotency_key,
         OLD.amount_minor, OLD.currency, OLD.currency_exponent, OLD.intent_created_at) THEN
    RAISE EXCEPTION 'PAYMENT_IDENTITY_IMMUTABLE: only status and the provider reference may change'
      USING ERRCODE = 'check_violation';
  END IF;

  -- (4) write-once, and a CONFLICT is an error rather than a silent discard.
  IF OLD.provider_txn_ref IS NOT NULL AND NEW.provider_txn_ref IS DISTINCT FROM OLD.provider_txn_ref THEN
    RAISE EXCEPTION 'PAYMENT_EXTERNAL_REF_CONFLICT: this intent is already pinned to provider reference '
                    '%; a different reference (%) means two provider transactions claim one intent',
      OLD.provider_txn_ref, coalesce(NEW.provider_txn_ref, '<null>') USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;
  IF OLD.status IN ('CAPTURED','FAILED','EXPIRED','CANCELLED','UNKNOWN') THEN
    RAISE EXCEPTION 'PAYMENT_STATUS_TERMINAL: % is terminal (attempted % -> %)',
      OLD.status, OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  -- §16: the ONLY edge out of CREATED is PENDING. An intent that was never attempted cannot be terminal.
  IF OLD.status = 'CREATED' AND NEW.status <> 'PENDING' THEN
    RAISE EXCEPTION 'PAYMENT_STATUS_TRANSITION: CREATED -> % is not an approved transition; the only edge '
                    'out of CREATED is PENDING (section 16)', NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status = 'PENDING' AND NEW.status NOT IN
     ('CAPTURED','FAILED','EXPIRED','CANCELLED','UNKNOWN') THEN
    RAISE EXCEPTION 'PAYMENT_STATUS_TRANSITION: PENDING -> % is not an approved transition', NEW.status
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_place_stay_posting_block(uuid, text, text, uuid, text, uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_place_stay_posting_block(p_stay uuid, p_reason text, p_source text, p_posting uuid, p_as text, p_actor uuid, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE st record;
BEGIN
  SELECT tenant_id, site_id, pms_interface_id INTO st FROM iam_v2.stays WHERE id = p_stay;
  IF st.tenant_id IS NULL THEN RETURN; END IF;
  INSERT INTO iam_v2.stay_posting_blocks
    (tenant_id, site_id, pms_interface_id, stay_id, reason, source, posting_id, pa_as_status, note, created_by)
  VALUES (st.tenant_id, st.site_id, st.pms_interface_id, p_stay, p_reason, p_source, p_posting, p_as, p_note, p_actor)
  ON CONFLICT DO NOTHING;
  PERFORM iam_v2.p4_refresh_stay_posting_permission(p_stay);
END $$;


--
-- Name: p4_posting_abort_before_send(uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_posting_abort_before_send(p_posting uuid, p_reason text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE p record; se record;
BEGIN
  SELECT * INTO p FROM iam_v2.pms_postings WHERE id = p_posting AND posting_type = 'CHARGE';
  IF p.id IS NULL THEN RAISE EXCEPTION 'POSTING_UNKNOWN' USING ERRCODE = 'no_data_found'; END IF;
  -- Only a charge that has provably never been transmitted: no attempt, or every attempt NOT_SENT.
  IF EXISTS (SELECT 1 FROM iam_v2.posting_attempts WHERE internal_posting_id = p.id AND outcome <> 'NOT_SENT') THEN
    RAISE EXCEPTION 'ABORT_AFTER_TRANSMISSION: a charge that may have reached the PMS is never aborted'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO se FROM iam_v2.settlements WHERE id = p.settlement_id FOR UPDATE;
  INSERT INTO iam_v2.posting_presend_aborts (tenant_id, site_id, posting_id, reason)
  VALUES (p.tenant_id, p.site_id, p.id, p_reason) ON CONFLICT (posting_id) DO NOTHING;
  UPDATE iam_v2.posting_outbox SET state = 'DONE' WHERE posting_id = p.id AND state IN ('QUEUED','IN_FLIGHT');
  IF se.status = 'IN_PROGRESS' THEN
    UPDATE iam_v2.settlements SET status = 'FAILED' WHERE id = se.id;
  END IF;
  RETURN 'ABORTED';
END $$;


--
-- Name: p4_posting_command_authorised(uuid, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_posting_command_authorised(p_iface uuid, p_pnum text, p_sha256 text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE a record; n int; v_outbox text; p record; st record; rdy record; v_block text;
BEGIN
  IF p_iface IS NULL OR p_pnum IS NULL OR p_pnum !~ '^[0-9]{1,18}$' OR p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$' THEN
    RETURN 'COMMAND_MALFORMED';
  END IF;
  SELECT count(*) INTO n FROM iam_v2.posting_attempts WHERE pms_interface_id = p_iface AND p_number = p_pnum;
  IF n = 0 THEN RETURN 'NO_SUCH_ATTEMPT'; END IF;
  IF n > 1 THEN RETURN 'P_NUMBER_NOT_UNIQUE'; END IF;
  SELECT * INTO a FROM iam_v2.posting_attempts x WHERE x.pms_interface_id = p_iface AND x.p_number = p_pnum;
  IF a.outcome <> 'SENDING' THEN RETURN 'ATTEMPT_NOT_SENDING'; END IF;
  IF a.ps_sha256 IS NULL OR a.ps_sha256 <> p_sha256 THEN RETURN 'COMMAND_BYTES_NOT_AUTHORISED'; END IF;
  IF a.sent_at < now() - interval '2 minutes' THEN RETURN 'ATTEMPT_TOO_OLD'; END IF;
  SELECT * INTO p FROM iam_v2.pms_postings WHERE id = a.internal_posting_id;
  IF p.posting_type IS DISTINCT FROM 'CHARGE' THEN RETURN 'NOT_A_CHARGE'; END IF;
  SELECT o.state INTO v_outbox FROM iam_v2.posting_outbox o WHERE o.posting_id = a.internal_posting_id;
  IF v_outbox IS DISTINCT FROM 'IN_FLIGHT' THEN RETURN 'POSTING_NOT_IN_FLIGHT'; END IF;
  SELECT * INTO rdy FROM iam_v2.pms_interface_financially_ready(a.tenant_id, a.site_id, p_iface);
  IF NOT COALESCE(rdy.ready, false) THEN RETURN 'INTERFACE_NOT_FINANCIALLY_READY'; END IF;
  -- The reservation the charge targets, as the database knows it NOW (Amendment A1, rule 7).
  SELECT status, posting_allowed, external_reservation_id, normalized_room_number INTO st
    FROM iam_v2.stays WHERE id = p.stay_id;
  IF st.external_reservation_id IS NULL OR st.external_reservation_id IS DISTINCT FROM a.g_number
     OR p.g_number IS DISTINCT FROM a.g_number THEN
    RETURN 'RESERVATION_MISMATCH';
  END IF;
  IF NOT COALESCE(iam_v2.p4_stay_postable_for(p.stay_id, p.id), false) THEN RETURN 'STAY_NOT_POSTABLE'; END IF;
  IF st.normalized_room_number IS NULL OR st.normalized_room_number IS DISTINCT FROM a.rn THEN RETURN 'ROOM_CHANGED'; END IF;
  v_block := iam_v2.p4_interface_freshness_block(a.tenant_id, a.site_id, p_iface, p.posting_interface_revision_id, now());
  IF v_block IS NOT NULL THEN RETURN 'INTERFACE_NOT_FRESH'; END IF;
  RETURN 'AUTHORISED';
END $_$;


--
-- Name: p4_posting_currency_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_posting_currency_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  v_if_cur char(3); v_if_exp smallint;
  v_pu_cur char(3); v_pu_exp smallint; v_pkg uuid;
  v_pk_cur char(3); v_pk_exp smallint;
BEGIN
  -- (1) the posting must state its own money explicitly. mg7 left both columns nullable.
  IF NEW.currency IS NULL OR NEW.currency_exponent IS NULL THEN
    RAISE EXCEPTION 'POSTING_CURRENCY_UNSET: posting % states no currency/exponent', NEW.id
      USING ERRCODE = 'check_violation';
  END IF;

  -- (2) the PINNED interface revision must be financially onboarded. Note the lookup is composite-pinned:
  -- a revision belonging to another tenant/site/interface simply does not resolve, and NULL fails closed.
  SELECT financial_base_currency, financial_base_currency_exponent
    INTO v_if_cur, v_if_exp
    FROM iam_v2.pms_interface_revisions
   WHERE tenant_id = NEW.tenant_id AND site_id = NEW.site_id
     AND pms_interface_id = NEW.pms_interface_id AND id = NEW.posting_interface_revision_id;
  IF v_if_cur IS NULL THEN
    RAISE EXCEPTION 'INTERFACE_CURRENCY_NOT_ONBOARDED: interface % revision % has no financial base currency',
      NEW.pms_interface_id, NEW.posting_interface_revision_id USING ERRCODE = 'check_violation';
  END IF;

  -- (3) posting currency must EQUAL the pinned interface currency, exponent included. Not convertible-to.
  IF NEW.currency <> v_if_cur OR NEW.currency_exponent IS DISTINCT FROM v_if_exp THEN
    RAISE EXCEPTION 'POSTING_CURRENCY_MISMATCH: posting %/% <> pinned interface %/% (no implicit FX)',
      NEW.currency, NEW.currency_exponent, v_if_cur, v_if_exp USING ERRCODE = 'check_violation';
  END IF;

  -- (4) the pinned Purchase must be in the same currency.
  SELECT currency, currency_exponent, package_revision_id
    INTO v_pu_cur, v_pu_exp, v_pkg
    FROM iam_v2.purchases
   WHERE tenant_id = NEW.tenant_id AND site_id = NEW.site_id AND id = NEW.purchase_id;
  IF v_pu_cur IS NULL OR v_pu_exp IS NULL THEN
    RAISE EXCEPTION 'PURCHASE_CURRENCY_UNSET: purchase % states no currency/exponent', NEW.purchase_id
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_pu_cur <> v_if_cur OR v_pu_exp IS DISTINCT FROM v_if_exp THEN
    RAISE EXCEPTION 'PURCHASE_CURRENCY_MISMATCH: purchase %/% <> pinned interface %/% (no implicit FX)',
      v_pu_cur, v_pu_exp, v_if_cur, v_if_exp USING ERRCODE = 'check_violation';
  END IF;

  -- (5) and so must the pinned Package Revision — this is the contract's "Package currency must equal the
  -- pinned PMS Interface currency" requirement, now that there is an interface currency to compare against.
  SELECT currency, currency_exponent INTO v_pk_cur, v_pk_exp
    FROM iam_v2.internet_package_revisions
   WHERE tenant_id = NEW.tenant_id AND site_id = NEW.site_id AND id = v_pkg;
  IF v_pk_cur IS NULL OR v_pk_exp IS NULL THEN
    RAISE EXCEPTION 'PACKAGE_CURRENCY_UNSET: package revision % states no currency/exponent', v_pkg
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_pk_cur <> v_if_cur OR v_pk_exp IS DISTINCT FROM v_if_exp THEN
    RAISE EXCEPTION 'PACKAGE_CURRENCY_MISMATCH: package %/% <> pinned interface %/% (no implicit FX)',
      v_pk_cur, v_pk_exp, v_if_cur, v_if_exp USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: p4_posting_freshness_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_posting_freshness_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_block text;
BEGIN
  IF NEW.posting_type = 'REVERSAL' THEN
    RETURN NEW;                       -- passive ledger row; it will never reach a wire
  END IF;
  v_block := iam_v2.p4_interface_freshness_block(
    NEW.tenant_id, NEW.site_id, NEW.pms_interface_id, NEW.posting_interface_revision_id, now());
  IF v_block IS NOT NULL THEN
    RAISE EXCEPTION 'INTERFACE_NOT_FRESH: %', v_block USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_posting_lifecycle_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_posting_lifecycle_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_state text;
BEGIN
  SELECT lifecycle_state INTO v_state FROM iam_v2.pms_interfaces
   WHERE tenant_id = NEW.tenant_id AND site_id = NEW.site_id AND id = NEW.pms_interface_id;
  IF v_state IS NULL THEN
    RAISE EXCEPTION 'INTERFACE_UNKNOWN: no interface % in tenant/site', NEW.pms_interface_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF NEW.posting_type = 'REVERSAL' THEN
    RETURN NEW;                       -- an audit record, not new financial work
  END IF;
  IF v_state IN ('DRAINING','DECOMMISSIONED') THEN
    RAISE EXCEPTION 'INTERFACE_NOT_ACCEPTING_WORK: interface % is %; no new financial work may be created',
      NEW.pms_interface_id, v_state USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_posting_review_apply(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_posting_review_apply(p_tenant uuid, p_site uuid, p_posting uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE p record; se record; rs record; v_ent uuid;
BEGIN
  SELECT * INTO p FROM iam_v2.pms_postings WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_posting AND posting_type = 'CHARGE';
  IF p.id IS NULL THEN RAISE EXCEPTION 'POSTING_UNKNOWN' USING ERRCODE = 'no_data_found'; END IF;
  SELECT * INTO rs FROM iam_v2.posting_review_state WHERE posting_id = p.id;
  IF rs.terminal_action IS NULL THEN RETURN 'NO_DECISION'; END IF;
  SELECT * INTO se FROM iam_v2.settlements WHERE id = p.settlement_id FOR UPDATE;
  IF rs.terminal_action = 'CONFIRM_NOT_POSTED_RETRY' THEN
    -- Still unresolved: the POSTING_UNRESOLVED block stays until the authorised attempt concludes.
    UPDATE iam_v2.posting_outbox SET state = 'QUEUED'
     WHERE posting_id = p.id AND state = 'HELD_RECOVERY' AND rs.retry_authorized_attempt_no IS NOT NULL
       AND rs.retry_authorization_consumed_at IS NULL;
    RETURN 'REQUEUED';
  END IF;
  IF se.method <> 'PMS_POSTING' THEN RETURN 'NOT_A_ROOM_CHARGE'; END IF;
  IF rs.terminal_action = 'CONFIRM_POSTED' THEN
    IF se.status IN ('IN_PROGRESS','MANUAL_REVIEW') THEN
      UPDATE iam_v2.settlements SET status = 'SETTLED' WHERE id = se.id;
    END IF;
    IF (SELECT status FROM iam_v2.settlements WHERE id = se.id) = 'SETTLED' THEN
      PERFORM iam_v2.p4_clear_posting_unresolved(p.id);
      SELECT entitlement_id INTO v_ent FROM iam_v2.p4_grant_paid_entitlement(p.tenant_id, p.site_id, se.id);
      RETURN 'GRANTED';
    END IF;
    RETURN 'NOT_SETTLED';
  END IF;
  IF rs.terminal_action = 'CONFIRM_NOT_POSTED_ABANDON' THEN
    IF se.status IN ('IN_PROGRESS','MANUAL_REVIEW') THEN
      UPDATE iam_v2.settlements SET status = 'FAILED' WHERE id = se.id;
    END IF;
    PERFORM iam_v2.p4_clear_posting_unresolved(p.id);
    RETURN 'FAILED';
  END IF;
  RETURN 'NO_EFFECT';
END $$;


--
-- Name: p4_posting_settlement_outcome(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_posting_settlement_outcome(p_posting uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE p record; se record; a record; v_target text; v_effect text; v_ent uuid;
BEGIN
  SELECT * INTO p FROM iam_v2.pms_postings WHERE id = p_posting AND posting_type = 'CHARGE';
  IF p.id IS NULL THEN RAISE EXCEPTION 'POSTING_UNKNOWN' USING ERRCODE = 'no_data_found'; END IF;
  SELECT * INTO se FROM iam_v2.settlements WHERE id = p.settlement_id FOR UPDATE;
  IF se.method <> 'PMS_POSTING' THEN RETURN 'NOT_A_ROOM_CHARGE'; END IF;
  SELECT * INTO a FROM iam_v2.posting_attempts WHERE internal_posting_id = p.id ORDER BY attempt_no DESC LIMIT 1;
  IF a.id IS NULL THEN RETURN 'NO_ATTEMPT'; END IF;
  IF a.outcome = 'ACKED' THEN
    v_effect := iam_v2.p4_answer_effect(p.pms_interface_id, a.pa_as_status);
  END IF;
  IF a.outcome = 'ACKED' AND v_effect = 'POSTED' THEN
    v_target := 'SETTLED';
  ELSIF a.outcome = 'ACKED' AND v_effect LIKE 'NOT_POSTED_%' THEN
    v_target := 'FAILED';
  ELSIF a.outcome = 'UNKNOWN' OR (a.outcome = 'ACKED' AND v_effect = 'UNPROVEN') THEN
    v_target := 'MANUAL_REVIEW';
  ELSE
    RETURN 'NOT_CONCLUSIVE';
  END IF;
  IF se.status = v_target OR se.status IN ('FAILED','PARTIALLY_REVERSED','REVERSED') THEN
    NULL;
  ELSIF se.status IN ('IN_PROGRESS','MANUAL_REVIEW') THEN
    IF NOT (se.status = 'MANUAL_REVIEW' AND v_target = 'MANUAL_REVIEW') THEN
      UPDATE iam_v2.settlements SET status = v_target WHERE id = se.id;
    END IF;
  ELSE
    RAISE EXCEPTION 'POSTING_SETTLEMENT_STATE: settlement is %', se.status USING ERRCODE = 'check_violation';
  END IF;
  -- The stay effect of the answer (contract section 9a rule 9).
  IF v_target = 'MANUAL_REVIEW' THEN
    PERFORM iam_v2.p4_place_stay_posting_block(p.stay_id, 'POSTING_UNRESOLVED', 'POSTING_LEDGER', p.id, NULL, NULL, NULL);
    RETURN v_target;
  END IF;
  PERFORM iam_v2.p4_clear_posting_unresolved(p.id);
  IF v_effect = 'NOT_POSTED_NO_POST' THEN
    PERFORM iam_v2.p4_place_stay_posting_block(p.stay_id, 'PMS_NO_POST', 'PMS_ANSWER', NULL, a.pa_as_status, NULL, NULL);
  ELSIF v_effect = 'NOT_POSTED_TARGET_INVALID' THEN
    PERFORM iam_v2.p4_place_stay_posting_block(p.stay_id, 'PMS_DATA_SUSPECT', 'PMS_ANSWER', NULL, a.pa_as_status, NULL, NULL);
    PERFORM iam_v2.request_full_resync(p.tenant_id, p.site_id, p.pms_interface_id, 'PMS_ANSWER_TARGET_INVALID');
  END IF;
  IF v_target = 'SETTLED' THEN
    SELECT entitlement_id INTO v_ent FROM iam_v2.p4_grant_paid_entitlement(p.tenant_id, p.site_id, se.id);
    RETURN 'GRANTED';
  END IF;
  RETURN v_target;
END $$;


--
-- Name: p4_purchase_follows_settlement(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_purchase_follows_settlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;
  IF NEW.status = 'FAILED' THEN
    UPDATE iam_v2.purchases SET state = 'FAILED'
     WHERE id = NEW.purchase_id AND state IN ('PENDING','AWAITING_SETTLEMENT','MANUAL_REVIEW');
  ELSIF NEW.status = 'MANUAL_REVIEW' THEN
    UPDATE iam_v2.purchases SET state = 'MANUAL_REVIEW'
     WHERE id = NEW.purchase_id AND state IN ('PENDING','AWAITING_SETTLEMENT');
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_reconcile_financial_epoch(uuid, uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_reconcile_financial_epoch(p_tenant uuid, p_site uuid, p_system_identity text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE cur record; v_epoch bigint;
BEGIN
  IF p_system_identity IS NULL OR btrim(p_system_identity) = '' THEN
    RAISE EXCEPTION 'RECOVERY_IDENTITY_REQUIRED: restore detection needs the running system identity'
      USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('p4.epoch:' || p_tenant::text || ':' || p_site::text));
  SELECT * INTO cur FROM iam_v2.financial_epochs
   WHERE tenant_id = p_tenant AND site_id = p_site ORDER BY epoch DESC LIMIT 1;

  IF cur.epoch IS NULL THEN
    INSERT INTO iam_v2.financial_epochs (tenant_id, site_id, epoch, system_identity, reason, released_at)
    VALUES (p_tenant, p_site, 1, p_system_identity, 'INITIAL', now());
    RETURN 'INITIALIZED';
  END IF;
  IF cur.system_identity = p_system_identity THEN
    RETURN CASE WHEN cur.released_at IS NULL THEN 'RECOVERY_ACTIVE' ELSE 'UNCHANGED' END;
  END IF;
  IF cur.released_at IS NULL THEN
    UPDATE iam_v2.financial_epochs SET system_identity = p_system_identity
     WHERE tenant_id = p_tenant AND site_id = p_site AND epoch = cur.epoch;
    PERFORM iam_v2.p4_hold_financial_rails(p_tenant, p_site, cur.epoch);
    RETURN 'RECOVERY_ACTIVE';
  END IF;

  v_epoch := cur.epoch + 1;
  INSERT INTO iam_v2.financial_epochs (tenant_id, site_id, epoch, system_identity, reason)
  VALUES (p_tenant, p_site, v_epoch, p_system_identity, 'RESTORE_DETECTED');
  PERFORM iam_v2.p4_hold_financial_rails(p_tenant, p_site, v_epoch);
  RETURN 'RECOVERY_ENTERED';
END $$;


--
-- Name: p4_reconcile_financial_epoch_v2(uuid, uuid, text, bigint, boolean); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_reconcile_financial_epoch_v2(p_tenant uuid, p_site uuid, p_system_identity text, p_marker_generation bigint, p_marker_present boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE cur record; v_epoch bigint; v_reason text := NULL; v_detect text; v_gen bigint;
BEGIN
  IF p_system_identity IS NULL OR btrim(p_system_identity) = '' THEN
    RAISE EXCEPTION 'RECOVERY_IDENTITY_REQUIRED' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('p4.epoch:' || p_tenant::text || ':' || p_site::text));
  SELECT * INTO cur FROM iam_v2.financial_epochs
   WHERE tenant_id = p_tenant AND site_id = p_site ORDER BY epoch DESC LIMIT 1;
  v_gen := CASE WHEN p_marker_present THEN p_marker_generation ELSE 0 END;

  IF cur.epoch IS NULL THEN
    INSERT INTO iam_v2.financial_epochs
      (tenant_id, site_id, epoch, system_identity, reason, released_at, restore_generation)
    VALUES (p_tenant, p_site, 1, p_system_identity, 'INITIAL', now(), v_gen);
    RETURN 'INITIALIZED';
  END IF;

  IF p_marker_present AND p_marker_generation > cur.restore_generation THEN
    -- The database is OLDER than the appliance knows it should be: a restore happened.
    v_reason := 'MARKER_AHEAD'; v_detect := 'MANAGEMENT_MARKER';
  ELSIF p_marker_present AND p_marker_generation < cur.restore_generation THEN
    -- The MARKER is older than the database. The management partition was rolled back -- which the
    -- documented runbook can do all by itself, because it backs up /etc/stayconnect as a tar and restoring
    -- an old one carries an old marker with it.
    --
    -- Held, not ignored. The two records disagree about how many times this site has been restored, and
    -- until someone establishes which is right, nobody can say whether the financial data is current. A
    -- disagreement is exactly as much reason to stop as a detected rollback.
    v_reason := 'MARKER_BEHIND'; v_detect := 'MANAGEMENT_MARKER';
  ELSIF cur.system_identity <> p_system_identity THEN
    v_reason := 'IDENTITY_CHANGED'; v_detect := 'SYSTEM_IDENTITY';
  ELSIF cur.restore_generation > 0 AND NOT p_marker_present THEN
    v_reason := 'MARKER_MISSING'; v_detect := 'MANAGEMENT_MARKER';
  END IF;

  IF v_reason IS NULL THEN
    RETURN CASE WHEN cur.released_at IS NULL THEN 'RECOVERY_ACTIVE' ELSE 'UNCHANGED' END;
  END IF;

  IF cur.released_at IS NULL THEN
    UPDATE iam_v2.financial_epochs
       SET system_identity = p_system_identity,
           restore_generation = greatest(cur.restore_generation, v_gen)
     WHERE tenant_id = p_tenant AND site_id = p_site AND epoch = cur.epoch;
    PERFORM iam_v2.p4_hold_financial_rails(p_tenant, p_site, cur.epoch);
    RETURN 'RECOVERY_ACTIVE';
  END IF;

  v_epoch := cur.epoch + 1;
  INSERT INTO iam_v2.financial_epochs
    (tenant_id, site_id, epoch, system_identity, reason, restore_generation)
  VALUES (p_tenant, p_site, v_epoch, p_system_identity, 'RESTORE_DETECTED',
          greatest(cur.restore_generation, v_gen));
  INSERT INTO iam_v2.financial_restore_events
    (tenant_id, site_id, restore_generation, manifest_sha256, restore_kind, detected_by, restored_by)
  VALUES (p_tenant, p_site, greatest(cur.restore_generation, v_gen), repeat('0', 64),
          'UNSUPPORTED_RAW_SNAPSHOT', v_detect, v_reason)
  ON CONFLICT DO NOTHING;
  PERFORM iam_v2.p4_hold_financial_rails(p_tenant, p_site, v_epoch);
  RETURN 'RECOVERY_ENTERED';
END $$;


--
-- Name: p4_record_compliance_archive(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_record_compliance_archive(p_tenant uuid, p_site uuid, p_manifest_sha text, p_artifact_path text, p_row_counts jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE v_id uuid;
BEGIN
  IF p_manifest_sha IS NULL OR p_manifest_sha !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'ARCHIVE_DIGEST_REQUIRED: a compliance archive is identified by the digest of the '
                    'artefact actually written' USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO iam_v2.compliance_archives
    (tenant_id, site_id, manifest_sha256, receipt_verified, purpose, artifact_path, row_counts,
     receipt_blocked_reason)
  VALUES (p_tenant, p_site, p_manifest_sha, false, 'CROSS_CUSTOMER_PURGE', p_artifact_path,
          coalesce(p_row_counts, '{}'::jsonb),
          'No external archival receipt authority exists in this product; the artefact and its digest are '
          'recorded, the counter-signature is not available')
  RETURNING id INTO v_id;
  RETURN v_id;
END $_$;


--
-- Name: p4_record_compliance_receipt(uuid, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_record_compliance_receipt(p_archive uuid, p_authority text, p_reference text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE a record;
BEGIN
  IF p_authority IS NULL OR btrim(p_authority) = '' OR p_reference IS NULL OR btrim(p_reference) = '' THEN
    RAISE EXCEPTION 'COMPLIANCE_RECEIPT_EVIDENCE_REQUIRED: a verified receipt names the authority that '
                    'acknowledged custody and its reference' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO a FROM iam_v2.compliance_archives WHERE id = p_archive FOR UPDATE;
  IF a.id IS NULL THEN
    RAISE EXCEPTION 'COMPLIANCE_ARCHIVE_UNKNOWN: %', p_archive USING ERRCODE = 'no_data_found';
  END IF;
  IF a.receipt_verified THEN
    RAISE EXCEPTION 'COMPLIANCE_RECEIPT_ALREADY_RECORDED: custody was already acknowledged by % at %',
      a.receipt_authority, a.receipt_verified_at USING ERRCODE = 'check_violation';
  END IF;
  UPDATE iam_v2.compliance_archives
     SET receipt_verified = true, receipt_authority = p_authority, receipt_reference = p_reference,
         receipt_verified_at = now(), receipt_blocked_reason = NULL
   WHERE id = p_archive;
END $$;


--
-- Name: p4_record_provider_reversal(uuid, uuid, uuid, text, bigint, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_record_provider_reversal(p_tenant uuid, p_site uuid, p_parent uuid, p_kind text, p_amount_minor bigint, p_provider_event_id text, p_provider_txn_ref text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE par record; v_key text; v_ref text; v_id uuid; v_result text;
BEGIN
  IF p_kind NOT IN ('REFUND','CHARGEBACK') THEN
    RAISE EXCEPTION 'REVERSAL_KIND: %', p_kind USING ERRCODE = 'check_violation';
  END IF;
  IF p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
    RAISE EXCEPTION 'REVERSAL_AMOUNT: must be positive' USING ERRCODE = 'check_violation';
  END IF;
  IF p_provider_event_id IS NULL OR btrim(p_provider_event_id) = '' THEN
    RAISE EXCEPTION 'REVERSAL_EVENT_ID: the provider event id is the deduplication key' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO par FROM iam_v2.payment_transactions
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_parent AND transaction_type = 'CHARGE' FOR UPDATE;
  IF par.id IS NULL OR par.status <> 'CAPTURED' THEN
    RAISE EXCEPTION 'REVERSAL_PARENT: a reversal belongs to a captured charge' USING ERRCODE = 'check_violation';
  END IF;
  v_key := left('provider-reversal:' || p_provider_event_id, 200);
  IF EXISTS (SELECT 1 FROM iam_v2.payment_transactions WHERE tenant_id = p_tenant AND idempotency_key = v_key) THEN
    RETURN 'DUPLICATE';
  END IF;
  v_ref := left('rev_' || md5(v_key), 200);
  INSERT INTO iam_v2.payment_transactions
    (tenant_id, site_id, settlement_id, merchant_account_id, transaction_type, parent_transaction_id,
     provider, provider_ref, idempotency_key, amount_minor, currency, currency_exponent, status)
  VALUES (p_tenant, p_site, par.settlement_id, par.merchant_account_id, p_kind, par.id,
          par.provider, v_ref, v_key, p_amount_minor, par.currency, par.currency_exponent, 'CREATED')
  RETURNING id INTO v_id;
  UPDATE iam_v2.payment_transactions SET status = 'PENDING' WHERE id = v_id;
  SELECT iam_v2.apply_payment_callback_v2(p_tenant, par.provider, par.merchant_account_id, v_ref,
           left(p_provider_event_id, 200), p_kind, 'CAPTURED', left('evt:' || p_provider_event_id, 200),
           jsonb_build_object('provider_status','CAPTURED','provider_message','provider-reported ' || lower(p_kind)))
    INTO v_result;
  RETURN v_result;
END $$;


--
-- Name: p4_record_settlement_report(uuid, uuid, uuid, text, bigint, text, bigint, bigint, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_record_settlement_report(p_tenant uuid, p_site uuid, p_transaction uuid, p_settlement_currency text, p_settlement_amount bigint, p_exchange_rate text, p_fee bigint, p_net bigint, p_balance_ref text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE t record; v_status text; v_converted boolean;
BEGIN
  SELECT * INTO t FROM iam_v2.payment_transactions
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_transaction AND transaction_type = 'CHARGE';
  IF t.id IS NULL OR t.status <> 'CAPTURED' THEN
    RAISE EXCEPTION 'SETTLEMENT_REPORT_PARENT: a settlement report belongs to a captured charge' USING ERRCODE = 'check_violation';
  END IF;
  v_status := CASE WHEN p_settlement_currency IS NULL OR p_settlement_amount IS NULL THEN 'NOT_REPORTED' ELSE 'REPORTED' END;
  v_converted := v_status = 'REPORTED' AND upper(p_settlement_currency) <> t.currency;
  INSERT INTO iam_v2.payment_settlement_reports
    (transaction_id, tenant_id, site_id, presentment_currency, presentment_amount_minor, settlement_currency,
     settlement_amount_minor, exchange_rate, fee_minor, net_minor, provider_balance_ref, converted, report_status)
  VALUES (t.id, p_tenant, p_site, t.currency, t.amount_minor, upper(p_settlement_currency), p_settlement_amount,
          NULLIF(btrim(coalesce(p_exchange_rate,'')),''), p_fee, p_net, NULLIF(btrim(coalesce(p_balance_ref,'')),''),
          v_converted, v_status)
  ON CONFLICT (transaction_id) DO NOTHING;
  RETURN v_status;
END $$;


--
-- Name: p4_record_supported_restore(uuid, uuid, bigint, text, timestamp with time zone, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_record_supported_restore(p_tenant uuid, p_site uuid, p_generation bigint, p_manifest_sha text, p_backup_taken_at timestamp with time zone, p_restored_by text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE cur record; v_epoch bigint;
BEGIN
  IF p_manifest_sha IS NULL OR p_manifest_sha !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'RESTORE_MANIFEST_REQUIRED: a supported restore is identified by its verified manifest '
                    'digest' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('p4.epoch:' || p_tenant::text || ':' || p_site::text));
  SELECT * INTO cur FROM iam_v2.financial_epochs
   WHERE tenant_id = p_tenant AND site_id = p_site ORDER BY epoch DESC LIMIT 1;
  IF cur.epoch IS NOT NULL AND p_generation <= cur.restore_generation THEN
    RAISE EXCEPTION 'RESTORE_GENERATION_NOT_ADVANCED: the database already records generation %; a restore '
                    'must advance it', cur.restore_generation USING ERRCODE = 'check_violation';
  END IF;

  v_epoch := coalesce(cur.epoch, 0) + 1;
  IF cur.epoch IS NOT NULL AND cur.released_at IS NULL THEN
    v_epoch := cur.epoch;  -- already held; a restore during recovery does not open a second epoch
    UPDATE iam_v2.financial_epochs SET restore_generation = p_generation
     WHERE tenant_id = p_tenant AND site_id = p_site AND epoch = v_epoch;
  ELSE
    INSERT INTO iam_v2.financial_epochs
      (tenant_id, site_id, epoch, system_identity, reason, restore_generation)
    VALUES (p_tenant, p_site, v_epoch, coalesce(cur.system_identity, 'restored'),
            'RESTORE_DETECTED', p_generation);
  END IF;

  INSERT INTO iam_v2.financial_restore_events
    (tenant_id, site_id, restore_generation, manifest_sha256, backup_taken_at, restored_by,
     restore_kind, detected_by)
  VALUES (p_tenant, p_site, p_generation, p_manifest_sha, p_backup_taken_at, p_restored_by,
          'SUPPORTED', 'RESTORE_TOOL')
  ON CONFLICT DO NOTHING;

  PERFORM iam_v2.p4_hold_financial_rails(p_tenant, p_site, v_epoch);
  RETURN v_epoch;
END $_$;


--
-- Name: p4_recovery_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_recovery_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF iam_v2.p4_financial_recovery_active(NEW.tenant_id, NEW.site_id) THEN
    RAISE EXCEPTION 'FINANCIAL_RECOVERY_MODE: this site is in financial recovery after a restore or an '
                    'operator declaration. New financial work is held until an operator has reconciled '
                    'what already happened. Guest access is unaffected'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_recovery_hold_immutable(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_recovery_hold_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'RECOVERY_HOLD_IMMUTABLE: a recovery hold is never deleted; it is resolved'
      USING ERRCODE = 'feature_not_supported';
  END IF;
  IF OLD.resolution IS NOT NULL THEN
    RAISE EXCEPTION 'RECOVERY_HOLD_ALREADY_RESOLVED: this hold was resolved as % at %; a conclusion about '
                    'money is not revised in place', OLD.resolution, OLD.resolved_at
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.work_kind, NEW.work_id, NEW.epoch, NEW.held_status) IS DISTINCT FROM
     (OLD.work_kind, OLD.work_id, OLD.epoch, OLD.held_status) THEN
    RAISE EXCEPTION 'RECOVERY_HOLD_IMMUTABLE: what was held cannot be rewritten'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_refresh_stay_posting_permission(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_refresh_stay_posting_permission(p_stay uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE st record; b record; v_allowed boolean; v_reason text; v_source text;
BEGIN
  SELECT id, status, external_reservation_id, posting_allowed, posting_block_reason, posting_permission_source
    INTO st FROM iam_v2.stays WHERE id = p_stay;
  IF st.id IS NULL THEN RETURN false; END IF;
  SELECT reason, source INTO b FROM iam_v2.stay_posting_blocks
   WHERE stay_id = p_stay AND cleared_at IS NULL
   ORDER BY CASE reason WHEN 'POSTING_UNRESOLVED' THEN 1 WHEN 'PMS_NO_POST' THEN 2
                        WHEN 'PMS_DATA_SUSPECT' THEN 3 ELSE 4 END, created_at
   LIMIT 1;
  IF st.status <> 'IN_HOUSE' THEN
    v_allowed := false; v_reason := 'NOT_IN_HOUSE'; v_source := 'PMS_FEED';
  ELSIF st.external_reservation_id IS NULL OR btrim(st.external_reservation_id) = '' THEN
    v_allowed := false; v_reason := 'NO_RESERVATION'; v_source := 'PMS_FEED';
  ELSIF b.reason IS NOT NULL THEN
    v_allowed := false; v_reason := b.reason; v_source := b.source;
  ELSE
    v_allowed := true; v_reason := NULL; v_source := 'PMS_FEED';
  END IF;
  IF st.posting_allowed IS DISTINCT FROM v_allowed OR st.posting_block_reason IS DISTINCT FROM v_reason
     OR st.posting_permission_source IS DISTINCT FROM v_source THEN
    UPDATE iam_v2.stays
       SET posting_allowed = v_allowed, posting_block_reason = v_reason,
           posting_permission_source = v_source, posting_checked_at = now()
     WHERE id = p_stay;
  END IF;
  RETURN v_allowed;
END $$;


--
-- Name: p4_release_financial_recovery(uuid, uuid, uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_release_financial_recovery(p_tenant uuid, p_site uuid, p_actor uuid, p_note text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE cur record; v_open int; v_sendable int; v_live int; v_inprog int;
BEGIN
  PERFORM iam_v2.p4_assert_financial_actor(p_tenant, p_actor);
  IF p_note IS NULL OR length(btrim(p_note)) < 10 THEN
    RAISE EXCEPTION 'RECOVERY_NOTE_REQUIRED: releasing recovery records why it is safe to resume'
      USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('p4.epoch:' || p_tenant::text || ':' || p_site::text));
  SELECT * INTO cur FROM iam_v2.financial_epochs
   WHERE tenant_id = p_tenant AND site_id = p_site AND released_at IS NULL;
  IF cur.epoch IS NULL THEN
    RAISE EXCEPTION 'RECOVERY_NOT_ACTIVE: this site is not in financial recovery'
      USING ERRCODE = 'no_data_found';
  END IF;

  SELECT count(*) INTO v_open FROM iam_v2.financial_recovery_holds
   WHERE tenant_id = p_tenant AND site_id = p_site AND epoch = cur.epoch AND resolution IS NULL;
  IF v_open > 0 THEN
    RAISE EXCEPTION 'RECOVERY_HOLDS_UNRESOLVED: % held item(s) have not been reconciled', v_open
      USING ERRCODE = 'check_violation';
  END IF;

  -- The check that a resolution count cannot give. A conclusion is a claim ABOUT a record; this asks the
  -- records themselves whether anything is still sendable or still in flight.
  -- Sendable work is only unsafe when nobody has accounted for it. A posting made sendable by the audited
  -- zero-attempt authorization (0025) is the opposite of unaccounted for: an operator established that the
  -- folio was never charged and authorized exactly one attempt, which is the whole point of that path.
  -- Refusing release for it would mean the one safe route out of a zero-attempt restore could never be
  -- completed -- two correct rules cancelling each other out.
  SELECT count(*) INTO v_sendable FROM iam_v2.posting_outbox o
   WHERE o.tenant_id = p_tenant AND o.site_id = p_site AND o.state IN ('QUEUED','IN_FLIGHT')
     AND NOT EXISTS (SELECT 1 FROM iam_v2.posting_review_state rs
                      WHERE rs.posting_id = o.posting_id
                        AND rs.retry_authorized_attempt_no IS NOT NULL);
  IF v_sendable > 0 THEN
    RAISE EXCEPTION 'RECOVERY_STATE_UNSAFE: % posting(s) are still sendable. Every hold may be resolved '
                    'and the underlying command still be waiting to go out', v_sendable
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT count(*) INTO v_live FROM iam_v2.payment_transactions
   WHERE tenant_id = p_tenant AND site_id = p_site AND status IN ('CREATED','PENDING');
  IF v_live > 0 THEN
    RAISE EXCEPTION 'RECOVERY_STATE_UNSAFE: % payment(s) are still live', v_live
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT count(*) INTO v_inprog FROM iam_v2.settlements
   WHERE tenant_id = p_tenant AND site_id = p_site AND status = 'IN_PROGRESS';
  IF v_inprog > 0 THEN
    RAISE EXCEPTION 'RECOVERY_STATE_UNSAFE: % settlement(s) are still IN_PROGRESS', v_inprog
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE iam_v2.financial_epochs
     SET released_at = now(), released_by = p_actor, release_note = p_note
   WHERE tenant_id = p_tenant AND site_id = p_site AND epoch = cur.epoch;
  RETURN cur.epoch;
END $$;


--
-- Name: p4_resolve_payment_account(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_resolve_payment_account(p_tenant uuid, p_site uuid) RETURNS TABLE(account_id uuid, provider text, merchant_account_ref text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE acct record;
BEGIN
  SELECT * INTO acct FROM iam_v2.payment_provider_accounts
   WHERE tenant_id = p_tenant AND site_id = p_site AND status = 'ACTIVE' AND is_default
   LIMIT 1;
  IF acct.id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_NO_CONFIGURED_ACCOUNT: this site has no ACTIVE default payment account; '
                    'online payment cannot be attempted' USING ERRCODE = 'no_data_found';
  END IF;
  account_id := acct.id; provider := acct.provider; merchant_account_ref := acct.merchant_account_ref;
  RETURN NEXT;
END $$;


--
-- Name: p4_resolve_payment_account_v2(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_resolve_payment_account_v2(p_tenant uuid, p_site uuid) RETURNS TABLE(account_id uuid, provider text, merchant_account_ref text, currency text, mode text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE acct record;
BEGIN
  SELECT * INTO acct FROM iam_v2.payment_provider_accounts
   WHERE tenant_id = p_tenant AND site_id = p_site AND status = 'ACTIVE' AND is_default LIMIT 1;
  IF acct.id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_NO_CONFIGURED_ACCOUNT' USING ERRCODE = 'no_data_found';
  END IF;
  account_id := acct.id; provider := acct.provider; merchant_account_ref := acct.merchant_account_ref;
  currency := acct.currency; mode := acct.mode;
  RETURN NEXT;
END $$;


--
-- Name: p4_resolve_recovery_hold(uuid, text, uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_resolve_recovery_hold(p_hold uuid, p_resolution text, p_actor uuid, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE h record; v_tx record;
BEGIN
  IF p_resolution NOT IN ('CONFIRMED_COMPLETED','CONFIRMED_NOT_COMPLETED','ABANDONED','ESCALATED') THEN
    RAISE EXCEPTION 'RECOVERY_RESOLUTION_INVALID: %', p_resolution USING ERRCODE = 'check_violation';
  END IF;
  IF p_note IS NULL OR length(btrim(p_note)) < 10 THEN
    RAISE EXCEPTION 'RECOVERY_NOTE_REQUIRED: a reconciliation decision records HOW it was established, in '
                    'at least 10 characters' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO h FROM iam_v2.financial_recovery_holds WHERE id = p_hold FOR UPDATE;
  IF h.id IS NULL THEN
    RAISE EXCEPTION 'RECOVERY_HOLD_UNKNOWN: %', p_hold USING ERRCODE = 'no_data_found';
  END IF;
  PERFORM iam_v2.p4_assert_financial_actor(h.tenant_id, p_actor);

  -- The reconciliation session flag. It is set ONLY here, so the outbox gate can tell an audited decision
  -- apart from an ordinary UPDATE, and it is scoped to this transaction.
  PERFORM set_config('iam_v2.p4_recovery_reconciling', 'on', true);

  IF h.work_kind = 'POSTING_OUTBOX' THEN
    -- CONFIRMED_COMPLETED: the folio already has it. The command must stop being sendable, permanently.
    -- ABANDONED: nothing further will be done about it, which is also terminal.
    IF p_resolution IN ('CONFIRMED_COMPLETED','ABANDONED') THEN
      UPDATE iam_v2.posting_outbox SET state = 'DONE'
       WHERE id = h.work_id AND state = 'HELD_RECOVERY';
    END IF;
    -- CONFIRMED_NOT_COMPLETED and ESCALATED deliberately leave the row HELD_RECOVERY. Re-queueing it here
    -- would be exactly the automatic replay recovery exists to prevent; a retry becomes possible only
    -- through record_posting_review_action, which authorizes ONE attempt and audits who authorized it.
  ELSIF h.work_kind = 'PAYMENT_TRANSACTION' THEN
    SELECT * INTO v_tx FROM iam_v2.payment_transactions WHERE id = h.work_id FOR UPDATE;
    IF v_tx.id IS NOT NULL AND v_tx.status IN ('CREATED','PENDING') THEN
      IF p_resolution = 'CONFIRMED_NOT_COMPLETED' THEN
        -- Nothing was charged. The intent is closed; a new attempt is a new purchase flow, never a replay
        -- of this one.
        IF v_tx.status = 'CREATED' THEN
          UPDATE iam_v2.payment_transactions SET status = 'PENDING' WHERE id = v_tx.id;
        END IF;
        UPDATE iam_v2.payment_transactions SET status = 'FAILED' WHERE id = v_tx.id;
      ELSE
        -- CONFIRMED_COMPLETED, ABANDONED and ESCALATED all leave the money AMBIGUOUS from the database's
        -- point of view. Recording a capture here would settle a settlement and grant access on an
        -- operator's say-so, bypassing the authenticated provider boundary entirely -- so the payment goes
        -- to UNKNOWN and the settlement to MANUAL_REVIEW, where the existing audited model decides.
        IF v_tx.status = 'CREATED' THEN
          UPDATE iam_v2.payment_transactions SET status = 'PENDING' WHERE id = v_tx.id;
        END IF;
        UPDATE iam_v2.payment_transactions SET status = 'UNKNOWN' WHERE id = v_tx.id;
        -- The ambiguity belongs to the SETTLEMENT as much as to the payment: an operator looking at the
        -- settlement must see that its outcome is unresolved, not that it is quietly still in progress.
        UPDATE iam_v2.settlements SET status = 'MANUAL_REVIEW'
         WHERE id = v_tx.settlement_id AND status = 'IN_PROGRESS';
      END IF;
    END IF;
  ELSIF h.work_kind = 'SETTLEMENT' THEN
    -- Only an IN_PROGRESS settlement is ambiguous: something was started against it and nobody knows how
    -- it ended. A REQUIRED settlement is simply still awaiting money, which a restore did not change, and
    -- section 16 has no REQUIRED -> MANUAL_REVIEW edge -- so it is left exactly where it is rather than
    -- widening the state machine to make the reconciliation look tidier.
    UPDATE iam_v2.settlements SET status = 'MANUAL_REVIEW'
     WHERE id = h.work_id AND status = 'IN_PROGRESS';
  END IF;

  UPDATE iam_v2.financial_recovery_holds
     SET resolution = p_resolution, resolved_at = now(), resolved_by = p_actor, resolution_note = p_note
   WHERE id = p_hold;
END $$;


--
-- Name: p4_resolve_reversal_review(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_resolve_reversal_review(p_tenant uuid, p_site uuid, p_review uuid, p_resolution text, p_actor text, p_reason text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE rv record; v_ent uuid;
BEGIN
  IF p_resolution NOT IN ('KEEP_ACCESS','END_ACCESS') THEN
    RAISE EXCEPTION 'resolution must be KEEP_ACCESS or END_ACCESS' USING ERRCODE = 'check_violation';
  END IF;
  IF COALESCE(btrim(p_actor), '') = '' OR COALESCE(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'a resolution needs an operator and a reason' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO rv FROM iam_v2.card_reversal_reviews
   WHERE id = p_review AND tenant_id = p_tenant AND site_id = p_site FOR UPDATE;
  IF NOT FOUND THEN
    RETURN 'NOT_FOUND';
  END IF;
  IF rv.resolution IS NOT NULL THEN
    RETURN 'ALREADY_RESOLVED';
  END IF;
  IF p_resolution = 'END_ACCESS' THEN
    SELECT e.id INTO v_ent FROM iam_v2.settlements se JOIN iam_v2.entitlements e ON e.purchase_id = se.purchase_id
     WHERE se.id = rv.settlement_id;
    IF v_ent IS NOT NULL THEN
      PERFORM iam_v2.p4_end_access_funded_by(v_ent, 'REVOKED');
    END IF;
  END IF;
  UPDATE iam_v2.card_reversal_reviews
     SET resolution = p_resolution, resolved_at = now(), resolved_by = btrim(p_actor), resolution_reason = btrim(p_reason)
   WHERE id = p_review;
  RETURN p_resolution;
END $$;


--
-- Name: p4_reversal_ledger_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_reversal_ledger_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE orig record; v_already bigint;
BEGIN
  IF NEW.posting_type <> 'REVERSAL' THEN
    RETURN NEW;
  END IF;

  -- (a) Only the audited Manual-Review operation may write one. The same transaction-scoped token that
  -- guards the review ledger guards this, so a reversal cannot appear from anywhere else -- not from a
  -- worker, not from a repair script, not from an ad-hoc session.
  IF current_setting('iam_v2.p4_review_writer', true) IS DISTINCT FROM txid_current()::text THEN
    RAISE EXCEPTION 'REVERSAL_WRITER_ONLY: a reversal ledger row is created only by the audited '
                    'CREATE_REVERSAL review action'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- (b) It must reference a real, in-scope CHARGE. A reversal of nothing is not evidence of anything.
  SELECT id, posting_type, amount_minor, currency, currency_exponent, tenant_id, site_id, pms_interface_id
    INTO orig FROM iam_v2.pms_postings WHERE id = NEW.reverses_posting_id;
  IF orig.id IS NULL THEN
    RAISE EXCEPTION 'REVERSAL_ORIGINAL_UNKNOWN: posting % does not exist', NEW.reverses_posting_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF orig.posting_type <> 'CHARGE' THEN
    RAISE EXCEPTION 'REVERSAL_ORIGINAL_NOT_A_CHARGE: % is a %', orig.id, orig.posting_type
      USING ERRCODE = 'check_violation';
  END IF;
  IF orig.tenant_id <> NEW.tenant_id OR orig.site_id <> NEW.site_id
     OR orig.pms_interface_id <> NEW.pms_interface_id THEN
    RAISE EXCEPTION 'REVERSAL_OUT_OF_SCOPE: the original belongs to a different tenant/site/interface'
      USING ERRCODE = 'check_violation';
  END IF;

  -- (c) Same money, same units. A reversal in another currency would be an implicit conversion, and the
  -- exponent has to match for the sum below to mean anything at all.
  IF NEW.currency IS DISTINCT FROM orig.currency OR NEW.currency_exponent IS DISTINCT FROM orig.currency_exponent THEN
    RAISE EXCEPTION 'REVERSAL_CURRENCY_MISMATCH: reversal %/% <> original %/% (no implicit FX)',
      NEW.currency, NEW.currency_exponent, orig.currency, orig.currency_exponent
      USING ERRCODE = 'check_violation';
  END IF;

  -- (d) TA is a POSITIVE amount here, exactly as on a charge. The direction is carried by posting_type, not
  -- by a negative number -- §9a rule 5 says a negative TA is unverified, so this schema never stores one.
  IF NEW.amount_minor <= 0 THEN
    RAISE EXCEPTION 'REVERSAL_AMOUNT_INVALID: a reversal records a POSITIVE amount; direction is carried '
                    'by posting_type, never by a negative TA (section 9a rule 5)'
      USING ERRCODE = 'check_violation';
  END IF;

  -- (e) Cumulative bound: the sum of reversals may never exceed the charge they reverse.
  SELECT coalesce(sum(amount_minor), 0) INTO v_already
    FROM iam_v2.pms_postings
   WHERE posting_type = 'REVERSAL' AND reverses_posting_id = NEW.reverses_posting_id;
  IF v_already + NEW.amount_minor > orig.amount_minor THEN
    RAISE EXCEPTION 'REVERSAL_EXCEEDS_CHARGE: % already reversed + % requested > % charged',
      v_already, NEW.amount_minor, orig.amount_minor USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: p4_reversal_never_executes(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_reversal_never_executes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_type text; v_posting uuid;
BEGIN
  -- Branch with IF, not CASE: plpgsql resolves record fields at RUNTIME, and a CASE evaluates the field
  -- reference in both arms, so NEW.posting_id would be looked up on posting_attempts and fail there.
  IF TG_TABLE_NAME = 'posting_outbox' THEN
    v_posting := NEW.posting_id;
  ELSE
    v_posting := NEW.internal_posting_id;
  END IF;
  SELECT posting_type INTO v_type FROM iam_v2.pms_postings WHERE id = v_posting;
  IF v_type = 'REVERSAL' THEN
    RAISE EXCEPTION 'REVERSAL_NOT_EXECUTABLE: programmatic PMS reversal is capability=false in v1. The '
                    'reversal ledger row is a passive audit record; correction is a manual Front Office '
                    'operation (section 9a rule 5, Gate 3B)'
      USING ERRCODE = 'feature_not_supported';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_review_writer_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_review_writer_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_tok text;
BEGIN
  v_tok := current_setting('iam_v2.p4_review_writer', true);
  IF v_tok IS NULL OR v_tok <> txid_current()::text THEN
    RAISE EXCEPTION 'REVIEW_WRITER_ONLY: posting_review_actions is written only by '
                    'iam_v2.record_posting_review_action() (concurrency-safe review boundary)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_room_charge_has_records(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_room_charge_has_records(p_tenant uuid, p_site uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM iam_v2.pms_postings WHERE tenant_id = p_tenant AND site_id = p_site);
$$;


--
-- Name: p4_room_charge_interface_fresh(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_room_charge_interface_fresh(p_tenant uuid, p_site uuid, p_iface uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM iam_v2.pms_interfaces i
                  WHERE i.tenant_id = p_tenant AND i.site_id = p_site AND i.id = p_iface
                    AND iam_v2.p4_interface_freshness_block(p_tenant, p_site, p_iface, i.current_revision_id, now()) IS NULL);
$$;


--
-- Name: p4_set_financial_mirror_max_age(uuid, uuid, uuid, integer, text, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_set_financial_mirror_max_age(p_tenant uuid, p_site uuid, p_iface uuid, p_seconds integer, p_reason text, p_actor uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_status text; v_old integer;
BEGIN
  IF p_seconds IS NULL OR p_seconds < 3600 OR p_seconds > 86400 THEN
    RAISE EXCEPTION 'MIRROR_AGE_OUT_OF_RANGE: the financial mirror maximum age is between 1 and 24 hours'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 4 OR length(p_reason) > 500 THEN
    RAISE EXCEPTION 'MIRROR_AGE_REASON: a reason is required' USING ERRCODE = 'check_violation';
  END IF;
  SELECT status INTO v_status FROM public.operators WHERE id = p_actor AND tenant_id = p_tenant;
  IF v_status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'MIRROR_AGE_ACTOR: an active operator of this tenant is required' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM iam_v2.pms_interfaces WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_iface) THEN
    RAISE EXCEPTION 'MIRROR_AGE_INTERFACE: no such interface at this site' USING ERRCODE = 'check_violation';
  END IF;
  SELECT mirror_max_age_seconds INTO v_old FROM iam_v2.pms_interface_financial_settings WHERE pms_interface_id = p_iface;
  INSERT INTO iam_v2.pms_interface_financial_settings (tenant_id, site_id, pms_interface_id, mirror_max_age_seconds, updated_at, updated_by)
  VALUES (p_tenant, p_site, p_iface, p_seconds, now(), p_actor)
  ON CONFLICT (pms_interface_id) DO UPDATE SET mirror_max_age_seconds = EXCLUDED.mirror_max_age_seconds,
    updated_at = EXCLUDED.updated_at, updated_by = EXCLUDED.updated_by;
  INSERT INTO iam_v2.pms_interface_financial_setting_changes
    (tenant_id, site_id, pms_interface_id, setting, old_value, new_value, reason, changed_by)
  VALUES (p_tenant, p_site, p_iface, 'mirror_max_age_seconds', v_old, p_seconds, btrim(p_reason), p_actor);
  RETURN p_seconds;
END $$;


--
-- Name: p4_settlement_birth(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_settlement_birth() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_trigger text; v_voucher uuid;
BEGIN
  IF NEW.method = 'NOT_REQUIRED' AND NEW.status = 'NOT_REQUIRED' THEN
    RETURN NEW;
  END IF;
  IF NEW.method IN ('ONLINE_PAYMENT','PMS_POSTING','MANUAL_APPROVAL') AND NEW.status = 'REQUIRED' THEN
    RETURN NEW;
  END IF;
  IF NEW.method = 'PREPAID' AND NEW.status = 'SETTLED' THEN
    SELECT pu.trigger, ac.voucher_id INTO v_trigger, v_voucher
      FROM iam_v2.purchases pu
      JOIN iam_v2.auth_contexts ac ON ac.id = pu.auth_context_id
     WHERE pu.id = NEW.purchase_id;
    IF v_trigger = 'VOUCHER_REDEMPTION' AND v_voucher IS NOT NULL THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'SETTLEMENT_BIRTH: a PREPAID settlement is born SETTLED only for a voucher redemption'
      USING ERRCODE = 'check_violation';
  END IF;
  RAISE EXCEPTION 'SETTLEMENT_BIRTH: % / % is not a coherent first state', NEW.method, NEW.status
    USING ERRCODE = 'check_violation';
END $$;


--
-- Name: p4_settlement_state_machine(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_settlement_state_machine() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_captured bigint; v_returned bigint;
BEGIN
  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;
  IF OLD.purchase_id <> NEW.purchase_id OR OLD.method <> NEW.method THEN
    RAISE EXCEPTION 'SETTLEMENT_IDENTITY_IMMUTABLE: purchase and method are fixed at creation'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT (
       (OLD.status = 'REQUIRED'      AND NEW.status = 'IN_PROGRESS')
    OR (OLD.status = 'IN_PROGRESS'   AND NEW.status IN ('SETTLED','FAILED','MANUAL_REVIEW'))
    OR (OLD.status = 'MANUAL_REVIEW' AND NEW.status IN ('SETTLED','FAILED'))
    OR (OLD.status = 'SETTLED'       AND NEW.status IN ('PARTIALLY_REVERSED','REVERSED'))
    OR (OLD.status = 'PARTIALLY_REVERSED' AND NEW.status = 'REVERSED')
  ) THEN
    RAISE EXCEPTION 'SETTLEMENT_TRANSITION: % -> % is not an approved transition (section 16)',
      OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status = 'SETTLED' THEN
    IF NEW.method = 'ONLINE_PAYMENT' THEN
      IF NOT EXISTS (SELECT 1 FROM iam_v2.payment_transactions
                      WHERE settlement_id = NEW.id AND transaction_type = 'CHARGE' AND status = 'CAPTURED') THEN
        RAISE EXCEPTION 'SETTLEMENT_NOT_EVIDENCED: ONLINE_PAYMENT settles only on a CAPTURED charge'
          USING ERRCODE = 'check_violation';
      END IF;
    ELSIF NEW.method = 'PMS_POSTING' THEN
      -- The PMS acknowledged the charge (PA=OK), OR an authorised reviewer recorded CONFIRM_POSTED after
      -- verifying from external evidence that an UNKNOWN attempt did post (the accepted Phase-0 review action).
      IF NOT EXISTS (SELECT 1 FROM iam_v2.pms_postings p
                       JOIN iam_v2.posting_attempts a ON a.internal_posting_id = p.id
                      WHERE p.settlement_id = NEW.id AND p.posting_type = 'CHARGE'
                        AND a.outcome = 'ACKED' AND a.pa_as_status = 'OK')
         AND NOT EXISTS (SELECT 1 FROM iam_v2.pms_postings p
                           JOIN iam_v2.posting_review_state rs ON rs.posting_id = p.id
                          WHERE p.settlement_id = NEW.id AND p.posting_type = 'CHARGE'
                            AND rs.terminal_action = 'CONFIRM_POSTED') THEN
        RAISE EXCEPTION 'SETTLEMENT_NOT_EVIDENCED: PMS_POSTING settles only on a posting the PMS ACKed OK '
                        'or a reviewed CONFIRM_POSTED'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  IF NEW.status IN ('PARTIALLY_REVERSED','REVERSED') THEN
    IF NEW.method <> 'ONLINE_PAYMENT' THEN
      RAISE EXCEPTION 'SETTLEMENT_REVERSAL_WRONG_RAIL: only an ONLINE_PAYMENT settlement is reversed by '
                      'provider refunds; the PMS rail records a PASSIVE reversal and is corrected manually'
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT coalesce(sum(amount_minor),0) INTO v_captured FROM iam_v2.payment_transactions
     WHERE settlement_id = NEW.id AND transaction_type = 'CHARGE' AND status = 'CAPTURED';
    SELECT coalesce(sum(amount_minor),0) INTO v_returned FROM iam_v2.payment_transactions
     WHERE settlement_id = NEW.id AND transaction_type IN ('REFUND','CHARGEBACK') AND status = 'CAPTURED';
    IF v_returned = 0 THEN
      RAISE EXCEPTION 'SETTLEMENT_NOT_EVIDENCED: nothing has been returned' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'REVERSED' AND v_returned < v_captured THEN
      RAISE EXCEPTION 'SETTLEMENT_PARTIAL: % of % returned; this is PARTIALLY_REVERSED', v_returned, v_captured
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'PARTIALLY_REVERSED' AND v_returned >= v_captured THEN
      RAISE EXCEPTION 'SETTLEMENT_FULL: % of % returned; this is REVERSED', v_returned, v_captured
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p4_stay_feed_confirms(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_stay_feed_confirms(p_stay uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE st record; n integer := 0;
BEGIN
  SELECT id, status, normalized_room_number, occupancy_evidence_at, occupancy_clock_suspect
    INTO st FROM iam_v2.stays WHERE id = p_stay;
  IF st.id IS NULL THEN RETURN 0; END IF;
  IF st.status = 'IN_HOUSE' AND st.normalized_room_number IS NOT NULL AND btrim(st.normalized_room_number) <> ''
     AND st.occupancy_evidence_at IS NOT NULL AND st.occupancy_clock_suspect IS NOT TRUE THEN
    UPDATE iam_v2.stay_posting_blocks
       SET cleared_at = now(), cleared_by_source = 'PMS_FEED'
     WHERE stay_id = p_stay AND reason = 'PMS_DATA_SUSPECT' AND cleared_at IS NULL
       AND created_at < st.occupancy_evidence_at;
    GET DIAGNOSTICS n = ROW_COUNT;
  END IF;
  RETURN n;
END $$;


--
-- Name: p4_stay_postable_for(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_stay_postable_for(p_stay uuid, p_posting uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT s.status = 'IN_HOUSE' AND s.external_reservation_id IS NOT NULL AND btrim(s.external_reservation_id) <> ''
     AND NOT EXISTS (SELECT 1 FROM iam_v2.stay_posting_blocks b
                      WHERE b.stay_id = s.id AND b.cleared_at IS NULL
                        AND NOT (b.reason = 'POSTING_UNRESOLVED' AND p_posting IS NOT NULL AND b.posting_id = p_posting))
    FROM iam_v2.stays s WHERE s.id = p_stay;
$$;


--
-- Name: p4_stay_room_charge_open(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_stay_room_charge_open(p_stay uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM iam_v2.pms_postings p JOIN iam_v2.settlements se ON se.id = p.settlement_id
                  WHERE p.stay_id = p_stay AND p.posting_type = 'CHARGE'
                    AND se.status IN ('REQUIRED','IN_PROGRESS','MANUAL_REVIEW'));
$$;


--
-- Name: p4_terminate_live_entitlement_for_subject(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p4_terminate_live_entitlement_for_subject(p_tenant uuid, p_site uuid, p_voucher uuid, p_account uuid, p_principal uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF p_voucher IS NULL AND p_account IS NULL AND p_principal IS NULL THEN
    RAISE EXCEPTION 'GRANT_SUBJECT_REQUIRED: an entitlement always belongs to exactly one subject'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT id INTO v_id FROM iam_v2.entitlements
   WHERE tenant_id = p_tenant AND site_id = p_site AND status IN ('PENDING','ACTIVE','SUSPENDED')
     AND ( (p_voucher   IS NOT NULL AND voucher_id         = p_voucher)
        OR (p_account   IS NOT NULL AND guest_account_id   = p_account)
        OR (p_principal IS NOT NULL AND guest_principal_id = p_principal) )
   ORDER BY activated_at DESC NULLS LAST, id
   LIMIT 1 FOR UPDATE;
  IF v_id IS NULL THEN RETURN NULL; END IF;
  PERFORM iam_v2.apply_entitlement_transition(v_id, 'TERMINATED', now(), 'SUPERSEDED');
  RETURN v_id;
END $$;


--
-- Name: p5_begin_controlled_operation(text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p5_begin_controlled_operation(p_family text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_token uuid;
BEGIN
  -- The allowlist IS the authorization decision, and it is also what keeps the GUC name below safe: by the
  -- time the family is concatenated it is never caller-shaped text.
  IF p_family NOT IN ('post_stay_identity','entitlement_transfer') THEN
    RAISE EXCEPTION 'no approved Phase-5 capability-scoped controlled-writer family %', p_family;
  END IF;
  DELETE FROM iam_v2.controlled_operation_scope WHERE opened_at < now() - interval '1 hour';
  v_token := gen_random_uuid();
  INSERT INTO iam_v2.controlled_operation_scope (txid, family, token)
  VALUES (txid_current(), p_family, v_token)
  ON CONFLICT (txid, family) DO UPDATE SET token = EXCLUDED.token, opened_at = now();
  PERFORM set_config('iam_v2.op_' || p_family, v_token::text, true);
END $$;


--
-- Name: p5_controlled_operation_open(text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p5_controlled_operation_open(p_family text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_tok text;
BEGIN
  v_tok := current_setting('iam_v2.op_' || p_family, true);   -- missing_ok: NULL when never set
  IF v_tok IS NULL OR v_tok = '' THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM iam_v2.controlled_operation_scope s
     WHERE s.txid = txid_current() AND s.family = p_family AND s.token::text = v_tok);
END $$;


--
-- Name: p5_controlled_writer_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p5_controlled_writer_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE owner_role text; v_oid oid; v_cap text;
BEGIN
  v_cap := CASE
    WHEN TG_TABLE_NAME = 'post_stay_profiles'     THEN 'post_stay_identity'
    WHEN TG_TABLE_NAME IN ('entitlement_transfers','stay_links') THEN 'entitlement_transfer'
    ELSE NULL END;
  IF v_cap IS NULL THEN
    RAISE EXCEPTION 'p5_controlled_writer_only attached to an unmapped table % (fail closed)', TG_TABLE_NAME;
  END IF;
  -- Resolve the opener's owner INLINE from the catalog, exactly as the Phase-3 guard does: this trigger runs
  -- as whichever role is writing, so a cross-function EXECUTE dependency would break the dedicated-owner
  -- separation Gate P needs.
  v_oid := to_regprocedure('iam_v2.p5_begin_controlled_operation(text)');
  IF v_oid IS NULL THEN
    RAISE EXCEPTION 'Phase-5 controlled-writer opener is not resolvable (fail closed)';
  END IF;
  SELECT pg_get_userbyid(proowner) INTO owner_role FROM pg_proc WHERE oid = v_oid;
  IF owner_role IS NULL OR owner_role = '' THEN
    RAISE EXCEPTION 'Phase-5 controlled-writer owner is not resolvable (fail closed)';
  END IF;
  -- DELETE is checked too. An authoritative record that can be removed outside a declared operation is a
  -- record that can be made never to have happened.
  IF current_user <> owner_role AND NOT iam_v2.p5_controlled_operation_open(v_cap) THEN
    RAISE EXCEPTION
      '%: writes to the % family require an open controlled operation (caller %) — call iam_v2.p5_begin_controlled_operation(''%'') in the transaction that performs them',
      TG_TABLE_NAME, v_cap, current_user, v_cap;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: p5_entitlement_transfer_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p5_entitlement_transfer_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  v_from_iface uuid; v_to_iface uuid;
  v_from_stay_of_ent uuid; v_to_stay_of_ent uuid;
  v_from_status text; v_from_reason text; v_to_supersedes uuid;
  v_cursor uuid; v_hops int := 0;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    -- Lineage is a historical fact. A transfer that can be edited or removed is a lineage that cannot be
    -- trusted to answer "where did this access come from".
    RAISE EXCEPTION 'entitlement_transfers is append-only (attempted %)', TG_OP;
  END IF;

  IF NEW.reason <> 'CROSS_PMS_TRANSFER' THEN
    RAISE EXCEPTION 'entitlement_transfers records CROSS_PMS_TRANSFER only (got %)', NEW.reason;
  END IF;

  -- (a) TWO DIFFERENT PMS INTERFACES. This is the line between a transfer and a room move, and until now
  --     nothing enforced it.
  SELECT pms_interface_id INTO v_from_iface FROM iam_v2.stays
   WHERE tenant_id=NEW.tenant_id AND site_id=NEW.site_id AND id=NEW.from_stay_id;
  SELECT pms_interface_id INTO v_to_iface FROM iam_v2.stays
   WHERE tenant_id=NEW.tenant_id AND site_id=NEW.site_id AND id=NEW.to_stay_id;
  IF v_from_iface IS NULL OR v_to_iface IS NULL THEN
    RAISE EXCEPTION 'both transfer Stays must exist in scope (fail closed)';
  END IF;
  IF v_from_iface = v_to_iface THEN
    RAISE EXCEPTION 'a cross-PMS transfer requires two DIFFERENT PMS interfaces; same-interface movement is a room move, not a transfer';
  END IF;

  -- (b) The entitlements must actually belong to the Stays named. Without this the lineage could point at a
  --     real pair of entitlements and a fictional pair of Stays.
  SELECT stay_id, status, terminal_reason INTO v_from_stay_of_ent, v_from_status, v_from_reason
    FROM iam_v2.entitlements
   WHERE tenant_id=NEW.tenant_id AND site_id=NEW.site_id AND id=NEW.from_entitlement_id;
  SELECT stay_id, supersedes_entitlement_id INTO v_to_stay_of_ent, v_to_supersedes
    FROM iam_v2.entitlements
   WHERE tenant_id=NEW.tenant_id AND site_id=NEW.site_id AND id=NEW.to_entitlement_id;
  IF v_from_stay_of_ent IS DISTINCT FROM NEW.from_stay_id THEN
    RAISE EXCEPTION 'the source entitlement does not belong to the source Stay';
  END IF;
  IF v_to_stay_of_ent IS DISTINCT FROM NEW.to_stay_id THEN
    RAISE EXCEPTION 'the destination entitlement does not belong to the destination Stay';
  END IF;

  -- (c) STATE COUPLING. A transfer row whose source is still live would claim the access moved while it is
  --     still being served in the old place.
  IF v_from_status <> 'TERMINATED' OR v_from_reason IS DISTINCT FROM 'TRANSFERRED' THEN
    RAISE EXCEPTION 'the source entitlement must be TERMINATED with reason TRANSFERRED (is % / %)',
      v_from_status, v_from_reason;
  END IF;

  -- (d) A TRANSFER IS NOT A SUPERSESSION. Supersession is same-subject; a transfer crosses Stays, which is
  --     exactly why it needs its own typed relationship. Both must never be asserted for one entitlement.
  IF v_to_supersedes IS NOT NULL THEN
    RAISE EXCEPTION 'a transfer-created entitlement carries no supersedes_entitlement_id (supersession is same-subject)';
  END IF;

  -- (e) CYCLE-FREE. from/to are UNIQUE, so the lineage is a set of chains; a cycle exists exactly when the
  --     source is reachable by walking FORWARD from the destination. The hop bound is a fail-closed backstop:
  --     a chain longer than this is not a legitimate guest movement and must not spin a trigger.
  v_cursor := NEW.to_entitlement_id;
  LOOP
    v_hops := v_hops + 1;
    IF v_hops > 64 THEN
      RAISE EXCEPTION 'transfer lineage exceeds the supported depth (fail closed)';
    END IF;
    SELECT to_entitlement_id INTO v_cursor FROM iam_v2.entitlement_transfers
     WHERE from_entitlement_id = v_cursor;
    EXIT WHEN v_cursor IS NULL;
    IF v_cursor = NEW.from_entitlement_id THEN
      RAISE EXCEPTION 'transfer would create a cycle in the entitlement lineage';
    END IF;
  END LOOP;

  RETURN NEW;
END $$;


--
-- Name: p5_post_stay_authenticable(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p5_post_stay_authenticable(p_tenant uuid, p_site uuid, p_profile uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM iam_v2.post_stay_profiles p
      JOIN iam_v2.stays s
        ON s.tenant_id = p.tenant_id AND s.site_id = p.site_id AND s.id = p.origin_stay_id
     WHERE p.tenant_id = p_tenant AND p.site_id = p_site AND p.id = p_profile
       AND p.status = 'ACTIVE'
       AND p.valid_until > now()
       AND s.lifecycle_version = p.origin_lifecycle_version
       AND s.status IN ('CHECKED_OUT','POST_STAY_ACTIVE'));
$$;


--
-- Name: p5_post_stay_profile_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p5_post_stay_profile_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_status text; v_lifecycle int;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'post_stay_profiles rows are never deleted; revoke the profile instead';
  END IF;

  IF TG_OP = 'INSERT' THEN
    SELECT s.status, s.lifecycle_version INTO v_status, v_lifecycle
      FROM iam_v2.stays s
     WHERE s.tenant_id = NEW.tenant_id AND s.site_id = NEW.site_id AND s.id = NEW.origin_stay_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'post-stay profile origin Stay % is not in scope (fail closed)', NEW.origin_stay_id;
    END IF;
    IF v_lifecycle <> NEW.origin_lifecycle_version THEN
      RAISE EXCEPTION 'post-stay profile must name the CURRENT Stay episode (stay is at lifecycle_version %, profile names %)',
        v_lifecycle, NEW.origin_lifecycle_version;
    END IF;
    IF v_status NOT IN ('IN_HOUSE','CHECKED_OUT') THEN
      RAISE EXCEPTION 'post-stay profile may only be issued from an IN_HOUSE or CHECKED_OUT Stay (stay is %)', v_status;
    END IF;
    -- The minting call returned the plaintext, so the reveal happened. A profile inserted WITHOUT one would
    -- be a credential nobody has ever seen and nobody can ever be given: unusable, and indistinguishable
    -- afterwards from one whose reveal was lost.
    IF NEW.pin_revealed_at IS NULL THEN
      RAISE EXCEPTION 'a post-stay profile records its one-time reveal at mint; the plaintext exists only in that response';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE. Identity and lineage are immutable.
  IF NEW.id                          IS DISTINCT FROM OLD.id
     OR NEW.tenant_id                IS DISTINCT FROM OLD.tenant_id
     OR NEW.site_id                  IS DISTINCT FROM OLD.site_id
     OR NEW.origin_stay_id           IS DISTINCT FROM OLD.origin_stay_id
     OR NEW.origin_lifecycle_version IS DISTINCT FROM OLD.origin_lifecycle_version
     OR NEW.created_at               IS DISTINCT FROM OLD.created_at
     OR NEW.issued_at                IS DISTINCT FROM OLD.issued_at THEN
    RAISE EXCEPTION 'post-stay profile identity and origin lineage are read-only';
  END IF;
  IF OLD.status = 'REVOKED' AND NEW.status <> 'REVOKED' THEN
    RAISE EXCEPTION 'a revoked post-stay profile is never reactivated (issue a new one)';
  END IF;

  IF NEW.pin_hash IS DISTINCT FROM OLD.pin_hash THEN
    -- A NEW GENERATION. It is a different secret, minted and returned by this same statement, so it carries
    -- its OWN reveal. Inheriting the previous generation's timestamp would silently consume the new secret's
    -- one-time reveal and leave no record that it was shown.
    IF NEW.pin_generation <> OLD.pin_generation + 1 THEN
      RAISE EXCEPTION 'a new post-stay PIN must increment pin_generation by exactly 1 (% -> %)',
        OLD.pin_generation, NEW.pin_generation;
    END IF;
    IF NEW.pin_revealed_at IS NULL OR NEW.pin_revealed_at IS NOT DISTINCT FROM OLD.pin_revealed_at THEN
      RAISE EXCEPTION 'a newly minted post-stay PIN records its own reveal';
    END IF;
  ELSE
    IF NEW.pin_generation IS DISTINCT FROM OLD.pin_generation THEN
      RAISE EXCEPTION 'pin_generation may not change without a new PIN';
    END IF;
    -- SAME generation: the reveal already happened and cannot happen again. This is the rule that makes
    -- "show me that PIN again" impossible rather than merely unimplemented.
    IF NEW.pin_revealed_at IS DISTINCT FROM OLD.pin_revealed_at THEN
      RAISE EXCEPTION 'a post-stay PIN is revealed exactly once per generation';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p5_stay_link_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p5_stay_link_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_from_iface uuid; v_to_iface uuid;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'stay_links is append-only (attempted %)', TG_OP;
  END IF;
  IF NEW.reason = 'POST_STAY' THEN
    RAISE EXCEPTION 'stay_links(POST_STAY) is not written: post-stay has one real Stay and its lineage is post_stay_profiles.origin_stay_id (contract 7.3)';
  END IF;
  IF NEW.from_stay = NEW.to_stay THEN
    RAISE EXCEPTION 'a stay link joins two different Stays';
  END IF;
  SELECT pms_interface_id INTO v_from_iface FROM iam_v2.stays
   WHERE tenant_id=NEW.tenant_id AND site_id=NEW.site_id AND id=NEW.from_stay;
  SELECT pms_interface_id INTO v_to_iface FROM iam_v2.stays
   WHERE tenant_id=NEW.tenant_id AND site_id=NEW.site_id AND id=NEW.to_stay;
  IF v_from_iface IS NULL OR v_to_iface IS NULL THEN
    RAISE EXCEPTION 'both linked Stays must exist in scope (fail closed)';
  END IF;
  IF v_from_iface = v_to_iface THEN
    RAISE EXCEPTION 'a CROSS_PMS_TRANSFER link requires two DIFFERENT PMS interfaces';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p6_advance_data_crossing(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_advance_data_crossing(p_tenant uuid, p_site uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE e record; b record; v_new bigint; v_max bigint; v_est numeric; v_exact timestamptz; n int := 0;
BEGIN
  FOR e IN
    SELECT en.id, COALESCE(en.data_quota_bytes, spr.data_quota_bytes) AS quota
      FROM iam_v2.entitlements en
      LEFT JOIN iam_v2.service_plan_revisions spr ON spr.id = en.service_plan_revision_id
     WHERE en.tenant_id = p_tenant AND en.site_id = p_site
       AND en.status IN ('ACTIVE', 'PENDING', 'SUSPENDED')
       AND COALESCE(en.data_quota_bytes, spr.data_quota_bytes) IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM iam_v2.data_crossing_state s
                        WHERE s.entitlement_id = en.id AND s.crossed_at IS NOT NULL
                          AND s.quota_bytes = COALESCE(en.data_quota_bytes, spr.data_quota_bytes))
     ORDER BY en.id
  LOOP
    n := n + 1;
    FOR b IN
      SELECT sb.id, sb.session_id, sb.bound_from, sb.bound_until, se.ended,
             COALESCE(pr.examined_seq, 0) AS seq, COALESCE(pr.final, false) AS final
        FROM iam_v2.session_entitlement_bindings sb
        JOIN iam_v2.sessions se ON se.id = sb.session_id
        LEFT JOIN iam_v2.data_crossing_progress pr ON pr.binding_id = sb.id
       WHERE sb.entitlement_id = e.id
    LOOP
      IF b.final THEN
        CONTINUE;   -- an ended session's records are complete; there is nothing new to read
      END IF;
      -- ONLY the records after the checkpoint: the unique (session_id, sample_seq) index answers this directly.
      SELECT COALESCE(sum(CASE WHEN b.bound_from <= ar.sampled_at
                                    AND (b.bound_until IS NULL OR b.bound_until > ar.sampled_at)
                               THEN ar.bytes_up + ar.bytes_down ELSE 0 END), 0),
             max(ar.sample_seq)
        INTO v_new, v_max
        FROM iam_v2.accounting_records ar
       WHERE ar.session_id = b.session_id AND ar.sample_seq > b.seq;
      INSERT INTO iam_v2.data_crossing_progress AS pr
        (binding_id, tenant_id, site_id, entitlement_id, session_id, examined_seq, counted_bytes, final)
      VALUES (b.id, p_tenant, p_site, e.id, b.session_id, COALESCE(v_max, b.seq), v_new,
              -- ingestion refuses an ended session outright, so once it has been ended for a while (longer than
              -- any in-flight observation could take) its record set is closed for good
              b.ended IS NOT NULL AND b.ended < now() - interval '5 minutes')
      ON CONFLICT (binding_id) DO UPDATE
        SET examined_seq = GREATEST(pr.examined_seq, EXCLUDED.examined_seq),
            counted_bytes = pr.counted_bytes + EXCLUDED.counted_bytes,
            final = EXCLUDED.final, updated_at = now();
    END LOOP;

    SELECT COALESCE(sum(pr.counted_bytes), 0) INTO v_est
      FROM iam_v2.data_crossing_progress pr WHERE pr.entitlement_id = e.id;
    IF v_est >= e.quota THEN
      -- The running total says the quota may have been reached: establish the exact instant ONCE.
      v_exact := iam_v2.p6_data_crossing_full(e.id);
      IF v_exact IS NULL THEN
        -- The checkpoint overstated (an attribution interval shrank after it counted). Recount every binding of
        -- this entitlement exactly, so the estimate is honest again and this branch is not taken every tick.
        UPDATE iam_v2.data_crossing_progress pr
           SET counted_bytes = COALESCE((
                 SELECT sum(ar.bytes_up + ar.bytes_down)
                   FROM iam_v2.accounting_records ar
                   JOIN iam_v2.session_entitlement_bindings sb ON sb.id = pr.binding_id
                  WHERE ar.session_id = pr.session_id AND ar.sample_seq <= pr.examined_seq
                    AND sb.bound_from <= ar.sampled_at
                    AND (sb.bound_until IS NULL OR sb.bound_until > ar.sampled_at)), 0),
               updated_at = now()
         WHERE pr.entitlement_id = e.id;
      END IF;
      INSERT INTO iam_v2.data_crossing_state AS s (entitlement_id, tenant_id, site_id, quota_bytes, crossed_at)
      VALUES (e.id, p_tenant, p_site, e.quota, v_exact)
      ON CONFLICT (entitlement_id) DO UPDATE
        SET quota_bytes = EXCLUDED.quota_bytes, crossed_at = EXCLUDED.crossed_at, verified_at = now();
    END IF;
  END LOOP;
  RETURN n;
END $$;


--
-- Name: FUNCTION p6_advance_data_crossing(p_tenant uuid, p_site uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_advance_data_crossing(p_tenant uuid, p_site uuid) IS 'Advances the data-crossing checkpoint of every live, quota-bearing entitlement of a site by the accounting records that arrived since the last call (0122), and establishes the exact crossing instant once the running total reaches the quota. Called by acctd before the expiry sweep. Deletes nothing.';


--
-- Name: p6_counts_online_time(text, bigint); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_counts_online_time(p_mode text, p_budget bigint) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT p_mode = 'AGGREGATE_ONLINE_TIME'
      OR (p_mode = 'VALIDITY_WINDOW' AND p_budget IS NOT NULL AND p_budget > 0);
$$;


--
-- Name: FUNCTION p6_counts_online_time(p_mode text, p_budget bigint); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_counts_online_time(p_mode text, p_budget bigint) IS 'Whether an entitlement in this time mode, pinned to a plan revision with this time_quota_seconds, is accounted in online time (0122): always for AGGREGATE_ONLINE_TIME, and for VALIDITY_WINDOW when the plan carries a positive time allowance. The one definition every online-time function uses.';


--
-- Name: p6_data_crossing(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_data_crossing(p_entitlement uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_quota bigint; st record; v_est numeric;
BEGIN
  SELECT COALESCE(e.data_quota_bytes, spr.data_quota_bytes) INTO v_quota
    FROM iam_v2.entitlements e
    LEFT JOIN iam_v2.service_plan_revisions spr ON spr.id = e.service_plan_revision_id
   WHERE e.id = p_entitlement;
  IF v_quota IS NULL THEN
    RETURN NULL;   -- no quota (or no such entitlement): nothing to cross, and nothing is read
  END IF;
  SELECT s.quota_bytes, s.crossed_at INTO st FROM iam_v2.data_crossing_state s WHERE s.entitlement_id = p_entitlement;
  IF FOUND AND st.crossed_at IS NOT NULL AND st.quota_bytes = v_quota THEN
    RETURN st.crossed_at;
  END IF;
  -- An UPPER BOUND on the attributed bytes: each binding's checkpoint plus whatever arrived after it (a binding
  -- with no checkpoint yet contributes everything it has). Below the quota it proves there is no crossing, and
  -- that is the steady state, answered from an index probe per binding instead of the whole history.
  SELECT COALESCE(sum(COALESCE(pr.counted_bytes, 0) + COALESCE(tail.bytes, 0)), 0) INTO v_est
    FROM iam_v2.session_entitlement_bindings sb
    LEFT JOIN iam_v2.data_crossing_progress pr ON pr.binding_id = sb.id
    LEFT JOIN LATERAL (
      SELECT sum(ar.bytes_up + ar.bytes_down) AS bytes
        FROM iam_v2.accounting_records ar
       WHERE ar.session_id = sb.session_id AND ar.sample_seq > COALESCE(pr.examined_seq, 0)
         AND sb.bound_from <= ar.sampled_at AND (sb.bound_until IS NULL OR sb.bound_until > ar.sampled_at)
    ) tail ON true
   WHERE sb.entitlement_id = p_entitlement;
  IF v_est < v_quota THEN
    RETURN NULL;
  END IF;
  RETURN iam_v2.p6_data_crossing_full(p_entitlement);
END $$;


--
-- Name: FUNCTION p6_data_crossing(p_entitlement uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_data_crossing(p_entitlement uuid) IS 'The instant attributed usage first reached this entitlement''s quota, or NULL. The quota is the entitlement''s own frozen data_quota_bytes when it has one (a PER_STAY_NIGHT grant) and the pinned plan revision''s otherwise. Since 0122 it answers from the durable checkpoint (data_crossing_progress / data_crossing_state) and runs the exact derivation (p6_data_crossing_full) only when the running total has reached the quota. Both the expiry sweep''s candidate query and the sanctioned expiry writer call it, so they cannot disagree.';


--
-- Name: p6_data_crossing_full(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_data_crossing_full(p_entitlement uuid) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT min(x.sampled_at)
    FROM iam_v2.entitlements e
    LEFT JOIN iam_v2.service_plan_revisions spr ON spr.id = e.service_plan_revision_id
    CROSS JOIN LATERAL (
      SELECT ar.sampled_at,
             sum(ar.bytes_up + ar.bytes_down) OVER (ORDER BY ar.sampled_at, ar.id) AS running
        FROM iam_v2.accounting_records ar
        JOIN iam_v2.session_entitlement_bindings b ON b.session_id = ar.session_id
         AND b.entitlement_id = e.id AND b.bound_from <= ar.sampled_at
         AND (b.bound_until IS NULL OR b.bound_until > ar.sampled_at)
    ) x
   WHERE e.id = p_entitlement
     AND COALESCE(e.data_quota_bytes, spr.data_quota_bytes) IS NOT NULL
     AND x.running >= COALESCE(e.data_quota_bytes, spr.data_quota_bytes);
$$;


--
-- Name: FUNCTION p6_data_crossing_full(p_entitlement uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_data_crossing_full(p_entitlement uuid) IS 'The exact data-quota crossing by full derivation over every attributed accounting record (the pre-0122 p6_data_crossing). Called only once the checkpointed running total says the quota may have been reached.';


--
-- Name: p6_due_terminal(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_due_terminal(p_entitlement uuid) RETURNS TABLE(reason text, at timestamp with time zone, time_cause text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  e      record;
  v_win  timestamptz;
  v_data timestamptz;
  v_agg  timestamptz;
BEGIN
  SELECT id, status, time_accounting_mode, window_ends_at
    INTO e FROM iam_v2.entitlements WHERE id = p_entitlement;
  IF NOT FOUND OR e.status NOT IN ('ACTIVE', 'PENDING', 'SUSPENDED') THEN
    RETURN;
  END IF;

  IF e.window_ends_at IS NOT NULL AND e.window_ends_at <= now() THEN
    v_win := e.window_ends_at;
  END IF;
  v_data := iam_v2.p6_data_crossing(p_entitlement);
  -- Exhaustion counts as a terminal condition only when its instant is provable.
  v_agg := iam_v2.p6_exhaustion_instant(p_entitlement);

  IF v_win IS NULL AND v_data IS NULL AND v_agg IS NULL THEN
    RETURN;
  END IF;

  at := LEAST(COALESCE(v_win, 'infinity'::timestamptz),
              COALESCE(v_data, 'infinity'::timestamptz),
              COALESCE(v_agg, 'infinity'::timestamptz));
  IF v_data IS NOT NULL AND v_data = at THEN
    reason := 'DATA'; time_cause := NULL;
  ELSIF v_agg IS NOT NULL AND v_agg = at THEN
    reason := 'TIME';
    -- Which online-time clock ran out: the aggregate mode's budget, or the time allowance a
    -- VALIDITY_WINDOW plan carries (0122). Same terminal reason, distinguishable evidence.
    time_cause := CASE WHEN e.time_accounting_mode = 'AGGREGATE_ONLINE_TIME'
                       THEN 'AGGREGATE_ONLINE_TIME_EXHAUSTED' ELSE 'ONLINE_TIME_ALLOWANCE_EXHAUSTED' END;
  ELSE
    reason := 'TIME';
    time_cause := CASE WHEN e.time_accounting_mode = 'AGGREGATE_ONLINE_TIME'
                       THEN 'AGGREGATE_OUTER_WINDOW_EXPIRED' ELSE 'VALIDITY_WINDOW_ELAPSED' END;
  END IF;
  RETURN NEXT;
END $$;


--
-- Name: FUNCTION p6_due_terminal(p_entitlement uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_due_terminal(p_entitlement uuid) IS 'The terminal condition an entitlement has ALREADY reached -- earliest of outer window, data crossing and aggregate exhaustion -- or no row when it is healthy. This is the fact the expiry writer establishes for itself instead of accepting from its caller.';


--
-- Name: p6_end_sessions_over_plan_limits(uuid, uuid, timestamp with time zone, boolean); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_end_sessions_over_plan_limits(p_tenant uuid, p_site uuid, p_now timestamp with time zone, p_judge_idle boolean) RETURNS TABLE(session_id uuid, entitlement_id uuid, end_reason text, ended_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  s          record;
  v_last     timestamptz;
  v_max_end  timestamptz;
  v_idle_end timestamptz;
  v_end      timestamptz;
BEGIN
  IF p_now IS NULL THEN
    RAISE EXCEPTION 'a reference instant is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  FOR s IN
    SELECT se.id, se.entitlement_id AS ent, se.started,
           COALESCE(spr.idle_timeout_seconds, 0) AS idle_s,
           COALESCE(spr.max_continuous_session_seconds, 0) AS max_s
      FROM iam_v2.sessions se
      JOIN iam_v2.entitlements e ON e.id = se.entitlement_id
      JOIN iam_v2.service_plan_revisions spr ON spr.id = e.service_plan_revision_id
     WHERE se.tenant_id = p_tenant AND se.site_id = p_site
       AND se.state = 'active' AND se.ended IS NULL
       AND (COALESCE(spr.idle_timeout_seconds, 0) > 0 OR COALESCE(spr.max_continuous_session_seconds, 0) > 0)
     ORDER BY se.id
     FOR UPDATE OF se
  LOOP
    v_max_end := NULL; v_idle_end := NULL;
    IF s.max_s > 0 THEN
      v_max_end := s.started + make_interval(secs => s.max_s);
    END IF;
    -- IDLE is judged only from evidence. The checkpoint's prev_sampled_at moves only when the session's counters
    -- moved (an unchanged reading is a replay and writes nothing), so it is the last instant traffic was seen. A
    -- session the accounting has never observed has no such evidence and is not judged; neither is any session
    -- when the caller says this tick's accounting pass did not complete -- silence from a broken meter is not
    -- idleness.
    IF p_judge_idle AND s.idle_s > 0 THEN
      SELECT max(cp.prev_sampled_at) INTO v_last FROM iam_v2.accounting_checkpoints cp WHERE cp.session_id = s.id;
      IF v_last IS NOT NULL THEN
        v_idle_end := GREATEST(v_last, s.started) + make_interval(secs => s.idle_s);
      END IF;
    END IF;
    v_end := LEAST(COALESCE(v_max_end, 'infinity'::timestamptz), COALESCE(v_idle_end, 'infinity'::timestamptz));
    IF v_end = 'infinity'::timestamptz OR v_end > p_now THEN
      CONTINUE;
    END IF;
    session_id := s.id; entitlement_id := s.ent; ended_at := GREATEST(v_end, s.started);
    end_reason := CASE WHEN v_max_end IS NOT NULL AND v_max_end = v_end THEN 'MAX_SESSION_DURATION'
                       ELSE 'IDLE_TIMEOUT' END;
    -- The SESSION ends at the instant the limit was reached. Nothing else moves: the entitlement stays ACTIVE
    -- with its window and allowance, and the device keeps its place on it, so signing in again simply opens a
    -- new session.
    UPDATE iam_v2.sessions se2 SET state = 'ended', ended = p6_end_sessions_over_plan_limits.ended_at,
           end_reason = p6_end_sessions_over_plan_limits.end_reason
     WHERE se2.id = s.id;
    RETURN NEXT;
  END LOOP;
END $$;


--
-- Name: FUNCTION p6_end_sessions_over_plan_limits(p_tenant uuid, p_site uuid, p_now timestamp with time zone, p_judge_idle boolean); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_end_sessions_over_plan_limits(p_tenant uuid, p_site uuid, p_now timestamp with time zone, p_judge_idle boolean) IS 'Ends live sessions whose pinned plan''s maximum continuous session (MAX_SESSION_DURATION, started + N) or idle timeout (IDLE_TIMEOUT, last metered traffic + N) has been reached, at that instant (0122). Idle is judged only when the caller''s accounting pass completed and only from a session''s own checkpoint. The entitlement and the device''s place are untouched.';


--
-- Name: p6_exhaustion_instant(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_exhaustion_instant(p_entitlement uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  e            record;
  a            record;
  v_budget     bigint;
  v_cons_floor bigint;
  v_run_bud    bigint;
  v_val        bigint;
  v_has_budget_history boolean;
BEGIN
  SELECT id, status, time_accounting_mode, consumed_online_seconds, online_time_exhausted_at,
         service_plan_revision_id
    INTO e FROM iam_v2.entitlements WHERE id = p_entitlement;
  IF NOT FOUND OR NOT iam_v2.p6_counts_online_time(e.time_accounting_mode,
       (SELECT spr0.time_quota_seconds FROM iam_v2.service_plan_revisions spr0
         WHERE spr0.id = e.service_plan_revision_id)) THEN
    RETURN NULL;
  END IF;
  IF e.online_time_exhausted_at IS NOT NULL THEN
    RETURN e.online_time_exhausted_at;
  END IF;

  SELECT spr.time_quota_seconds INTO v_budget
    FROM iam_v2.service_plan_revisions spr WHERE spr.id = e.service_plan_revision_id;
  IF v_budget IS NULL OR COALESCE(e.consumed_online_seconds, 0) < v_budget THEN
    RETURN NULL;
  END IF;

  SELECT EXISTS (SELECT 1 FROM iam_v2.entitlement_adjustments adj
                  WHERE adj.entitlement_id = p_entitlement
                    AND adj.field IN ('time_quota_seconds', 'service_plan_revision_id'))
    INTO v_has_budget_history;

  IF v_has_budget_history THEN
    BEGIN
      SELECT CASE WHEN first_adj.field = 'time_quota_seconds'
                  THEN NULLIF(first_adj.old_value, '')::bigint
                  ELSE (SELECT spr.time_quota_seconds FROM iam_v2.service_plan_revisions spr
                         WHERE spr.id = NULLIF(first_adj.old_value, '')::uuid) END
        INTO v_run_bud
        FROM (SELECT adj.field, adj.old_value FROM iam_v2.entitlement_adjustments adj
               WHERE adj.entitlement_id = p_entitlement
                 AND adj.field IN ('time_quota_seconds', 'service_plan_revision_id')
               ORDER BY adj.created_at, adj.id LIMIT 1) first_adj;
    EXCEPTION WHEN others THEN
      RETURN NULL;
    END;
    IF v_run_bud IS NULL THEN
      RETURN NULL;
    END IF;
  ELSE
    v_run_bud := v_budget;
  END IF;

  v_cons_floor := NULL;

  FOR a IN
    SELECT adj.field, adj.old_value, adj.new_value, adj.created_at
      FROM iam_v2.entitlement_adjustments adj
     WHERE adj.entitlement_id = p_entitlement
       AND adj.field IN ('consumed_online_seconds', 'time_quota_seconds', 'service_plan_revision_id')
     ORDER BY adj.created_at, adj.id
  LOOP
    BEGIN
      IF a.field = 'consumed_online_seconds' THEN
        v_val := NULLIF(a.new_value, '')::bigint;
        IF v_val IS NULL THEN RETURN NULL; END IF;
        v_cons_floor := v_val;
      ELSIF a.field = 'time_quota_seconds' THEN
        v_val := NULLIF(a.new_value, '')::bigint;
        IF v_val IS NULL THEN RETURN NULL; END IF;
        v_run_bud := v_val;
      ELSE
        SELECT spr.time_quota_seconds INTO v_val FROM iam_v2.service_plan_revisions spr
         WHERE spr.id = NULLIF(a.new_value, '')::uuid;
        IF v_val IS NULL THEN RETURN NULL; END IF;
        v_run_bud := v_val;
      END IF;
    EXCEPTION WHEN others THEN
      RETURN NULL;
    END;

    IF v_cons_floor IS NOT NULL AND v_run_bud IS NOT NULL AND v_cons_floor >= v_run_bud THEN
      RETURN a.created_at;
    END IF;
  END LOOP;

  -- Warn only while nothing has been done about it. A suspended entitlement has been handled: access is
  -- withheld and the transition says why, so repeating the line every sweep would bury the ones that still
  -- need somebody.
  IF e.status IN ('ACTIVE', 'PENDING') THEN
    RAISE WARNING 'entitlement % is at or over its online-time budget and its audited history cannot prove '
                  'when it crossed; access will be withheld and it will not be terminated for TIME until '
                  'something can date it', p_entitlement;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: FUNCTION p6_exhaustion_instant(p_entitlement uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_exhaustion_instant(p_entitlement uuid) IS 'The instant an AGGREGATE_ONLINE_TIME budget ran out, from evidence only: the tick''s stamp, else the first instant at which the adjustment-recorded LOWER BOUND on consumption had already reached the budget as it then stood, else NULL. Ordinary accrual writes no adjustment, so the history bounds consumption from below and can never be used to argue that a budget cut found the entitlement under budget.';


--
-- Name: p6_expire_entitlement(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_expire_entitlement(p_entitlement uuid) RETURNS TABLE(reason text, at timestamp with time zone, devices integer, sessions integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  due        record;
  v_status   text;
  v_devices  int;
  v_sessions int;
BEGIN
  -- The entitlement row is locked FIRST, in the global lock order, so the condition cannot be established
  -- against state another transaction is changing underneath.
  SELECT status INTO v_status FROM iam_v2.entitlements WHERE id = p_entitlement FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such entitlement %', p_entitlement USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_status = 'TERMINATED' THEN
    -- Idempotent: a re-run, or a sweep that lost the race, changes nothing.
    RETURN;
  END IF;

  SELECT d.reason, d.at, d.time_cause INTO due FROM iam_v2.p6_due_terminal(p_entitlement) d;
  IF due.reason IS NULL THEN
    -- THE REFUSAL THAT MATTERS. A caller naming a healthy entitlement gets nothing: no termination, no
    -- revocation, no evidence. It cannot end access by asserting that access is over.
    RAISE EXCEPTION 'entitlement % has not reached any terminal condition', p_entitlement
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- The ONE termination path, with the reason and instant this function derived.
  PERFORM iam_v2.terminate_entitlement_at_boundary(p_entitlement, due.at, due.reason);

  -- Phase-6 time evidence, likewise derived: which clock ran out is not a caller's claim either.
  IF due.time_cause IS NOT NULL THEN
    PERFORM iam_v2.p6_record_time_termination(p_entitlement, due.time_cause);
  END IF;

  PERFORM iam_v2.begin_controlled_operation('device_auth');

  WITH closed AS (
    UPDATE iam_v2.entitlement_device_authorizations a
       SET deauthorized_at = GREATEST(due.at, a.authorized_at)
     WHERE a.entitlement_id = p_entitlement AND a.deauthorized_at IS NULL
     RETURNING a.entitlement_id, a.device_id)
  UPDATE iam_v2.entitlement_devices ed
     SET status = 'DISCONNECTED', disconnected_reason = 'ENTITLEMENT_ENDED'
    FROM closed
   WHERE ed.entitlement_id = closed.entitlement_id AND ed.device_id = closed.device_id;
  GET DIAGNOSTICS v_devices = ROW_COUNT;

  UPDATE iam_v2.sessions
     SET state = 'ended', ended = GREATEST(due.at, started), end_reason = 'ENTITLEMENT_ENDED'
   WHERE entitlement_id = p_entitlement AND state IN ('active', 'PENDING_ENFORCEMENT');
  GET DIAGNOSTICS v_sessions = ROW_COUNT;

  reason := due.reason; at := due.at; devices := v_devices; sessions := v_sessions;
  RETURN NEXT;
END $$;


--
-- Name: FUNCTION p6_expire_entitlement(p_entitlement uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_expire_entitlement(p_entitlement uuid) IS 'Ends an entitlement that the DATABASE says has already reached a terminal condition, at the instant it reached it, with the reason and time-cause derived here rather than supplied. Refuses a healthy entitlement. The accounting daemon holds EXECUTE on this and on nothing it calls.';


--
-- Name: p6_guest_device_actions_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_guest_device_actions_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'iam_v2.guest_device_actions is append-only: % refused', TG_OP
    USING ERRCODE = 'restrict_violation';
END $$;


--
-- Name: p6_guest_release_device(uuid, uuid, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_guest_release_device(p_entitlement uuid, p_device uuid, p_max_releases_per_hour integer DEFAULT 20) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  e record;
  b record;
  live_sessions int;
  recent int;
  released boolean;
BEGIN
  -- L3 FIRST, in the global lock order, exactly as authorize_entitlement_device and
  -- deauthorize_entitlement_device do. This is the boundary the admission path also takes, which is what
  -- makes the two mutually exclusive rather than merely usually-not-simultaneous.
  SELECT id, tenant_id, site_id, status INTO e
    FROM iam_v2.entitlements WHERE id = p_entitlement FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such entitlement' USING ERRCODE = 'foreign_key_violation';
  END IF;

  SELECT count(*) INTO recent FROM iam_v2.guest_device_actions
   WHERE entitlement_id = p_entitlement AND action = 'RELEASE'
     AND acted_at > now() - interval '1 hour';
  IF recent >= p_max_releases_per_hour THEN
    INSERT INTO iam_v2.guest_device_actions (tenant_id, site_id, entitlement_id, device_id, action, outcome, detail)
      VALUES (e.tenant_id, e.site_id, e.id, p_device, 'RELEASE', 'REFUSED_THROTTLED',
              format('%s release attempts in the last hour', recent));
    RETURN 'REFUSED_THROTTLED';
  END IF;

  SELECT entitlement_id, device_id, status INTO b
    FROM iam_v2.entitlement_devices
   WHERE entitlement_id = p_entitlement AND device_id = p_device;
  IF NOT FOUND THEN
    INSERT INTO iam_v2.guest_device_actions (tenant_id, site_id, entitlement_id, device_id, action, outcome, detail)
      VALUES (e.tenant_id, e.site_id, e.id, p_device, 'RELEASE', 'REFUSED_NOT_FOUND',
              'the device is not bound to this entitlement');
    RETURN 'REFUSED_NOT_FOUND';
  END IF;

  IF b.status <> 'AUTHORIZED' THEN
    INSERT INTO iam_v2.guest_device_actions (tenant_id, site_id, entitlement_id, device_id, action, outcome, detail)
      VALUES (e.tenant_id, e.site_id, e.id, p_device, 'RELEASE', 'REFUSED_ALREADY_RELEASED',
              format('binding is already %s', b.status));
    RETURN 'REFUSED_ALREADY_RELEASED';
  END IF;

  -- The offline read, still inside the L3 lock. It no longer needs FOR UPDATE: holding the entitlement lock
  -- excludes the admission path entirely, and the structural guard catches anything that could still slip
  -- past a lock. Counting here decides whether to refuse; the guard decides whether the world stays coherent.
  SELECT count(*) INTO live_sessions FROM iam_v2.sessions
   WHERE entitlement_id = p_entitlement AND device_id = p_device
     AND state IN ('active', 'PENDING_ENFORCEMENT');
  IF live_sessions > 0 THEN
    INSERT INTO iam_v2.guest_device_actions (tenant_id, site_id, entitlement_id, device_id, action, outcome, detail)
      VALUES (e.tenant_id, e.site_id, e.id, p_device, 'RELEASE', 'REFUSED_ONLINE',
              format('%s live session(s) on this device', live_sessions));
    RETURN 'REFUSED_ONLINE';
  END IF;

  -- THE APPROVED PRIMITIVE, not a second implementation of it. It closes the interval, flips the binding,
  -- declares the device_auth scope and re-takes L3 (already held, so it is a no-op that keeps the contract).
  released := iam_v2.deauthorize_entitlement_device(p_entitlement, p_device, now(), 'GUEST_SELF_SERVICE');
  IF NOT released THEN
    -- No open interval: the binding said AUTHORIZED but no interval was open, which means something else
    -- closed it between the two reads. Report it as already released rather than inventing a success.
    INSERT INTO iam_v2.guest_device_actions (tenant_id, site_id, entitlement_id, device_id, action, outcome, detail)
      VALUES (e.tenant_id, e.site_id, e.id, p_device, 'RELEASE', 'REFUSED_ALREADY_RELEASED',
              'no open authorization interval');
    RETURN 'REFUSED_ALREADY_RELEASED';
  END IF;

  INSERT INTO iam_v2.guest_device_actions (tenant_id, site_id, entitlement_id, device_id, action, outcome, detail)
    VALUES (e.tenant_id, e.site_id, e.id, p_device, 'RELEASE', 'OK', 'slot released by guest self-service');
  RETURN 'OK';
END $$;


--
-- Name: FUNCTION p6_guest_release_device(p_entitlement uuid, p_device uuid, p_max_releases_per_hour integer); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_guest_release_device(p_entitlement uuid, p_device uuid, p_max_releases_per_hour integer) IS 'The guest device release, and the PRIVILEGE BOUNDARY for it. SECURITY DEFINER so the guest-facing runtime role can perform a controlled release without ever holding EXECUTE on deauthorize_entitlement_device -- which would release any device on any entitlement with no throttle, no ownership scope, no offline check and no audit. The only release the runtime can perform is one that passed all four.';


--
-- Name: p6_guest_release_device_policy(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_guest_release_device_policy(p_entitlement uuid, p_device uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  -- The policy limit lives HERE, on the server, next to the operation it governs. It is a constant rather
  -- than a setting because a per-appliance throttle would be a per-appliance way to disable the throttle,
  -- and nothing in the product needs that.
  c_max_releases_per_hour CONSTANT int := 20;
BEGIN
  RETURN iam_v2.p6_guest_release_device(p_entitlement, p_device, c_max_releases_per_hour);
END $$;


--
-- Name: FUNCTION p6_guest_release_device_policy(p_entitlement uuid, p_device uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_guest_release_device_policy(p_entitlement uuid, p_device uuid) IS 'THE ONLY release entry point a runtime role may hold. Its security policy is derived server-side: the hourly throttle is not a parameter, so no caller can choose it. The three-argument form is the internal test primitive and is never granted to a runtime role -- a role that can pass its own limit can pass 2147483647 and use the approved function to bypass the approved policy.';


--
-- Name: p6_online_watermark_monotonic(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_online_watermark_monotonic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.accounted_through < OLD.accounted_through THEN
    RAISE EXCEPTION 'online watermark may not move backwards (% -> %): the interval before it is already charged',
      OLD.accounted_through, NEW.accounted_through USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.accounted_seconds < OLD.accounted_seconds THEN
    RAISE EXCEPTION 'accounted_seconds may not decrease (% -> %): corrections go through entitlement_adjustments',
      OLD.accounted_seconds, NEW.accounted_seconds USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: p6_over_budget_now(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_over_budget_now(p_entitlement uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT COALESCE(e.consumed_online_seconds, 0) >= spr.time_quota_seconds
    FROM iam_v2.entitlements e
    JOIN iam_v2.service_plan_revisions spr ON spr.id = e.service_plan_revision_id
   WHERE e.id = p_entitlement
     AND iam_v2.p6_counts_online_time(e.time_accounting_mode, spr.time_quota_seconds);
$$;


--
-- Name: FUNCTION p6_over_budget_now(p_entitlement uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_over_budget_now(p_entitlement uuid) IS 'Whether an AGGREGATE_ONLINE_TIME entitlement has spent its budget as of NOW, from current authoritative state. It says nothing about WHEN that happened, which is a separate and much harder question.';


--
-- Name: p6_record_time_termination(uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_record_time_termination(p_entitlement uuid, p_cause text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE e record; v_budget bigint;
BEGIN
  IF p_cause NOT IN ('VALIDITY_WINDOW_ELAPSED','AGGREGATE_ONLINE_TIME_EXHAUSTED','AGGREGATE_OUTER_WINDOW_EXPIRED',
                     'ONLINE_TIME_ALLOWANCE_EXHAUSTED') THEN
    RAISE EXCEPTION 'unknown time-termination cause %', p_cause USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT id, tenant_id, site_id, status, terminal_reason, terminated_at, time_accounting_mode,
         window_ends_at, consumed_online_seconds, service_plan_revision_id
    INTO e FROM iam_v2.entitlements WHERE id = p_entitlement FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such entitlement %', p_entitlement USING ERRCODE = 'foreign_key_violation';
  END IF;
  SELECT spr.time_quota_seconds INTO v_budget FROM iam_v2.service_plan_revisions spr
   WHERE spr.id = e.service_plan_revision_id;

  INSERT INTO iam_v2.entitlement_termination_evidence
    (entitlement_id, tenant_id, site_id, terminal_reason, cause_detail, time_mode,
     budget_seconds, consumed_online_seconds, window_ends_at, terminated_at)
  VALUES (e.id, e.tenant_id, e.site_id, e.terminal_reason, p_cause, e.time_accounting_mode,
          v_budget, e.consumed_online_seconds, e.window_ends_at, e.terminated_at);
END $$;


--
-- Name: FUNCTION p6_record_time_termination(p_entitlement uuid, p_cause text); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_record_time_termination(p_entitlement uuid, p_cause text) IS 'The sanctioned way to record why a time-mode entitlement ended. It accepts the entitlement and the cause and derives every number from the entitlement and its pinned immutable plan revision, so no caller is in a position to state a budget, a consumption or a window at all.';


--
-- Name: p6_session_requires_authorized_binding(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_session_requires_authorized_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_status text;
BEGIN
  -- Only live states are constrained. A session may END on a released binding -- that is the ordinary result
  -- of a revocation -- and forbidding it would make every deauthorization path fail.
  IF NEW.state NOT IN ('active', 'PENDING_ENFORCEMENT') THEN
    RETURN NEW;
  END IF;

  SELECT status INTO v_status FROM iam_v2.entitlement_devices
   WHERE entitlement_id = NEW.entitlement_id AND device_id = NEW.device_id;

  IF v_status IS NULL THEN
    RAISE EXCEPTION 'session for a device with no authorization binding on entitlement % (device %)',
      NEW.entitlement_id, NEW.device_id USING ERRCODE = 'restrict_violation';
  END IF;
  IF v_status <> 'AUTHORIZED' THEN
    RAISE EXCEPTION 'a % session may not exist on a % binding: the device must be re-authorized through '
      'iam_v2.authorize_entitlement_device first', NEW.state, v_status USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION p6_session_requires_authorized_binding(); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_session_requires_authorized_binding() IS 'A live session may not exist on a binding that is not AUTHORIZED. Row locks cannot lock the ABSENCE of a row, so no lock ordering alone can stop a release and a concurrent admission from producing a DISCONNECTED binding with an active session. This makes that state unrepresentable, and forces a released device back through authorize_entitlement_device -- re-checking the device limit and opening a new interval -- before it can be online again.';


--
-- Name: p6_set_guest_device_self_service(uuid, uuid, uuid, boolean, uuid, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_set_guest_device_self_service(p_tenant uuid, p_site uuid, p_appliance uuid, p_on boolean, p_operator uuid, p_operator_label text, p_reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  v_old boolean;
  -- Advisory-lock namespace for Phase-6 per-appliance product settings, following the existing convention of
  -- a fixed namespace per contended resource (Phase 1A recorded LN_DEVICE_SLOT=11 and LN_CAPACITY=7).
  c_ln_appliance_setting CONSTANT int := 61;
BEGIN
  IF p_operator_label IS NULL OR btrim(p_operator_label) = '' THEN
    RAISE EXCEPTION 'an operator label is required: "somebody changed it" is not an audit record'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- THE APPLIANCE IS THE ANCHOR. The settings row may not exist yet, so locking it would order nothing; the
  -- appliance identity always exists because the settings row is foreign-keyed to it. Transaction-scoped, so
  -- it is released at commit or rollback without any explicit unlock path to forget.
  PERFORM pg_advisory_xact_lock(c_ln_appliance_setting, hashtext(p_appliance::text));

  -- The row lock is still taken when the row DOES exist: the advisory lock orders the writers, and this keeps
  -- the ordinary row-level contract for anything else that touches the row.
  SELECT guest_device_self_service INTO v_old
    FROM iam_v2.appliance_product_settings
   WHERE tenant_id = p_tenant AND site_id = p_site AND appliance_id = p_appliance
   FOR UPDATE;

  INSERT INTO iam_v2.appliance_product_settings
      (tenant_id, site_id, appliance_id, guest_device_self_service, updated_at)
  VALUES (p_tenant, p_site, p_appliance, p_on, now())
  ON CONFLICT (tenant_id, site_id, appliance_id)
  DO UPDATE SET guest_device_self_service = EXCLUDED.guest_device_self_service, updated_at = now();

  INSERT INTO iam_v2.appliance_product_setting_changes
      (tenant_id, site_id, appliance_id, setting_key, old_value, new_value,
       changed_by_operator_id, changed_by, change_reason)
  VALUES (p_tenant, p_site, p_appliance, 'guest_device_self_service', v_old, p_on,
          p_operator, p_operator_label, nullif(btrim(coalesce(p_reason, '')), ''));

  RETURN v_old IS DISTINCT FROM p_on;
END $$;


--
-- Name: FUNCTION p6_set_guest_device_self_service(p_tenant uuid, p_site uuid, p_appliance uuid, p_on boolean, p_operator uuid, p_operator_label text, p_reason text); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_set_guest_device_self_service(p_tenant uuid, p_site uuid, p_appliance uuid, p_on boolean, p_operator uuid, p_operator_label text, p_reason text) IS 'The ONLY way a runtime role may change the per-appliance setting. Change and audit are one operation, so the audit is mandatory by PRIVILEGE rather than convention. Mutations are serialized per APPLIANCE on a transaction advisory lock, because the settings row may not exist yet and a lock on an absent row orders nothing -- two concurrent first writes would each record a transition from "unset".';


--
-- Name: p6_setting_changes_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_setting_changes_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'iam_v2.appliance_product_setting_changes is append-only: % refused', TG_OP
    USING ERRCODE = 'restrict_violation';
END $$;


--
-- Name: p6_skipped_intervals_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_skipped_intervals_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'iam_v2.online_time_skipped_intervals is append-only (attempted %)', TG_OP
    USING ERRCODE = 'restrict_violation';
END $$;


--
-- Name: p6_suspend_over_budget(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_suspend_over_budget(p_tenant uuid, p_site uuid) RETURNS TABLE(entitlement uuid, devices integer, sessions integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  e          record;
  v_devices  int;
  v_sessions int;
BEGIN
  FOR e IN
    SELECT en.id
      FROM iam_v2.entitlements en
     WHERE en.tenant_id = p_tenant AND en.site_id = p_site
       AND iam_v2.p6_counts_online_time(en.time_accounting_mode,
             (SELECT spr0.time_quota_seconds FROM iam_v2.service_plan_revisions spr0
               WHERE spr0.id = en.service_plan_revision_id))
       AND en.status IN ('ACTIVE', 'PENDING')          -- already SUSPENDED: nothing to do, and nothing to say
       AND iam_v2.p6_over_budget_now(en.id)
       AND iam_v2.p6_exhaustion_instant(en.id) IS NULL -- datable ones terminate through the normal path
     ORDER BY en.id
     FOR UPDATE
  LOOP
    -- The status change goes through the SAME writer every other status change uses, so the transition
    -- history stays the single account of what happened to this entitlement. now() is honest here: this is
    -- when the system decided to withhold access, not a claim about when the budget ran out.
    PERFORM iam_v2.apply_entitlement_transition(e.id, 'SUSPENDED', now(), 'AGGREGATE_OVER_BUDGET');

    -- Fail closed on what it already holds. Closing an authorization interval is a device-authorization
    -- write, so the scope is declared, exactly as the expiry writer does.
    PERFORM iam_v2.begin_controlled_operation('device_auth');

    WITH closed AS (
      UPDATE iam_v2.entitlement_device_authorizations a
         SET deauthorized_at = GREATEST(now(), a.authorized_at)
       WHERE a.entitlement_id = e.id AND a.deauthorized_at IS NULL
       RETURNING a.entitlement_id, a.device_id)
    UPDATE iam_v2.entitlement_devices ed
       SET status = 'DISCONNECTED', disconnected_reason = 'ENTITLEMENT_SUSPENDED'
      FROM closed
     WHERE ed.entitlement_id = closed.entitlement_id AND ed.device_id = closed.device_id;
    GET DIAGNOSTICS v_devices = ROW_COUNT;

    UPDATE iam_v2.sessions se
       SET state = 'ended', ended = GREATEST(now(), se.started), end_reason = 'ENTITLEMENT_SUSPENDED'
     WHERE se.entitlement_id = e.id AND se.state IN ('active', 'PENDING_ENFORCEMENT');
    GET DIAGNOSTICS v_sessions = ROW_COUNT;

    entitlement := e.id; devices := v_devices; sessions := v_sessions;
    RETURN NEXT;
  END LOOP;
END $$;


--
-- Name: FUNCTION p6_suspend_over_budget(p_tenant uuid, p_site uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_suspend_over_budget(p_tenant uuid, p_site uuid) IS 'Withholds access from aggregate entitlements that are over budget now and whose crossing instant cannot be proven: SUSPENDED through the ordinary transition writer, devices and sessions closed with the non-terminal reason ENTITLEMENT_SUSPENDED. No terminated_at, no terminal_reason and no TIME evidence at either level, because nothing here is a claim that the entitlement ended.';


--
-- Name: p6_termination_evidence_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_termination_evidence_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'iam_v2.entitlement_termination_evidence is append-only: % refused', TG_OP
    USING ERRCODE = 'restrict_violation';
END $$;


--
-- Name: p6_termination_evidence_matches_transition(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_termination_evidence_matches_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE e record; real_budget bigint;
BEGIN
  SELECT status, terminal_reason, terminated_at, time_accounting_mode, window_ends_at,
         consumed_online_seconds, service_plan_revision_id
    INTO e FROM iam_v2.entitlements
   WHERE id = NEW.entitlement_id AND tenant_id = NEW.tenant_id AND site_id = NEW.site_id
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'termination evidence for an entitlement that does not exist in this scope (%)',
      NEW.entitlement_id USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF e.status <> 'TERMINATED' THEN
    RAISE EXCEPTION 'termination evidence for entitlement % which is % , not TERMINATED: evidence may not describe a transition that did not occur',
      NEW.entitlement_id, e.status USING ERRCODE = 'restrict_violation';
  END IF;
  IF e.terminal_reason IS DISTINCT FROM NEW.terminal_reason THEN
    RAISE EXCEPTION 'termination evidence claims reason % but the entitlement terminated with %',
      NEW.terminal_reason, e.terminal_reason USING ERRCODE = 'restrict_violation';
  END IF;
  IF e.terminated_at IS DISTINCT FROM NEW.terminated_at THEN
    RAISE EXCEPTION 'termination evidence claims % but the entitlement terminated at %',
      NEW.terminated_at, e.terminated_at USING ERRCODE = 'restrict_violation';
  END IF;
  IF e.time_accounting_mode IS DISTINCT FROM NEW.time_mode THEN
    RAISE EXCEPTION 'termination evidence claims time mode % but the entitlement is %',
      NEW.time_mode, e.time_accounting_mode USING ERRCODE = 'restrict_violation';
  END IF;

  -- THE NUMBERS MUST BE THE REAL ONES, not merely numbers that agree with each other. Everything above this
  -- point makes a row internally consistent, and an internally consistent fabrication is still a fabrication:
  -- a caller could invent a budget and a consumption that satisfy every CHECK and describe a termination that
  -- never had those values. So each is compared against the state the termination actually used -- the
  -- entitlement's own counter, and the budget on the IMMUTABLE plan revision pinned into it at grant time.
  IF NEW.consumed_online_seconds IS NOT NULL
     AND NEW.consumed_online_seconds IS DISTINCT FROM e.consumed_online_seconds THEN
    RAISE EXCEPTION 'termination evidence claims % consumed seconds but the entitlement recorded %',
      NEW.consumed_online_seconds, e.consumed_online_seconds USING ERRCODE = 'restrict_violation';
  END IF;

  SELECT spr.time_quota_seconds INTO real_budget
    FROM iam_v2.service_plan_revisions spr
   WHERE spr.id = e.service_plan_revision_id;
  IF NEW.budget_seconds IS NOT NULL AND NEW.budget_seconds IS DISTINCT FROM real_budget THEN
    RAISE EXCEPTION 'termination evidence claims a % second budget but the pinned plan revision states %',
      NEW.budget_seconds, coalesce(real_budget::text, 'none') USING ERRCODE = 'restrict_violation';
  END IF;

  -- An outer-window expiry must name the entitlement's OWN immutable window. window_ends_at is stamped once
  -- and never moves, so evidence naming a different instant is describing a boundary that does not exist.
  IF NEW.window_ends_at IS NOT NULL AND NEW.window_ends_at IS DISTINCT FROM e.window_ends_at THEN
    RAISE EXCEPTION 'termination evidence names window % but the entitlement''s immutable window is %',
      NEW.window_ends_at, coalesce(e.window_ends_at::text, 'none') USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.cause_detail = 'AGGREGATE_OUTER_WINDOW_EXPIRED' AND e.window_ends_at IS NULL THEN
    RAISE EXCEPTION 'outer-window expiry evidence for an entitlement that has no window at all'
      USING ERRCODE = 'restrict_violation';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: p6_tick_online_time(uuid, uuid, timestamp with time zone, integer, uuid[], timestamp with time zone[]); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.p6_tick_online_time(p_tenant uuid, p_site uuid, p_now timestamp with time zone, p_max_charge_seconds integer, p_capped_entitlements uuid[] DEFAULT '{}'::uuid[], p_caps timestamp with time zone[] DEFAULT '{}'::timestamp with time zone[]) RETURNS TABLE(entitlement_id uuid, exhausted_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  e           record;
  s           record;
  v_budget    bigint;
  v_before    bigint;
  v_charged   numeric;      -- exact seconds charged this tick, before flooring
  v_base      timestamptz;
  v_ceiling   timestamptz;  -- the last instant that is billable at all
  v_billable  timestamptz;  -- the last instant this tick may charge (observation bound)
  v_charge    numeric;
  v_whole     bigint;       -- the whole seconds this session is charged this tick (0126)
  v_through   timestamptz;  -- where this session's watermark ends after this tick (0126)
  v_remaining numeric;
  -- The billable intervals of this tick, one pair per contributing session. They are what the crossing is
  -- computed from: a rate that changes at every boundary cannot be derived from a count alone.
  v_starts    timestamptz[];
  v_ends      timestamptz[];
  v_points    timestamptz[];
  v_acc       numeric;
  v_rate      int;
  v_seg       numeric;
  v_p0        timestamptz;
  v_p1        timestamptz;
  v_cross     timestamptz;
  v_cap       timestamptz;   -- the caller's earliest known terminal instant for this entitlement
  k           int;
  i           int;
BEGIN
  IF p_max_charge_seconds IS NULL OR p_max_charge_seconds <= 0 THEN
    RAISE EXCEPTION 'a charge bound is required: unbounded accrual would charge unobserved time'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  FOR e IN
    SELECT en.id, en.consumed_online_seconds, en.service_plan_revision_id, en.online_time_exhausted_at,
           en.window_ends_at
      FROM iam_v2.entitlements en
     WHERE en.tenant_id = p_tenant AND en.site_id = p_site
       AND iam_v2.p6_counts_online_time(en.time_accounting_mode,
             (SELECT spr0.time_quota_seconds FROM iam_v2.service_plan_revisions spr0
               WHERE spr0.id = en.service_plan_revision_id))
       AND en.status IN ('ACTIVE', 'PENDING', 'SUSPENDED')
     ORDER BY en.id
     FOR UPDATE
  LOOP
    SELECT spr.time_quota_seconds INTO v_budget
      FROM iam_v2.service_plan_revisions spr WHERE spr.id = e.service_plan_revision_id;

    -- The caller's cap for this entitlement, if it named one. A DATA crossing that already happened is a
    -- terminal instant like any other: nothing after it was access, so nothing after it is billable.
    v_cap := NULL;
    IF array_length(p_capped_entitlements, 1) IS NOT NULL THEN
      FOR i IN 1 .. array_length(p_capped_entitlements, 1) LOOP
        IF p_capped_entitlements[i] = e.id THEN
          v_cap := p_caps[i];
          EXIT;
        END IF;
      END LOOP;
    END IF;

    v_before  := COALESCE(e.consumed_online_seconds, 0);

    -- Already exhausted and still live: charge nothing more, and report again so a caller that failed to
    -- terminate last time still converges -- but ONLY with a provable instant.
    --
    -- This branch used to stamp now() when the entitlement had reached its budget without a stamp, which
    -- wrote a historical fact nobody observed and then handed it to the termination, the evidence row and
    -- every session end time. p6_exhaustion_instant answers from evidence or answers NULL, and NULL means
    -- nothing is claimed: no stamp, no report, no termination for TIME. The entitlement stays subject to its
    -- window and its data quota, and the next tick that observes real online time crosses the budget
    -- properly and stamps it then.
    IF v_budget IS NOT NULL AND (e.online_time_exhausted_at IS NOT NULL OR v_before >= v_budget) THEN
      exhausted_at := iam_v2.p6_exhaustion_instant(e.id);
      IF exhausted_at IS NULL THEN
        CONTINUE;
      END IF;
      entitlement_id := e.id;
      RETURN NEXT;
      CONTINUE;
    END IF;

    v_charged := 0;
    v_starts  := ARRAY[]::timestamptz[];
    v_ends    := ARRAY[]::timestamptz[];

    FOR s IN
      SELECT se.id, se.state, se.started, se.ended, w.accounted_through
        FROM iam_v2.sessions se
        LEFT JOIN iam_v2.session_online_watermarks w ON w.session_id = se.id
       WHERE se.entitlement_id = e.id
         AND (se.state = 'active' OR (se.ended IS NOT NULL AND w.accounted_through IS NOT NULL
                                      AND w.accounted_through < se.ended))
       ORDER BY se.id
       FOR UPDATE OF se
    LOOP
      -- THE CEILING: the earliest applicable boundary. now, the session's own end, and -- the correction --
      -- the entitlement's immutable outer window. Access ended at the window, so no second after it was ever
      -- access, whatever the session row still says.
      v_ceiling := LEAST(p_now, COALESCE(s.ended, p_now),
                         COALESCE(e.window_ends_at, 'infinity'::timestamptz),
                         COALESCE(v_cap, 'infinity'::timestamptz));

      -- First observation: charge nothing, baseline here. A session with no watermark has never been seen by
      -- this path, so the interval since it started is not evidence of anything -- it may have been spent
      -- PENDING_ENFORCEMENT with no forwarding at all.
      IF s.accounted_through IS NULL THEN
        IF EXTRACT(EPOCH FROM (v_ceiling - s.started)) > p_max_charge_seconds THEN
          INSERT INTO iam_v2.online_time_skipped_intervals
            (tenant_id, site_id, session_id, entitlement_id, skipped_from, skipped_to, cause)
          VALUES (p_tenant, p_site, s.id, e.id, s.started, v_ceiling, 'UNOBSERVED_GAP');
        END IF;
        INSERT INTO iam_v2.session_online_watermarks
          (tenant_id, site_id, session_id, accounted_through, accounted_seconds)
        VALUES (p_tenant, p_site, s.id, GREATEST(v_ceiling, s.started), 0)
        ON CONFLICT (session_id) DO NOTHING;
        CONTINUE;
      END IF;

      v_base := s.accounted_through;
      IF v_ceiling <= v_base THEN
        CONTINUE;   -- nothing billable: already charged through, or entirely past the boundary
      END IF;

      -- The observation bound. Anything beyond it was not watched and is recorded rather than charged.
      v_billable := LEAST(v_ceiling, v_base + make_interval(secs => p_max_charge_seconds));
      IF v_billable < v_ceiling THEN
        INSERT INTO iam_v2.online_time_skipped_intervals
          (tenant_id, site_id, session_id, entitlement_id, skipped_from, skipped_to, cause)
        VALUES (p_tenant, p_site, s.id, e.id, v_billable, v_ceiling, 'UNOBSERVED_GAP');
      END IF;

      v_charge := EXTRACT(EPOCH FROM (v_billable - v_base));
      IF v_charge <= 0 THEN
        CONTINUE;
      END IF;

      -- WHOLE SECONDS ONLY, AND THE REMAINDER CARRIES (0126). The budget and the entitlement counter are whole
      -- seconds. This used to floor each tick's charge but still move the watermark to the ceiling, so the
      -- fraction was discarded every tick: with acctd's 1 s tick a slightly short tick charged nothing, and a
      -- 90 s allowance lasted about 180 s of wall time (measured on PRE-LIVE). Now the watermark advances only
      -- by what was charged; the fraction is charged on a later tick. When the observation bound skipped time
      -- (recorded in online_time_skipped_intervals), the watermark still jumps to the ceiling, losing at most
      -- one sub-second remainder per skipped gap.
      v_whole := FLOOR(v_charge)::bigint;
      IF v_billable < v_ceiling THEN
        v_through := v_ceiling;
      ELSE
        v_through := v_base + make_interval(secs => v_whole);
      END IF;
      IF v_whole <= 0 THEN
        IF v_through > v_base THEN   -- only a skipped gap moves an uncharged watermark
          UPDATE iam_v2.session_online_watermarks
             SET accounted_through = v_through, updated_at = now()
           WHERE session_id = s.id;
        END IF;
        CONTINUE;
      END IF;
      v_billable := v_base + make_interval(secs => v_whole);

      INSERT INTO iam_v2.session_online_watermarks
        (tenant_id, site_id, session_id, accounted_through, accounted_seconds)
      VALUES (p_tenant, p_site, s.id, v_through, v_whole)
      ON CONFLICT (session_id) DO UPDATE
        SET accounted_through = EXCLUDED.accounted_through,
            accounted_seconds = iam_v2.session_online_watermarks.accounted_seconds + EXCLUDED.accounted_seconds,
            updated_at = now();

      v_charged := v_charged + v_whole;
      v_starts  := v_starts || v_base;
      v_ends    := v_ends || v_billable;
    END LOOP;

    IF v_charged <= 0 THEN
      CONTINUE;
    END IF;

    IF v_budget IS NOT NULL AND v_before + v_charged >= v_budget THEN
      v_remaining := GREATEST(0, v_budget - v_before);

      -- THE PIECEWISE CROSSING. Every interval boundary is a point where the burn rate changes, so the
      -- budget is walked segment by segment: rate = how many intervals cover the segment, and the crossing
      -- falls inside the first segment whose contribution reaches what was left.
      SELECT array_agg(p ORDER BY p) INTO v_points
        FROM (SELECT DISTINCT unnest(v_starts || v_ends) AS p) x;

      v_acc   := 0;
      v_cross := NULL;
      FOR k IN 1 .. COALESCE(array_length(v_points, 1), 0) - 1 LOOP
        v_p0 := v_points[k];
        v_p1 := v_points[k + 1];
        v_rate := 0;
        FOR i IN 1 .. array_length(v_starts, 1) LOOP
          IF v_starts[i] <= v_p0 AND v_ends[i] >= v_p1 THEN
            v_rate := v_rate + 1;
          END IF;
        END LOOP;
        IF v_rate = 0 THEN
          CONTINUE;   -- a gap: nobody is online, and nothing burns
        END IF;
        v_seg := EXTRACT(EPOCH FROM (v_p1 - v_p0)) * v_rate;
        IF v_acc + v_seg >= v_remaining THEN
          v_cross := v_p0 + make_interval(secs => ((v_remaining - v_acc) / v_rate)::double precision);
          EXIT;
        END IF;
        v_acc := v_acc + v_seg;
      END LOOP;
      IF v_cross IS NULL THEN
        -- Only reachable through floating-point slack at the very last instant; the last boundary is the
        -- honest answer and it is never later than the window or now, both of which capped every interval.
        v_cross := v_points[array_length(v_points, 1)];
      END IF;

      exhausted_at := v_cross;
      UPDATE iam_v2.entitlements
         SET consumed_online_seconds = v_budget, online_time_exhausted_at = v_cross
       WHERE id = e.id;
      entitlement_id := e.id;
      RETURN NEXT;
    ELSE
      UPDATE iam_v2.entitlements
         SET consumed_online_seconds = v_before + FLOOR(v_charged)::bigint
       WHERE id = e.id;
    END IF;
  END LOOP;
END $$;


--
-- Name: FUNCTION p6_tick_online_time(p_tenant uuid, p_site uuid, p_now timestamp with time zone, p_max_charge_seconds integer, p_capped_entitlements uuid[], p_caps timestamp with time zone[]); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.p6_tick_online_time(p_tenant uuid, p_site uuid, p_now timestamp with time zone, p_max_charge_seconds integer, p_capped_entitlements uuid[], p_caps timestamp with time zone[]) IS 'One online-time accrual tick for a site: AGGREGATE_ONLINE_TIME entitlements, and VALIDITY_WINDOW entitlements whose plan carries a time allowance (0122). Billable only to the earliest of now, session end, the immutable outer window and any cap the caller passes; charges only sessions in state active, within the per-tick observation bound. Exhaustion is the exact piecewise crossing, re-reported only with a provable instant. It terminates nothing.';


--
-- Name: payment_account_has_open_checkouts(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.payment_account_has_open_checkouts(p_account uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM iam_v2.payment_transactions pt
                  WHERE pt.merchant_account_id = p_account AND pt.transaction_type = 'CHARGE'
                    AND pt.status IN ('CREATED','PENDING'))
$$;


--
-- Name: payment_account_identity_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.payment_account_identity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF (NEW.provider, NEW.merchant_account_ref, NEW.mode, NEW.currency)
     IS DISTINCT FROM (OLD.provider, OLD.merchant_account_ref, OLD.mode, OLD.currency)
     AND iam_v2.payment_account_has_open_checkouts(OLD.id) THEN
    RAISE EXCEPTION 'PAYMENT_ACCOUNT_CHECKOUTS_OPEN: this account has card checkouts in progress, so its provider, merchant, mode and currency cannot change until they finish. Try again later, or add a new account.'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: payment_account_save(uuid, uuid, uuid, text, text, text, text, text, text, boolean, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.payment_account_save(p_tenant uuid, p_site uuid, p_id uuid, p_provider text, p_merchant_ref text, p_display_name text, p_currency text, p_mode text, p_status text, p_is_default boolean, p_operator text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE v_id uuid; v_old jsonb; v_new jsonb;
BEGIN
  IF p_operator IS NULL OR btrim(p_operator) = '' THEN
    RAISE EXCEPTION 'an operator label is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_provider NOT IN ('stripe','paymob') THEN
    RAISE EXCEPTION 'PAYMENT_PROVIDER_UNSUPPORTED: %', p_provider USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_currency IS NULL OR p_currency !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'a three-letter currency is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('payment_account_save'), hashtext(p_site::text));
  IF p_is_default THEN
    UPDATE iam_v2.payment_provider_accounts SET is_default = false, updated_at = now()
     WHERE tenant_id = p_tenant AND site_id = p_site AND is_default AND id IS DISTINCT FROM p_id;
  END IF;
  IF p_id IS NULL THEN
    INSERT INTO iam_v2.payment_provider_accounts
      (tenant_id, site_id, provider, merchant_account_ref, display_name, currency, mode, status, is_default, provenance)
    VALUES (p_tenant, p_site, p_provider, p_merchant_ref, p_display_name, p_currency, p_mode, p_status, p_is_default, 'CONFIGURED')
    RETURNING id INTO v_id;
  ELSE
    SELECT to_jsonb(a) - 'created_at' - 'updated_at' INTO v_old FROM iam_v2.payment_provider_accounts a
     WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_id FOR UPDATE;
    IF v_old IS NULL THEN
      RAISE EXCEPTION 'PAYMENT_ACCOUNT_UNKNOWN' USING ERRCODE = 'no_data_found';
    END IF;
    UPDATE iam_v2.payment_provider_accounts
       SET provider = p_provider, merchant_account_ref = p_merchant_ref, display_name = p_display_name,
           currency = p_currency, mode = p_mode, status = p_status, is_default = p_is_default,
           provenance = 'CONFIGURED', updated_at = now()
     WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_id
    RETURNING id INTO v_id;
  END IF;
  SELECT to_jsonb(a) - 'created_at' - 'updated_at' INTO v_new FROM iam_v2.payment_provider_accounts a WHERE id = v_id;
  INSERT INTO iam_v2.payment_provider_account_changes
    (tenant_id, site_id, account_id, changed_by, change_reason, change_kind, old_values, new_values)
  VALUES (p_tenant, p_site, v_id, btrim(p_operator), NULLIF(btrim(coalesce(p_reason,'')),''),
          CASE WHEN v_old IS NULL THEN 'CREATED' ELSE 'UPDATED' END, v_old, v_new);
  RETURN v_id;
END $_$;


--
-- Name: payment_account_secret_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.payment_account_secret_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF iam_v2.payment_account_has_open_checkouts(NEW.account_id) THEN
    RAISE EXCEPTION 'PAYMENT_ACCOUNT_CHECKOUTS_OPEN: this account has card checkouts in progress, so its credentials cannot change until they finish. Try again later, or add a new account.'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: payment_account_set_conversion(uuid, uuid, uuid, boolean, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.payment_account_set_conversion(p_tenant uuid, p_site uuid, p_account uuid, p_converts boolean, p_operator text, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE acct record; v_old boolean;
BEGIN
  IF p_operator IS NULL OR btrim(p_operator) = '' THEN
    RAISE EXCEPTION 'an operator label is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT * INTO acct FROM iam_v2.payment_provider_accounts WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_account;
  IF acct.id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_ACCOUNT_UNKNOWN' USING ERRCODE = 'no_data_found';
  END IF;
  -- Only a provider that converts may be told to. Paymob settles in the merchant's currency.
  IF p_converts AND acct.provider <> 'stripe' THEN
    RAISE EXCEPTION 'PAYMENT_CONVERSION_UNSUPPORTED: % does not convert card payments into the account currency',
      acct.provider USING ERRCODE = 'check_violation';
  END IF;
  SELECT provider_converts INTO v_old FROM iam_v2.payment_account_conversion WHERE account_id = p_account FOR UPDATE;
  INSERT INTO iam_v2.payment_account_conversion (account_id, tenant_id, site_id, provider_converts, changed_by)
  VALUES (p_account, p_tenant, p_site, p_converts, btrim(p_operator))
  ON CONFLICT (account_id) DO UPDATE SET provider_converts = EXCLUDED.provider_converts, changed_at = now(),
                                         changed_by = EXCLUDED.changed_by;
  INSERT INTO iam_v2.payment_account_conversion_changes
    (tenant_id, site_id, account_id, changed_by, change_reason, old_value, new_value)
  VALUES (p_tenant, p_site, p_account, btrim(p_operator), NULLIF(btrim(coalesce(p_reason,'')),''), v_old, p_converts);
  RETURN p_converts;
END $$;


--
-- Name: payment_account_set_secret(uuid, uuid, uuid, uuid, bytea, bytea, text, smallint, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.payment_account_set_secret(p_tenant uuid, p_site uuid, p_account uuid, p_generation uuid, p_ciphertext bytea, p_nonce bytea, p_key_id text, p_cipher_version smallint, p_operator text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF p_operator IS NULL OR btrim(p_operator) = '' THEN
    RAISE EXCEPTION 'an operator label is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  PERFORM 1 FROM iam_v2.payment_provider_accounts
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_account FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_ACCOUNT_UNKNOWN' USING ERRCODE = 'no_data_found';
  END IF;
  UPDATE iam_v2.payment_provider_secret_generations SET superseded_at = now()
   WHERE account_id = p_account AND superseded_at IS NULL;
  INSERT INTO iam_v2.payment_provider_secret_generations
    (id, tenant_id, site_id, account_id, ciphertext, nonce, key_id, cipher_version, created_by)
  VALUES (p_generation, p_tenant, p_site, p_account, p_ciphertext, p_nonce, p_key_id, p_cipher_version, btrim(p_operator));
  INSERT INTO iam_v2.payment_provider_account_changes
    (tenant_id, site_id, account_id, changed_by, change_kind, new_values)
  VALUES (p_tenant, p_site, p_account, btrim(p_operator), 'CREDENTIALS_ROTATED',
          jsonb_build_object('generation', p_generation, 'key_id', p_key_id));
END $$;


--
-- Name: payment_checkouts_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.payment_checkouts_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'payment_checkouts rows are never deleted' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.provider_session_ref IS NOT NULL AND NEW.provider_session_ref IS DISTINCT FROM OLD.provider_session_ref THEN
    RAISE EXCEPTION 'PAYMENT_SESSION_REF_IMMUTABLE: a checkout keeps the provider reference it was created with'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.transaction_id <> OLD.transaction_id OR NEW.tenant_id <> OLD.tenant_id OR NEW.site_id <> OLD.site_id
     OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'payment_checkouts identity is immutable' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: pms_accept_startup_data_gap(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_accept_startup_data_gap(p_tenant uuid, p_site uuid, p_event uuid, p_operator text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_iface uuid; v_kind text; v_type text; v_status text; v_res uuid;
BEGIN
    IF p_operator IS NULL OR length(btrim(p_operator)) = 0 THEN
        RAISE EXCEPTION 'accepting a startup data gap requires an operator identity'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF p_reason IS NULL OR length(btrim(p_reason)) = 0 THEN
        RAISE EXCEPTION 'accepting a startup data gap requires a recorded reason'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    SELECT e.pms_interface_id, e.admission_kind, e.event_type, e.processing_status
      INTO v_iface, v_kind, v_type, v_status
      FROM iam_v2.stay_events e
     WHERE e.id = p_event AND e.tenant_id = p_tenant AND e.site_id = p_site;

    IF v_iface IS NULL THEN
        RAISE EXCEPTION 'no such recorded event for this property' USING ERRCODE = 'no_data_found';
    END IF;
    -- Only an unanswered LIVE departure can be a startup gap. A roster snapshot is answered by what it is,
    -- and an applied event was never outstanding.
    IF v_status <> 'MANUAL_REVIEW' OR v_type <> 'GO' OR v_kind <> 'LIVE' THEN
        RAISE EXCEPTION 'only an unanswered live departure can be accepted as a startup data gap '
                        '(this one is % / % / %)', v_status, v_type, v_kind
            USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM iam_v2.pms_case_resolutions x WHERE x.stay_event_id = p_event) THEN
        RAISE EXCEPTION 'this record already carries a disposition; it is not outstanding'
            USING ERRCODE = 'unique_violation';
    END IF;

    INSERT INTO iam_v2.pms_case_resolutions
           (tenant_id, site_id, pms_interface_id, stay_event_id, stay_id, disposition,
            evidence_kind, evidence_ref, resolved_by, note)
    VALUES (p_tenant, p_site, v_iface, p_event, NULL, 'ACCEPTED_STARTUP_DATA_GAP',
            'OPERATOR_DECISION', NULL, btrim(p_operator), btrim(p_reason))
    RETURNING id INTO v_res;

    RETURN v_res;
END;
$$;


--
-- Name: pms_answer_confirmation_record(uuid, uuid, uuid, text, text, text, text, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_answer_confirmation_record(p_tenant uuid, p_site uuid, p_iface uuid, p_as text, p_action text, p_evidence text, p_reason text, p_operator uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'public', 'pg_temp'
    AS $$
DECLARE v_status text; v_id uuid;
BEGIN
  IF p_as NOT IN ('NP','NG','NR','NA','RY') THEN
    RAISE EXCEPTION 'ANSWER_CODE: only NP, NG, NR, NA and RY can be confirmed as definitely not posted' USING ERRCODE = 'check_violation';
  END IF;
  IF p_action NOT IN ('CONFIRM','WITHDRAW') THEN
    RAISE EXCEPTION 'ANSWER_ACTION: CONFIRM or WITHDRAW' USING ERRCODE = 'check_violation';
  END IF;
  IF length(btrim(coalesce(p_evidence,''))) < 20 THEN
    RAISE EXCEPTION 'ANSWER_EVIDENCE: state the vendor confirmation (who, when, document reference)' USING ERRCODE = 'check_violation';
  END IF;
  IF length(btrim(coalesce(p_reason,''))) < 4 THEN
    RAISE EXCEPTION 'ANSWER_REASON: a reason is required' USING ERRCODE = 'check_violation';
  END IF;
  SELECT status INTO v_status FROM public.operators WHERE id = p_operator AND tenant_id = p_tenant;
  IF v_status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'ANSWER_ACTOR: an active operator of this tenant is required' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM iam_v2.pms_interfaces WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_iface
                  AND connector_kind = 'protel-fias') THEN
    RAISE EXCEPTION 'ANSWER_INTERFACE: a FIAS interface of this site is required' USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO iam_v2.pms_answer_confirmations
    (tenant_id, site_id, pms_interface_id, as_status, action, evidence, reason, recorded_by)
  VALUES (p_tenant, p_site, p_iface, p_as, p_action, btrim(p_evidence), btrim(p_reason), p_operator)
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;


--
-- Name: pms_case_resolutions_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_case_resolutions_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE'
       AND current_setting('iam_v2.anonymise', true) = 'retention'
       AND current_user = (SELECT pg_get_userbyid(c.relowner) FROM pg_class c WHERE c.oid = TG_RELID)
       AND NEW.note = 'Removed after the staff-notes period'
       AND (to_jsonb(NEW) - 'note') = (to_jsonb(OLD) - 'note') THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'iam_v2.pms_case_resolutions is append-only: % refused', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: pms_connection_settings_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_connection_settings_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'iam_v2.pms_connection_settings_changes is append-only: % refused', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: pms_connection_settings_get(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_connection_settings_get(p_tenant uuid, p_site uuid, p_interface uuid) RETURNS TABLE(backoff_min_ms integer, backoff_max_ms integer, stable_reset_seconds integer, link_down_alert_seconds integer, blocked_after_refusals integer, config_version bigint, is_default boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
    -- Absence of a row still yields the approved defaults, so a NEWLY CREATED interface reconnects sensibly
    -- before anyone has configured it -- and is_default says truthfully that nobody has.
    SELECT COALESCE(s.backoff_min_ms, 500),
           COALESCE(s.backoff_max_ms, 30000),
           COALESCE(s.stable_reset_seconds, 60),
           COALESCE(s.link_down_alert_seconds, 900),
           COALESCE(s.blocked_after_refusals, 3),
           COALESCE(s.config_version, 0),
           (s.tenant_id IS NULL)
      FROM (SELECT p_tenant AS t, p_site AS s, p_interface AS i) k
      LEFT JOIN iam_v2.pms_connection_settings s
             ON s.tenant_id = k.t AND s.site_id = k.s AND s.pms_interface_id = k.i;
$$;


--
-- Name: pms_connection_settings_set(uuid, uuid, uuid, text, text, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_connection_settings_set(p_tenant uuid, p_site uuid, p_interface uuid, p_operator text, p_reason text DEFAULT NULL::text, p_backoff_min_ms integer DEFAULT NULL::integer, p_backoff_max_ms integer DEFAULT NULL::integer, p_stable_reset_seconds integer DEFAULT NULL::integer, p_link_down_alert_seconds integer DEFAULT NULL::integer, p_blocked_after_refusals integer DEFAULT NULL::integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_old jsonb; v_ver bigint; c record; v_belongs boolean;
BEGIN
    IF p_operator IS NULL OR length(btrim(p_operator)) = 0 THEN
        RAISE EXCEPTION 'connection settings: an operator identity is required'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    -- THE INTERFACE MUST BE THIS SITE'S. Without this an operator scoped to one property could write bounds
    -- onto another property's connection by passing its id, and the foreign key alone would permit it.
    SELECT EXISTS (SELECT 1 FROM iam_v2.pms_interfaces i
                    WHERE i.id = p_interface AND i.tenant_id = p_tenant AND i.site_id = p_site)
      INTO v_belongs;
    IF NOT v_belongs THEN
        RAISE EXCEPTION 'connection settings: interface % does not belong to this site', p_interface
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    -- Serialised PER INTERFACE, which is the point of the whole change: two operators tuning two different
    -- connections no longer queue behind each other.
    PERFORM pg_advisory_xact_lock(hashtext('pms_conn_settings'), hashtext(p_interface::text));
    SELECT to_jsonb(s) INTO v_old FROM iam_v2.pms_connection_settings s
     WHERE s.tenant_id = p_tenant AND s.site_id = p_site AND s.pms_interface_id = p_interface FOR UPDATE;
    SELECT * INTO c FROM iam_v2.pms_connection_settings_get(p_tenant, p_site, p_interface);

    INSERT INTO iam_v2.pms_connection_settings AS s
           (tenant_id, site_id, pms_interface_id, backoff_min_ms, backoff_max_ms, stable_reset_seconds,
            link_down_alert_seconds, blocked_after_refusals, config_version, updated_at)
    VALUES (p_tenant, p_site, p_interface,
            COALESCE(p_backoff_min_ms, c.backoff_min_ms),
            COALESCE(p_backoff_max_ms, c.backoff_max_ms),
            COALESCE(p_stable_reset_seconds, c.stable_reset_seconds),
            COALESCE(p_link_down_alert_seconds, c.link_down_alert_seconds),
            COALESCE(p_blocked_after_refusals, c.blocked_after_refusals), 1, now())
    ON CONFLICT (tenant_id, site_id, pms_interface_id) DO UPDATE
       SET backoff_min_ms = EXCLUDED.backoff_min_ms,
           backoff_max_ms = EXCLUDED.backoff_max_ms,
           stable_reset_seconds = EXCLUDED.stable_reset_seconds,
           link_down_alert_seconds = EXCLUDED.link_down_alert_seconds,
           blocked_after_refusals = EXCLUDED.blocked_after_refusals,
           config_version = s.config_version + 1, updated_at = now()
    RETURNING s.config_version INTO v_ver;

    INSERT INTO iam_v2.pms_connection_settings_changes
           (tenant_id, site_id, pms_interface_id, changed_by, reason, old_values, new_values,
            new_config_version)
    SELECT p_tenant, p_site, p_interface, btrim(p_operator),
           NULLIF(btrim(COALESCE(p_reason,'')),''), v_old,
           to_jsonb(n) - 'tenant_id' - 'site_id' - 'pms_interface_id', v_ver
      FROM iam_v2.pms_connection_settings n
     WHERE n.tenant_id = p_tenant AND n.site_id = p_site AND n.pms_interface_id = p_interface;
    RETURN v_ver;
END;
$$;


--
-- Name: pms_dispose_snapshot_cases(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_dispose_snapshot_cases(p_tenant uuid, p_site uuid, p_iface uuid, p_operator text, p_note text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_n integer;
BEGIN
    IF p_operator IS NULL OR length(btrim(p_operator)) = 0 THEN
        RAISE EXCEPTION 'case disposition: an operator identity is required'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    INSERT INTO iam_v2.pms_case_resolutions
        (tenant_id, site_id, pms_interface_id, stay_event_id, disposition, evidence_kind, evidence_ref,
         resolved_by, note)
    SELECT e.tenant_id, e.site_id, e.pms_interface_id, e.id,
           'NOT_A_DEPARTURE_ROSTER_SNAPSHOT', 'ADMISSION_KIND',
           'RESYNC generation ' || e.resync_generation::text,
           btrim(p_operator), NULLIF(btrim(COALESCE(p_note,'')),'')
      FROM iam_v2.stay_events e
     WHERE e.tenant_id = p_tenant AND e.site_id = p_site AND e.pms_interface_id = p_iface
       AND e.event_type = 'GO'
       AND e.processing_status = 'MANUAL_REVIEW'
       AND e.admission_kind = 'RESYNC'
       AND btrim(COALESCE(e.payload->>'reservation','')) = ''
    ON CONFLICT (stay_event_id) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n;
END;
$$;


--
-- Name: pms_financial_onboardings_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_financial_onboardings_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'iam_v2.pms_financial_onboardings is append-only: % refused', TG_OP USING ERRCODE = 'restrict_violation';
END $$;


--
-- Name: pms_integration_blockers(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_integration_blockers(p_tenant uuid, p_site uuid) RETURNS TABLE(blocker text, since timestamp with time zone, detail text, guests_affected boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
    -- LINK_DOWN is now judged per interface. It already iterated the runtime rows, one per interface, and
    -- then compared every one of them against a single site-wide threshold -- so a patient connection's
    -- tolerance decided when an impatient one was called down. The lateral now takes the interface from the
    -- runtime row it is judging, which is the only reading that survives a second connection.
    SELECT 'LINK_DOWN'::text,
           r.disconnected_since,
           'The PMS link has been down since then. Guests continue to be authorised from the last good '
             || 'roster; new arrivals and departures are not being seen.',
           false
      FROM iam_v2.pms_interface_runtime r,
           LATERAL iam_v2.pms_connection_settings_get(r.tenant_id, r.site_id, r.pms_interface_id) s
     WHERE r.tenant_id = p_tenant AND r.site_id = p_site
       AND r.transport_status = 'DISCONNECTED'
       AND r.disconnected_since IS NOT NULL
       AND r.disconnected_since < now() - make_interval(secs => s.link_down_alert_seconds)

    UNION ALL

    -- RECONCILIATION_BLOCKED stays a SITE-level fact, deliberately. Reconciliation reconciles the property's
    -- mirror against the roster; pms_roster_reconciliation_runs is keyed by site and has no interface column,
    -- so there is no per-interface run to threshold. Where several interfaces disagree on how many refusals
    -- are too many, the most patient one wins: reporting at the strictest threshold would raise a blocker
    -- about the whole property on the say-so of its twitchiest connection.
    SELECT 'RECONCILIATION_BLOCKED'::text,
           min(x.run_at),
           'Roster reconciliation has refused ' || count(*)::text || ' times in a row ('
             || max(x.outcome) || '). Departures are not being closed automatically until the PMS sends a '
             || 'complete, uncontradicted roster.',
           false
      FROM (SELECT run_at, outcome
              FROM iam_v2.pms_roster_reconciliation_runs
             WHERE tenant_id = p_tenant AND site_id = p_site AND mode = 'APPLY'
             ORDER BY run_at DESC
             LIMIT (SELECT iam_v2.pms_site_blocked_after_refusals(p_tenant, p_site))
           ) x
     HAVING count(*) = (SELECT iam_v2.pms_site_blocked_after_refusals(p_tenant, p_site))
        AND count(*) FILTER (WHERE x.outcome = 'COMPLETED') = 0

    UNION ALL

    -- The historical exception. Unlike the two above it does NOT clear itself, and it is the only one an
    -- operator may reasonably decide to leave exactly where it is.
    SELECT 'DEPARTURE_FOR_UNKNOWN_STAY'::text,
           min(e.received_at),
           'HISTORICAL EXCEPTION, not a fault and not something that will clear on its own. '
             || count(*)::text || ' departure(s) from before this appliance had a complete picture of the '
             || 'property name a reservation it never received an arrival for. Guests are unaffected. Only '
             || 'the PMS can say whether those stays existed; nothing local can place them without inventing '
             || 'the arrival, so this stays on the list until somebody asks Protel or records a decision to '
             || 'leave it.',
           false
      FROM iam_v2.stay_events e
     WHERE e.tenant_id = p_tenant AND e.site_id = p_site
       AND e.processing_status = 'MANUAL_REVIEW'
       AND e.event_type = 'GO'
       AND e.admission_kind = 'LIVE'
       AND NOT EXISTS (SELECT 1 FROM iam_v2.pms_case_resolutions x WHERE x.stay_event_id = e.id)
     HAVING count(*) > 0;
$$;


--
-- Name: pms_interface_financial_onboard(uuid, uuid, uuid, uuid, text, text, smallint, text, text, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_interface_financial_onboard(p_tenant uuid, p_site uuid, p_iface uuid, p_expected_revision uuid, p_target_model text, p_currency text, p_exponent smallint, p_attestation text, p_reason text, p_operator uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'public', 'pg_temp'
    AS $_$
DECLARE v_current uuid; v_kind text; v_new uuid; v_status text;
BEGIN
  IF p_target_model IS DISTINCT FROM 'RESERVATION' THEN
    RAISE EXCEPTION 'ONBOARDING_TARGET: the posting target must be RESERVATION (RN + G#)' USING ERRCODE = 'check_violation';
  END IF;
  IF p_currency IS NULL OR p_currency !~ '^[A-Z]{3}$' OR p_exponent IS NULL OR p_exponent NOT BETWEEN 0 AND 4 THEN
    RAISE EXCEPTION 'ONBOARDING_CURRENCY: a three-letter currency and an exponent 0..4 are required' USING ERRCODE = 'check_violation';
  END IF;
  IF length(btrim(coalesce(p_attestation,''))) < 20 THEN
    RAISE EXCEPTION 'ONBOARDING_ATTESTATION: state the vendor confirmation that reservation numbers are unique and never reused' USING ERRCODE = 'check_violation';
  END IF;
  IF length(btrim(coalesce(p_reason,''))) < 4 THEN
    RAISE EXCEPTION 'ONBOARDING_REASON: a reason is required' USING ERRCODE = 'check_violation';
  END IF;
  SELECT status INTO v_status FROM public.operators WHERE id = p_operator AND tenant_id = p_tenant;
  IF v_status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'ONBOARDING_ACTOR: an active operator of this tenant must approve onboarding' USING ERRCODE = 'check_violation';
  END IF;
  SELECT current_revision_id, connector_kind INTO v_current, v_kind FROM iam_v2.pms_interfaces
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_iface FOR UPDATE;
  IF v_current IS NULL THEN
    RAISE EXCEPTION 'ONBOARDING_INTERFACE: no published revision for this interface' USING ERRCODE = 'no_data_found';
  END IF;
  IF v_current IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'ONBOARDING_REVISION_CONFLICT: the interface changed while this form was open' USING ERRCODE = 'serialization_failure';
  END IF;
  IF v_kind <> 'protel-fias' THEN
    RAISE EXCEPTION 'ONBOARDING_CONNECTOR: room charge is supported for FIAS interfaces only' USING ERRCODE = 'check_violation';
  END IF;
  IF p_exponent <> 2 THEN
    RAISE EXCEPTION 'ONBOARDING_EXPONENT: FIAS transmits amounts with exponent 2' USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO iam_v2.pms_interface_revisions
    (tenant_id, site_id, pms_interface_id, revision_no, source_timezone, posting_target_model, config,
     normalization_version, source_fingerprint, financial_base_currency, financial_base_currency_exponent)
  SELECT r.tenant_id, r.site_id, r.pms_interface_id,
         (SELECT COALESCE(MAX(x.revision_no),0)+1 FROM iam_v2.pms_interface_revisions x
           WHERE x.tenant_id = r.tenant_id AND x.site_id = r.site_id AND x.pms_interface_id = r.pms_interface_id),
         r.source_timezone, 'RESERVATION', r.config, r.normalization_version, r.source_fingerprint, p_currency, p_exponent
    FROM iam_v2.pms_interface_revisions r WHERE r.id = v_current
  RETURNING id INTO v_new;
  UPDATE iam_v2.pms_interfaces SET current_revision_id = v_new
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_iface;
  INSERT INTO iam_v2.pms_financial_onboardings
    (tenant_id, site_id, pms_interface_id, revision_id, previous_revision_id, posting_target_model, currency,
     currency_exponent, attestation, reason, approved_by)
  VALUES (p_tenant, p_site, p_iface, v_new, v_current, 'RESERVATION', p_currency, p_exponent, btrim(p_attestation),
          btrim(p_reason), p_operator);
  RETURN v_new;
END $_$;


--
-- Name: pms_interface_financially_ready(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_interface_financially_ready(p_tenant uuid, p_site uuid, p_iface uuid) RETURNS TABLE(ready boolean, reason text, currency character, currency_exponent smallint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE i record; r record;
BEGIN
  SELECT * INTO i FROM iam_v2.pms_interfaces WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_iface;
  IF i.id IS NULL THEN ready := false; reason := 'INTERFACE_UNKNOWN'; RETURN NEXT; RETURN; END IF;
  IF i.connector_kind <> 'protel-fias' THEN ready := false; reason := 'CONNECTOR_NOT_FINANCIAL'; RETURN NEXT; RETURN; END IF;
  IF i.lifecycle_state NOT IN ('ACTIVE','AUTH_DISABLED') THEN ready := false; reason := 'INTERFACE_NOT_ACTIVE'; RETURN NEXT; RETURN; END IF;
  SELECT * INTO r FROM iam_v2.pms_interface_revisions WHERE id = i.current_revision_id;
  currency := r.financial_base_currency; currency_exponent := r.financial_base_currency_exponent;
  IF r.posting_target_model <> 'RESERVATION' OR r.financial_base_currency IS NULL THEN
    ready := false; reason := 'NOT_ONBOARDED'; RETURN NEXT; RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM iam_v2.pms_financial_onboardings o WHERE o.revision_id = r.id) THEN
    ready := false; reason := 'ONBOARDING_NOT_APPROVED'; RETURN NEXT; RETURN;
  END IF;
  ready := true; reason := NULL; RETURN NEXT;
END $$;


--
-- Name: pms_interface_has_undrained_postings(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_interface_has_undrained_postings(p_tenant uuid, p_site uuid, p_iface uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
    -- The same set the decommission gate (p4_interface_decommission_gate) refuses on: work that was authorized
    -- and has not reached a terminal answer. While any exists, wind down keeps the link to the PMS.
    SELECT EXISTS (SELECT 1 FROM iam_v2.posting_outbox o
                    WHERE o.tenant_id = p_tenant AND o.site_id = p_site AND o.pms_interface_id = p_iface
                      AND o.state IN ('QUEUED','IN_FLIGHT','HELD_RECOVERY'))
        OR EXISTS (SELECT 1 FROM iam_v2.posting_attempts a
                    WHERE a.tenant_id = p_tenant AND a.site_id = p_site AND a.pms_interface_id = p_iface
                      AND a.outcome IN ('SENDING','UNKNOWN'));
$$;


--
-- Name: pms_known_room_inventory(uuid, uuid, uuid, bigint, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_known_room_inventory(p_tenant uuid, p_site uuid, p_iface uuid, p_generation bigint, p_lookback integer) RETURNS TABLE(room text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
    SELECT unnest(i.rooms) FROM iam_v2.pms_room_inventory i
     WHERE i.tenant_id = p_tenant AND i.site_id = p_site AND i.pms_interface_id = p_iface;
$$;


--
-- Name: pms_rebaseline_room_inventory(uuid, uuid, uuid, bigint, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_rebaseline_room_inventory(p_tenant uuid, p_site uuid, p_iface uuid, p_generation bigint, p_operator text, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_rooms text[]; v_before text[]; v_ver bigint; v_conflicts int;
BEGIN
    IF p_operator IS NULL OR length(btrim(p_operator)) = 0 THEN
        RAISE EXCEPTION 'room inventory: an operator identity is required'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF p_reason IS NULL OR length(btrim(p_reason)) = 0 THEN
        RAISE EXCEPTION 'room inventory: shrinking the known building requires a recorded reason'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    SELECT c.rooms, c.conflicting_rooms INTO v_rooms, v_conflicts
      FROM iam_v2.pms_resync_coverage c
     WHERE c.tenant_id = p_tenant AND c.site_id = p_site AND c.pms_interface_id = p_iface
       AND c.resync_generation = p_generation;
    IF v_rooms IS NULL THEN
        RAISE EXCEPTION 'room inventory: generation % has no recorded observation to adopt', p_generation
            USING ERRCODE = 'no_data_found';
    END IF;
    IF v_conflicts > 0 THEN
        RAISE EXCEPTION 'room inventory: generation % contradicted itself and cannot define the building',
            p_generation USING ERRCODE = 'check_violation';
    END IF;

    SELECT i.rooms INTO v_before FROM iam_v2.pms_room_inventory i
     WHERE i.tenant_id = p_tenant AND i.site_id = p_site AND i.pms_interface_id = p_iface FOR UPDATE;

    INSERT INTO iam_v2.pms_room_inventory AS i
           (tenant_id, site_id, pms_interface_id, rooms, established_from, config_version)
    VALUES (p_tenant, p_site, p_iface, v_rooms, p_generation, 1)
    ON CONFLICT (tenant_id, site_id, pms_interface_id) DO UPDATE
       SET rooms = EXCLUDED.rooms, established_from = p_generation,
           updated_at = now(), config_version = i.config_version + 1
    RETURNING i.config_version INTO v_ver;

    INSERT INTO iam_v2.pms_room_inventory_changes
           (tenant_id, site_id, pms_interface_id, changed_by, reason, change_kind,
            rooms_before, rooms_after, removed, added, new_config_version)
    VALUES (p_tenant, p_site, p_iface, btrim(p_operator), btrim(p_reason), 'REBASELINED',
            COALESCE(array_length(v_before,1),0), COALESCE(array_length(v_rooms,1),0),
            COALESCE(ARRAY(SELECT unnest(v_before) EXCEPT SELECT unnest(v_rooms)), '{}'),
            COALESCE(ARRAY(SELECT unnest(v_rooms) EXCEPT SELECT unnest(COALESCE(v_before,'{}'))), '{}'),
            v_ver);
    RETURN COALESCE(array_length(v_rooms,1),0);
END;
$$;


--
-- Name: pms_reconciliation_settings_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_reconciliation_settings_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'iam_v2.pms_reconciliation_settings_changes is append-only: % refused', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: pms_reconciliation_settings_get(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_reconciliation_settings_get(p_tenant uuid, p_site uuid) RETURNS TABLE(roster_trust_min integer, inventory_tolerance integer, inventory_lookback integer, max_close_per_run integer, config_version bigint, is_default boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
    SELECT COALESCE(s.roster_trust_min, 50),
           COALESCE(s.inventory_tolerance, 2),
           COALESCE(s.inventory_lookback, 10),
           COALESCE(s.max_close_per_run, 500),
           COALESCE(s.config_version, 0),
           (s.tenant_id IS NULL)
      FROM (SELECT p_tenant AS t, p_site AS s) k
      LEFT JOIN iam_v2.pms_reconciliation_settings s ON s.tenant_id = k.t AND s.site_id = k.s;
$$;


--
-- Name: pms_reconciliation_settings_set(uuid, uuid, integer, integer, text, text, integer, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_reconciliation_settings_set(p_tenant uuid, p_site uuid, p_floor integer, p_cap integer, p_operator text, p_reason text DEFAULT NULL::text, p_tolerance integer DEFAULT NULL::integer, p_lookback integer DEFAULT NULL::integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_old jsonb; v_ver bigint;
BEGIN
    IF p_operator IS NULL OR length(btrim(p_operator)) = 0 THEN
        RAISE EXCEPTION 'reconciliation settings: an operator identity is required'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtext('pms_recon_settings'), hashtext(p_site::text));
    SELECT to_jsonb(s) INTO v_old FROM iam_v2.pms_reconciliation_settings s
     WHERE s.tenant_id = p_tenant AND s.site_id = p_site FOR UPDATE;

    INSERT INTO iam_v2.pms_reconciliation_settings AS s
           (tenant_id, site_id, roster_trust_min, max_close_per_run,
            inventory_tolerance, inventory_lookback, config_version, updated_at)
    VALUES (p_tenant, p_site, p_floor, p_cap,
            COALESCE(p_tolerance, 2), COALESCE(p_lookback, 10), 1, now())
    ON CONFLICT (tenant_id, site_id) DO UPDATE
       SET roster_trust_min = EXCLUDED.roster_trust_min,
           max_close_per_run = EXCLUDED.max_close_per_run,
           inventory_tolerance = COALESCE(p_tolerance, s.inventory_tolerance),
           inventory_lookback = COALESCE(p_lookback, s.inventory_lookback),
           config_version = s.config_version + 1, updated_at = now()
    RETURNING s.config_version INTO v_ver;

    INSERT INTO iam_v2.pms_reconciliation_settings_changes
           (tenant_id, site_id, changed_by, reason, old_values, new_values, new_config_version)
    VALUES (p_tenant, p_site, btrim(p_operator), NULLIF(btrim(COALESCE(p_reason,'')),''), v_old,
            jsonb_build_object('roster_trust_min', p_floor, 'max_close_per_run', p_cap,
                               'inventory_tolerance', p_tolerance, 'inventory_lookback', p_lookback), v_ver);
    RETURN v_ver;
END;
$$;


--
-- Name: pms_reconciliation_settings_set_checked(uuid, uuid, bigint, integer, integer, integer, integer, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_reconciliation_settings_set_checked(p_tenant uuid, p_site uuid, p_expected_version bigint, p_floor integer, p_cap integer, p_tolerance integer, p_lookback integer, p_operator text, p_reason text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_cur bigint;
BEGIN
    IF p_operator IS NULL OR length(btrim(p_operator)) = 0 THEN
        RAISE EXCEPTION 'RECON_SETTINGS_ACTOR: an operator identity is required' USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF p_reason IS NULL OR length(btrim(p_reason)) < 3 OR length(p_reason) > 500 THEN
        RAISE EXCEPTION 'RECON_SETTINGS_REASON: a reason of 3 to 500 characters is required' USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF p_floor IS NULL OR p_floor < 1 OR p_floor > 100000 THEN
        RAISE EXCEPTION 'RECON_SETTINGS_BOUNDS: the minimum roster size must be between 1 and 100000' USING ERRCODE = 'check_violation';
    END IF;
    IF p_cap IS NULL OR p_cap < 1 OR p_cap > 100000 THEN
        RAISE EXCEPTION 'RECON_SETTINGS_BOUNDS: the most stays one run may close must be between 1 and 100000' USING ERRCODE = 'check_violation';
    END IF;
    IF p_tolerance IS NULL OR p_tolerance < 0 OR p_tolerance > 10000 THEN
        RAISE EXCEPTION 'RECON_SETTINGS_BOUNDS: the room tolerance must be between 0 and 10000' USING ERRCODE = 'check_violation';
    END IF;
    IF p_lookback IS NULL OR p_lookback < 1 OR p_lookback > 1000 THEN
        RAISE EXCEPTION 'RECON_SETTINGS_BOUNDS: the inventory look-back must be between 1 and 1000 sweeps' USING ERRCODE = 'check_violation';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtext('pms_recon_settings'), hashtext(p_site::text));
    SELECT g.config_version INTO v_cur FROM iam_v2.pms_reconciliation_settings_get(p_tenant, p_site) g;
    IF p_expected_version IS NULL OR v_cur IS DISTINCT FROM p_expected_version THEN
        RAISE EXCEPTION 'RECON_SETTINGS_VERSION_CONFLICT: the settings changed (now version %); reload and try again', v_cur
            USING ERRCODE = 'serialization_failure';
    END IF;
    RETURN iam_v2.pms_reconciliation_settings_set(p_tenant, p_site, p_floor, p_cap, p_operator, btrim(p_reason),
                                                   p_tolerance, p_lookback);
END;
$$;


--
-- Name: pms_record_resync_coverage(uuid, uuid, uuid, bigint, text[], integer, integer, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_record_resync_coverage(p_tenant uuid, p_site uuid, p_iface uuid, p_generation bigint, p_rooms text[], p_roster integer, p_vacant integer, p_conflicts integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
    INSERT INTO iam_v2.pms_resync_coverage AS c
        (tenant_id, site_id, pms_interface_id, resync_generation,
         rooms_named, roster_records, vacant_rooms, rooms, conflicting_rooms)
    VALUES (p_tenant, p_site, p_iface, p_generation,
            COALESCE(array_length(p_rooms, 1), 0), p_roster, p_vacant,
            COALESCE(p_rooms, '{}'), COALESCE(p_conflicts, 0))
    ON CONFLICT (tenant_id, site_id, pms_interface_id, resync_generation) DO UPDATE
       SET rooms_named       = COALESCE(array_length(EXCLUDED.rooms, 1), 0),
           roster_records    = EXCLUDED.roster_records,
           vacant_rooms      = EXCLUDED.vacant_rooms,
           rooms             = EXCLUDED.rooms,
           conflicting_rooms = EXCLUDED.conflicting_rooms,
           observed_at       = now();

    -- Bounded history. One row per sweep and this property resyncs constantly, so without this the table
    -- grows for ever to answer a question that only ever looks at recent generations.
    DELETE FROM iam_v2.pms_resync_coverage d
     WHERE d.tenant_id = p_tenant AND d.site_id = p_site AND d.pms_interface_id = p_iface
       AND d.resync_generation <= p_generation - 500;
END;
$$;


--
-- Name: pms_review_decide(uuid, uuid, uuid, text, uuid, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_review_decide(p_tenant uuid, p_site uuid, p_event uuid, p_action text, p_stay uuid, p_operator text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_iface uuid; v_status text; v_res uuid; v_match text;
BEGIN
    IF p_operator IS NULL OR length(btrim(p_operator)) = 0 THEN
        RAISE EXCEPTION 'REVIEW_ACTOR: an operator identity is required' USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF p_reason IS NULL OR length(btrim(p_reason)) < 3 OR length(p_reason) > 500 THEN
        RAISE EXCEPTION 'REVIEW_REASON: a reason of 3 to 500 characters is required' USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF p_action NOT IN ('ACKNOWLEDGE','LINK') THEN
        RAISE EXCEPTION 'REVIEW_ACTION: ACKNOWLEDGE or LINK' USING ERRCODE = 'invalid_parameter_value';
    END IF;

    SELECT e.pms_interface_id, e.processing_status INTO v_iface, v_status
      FROM iam_v2.stay_events e
     WHERE e.id = p_event AND e.tenant_id = p_tenant AND e.site_id = p_site
       FOR SHARE;
    IF v_iface IS NULL THEN
        RAISE EXCEPTION 'REVIEW_NOT_FOUND: no such PMS message on this property' USING ERRCODE = 'no_data_found';
    END IF;
    IF v_status <> 'MANUAL_REVIEW' THEN
        RAISE EXCEPTION 'REVIEW_NOT_WAITING: this message is % and needs no decision', v_status USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM iam_v2.pms_case_resolutions x WHERE x.stay_event_id = p_event) THEN
        RAISE EXCEPTION 'REVIEW_ALREADY_DECIDED: this message already carries a decision' USING ERRCODE = 'unique_violation';
    END IF;

    IF p_action = 'ACKNOWLEDGE' THEN
        INSERT INTO iam_v2.pms_case_resolutions
               (tenant_id, site_id, pms_interface_id, stay_event_id, stay_id, disposition,
                evidence_kind, evidence_ref, resolved_by, note)
        VALUES (p_tenant, p_site, v_iface, p_event, NULL, 'ACKNOWLEDGED_BY_OPERATOR',
                'OPERATOR_DECISION', NULL, btrim(p_operator), btrim(p_reason))
        RETURNING id INTO v_res;
        RETURN v_res;
    END IF;

    IF p_stay IS NULL THEN
        RAISE EXCEPTION 'REVIEW_STAY_REQUIRED: choose the stay this message is about' USING ERRCODE = 'invalid_parameter_value';
    END IF;
    SELECT c.matched_by INTO v_match
      FROM iam_v2.pms_review_link_candidates(p_tenant, p_site, p_event) c WHERE c.stay_id = p_stay;
    IF v_match IS NULL THEN
        RAISE EXCEPTION 'REVIEW_NOT_MATCHABLE: this message cannot be matched to that stay (different connection, reservation or room)'
            USING ERRCODE = 'check_violation';
    END IF;
    INSERT INTO iam_v2.pms_case_resolutions
           (tenant_id, site_id, pms_interface_id, stay_event_id, stay_id, disposition,
            evidence_kind, evidence_ref, resolved_by, note)
    VALUES (p_tenant, p_site, v_iface, p_event, p_stay, 'LINKED_TO_STAY',
            'OPERATOR_DECISION', 'matched by ' || lower(v_match), btrim(p_operator), btrim(p_reason))
    RETURNING id INTO v_res;
    RETURN v_res;
END;
$$;


--
-- Name: pms_review_expire_due(uuid, uuid, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_review_expire_due(p_tenant uuid, p_site uuid, p_limit integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_on boolean; v_days int; v_from timestamptz; v_ver bigint; v_n int := 0;
BEGIN
    SELECT s.enabled, s.expire_after_days, s.applies_from, s.config_version INTO v_on, v_days, v_from, v_ver
      FROM iam_v2.pms_review_expiry_settings s WHERE s.tenant_id = p_tenant AND s.site_id = p_site;
    IF NOT COALESCE(v_on, false) OR v_from IS NULL THEN
        RETURN 0;
    END IF;
    INSERT INTO iam_v2.pms_case_resolutions
           (tenant_id, site_id, pms_interface_id, stay_event_id, stay_id, disposition,
            evidence_kind, evidence_ref, resolved_by, note)
    SELECT e.tenant_id, e.site_id, e.pms_interface_id, e.id, NULL, 'EXPIRED_UNDECIDED',
           'EXPIRY_SETTING', 'setting version ' || v_ver::text || ', after ' || v_days::text || ' days',
           'automatic expiry', NULL
      FROM iam_v2.stay_events e
     WHERE e.tenant_id = p_tenant AND e.site_id = p_site
       AND e.processing_status = 'MANUAL_REVIEW'
       AND e.received_at >= v_from
       AND e.received_at < now() - make_interval(days => v_days)
       AND NOT EXISTS (SELECT 1 FROM iam_v2.pms_case_resolutions x WHERE x.stay_event_id = e.id)
     ORDER BY e.received_at
     LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 500), 5000))
    ON CONFLICT (stay_event_id) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n;
END;
$$;


--
-- Name: pms_review_expiry_settings_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_review_expiry_settings_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'iam_v2.pms_review_expiry_settings_changes is append-only: % refused', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: pms_review_expiry_settings_get(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_review_expiry_settings_get(p_tenant uuid, p_site uuid) RETURNS TABLE(enabled boolean, expire_after_days integer, applies_from timestamp with time zone, config_version bigint, is_default boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
    SELECT COALESCE(s.enabled, false), COALESCE(s.expire_after_days, 30), s.applies_from,
           COALESCE(s.config_version, 0), (s.tenant_id IS NULL)
      FROM (SELECT p_tenant AS t, p_site AS si) k
      LEFT JOIN iam_v2.pms_review_expiry_settings s ON s.tenant_id = k.t AND s.site_id = k.si;
$$;


--
-- Name: pms_review_expiry_settings_set(uuid, uuid, bigint, boolean, integer, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_review_expiry_settings_set(p_tenant uuid, p_site uuid, p_expected_version bigint, p_enabled boolean, p_days integer, p_operator text, p_reason text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_old jsonb; v_cur bigint; v_was boolean; v_from timestamptz; v_ver bigint;
BEGIN
    IF p_operator IS NULL OR length(btrim(p_operator)) = 0 THEN
        RAISE EXCEPTION 'REVIEW_EXPIRY_ACTOR: an operator identity is required' USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF p_reason IS NULL OR length(btrim(p_reason)) < 3 OR length(p_reason) > 500 THEN
        RAISE EXCEPTION 'REVIEW_EXPIRY_REASON: a reason of 3 to 500 characters is required' USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF p_enabled IS NULL OR p_days IS NULL OR p_days < 1 OR p_days > 365 THEN
        RAISE EXCEPTION 'REVIEW_EXPIRY_BOUNDS: the waiting period must be between 1 and 365 days' USING ERRCODE = 'check_violation';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtext('pms_review_expiry'), hashtext(p_site::text));
    SELECT to_jsonb(s), s.config_version, s.enabled, s.applies_from INTO v_old, v_cur, v_was, v_from
      FROM iam_v2.pms_review_expiry_settings s
     WHERE s.tenant_id = p_tenant AND s.site_id = p_site FOR UPDATE;
    IF p_expected_version IS NULL OR COALESCE(v_cur, 0) <> p_expected_version THEN
        RAISE EXCEPTION 'REVIEW_EXPIRY_VERSION_CONFLICT: the setting changed (now version %); reload and try again', COALESCE(v_cur,0)
            USING ERRCODE = 'serialization_failure';
    END IF;
    -- Switching ON starts the clock now; staying on keeps it; switching off clears it.
    IF p_enabled AND NOT COALESCE(v_was, false) THEN
        v_from := now();
    ELSIF NOT p_enabled THEN
        v_from := NULL;
    END IF;
    INSERT INTO iam_v2.pms_review_expiry_settings AS s
           (tenant_id, site_id, enabled, expire_after_days, applies_from, config_version, updated_at)
    VALUES (p_tenant, p_site, p_enabled, p_days, v_from, 1, now())
    ON CONFLICT (tenant_id, site_id) DO UPDATE
       SET enabled = EXCLUDED.enabled, expire_after_days = EXCLUDED.expire_after_days,
           applies_from = EXCLUDED.applies_from,
           config_version = s.config_version + 1, updated_at = now()
    RETURNING s.config_version INTO v_ver;
    INSERT INTO iam_v2.pms_review_expiry_settings_changes
           (tenant_id, site_id, changed_by, reason, old_values, new_values, new_config_version)
    VALUES (p_tenant, p_site, btrim(p_operator), btrim(p_reason), v_old,
            jsonb_build_object('enabled', p_enabled, 'expire_after_days', p_days, 'applies_from', v_from), v_ver);
    RETURN v_ver;
END;
$$;


--
-- Name: pms_review_link_candidates(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_review_link_candidates(p_tenant uuid, p_site uuid, p_event uuid) RETURNS TABLE(stay_id uuid, matched_by text, room text, status text, arrival date, departure date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
    WITH ev AS (
        SELECT e.tenant_id, e.site_id, e.pms_interface_id, e.received_at,
               btrim(COALESCE(e.payload->>'reservation','')) AS res,
               upper(btrim(COALESCE(e.payload->>'room',''))) AS room
          FROM iam_v2.stay_events e
         WHERE e.id = p_event AND e.tenant_id = p_tenant AND e.site_id = p_site
           AND e.processing_status = 'MANUAL_REVIEW')
    SELECT s.id, 'RESERVATION', s.normalized_room_number, s.status, s.arrival::date, s.departure::date
      FROM ev JOIN iam_v2.stays s
        ON s.tenant_id = ev.tenant_id AND s.site_id = ev.site_id AND s.pms_interface_id = ev.pms_interface_id
     WHERE ev.res <> '' AND btrim(s.external_reservation_id) = ev.res
    UNION ALL
    -- A message that names no reservation is about a ROOM. The stays it can be about are the ones that were in
    -- that room when it arrived: arrived by then, and not checked out before it.
    SELECT s.id, 'ROOM', s.normalized_room_number, s.status, s.arrival::date, s.departure::date
      FROM ev JOIN iam_v2.stays s
        ON s.tenant_id = ev.tenant_id AND s.site_id = ev.site_id AND s.pms_interface_id = ev.pms_interface_id
     WHERE ev.res = '' AND ev.room <> '' AND s.normalized_room_number = ev.room
       AND (s.arrival IS NULL OR s.arrival <= ev.received_at)
       AND (s.effective_checkout_at IS NULL OR s.effective_checkout_at >= ev.received_at)
     ORDER BY 2, 4, 5 DESC
     LIMIT 50;
$$;


--
-- Name: pms_room_inventory_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_room_inventory_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'iam_v2.pms_room_inventory_changes is append-only: % refused', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: pms_roster_of_generation(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_roster_of_generation(p_tenant uuid, p_site uuid, p_iface uuid, p_generation bigint) RETURNS TABLE(reservation text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
    SELECT DISTINCT btrim(e.payload->>'reservation')
      FROM iam_v2.stay_events e
     WHERE e.tenant_id = p_tenant AND e.site_id = p_site AND e.pms_interface_id = p_iface
       AND e.resync_generation = p_generation
       AND e.event_type IN ('GI','GC')
       AND btrim(COALESCE(e.payload->>'reservation','')) <> '';
$$;


--
-- Name: pms_roster_reconcile(uuid, uuid, uuid, bigint, text, boolean, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_roster_reconcile(p_tenant uuid, p_site uuid, p_iface uuid, p_generation bigint, p_operator text, p_apply boolean DEFAULT false, p_reason text DEFAULT NULL::text) RETURNS TABLE(outcome text, roster_size integer, mirror_in_house integer, absent_from_roster integer, stays_closed integer, rooms_enumerated integer, rooms_expected integer, protected integer, run_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
    v_floor int; v_cap int; v_tol int; v_look int;
    v_roster int; v_mirror int; v_absent int; v_closed int := 0; v_protected int := 0;
    v_rooms int; v_expected int := 0; v_missing int := 0; v_conflicts int := 0;
    v_have boolean := false; v_swept text[]; v_known text[]; v_added text[];
    v_published bigint; v_boundary timestamptz; v_run uuid; v_outcome text;
    v_sync text; v_cont text; v_scope int; v_ver bigint; v_norm int;
BEGIN
    IF p_operator IS NULL OR length(btrim(p_operator)) = 0 THEN
        RAISE EXCEPTION 'roster reconciliation: an operator identity is required'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtext('pms_roster_reconcile'), hashtext(p_iface::text));

    SELECT s.roster_trust_min, s.max_close_per_run, s.inventory_tolerance, s.inventory_lookback
      INTO v_floor, v_cap, v_tol, v_look
      FROM iam_v2.pms_reconciliation_settings_get(p_tenant, p_site) s;

    SELECT count(*) INTO v_scope FROM iam_v2.pms_interfaces i
     WHERE i.id = p_iface AND i.tenant_id = p_tenant AND i.site_id = p_site;

    SELECT r.published_resync_generation, r.sync_status, r.continuity_status,
           COALESCE((SELECT rv.normalization_version FROM iam_v2.pms_interface_revisions rv
                      WHERE rv.id = r.pinned_revision_id), 1)
      INTO v_published, v_sync, v_cont, v_norm
      FROM iam_v2.pms_interface_runtime r
     WHERE r.tenant_id = p_tenant AND r.site_id = p_site AND r.pms_interface_id = p_iface;

    -- The boundary is the roster's own: the latest record the PMS sent in this generation. The checkouts this
    -- function queues are admitted under the same generation and are excluded here, so re-running a generation
    -- measures the same roster it measured the first time.
    SELECT max(e.received_at) INTO v_boundary
      FROM iam_v2.stay_events e
     WHERE e.tenant_id = p_tenant AND e.site_id = p_site AND e.pms_interface_id = p_iface
       AND e.resync_generation = p_generation
       AND e.external_event_identity NOT LIKE 'ROSTER_RECONCILIATION:%';

    SELECT count(*) INTO v_roster
      FROM iam_v2.pms_roster_of_generation(p_tenant, p_site, p_iface, p_generation);

    SELECT count(*) INTO v_mirror FROM iam_v2.stays s
     WHERE s.tenant_id = p_tenant AND s.site_id = p_site AND s.pms_interface_id = p_iface
       AND s.status = 'IN_HOUSE';

    SELECT true, c.rooms_named, c.conflicting_rooms, c.rooms
      INTO v_have, v_rooms, v_conflicts, v_swept
      FROM iam_v2.pms_resync_coverage c
     WHERE c.tenant_id = p_tenant AND c.site_id = p_site AND c.pms_interface_id = p_iface
       AND c.resync_generation = p_generation;

    SELECT i.rooms INTO v_known FROM iam_v2.pms_room_inventory i
     WHERE i.tenant_id = p_tenant AND i.site_id = p_site AND i.pms_interface_id = p_iface;

    -- BOOTSTRAP. The first uncontradicted sweep establishes the building -- on an APPLY only. A dry run
    -- describes what a run would do and changes nothing it describes (H-13): opening a screen, or pressing
    -- "Run dry run", must never be what established the inventory every later run is judged against.
    IF p_apply AND v_known IS NULL AND v_have AND v_conflicts = 0 AND COALESCE(array_length(v_swept,1),0) > 0 THEN
        INSERT INTO iam_v2.pms_room_inventory
               (tenant_id, site_id, pms_interface_id, rooms, established_from, config_version)
        VALUES (p_tenant, p_site, p_iface, v_swept, p_generation, 1)
        RETURNING rooms, config_version INTO v_known, v_ver;
        INSERT INTO iam_v2.pms_room_inventory_changes
               (tenant_id, site_id, pms_interface_id, changed_by, reason, change_kind,
                rooms_before, rooms_after, added, new_config_version)
        VALUES (p_tenant, p_site, p_iface, btrim(p_operator),
                'established from the first uncontradicted sweep', 'ESTABLISHED',
                0, COALESCE(array_length(v_swept,1),0), v_swept, v_ver);
    END IF;

    v_expected := COALESCE(array_length(v_known,1),0);
    IF v_have AND v_known IS NOT NULL THEN
        SELECT count(*) INTO v_missing
          FROM (SELECT unnest(v_known) EXCEPT SELECT unnest(COALESCE(v_swept,'{}'))) m;
    END IF;

    DROP TABLE IF EXISTS _absent;
    CREATE TEMP TABLE _absent ON COMMIT DROP AS
    SELECT s.id, s.external_reservation_id, s.normalized_room_number
      FROM iam_v2.stays s
     WHERE s.tenant_id = p_tenant AND s.site_id = p_site AND s.pms_interface_id = p_iface
       AND s.status = 'IN_HOUSE'
       AND btrim(COALESCE(s.external_reservation_id,'')) <> ''
       AND (v_boundary IS NULL OR s.arrival IS NULL OR s.arrival <= v_boundary)
       AND NOT EXISTS (
           SELECT 1 FROM iam_v2.pms_roster_of_generation(p_tenant, p_site, p_iface, p_generation) g
            WHERE g.reservation = btrim(s.external_reservation_id))
       AND NOT EXISTS (
           SELECT 1 FROM iam_v2.stay_events e2
            WHERE e2.tenant_id = p_tenant AND e2.site_id = p_site AND e2.pms_interface_id = p_iface
              AND v_boundary IS NOT NULL AND e2.received_at > v_boundary
              AND e2.external_event_identity NOT LIKE 'ROSTER_RECONCILIATION:%'
              AND (e2.stay_id = s.id
                   OR btrim(COALESCE(e2.payload->>'reservation','')) = btrim(s.external_reservation_id)));
    SELECT count(*) INTO v_absent FROM _absent;

    SELECT count(*) INTO v_protected
      FROM iam_v2.stays s
     WHERE s.tenant_id = p_tenant AND s.site_id = p_site AND s.pms_interface_id = p_iface
       AND s.status = 'IN_HOUSE'
       AND btrim(COALESCE(s.external_reservation_id,'')) <> ''
       AND NOT EXISTS (
           SELECT 1 FROM iam_v2.pms_roster_of_generation(p_tenant, p_site, p_iface, p_generation) g
            WHERE g.reservation = btrim(s.external_reservation_id))
       AND NOT EXISTS (SELECT 1 FROM _absent a WHERE a.id = s.id);

    IF v_scope <> 1 THEN
        v_outcome := 'REFUSED_SCOPE_MISMATCH';
    ELSIF v_published IS NULL OR v_published < p_generation THEN
        v_outcome := 'REFUSED_GENERATION_UNPUBLISHED';
    ELSIF v_published <> p_generation THEN
        v_outcome := 'REFUSED_GENERATION_NOT_LATEST';
    ELSIF v_sync IS DISTINCT FROM 'IN_SYNC' OR v_cont IS DISTINCT FROM 'CONTINUOUS' THEN
        v_outcome := 'REFUSED_LINK_NOT_HEALTHY';
    ELSIF NOT v_have THEN
        v_outcome := 'REFUSED_NO_COVERAGE_EVIDENCE';
    ELSIF v_conflicts > 0 THEN
        v_outcome := 'REFUSED_CONFLICTING_OBSERVATIONS';
    ELSIF v_expected > 0 AND v_missing > v_tol THEN
        v_outcome := 'REFUSED_ROSTER_INCOMPLETE';
    ELSIF v_roster < v_floor THEN
        v_outcome := 'REFUSED_ROSTER_TOO_SMALL';
    ELSIF v_absent > v_cap THEN
        v_outcome := 'REFUSED_CAP_EXCEEDED';
    ELSE
        v_outcome := 'COMPLETED';
    END IF;

    INSERT INTO iam_v2.pms_roster_reconciliation_runs
        (tenant_id, site_id, pms_interface_id, resync_generation, mode, outcome,
         roster_size, mirror_in_house, absent_from_roster, stays_closed, boundary_at, run_by, reason,
         rooms_enumerated, rooms_expected, protected_by_newer_events)
    VALUES (p_tenant, p_site, p_iface, p_generation,
            CASE WHEN p_apply THEN 'APPLY' ELSE 'DRY_RUN' END, v_outcome,
            v_roster, v_mirror, v_absent, 0, v_boundary, btrim(p_operator),
            NULLIF(btrim(COALESCE(p_reason,'')),''), COALESCE(v_rooms,0), v_expected, v_protected)
    RETURNING id INTO v_run;

    IF v_outcome = 'COMPLETED' AND p_apply THEN
        -- GROWTH, and only on an apply (see BOOTSTRAP above).
        SELECT COALESCE(ARRAY(SELECT unnest(COALESCE(v_swept,'{}')) EXCEPT SELECT unnest(v_known)), '{}')
          INTO v_added;
        IF v_known IS NOT NULL AND COALESCE(array_length(v_added,1),0) > 0 THEN
            UPDATE iam_v2.pms_room_inventory
               SET rooms = ARRAY(SELECT DISTINCT unnest(rooms || v_added) ORDER BY 1),
                   updated_at = now(), config_version = config_version + 1
             WHERE tenant_id = p_tenant AND site_id = p_site AND pms_interface_id = p_iface
            RETURNING config_version INTO v_ver;
            INSERT INTO iam_v2.pms_room_inventory_changes
                   (tenant_id, site_id, pms_interface_id, changed_by, reason, change_kind,
                    rooms_before, rooms_after, added, new_config_version)
            VALUES (p_tenant, p_site, p_iface, btrim(p_operator),
                    'a complete sweep named rooms not previously known', 'GREW',
                    v_expected, v_expected + array_length(v_added,1), v_added, v_ver);
        END IF;

        -- THE CHECKOUT, AS A PMS CHECKOUT. One durable GO per stay, admitted under the published generation
        -- the roster came from. The Stay Engine applies it and runs the Checkout Converter in the same
        -- transaction, so the entitlement, devices, sessions, grace and audit follow exactly the rules a
        -- checkout the PMS sent follows. A stay with a checkout already waiting gets no second one.
        INSERT INTO iam_v2.stay_events
               (tenant_id, site_id, pms_interface_id, external_event_identity, event_type,
                pms_timestamp_utc, normalization_version, clock_suspect, payload,
                admission_kind, admission_runtime_generation, resync_generation)
        SELECT p_tenant, p_site, p_iface,
               'ROSTER_RECONCILIATION:' || p_generation::text || ':' || a.id::text, 'GO',
               v_boundary, v_norm, false,
               jsonb_build_object('reservation', a.external_reservation_id,
                                  'room', COALESCE(a.normalized_room_number, ''),
                                  'source', 'ROSTER_RECONCILIATION',
                                  'run_id', v_run::text,
                                  'resync_generation', p_generation),
               'RESYNC', 0, p_generation
          FROM _absent a
         WHERE NOT EXISTS (
               SELECT 1 FROM iam_v2.stay_events q
                WHERE q.tenant_id = p_tenant AND q.site_id = p_site AND q.pms_interface_id = p_iface
                  AND q.processing_status = 'PENDING' AND q.event_type = 'GO'
                  AND btrim(COALESCE(q.payload->>'reservation','')) = btrim(a.external_reservation_id))
        ON CONFLICT DO NOTHING;
        GET DIAGNOSTICS v_closed = ROW_COUNT;

        INSERT INTO iam_v2.pms_case_resolutions
            (tenant_id, site_id, pms_interface_id, stay_event_id, stay_id, disposition,
             evidence_kind, evidence_ref, run_id, resolved_by, note)
        SELECT e.tenant_id, e.site_id, e.pms_interface_id, e.id, e.stay_id,
               'DEPARTED_CONFIRMED_BY_ROSTER', 'PUBLISHED_ROSTER_GENERATION',
               'generation ' || p_generation::text, v_run, btrim(p_operator), NULL
          FROM iam_v2.stay_events e
          JOIN _absent a ON a.id = e.stay_id
         WHERE e.processing_status = 'MANUAL_REVIEW'
        ON CONFLICT (stay_event_id) DO NOTHING;

        UPDATE iam_v2.pms_roster_reconciliation_runs SET stays_closed = v_closed WHERE id = v_run;
    END IF;

    RETURN QUERY SELECT v_outcome, v_roster, v_mirror, v_absent, v_closed,
                        COALESCE(v_rooms,0), v_expected, v_protected, v_run;
END;
$$;


--
-- Name: FUNCTION pms_roster_reconcile(p_tenant uuid, p_site uuid, p_iface uuid, p_generation bigint, p_operator text, p_apply boolean, p_reason text); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.pms_roster_reconcile(p_tenant uuid, p_site uuid, p_iface uuid, p_generation bigint, p_operator text, p_apply boolean, p_reason text) IS 'Reconciles the mirror against a complete published roster. APPLY queues one checkout (GO) stay event per absent stay, which the Stay Engine applies through the Checkout Converter (0123); stays_closed counts the checkouts queued. A dry run changes nothing but its own run row.';


--
-- Name: pms_site_blocked_after_refusals(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.pms_site_blocked_after_refusals(p_tenant uuid, p_site uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
    SELECT COALESCE(max(blocked_after_refusals), 3)
      FROM iam_v2.pms_connection_settings
     WHERE tenant_id = p_tenant AND site_id = p_site;
$$;


--
-- Name: publish_checkout_grace_config(uuid, uuid, uuid, integer, integer, integer, bigint, integer, text, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.publish_checkout_grace_config(p_tenant uuid, p_site uuid, p_pkg_rev uuid, p_duration integer, p_down integer, p_up integer, p_quota bigint, p_dev_limit integer, p_dev_policy text, p_eligibility integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_ver bigint;
BEGIN
  -- (item 2) eligibility_window_seconds is an AUTHORITATIVE grace-policy field: validated, versioned, compared
  -- for idempotency and included in material-change detection exactly like the shaping/quota/device fields.
  IF p_eligibility IS NULL OR p_eligibility <= 0 OR p_eligibility > 604800 THEN
    RAISE EXCEPTION 'eligibility_window_seconds must be within 1..604800 (got %)', p_eligibility;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant::text || ':' || p_site::text || ':grace-config', 0));
  SELECT config_version INTO v_ver FROM iam_v2.site_checkout_grace_config
    WHERE tenant_id=p_tenant AND site_id=p_site FOR UPDATE;
  IF v_ver IS NULL THEN
    INSERT INTO iam_v2.site_checkout_grace_config
      (tenant_id,site_id,grace_package_revision_id,grace_duration_seconds,grace_down_kbps,grace_up_kbps,
       grace_data_quota_bytes,grace_device_limit,grace_device_limit_policy,eligibility_window_seconds,config_version)
      VALUES (p_tenant,p_site,p_pkg_rev,p_duration,p_down,p_up,p_quota,p_dev_limit,p_dev_policy,p_eligibility,1);
    RETURN 1;
  END IF;
  -- idempotent re-publication of the IDENTICAL typed policy does NOT bump the version (a material change does).
  IF EXISTS (SELECT 1 FROM iam_v2.site_checkout_grace_config
             WHERE tenant_id=p_tenant AND site_id=p_site
               AND grace_package_revision_id IS NOT DISTINCT FROM p_pkg_rev
               AND grace_duration_seconds IS NOT DISTINCT FROM p_duration
               AND grace_down_kbps IS NOT DISTINCT FROM p_down AND grace_up_kbps IS NOT DISTINCT FROM p_up
               AND grace_data_quota_bytes IS NOT DISTINCT FROM p_quota
               AND grace_device_limit IS NOT DISTINCT FROM p_dev_limit
               AND grace_device_limit_policy IS NOT DISTINCT FROM p_dev_policy
               AND eligibility_window_seconds IS NOT DISTINCT FROM p_eligibility) THEN
    RETURN v_ver;
  END IF;
  UPDATE iam_v2.site_checkout_grace_config SET
    grace_package_revision_id=p_pkg_rev, grace_duration_seconds=p_duration, grace_down_kbps=p_down,
    grace_up_kbps=p_up, grace_data_quota_bytes=p_quota, grace_device_limit=p_dev_limit,
    grace_device_limit_policy=p_dev_policy, eligibility_window_seconds=p_eligibility, config_version=v_ver+1
    WHERE tenant_id=p_tenant AND site_id=p_site;
  RETURN v_ver+1;
END $$;


--
-- Name: publish_checkout_grace_policy(uuid, uuid, uuid, integer, integer, integer, bigint, integer, text, integer, integer, uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.publish_checkout_grace_policy(p_tenant uuid, p_site uuid, p_pkg_rev uuid, p_duration integer, p_down integer, p_up integer, p_quota bigint, p_dev_limit integer, p_dev_policy text, p_eligibility integer, p_expected_version integer, p_actor uuid, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE v_current int; v_new int; v_mismatch text;
BEGIN
  -- This operation writes a capability-scoped family, so it declares its own scope. Doing it here
  -- rather than relying on ownership is what lets Gate-P give every function its own owner without
  -- any of them losing the right to perform its own writes.
  PERFORM iam_v2.begin_controlled_operation('grace_publication');
  -- ACTOR: an existing, active operator of this tenant. A policy nobody can be held to is not governed.
  IF p_actor IS NULL THEN RAISE EXCEPTION 'GRACE_ACTOR_INVALID: an actor is required'; END IF;
  PERFORM 1 FROM public.operators o
    WHERE o.id = p_actor AND o.status = 'active' AND (o.tenant_id IS NULL OR o.tenant_id = p_tenant);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'GRACE_ACTOR_INVALID: actor % is not an active operator of this tenant', p_actor;
  END IF;
  -- A publication with no recorded reason is an unattributable change to what every departing guest receives.
  IF p_reason IS NULL OR p_reason !~ '^[A-Z][A-Z0-9_]{0,63}$' THEN
    RAISE EXCEPTION 'GRACE_ACTOR_INVALID: a bounded machine reason code is required';
  END IF;

  -- POLICY: only the capability that actually exists. DISCONNECT_OLDEST and ADMIN_APPROVAL are refused rather
  -- than accepted-and-approximated, because a policy the enforcement path cannot honour is worse than none.
  IF p_dev_policy <> 'REJECT_NEW_DEVICE' THEN
    RAISE EXCEPTION 'GRACE_POLICY_UNSUPPORTED: device limit policy % is not implemented', p_dev_policy;
  END IF;

  -- PACKAGE GRAPH: validated by THE SAME function the Checkout conversion uses, so a policy that would later
  -- be judged invalid (and silently fall back to Emergency Grace on every departure) is refused NOW, while an
  -- operator is looking at it. A NULL package is refused for exactly that reason: it is not a policy, it is a
  -- guaranteed Emergency fallback wearing a success message.
  v_mismatch := iam_v2.grace_package_mismatch_reason(p_tenant, p_site, p_pkg_rev,
                                                     p_duration, p_down, p_up, p_quota, p_dev_limit, p_dev_policy);
  IF v_mismatch IS NOT NULL THEN
    RAISE EXCEPTION 'GRACE_PACKAGE_INVALID: %', v_mismatch;
  END IF;

  -- OPTIMISTIC VERSION: the caller edited what it last read. Two operators publishing at once produce one
  -- winner and one explicit conflict, never a silent overwrite. 0 means "I believe nothing is published yet".
  -- It is MANDATORY here, not just at the HTTP layer: a NULL that meant "skip concurrency control" would make
  -- the database's own guarantee depend on a caller remembering to ask for it.
  IF p_expected_version IS NULL OR p_expected_version < 0 THEN
    RAISE EXCEPTION 'GRACE_VERSION_CONFLICT: an expected config_version (>= 0) is required';
  END IF;
  SELECT config_version INTO v_current FROM iam_v2.site_checkout_grace_config
    WHERE tenant_id = p_tenant AND site_id = p_site FOR UPDATE;
  IF COALESCE(v_current,0) <> p_expected_version THEN
    RAISE EXCEPTION 'GRACE_VERSION_CONFLICT: current version is % (caller expected %)', COALESCE(v_current,0), p_expected_version;
  END IF;

  v_new := iam_v2.publish_checkout_grace_config(p_tenant, p_site, p_pkg_rev, p_duration, p_down, p_up,
                                                p_quota, p_dev_limit, p_dev_policy, p_eligibility);

  -- IMMUTABLE publication audit. An identical re-publish is idempotent in the writer (the version does not
  -- move), so the audit is only appended when a NEW version was actually created — the record then means
  -- exactly what it says: this actor put this policy in force.
  INSERT INTO iam_v2.checkout_grace_policy_publications
    (tenant_id, site_id, config_version, actor, reason_code, grace_package_revision_id, policy_snapshot)
    SELECT p_tenant, p_site, v_new, p_actor, p_reason, p_pkg_rev,
           jsonb_build_object('grace_duration_seconds', p_duration, 'grace_down_kbps', p_down,
                              'grace_up_kbps', p_up, 'grace_data_quota_bytes', p_quota,
                              'grace_device_limit', p_dev_limit, 'grace_device_limit_policy', p_dev_policy,
                              'eligibility_window_seconds', p_eligibility)
    WHERE NOT EXISTS (SELECT 1 FROM iam_v2.checkout_grace_policy_publications
                      WHERE tenant_id = p_tenant AND site_id = p_site AND config_version = v_new);
  RETURN v_new;
END $_$;


--
-- Name: purge_accounting_detail(uuid, uuid, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.purge_accounting_detail(p_tenant uuid, p_site uuid, p_batch integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_days integer; v_cutoff timestamptz; v_n integer;
BEGIN
  IF p_batch IS NULL OR p_batch NOT BETWEEN 1 AND 100000 THEN
    RAISE EXCEPTION 'a batch of 1-100000 records is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT g.detail_retention_days INTO v_days FROM iam_v2.accounting_retention_get(p_tenant, p_site) g;
  IF v_days IS NULL THEN
    RETURN 0;   -- UNLIMITED (the administrator's choice): nothing is read, nothing is deleted, nothing is recorded
  END IF;
  v_cutoff := now() - make_interval(days => v_days);
  PERFORM set_config('iam_v2.accounting_purge', 'retention', true);
  WITH doomed AS (
    SELECT ar.id
      FROM iam_v2.accounting_records ar
      JOIN iam_v2.sessions se ON se.id = ar.session_id
      JOIN iam_v2.entitlements cur ON cur.id = se.entitlement_id
     WHERE ar.tenant_id = p_tenant AND ar.site_id = p_site
       AND ar.sampled_at < v_cutoff
       AND se.ended IS NOT NULL AND se.ended < v_cutoff
       AND cur.status = 'TERMINATED'
       -- every entitlement the session was ever attributed to has ended: live usage is never touched
       AND NOT EXISTS (SELECT 1 FROM iam_v2.session_entitlement_bindings b
                         JOIN iam_v2.entitlements be ON be.id = b.entitlement_id
                        WHERE b.session_id = ar.session_id AND be.status <> 'TERMINATED')
     LIMIT p_batch)
  DELETE FROM iam_v2.accounting_records ar USING doomed WHERE ar.id = doomed.id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  PERFORM set_config('iam_v2.accounting_purge', '', true);
  IF v_n > 0 THEN
    INSERT INTO iam_v2.accounting_purge_runs (tenant_id, site_id, retention_days, cutoff, records_deleted)
    VALUES (p_tenant, p_site, v_days, v_cutoff, v_n);
  END IF;
  RETURN v_n;
END $$;


--
-- Name: FUNCTION purge_accounting_detail(p_tenant uuid, p_site uuid, p_batch integer); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.purge_accounting_detail(p_tenant uuid, p_site uuid, p_batch integer) IS 'The accounting-detail retention purge (0122; 0131: a site that never chose keeps 365 days). Does nothing while the site''s administrator has chosen unlimited. Otherwise removes at most p_batch accounting records older than the retention, of sessions ended before it whose every entitlement is TERMINATED, and records the run. Totals on entitlements and sessions are not touched.';


--
-- Name: rebind_session_entitlement(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.rebind_session_entitlement(p_session uuid, p_ent uuid, p_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_t uuid; v_s uuid; v_open uuid; v_from timestamptz; v_cur uuid; v_seq bigint; v_id uuid;
BEGIN
  -- This operation writes a capability-scoped family, so it declares its own scope. Doing it here
  -- rather than relying on ownership is what lets Gate-P give every function its own owner without
  -- any of them losing the right to perform its own writes.
  PERFORM iam_v2.begin_controlled_operation('session_binding');
  SELECT tenant_id, site_id, entitlement_id INTO v_t, v_s, v_cur FROM iam_v2.sessions WHERE id = p_session FOR UPDATE;
  IF v_t IS NULL THEN RAISE EXCEPTION 'session % not found', p_session; END IF;
  PERFORM 1 FROM iam_v2.entitlements WHERE id = p_ent AND tenant_id = v_t AND site_id = v_s;
  IF NOT FOUND THEN RAISE EXCEPTION 'entitlement % is not in the session scope', p_ent; END IF;
  SELECT id, bound_from INTO v_open, v_from FROM iam_v2.session_entitlement_bindings
    WHERE session_id = p_session AND bound_until IS NULL;
  IF v_open IS NOT NULL THEN
    IF p_at < v_from THEN RAISE EXCEPTION 'rebinding at % precedes the open interval start %', p_at, v_from; END IF;
    UPDATE iam_v2.session_entitlement_bindings SET bound_until = p_at WHERE id = v_open;
  END IF;
  SELECT COALESCE(max(seq),0)+1 INTO v_seq FROM iam_v2.session_entitlement_bindings WHERE session_id = p_session;
  INSERT INTO iam_v2.session_entitlement_bindings(tenant_id,site_id,session_id,entitlement_id,seq,bound_from)
    VALUES (v_t,v_s,p_session,p_ent,v_seq,p_at) RETURNING id INTO v_id;
  UPDATE iam_v2.sessions SET entitlement_id = p_ent WHERE id = p_session;
  RETURN v_id;
END $$;


--
-- Name: record_alert_action(uuid, uuid, uuid, text, uuid, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.record_alert_action(p_tenant uuid, p_site uuid, p_audit uuid, p_action text, p_actor uuid, p_reason text, p_expected_state text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE v_seq bigint; v_head text; v_head_seq bigint; v_audit uuid;
BEGIN
  -- This operation writes a capability-scoped family, so it declares its own scope. Doing it here
  -- rather than relying on ownership is what lets Gate-P give every function its own owner without
  -- any of them losing the right to perform its own writes.
  PERFORM iam_v2.begin_controlled_operation('alert');
  IF p_action NOT IN ('ACKNOWLEDGED','RESOLVED') THEN
    -- OPEN belongs to the audit that raised the alert; an operator can only move it forward.
    RAISE EXCEPTION 'ALERT_ACTION_INVALID: % is not an operator action', p_action;
  END IF;
  -- Mandatory, and enforced HERE rather than only at the HTTP layer: an operator action with no reason is an
  -- unexplained state change in an audit trail whose whole purpose is explaining state changes.
  IF p_reason IS NULL OR p_reason !~ '^[A-Z][A-Z0-9_]{0,63}$' THEN
    RAISE EXCEPTION 'ALERT_ACTION_INVALID: a bounded machine reason code is required';
  END IF;
  -- NULL must never mean "act against whatever state you find": that is precisely the race the expected-state
  -- check exists to prevent.
  IF p_expected_state IS NULL OR p_expected_state NOT IN ('OPEN','ACKNOWLEDGED') THEN
    RAISE EXCEPTION 'ALERT_STATE_CONFLICT: an expected state of OPEN or ACKNOWLEDGED is required';
  END IF;
  -- scope: the alert must belong to THIS tenant+site, and the row lock serializes the whole lifecycle
  SELECT id INTO v_audit FROM iam_v2.checkout_grace_audit
    WHERE id = p_audit AND tenant_id = p_tenant AND site_id = p_site AND alert_code IS NOT NULL
    FOR UPDATE;
  IF v_audit IS NULL THEN
    RAISE EXCEPTION 'ALERT_NOT_FOUND: no alert % in this scope', p_audit;
  END IF;
  -- actor: an existing, active operator of the SAME tenant. An action nobody can be held to is not an audit.
  IF p_actor IS NULL THEN
    RAISE EXCEPTION 'ALERT_ACTOR_INVALID: an actor is required';
  END IF;
  PERFORM 1 FROM public.operators o
    WHERE o.id = p_actor AND o.status = 'active'
      AND (o.tenant_id IS NULL OR o.tenant_id = p_tenant);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ALERT_ACTOR_INVALID: actor % is not an active operator of this tenant', p_actor;
  END IF;
  SELECT action, seq INTO v_head, v_head_seq FROM iam_v2.checkout_grace_alert_actions
    WHERE audit_id = p_audit ORDER BY seq DESC LIMIT 1;
  IF v_head IS NULL THEN
    RAISE EXCEPTION 'ALERT_NOT_FOUND: alert % has no lifecycle', p_audit;
  END IF;
  -- optimistic state match: the caller acted on what it last saw, and nothing has moved since.
  IF p_expected_state <> v_head THEN
    RAISE EXCEPTION 'ALERT_STATE_CONFLICT: alert is % (caller expected %)', v_head, p_expected_state;
  END IF;
  IF v_head = 'RESOLVED' THEN
    RAISE EXCEPTION 'ALERT_STATE_CONFLICT: alert is already RESOLVED';
  END IF;
  IF v_head = 'ACKNOWLEDGED' AND p_action = 'ACKNOWLEDGED' THEN
    RAISE EXCEPTION 'ALERT_STATE_CONFLICT: alert is already ACKNOWLEDGED';
  END IF;
  v_seq := v_head_seq + 1;
  INSERT INTO iam_v2.checkout_grace_alert_actions(tenant_id, site_id, audit_id, seq, action, actor, reason_code)
    VALUES (p_tenant, p_site, p_audit, v_seq, p_action, p_actor, p_reason);
  RETURN v_seq;
END $_$;


--
-- Name: record_auth_context_offer(uuid, uuid, uuid, uuid, integer, bigint, timestamp with time zone); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.record_auth_context_offer(p_tenant uuid, p_site uuid, p_auth_context uuid, p_package_revision uuid, p_tier integer, p_evidence_version bigint, p_expires_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_id uuid; v_consumed timestamptz;
BEGIN
  IF p_evidence_version IS NULL OR p_evidence_version <= 0 THEN
    RAISE EXCEPTION 'OFFER_INVALID: an offer must record the evidence version it was decided under';
  END IF;
  SELECT consumed_at INTO v_consumed FROM iam_v2.auth_contexts
    WHERE id = p_auth_context AND tenant_id = p_tenant AND site_id = p_site;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OFFER_INVALID: auth context % is not in this tenant/site', p_auth_context;
  END IF;
  IF v_consumed IS NOT NULL THEN
    -- Offering something to a context that has already been redeemed would let a second grant find an offer
    -- that was never shown to the guest at the time they proved who they were.
    RAISE EXCEPTION 'OFFER_INVALID: auth context % is already consumed', p_auth_context;
  END IF;
  INSERT INTO iam_v2.auth_context_offers
    (tenant_id, site_id, auth_context_id, package_revision_id, matched_tier_order, evidence_version, expires_at)
    VALUES (p_tenant, p_site, p_auth_context, p_package_revision, p_tier, p_evidence_version, p_expires_at)
    ON CONFLICT (auth_context_id, package_revision_id) DO NOTHING
    RETURNING id INTO v_id;
  RETURN v_id;
END $$;


--
-- Name: record_posting_review_action(uuid, text, uuid, text, jsonb, integer, bigint); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.record_posting_review_action(p_posting uuid, p_action text, p_actor uuid, p_reason text, p_evidence jsonb DEFAULT '{}'::jsonb, p_expected_version integer DEFAULT NULL::integer, p_reversal_amount bigint DEFAULT NULL::bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE
  v_t uuid; v_s uuid; st record; v_action_id uuid; v_next_attempt int; v_attempts int; la record;
  o record; v_amount bigint; v_rev uuid;
BEGIN
  IF p_action NOT IN ('CONFIRM_POSTED','CONFIRM_NOT_POSTED_RETRY','CONFIRM_NOT_POSTED_ABANDON',
                      'CREATE_REVERSAL','ESCALATE') THEN
    RAISE EXCEPTION 'REVIEW_ACTION_UNKNOWN: % is not in the approved review catalog', p_action
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_actor IS NULL OR p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'REVIEW_ACTOR_REASON_REQUIRED: every financial review decision is attributable'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_action <> 'ESCALATE'
     AND (p_evidence IS NULL OR jsonb_typeof(p_evidence) <> 'object' OR p_evidence = '{}'::jsonb) THEN
    RAISE EXCEPTION 'REVIEW_EVIDENCE_REQUIRED: a terminal financial decision must record its evidence'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO o FROM iam_v2.pms_postings WHERE id = p_posting;
  IF o.id IS NULL THEN
    RAISE EXCEPTION 'REVIEW_POSTING_UNKNOWN: posting % does not exist', p_posting
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  v_t := o.tenant_id; v_s := o.site_id;

  PERFORM pg_advisory_xact_lock(iam_v2.ns_financial_review(p_posting::text));
  INSERT INTO iam_v2.posting_review_state (posting_id, tenant_id, site_id)
  VALUES (p_posting, v_t, v_s) ON CONFLICT (posting_id) DO NOTHING;
  SELECT * INTO st FROM iam_v2.posting_review_state WHERE posting_id = p_posting FOR UPDATE;

  IF p_expected_version IS NOT NULL AND p_expected_version <> st.review_version THEN
    RAISE EXCEPTION 'REVIEW_VERSION_STALE: expected version %, current is %',
      p_expected_version, st.review_version USING ERRCODE = 'serialization_failure';
  END IF;

  SELECT count(*) INTO v_attempts FROM iam_v2.posting_attempts WHERE internal_posting_id = p_posting;
  IF v_attempts = 0 AND p_action <> 'ESCALATE' THEN
    RAISE EXCEPTION 'REVIEW_NOT_APPLICABLE: posting % has no transmission attempt to decide about', p_posting
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_action <> 'ESCALATE' AND st.terminal_action IS NOT NULL THEN
    IF st.terminal_action = p_action THEN
      RAISE EXCEPTION 'REVIEW_ALREADY_DECIDED: posting % is already decided as %', p_posting, st.terminal_action
        USING ERRCODE = 'unique_violation';
    END IF;
    RAISE EXCEPTION 'REVIEW_CONFLICT: posting % is already decided as %; % is incompatible',
      p_posting, st.terminal_action, p_action USING ERRCODE = 'unique_violation';
  END IF;

  SELECT attempt_no, outcome, pa_as_status INTO la
    FROM iam_v2.posting_attempts WHERE internal_posting_id = p_posting
    ORDER BY attempt_no DESC LIMIT 1;

  -- THE ACTION/STATE MATRIX.
  IF p_action = 'CONFIRM_NOT_POSTED_RETRY' THEN
    IF la.outcome = 'ACKED' AND la.pa_as_status = 'OK' THEN
      RAISE EXCEPTION 'REVIEW_RETRY_REFUSED: attempt % was ACKed OK by the PMS; retrying it would post the '
                      'charge twice. Use CREATE_REVERSAL or CONFIRM_POSTED.', la.attempt_no
        USING ERRCODE = 'check_violation';
    END IF;
    IF la.outcome = 'SENDING' THEN
      RAISE EXCEPTION 'REVIEW_RETRY_REFUSED: attempt % is still SENDING; its outcome is not yet known',
        la.attempt_no USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- CREATE_REVERSAL corrects money the PMS is believed to hold. Reversing a charge nobody thinks was
  -- posted would put a correction in the ledger for a debit that never happened.
  IF p_action = 'CREATE_REVERSAL' THEN
    IF o.posting_type <> 'CHARGE' THEN
      RAISE EXCEPTION 'REVIEW_REVERSAL_REFUSED: only a CHARGE can be reversed' USING ERRCODE = 'check_violation';
    END IF;
    IF la.outcome = 'SENDING' THEN
      RAISE EXCEPTION 'REVIEW_REVERSAL_REFUSED: attempt % is still SENDING; its outcome is not yet known',
        la.attempt_no USING ERRCODE = 'check_violation';
    END IF;
    IF NOT (la.outcome = 'UNKNOWN' OR (la.outcome = 'ACKED' AND la.pa_as_status = 'OK')) THEN
      RAISE EXCEPTION 'REVIEW_REVERSAL_REFUSED: the latest attempt is %/%; nothing is believed posted, so '
                      'there is nothing to reverse. Use CONFIRM_NOT_POSTED_ABANDON.',
        la.outcome, coalesce(la.pa_as_status,'-') USING ERRCODE = 'check_violation';
    END IF;
    v_amount := coalesce(p_reversal_amount, o.amount_minor);
  ELSIF p_reversal_amount IS NOT NULL THEN
    RAISE EXCEPTION 'REVIEW_AMOUNT_NOT_APPLICABLE: only CREATE_REVERSAL carries an amount'
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('iam_v2.p4_review_writer', txid_current()::text, true);

  INSERT INTO iam_v2.posting_review_actions (tenant_id, site_id, posting_id, action, actor, reason, evidence)
  VALUES (v_t, v_s, p_posting, p_action, p_actor, p_reason, coalesce(p_evidence, '{}'::jsonb))
  RETURNING id INTO v_action_id;

  IF p_action = 'CREATE_REVERSAL' THEN
    -- §15: "a new ledger row referencing the original". It pins the SAME evidence the original pinned, so
    -- the correction is attached to the same authorization rather than to a fresh resolution.
    INSERT INTO iam_v2.pms_postings
      (tenant_id, site_id, pms_interface_id, settlement_id, purchase_id, stay_id, g_number,
       posting_interface_revision_id, secret_generation_id, posting_type, reverses_posting_id,
       amount_minor, currency, currency_exponent, idempotency_key)
    VALUES (o.tenant_id, o.site_id, o.pms_interface_id, o.settlement_id, o.purchase_id, o.stay_id, o.g_number,
            o.posting_interface_revision_id, o.secret_generation_id, 'REVERSAL', o.id,
            v_amount, o.currency, o.currency_exponent, o.idempotency_key || ':rev:' || v_action_id::text)
    RETURNING id INTO v_rev;
  END IF;

  PERFORM set_config('iam_v2.p4_review_writer', '', true);

  IF p_action = 'ESCALATE' THEN
    UPDATE iam_v2.posting_review_state
       SET escalation_count = escalation_count + 1, review_version = review_version + 1, updated_at = now()
     WHERE posting_id = p_posting;
  ELSE
    IF p_action = 'CONFIRM_NOT_POSTED_RETRY' THEN
      SELECT coalesce(max(attempt_no), 0) + 1 INTO v_next_attempt
        FROM iam_v2.posting_attempts WHERE internal_posting_id = p_posting;
    ELSE
      v_next_attempt := NULL;
    END IF;
    UPDATE iam_v2.posting_review_state
       SET terminal_action = p_action, terminal_action_id = v_action_id, decided_at = now(),
           retry_authorized_attempt_no = v_next_attempt, reversal_posting_id = v_rev,
           review_version = review_version + 1, updated_at = now()
     WHERE posting_id = p_posting;
  END IF;

  RETURN v_action_id;
END $$;


--
-- Name: redact_guest_text(jsonb, text[], boolean); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.redact_guest_text(p_payload jsonb, p_vals text[], p_search boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE r jsonb; k text; v jsonb;
BEGIN
  CASE jsonb_typeof(p_payload)
    WHEN 'object' THEN
      r := '{}'::jsonb;
      FOR k, v IN SELECT * FROM jsonb_each(p_payload) LOOP
        r := r || jsonb_build_object(k, iam_v2.redact_guest_text(v, p_vals, p_search));
      END LOOP;
      RETURN r;
    WHEN 'array' THEN
      RETURN COALESCE((SELECT jsonb_agg(iam_v2.redact_guest_text(x, p_vals, p_search) ORDER BY n)
                         FROM jsonb_array_elements(p_payload) WITH ORDINALITY t(x, n)), '[]'::jsonb);
    WHEN 'string' THEN
      IF iam_v2.text_names_any(p_payload #>> '{}', p_vals)
         OR (p_search AND length(btrim(p_payload #>> '{}')) >= 2
             AND EXISTS (SELECT 1 FROM unnest(p_vals) x WHERE position(lower(btrim(p_payload #>> '{}')) IN x) > 0)) THEN
        RETURN to_jsonb('[erased]'::text);
      END IF;
      RETURN p_payload;
    ELSE
      RETURN p_payload;
  END CASE;
END $$;


--
-- Name: refund_access_terminations_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.refund_access_terminations_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION 'refund termination evidence is append-only' USING ERRCODE = 'insufficient_privilege';
END $$;


--
-- Name: register_class_origin(uuid, uuid, uuid, uuid, text, integer, bigint, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.register_class_origin(p_tenant uuid, p_site uuid, p_session uuid, p_source_device uuid, p_bridge text, p_class_minor integer, p_epoch bigint, p_origin_up bigint, p_origin_down bigint, p_created_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_started timestamptz; v_device uuid; v_ended timestamptz; v_iface text; v_ip inet; cp record;
BEGIN
  IF p_origin_up IS NULL OR p_origin_down IS NULL OR p_origin_up < 0 OR p_origin_down < 0 THEN
    RAISE EXCEPTION 'ACCT_INVALID: origin counters must be non-negative';
  END IF;
  IF p_epoch IS NULL OR p_epoch < 1 OR p_created_at IS NULL THEN
    RAISE EXCEPTION 'ACCT_INVALID: a class origin needs a source epoch (>= 1) and a creation time';
  END IF;

  -- the SAME source coherence the ingestion operation enforces: an origin is a checkpoint, and a checkpoint
  -- for a source tuple that does not describe this Session would be a way to pre-seed someone else's series
  SELECT started, device_id, ended, ingress_interface, ip
    INTO v_started, v_device, v_ended, v_iface, v_ip
    FROM iam_v2.sessions WHERE id = p_session AND tenant_id = p_tenant AND site_id = p_site;
  IF v_started IS NULL THEN
    RAISE EXCEPTION 'ACCT_SESSION_OUT_OF_SCOPE: session % is not in this tenant/site', p_session;
  END IF;
  IF v_ended IS NOT NULL THEN
    RAISE EXCEPTION 'ACCT_SESSION_OUT_OF_SCOPE: session % has ended', p_session;
  END IF;
  IF v_device IS DISTINCT FROM p_source_device
     OR v_iface IS DISTINCT FROM p_bridge
     OR iam_v2.p3_expected_class_minor(v_ip) IS DISTINCT FROM p_class_minor THEN
    RAISE EXCEPTION 'ACCT_SOURCE_MISMATCH: the class origin does not describe session %', p_session;
  END IF;

  SELECT * INTO cp FROM iam_v2.accounting_checkpoints
    WHERE session_id = p_session AND source_device_id = p_source_device
      AND bridge = p_bridge AND class_minor = p_class_minor
    FOR UPDATE;

  IF cp.id IS NULL THEN
    INSERT INTO iam_v2.accounting_checkpoints
      (tenant_id, site_id, session_id, source_device_id, bridge, class_minor, source_epoch,
       prev_bytes_up, prev_bytes_down, prev_sampled_at, last_classification)
      VALUES (p_tenant, p_site, p_session, p_source_device, p_bridge, p_class_minor, p_epoch,
              p_origin_up, p_origin_down, p_created_at, 'BASELINED');
    RETURN 'ORIGIN_REGISTERED';
  END IF;

  IF p_epoch < cp.source_epoch THEN
    RAISE EXCEPTION 'ACCT_STALE_EPOCH: origin epoch % is older than the accepted epoch %', p_epoch, cp.source_epoch;
  END IF;
  IF p_epoch = cp.source_epoch THEN
    -- The same class generation is already registered. Re-registering would move the origin forward and
    -- silently forgive whatever was used since — which is exactly the loss this operation exists to close.
    RETURN 'ORIGIN_UNCHANGED';
  END IF;

  -- A NEW generation: the class was replaced, so its counters legitimately restart from the stated origin.
  UPDATE iam_v2.accounting_checkpoints
     SET source_epoch = p_epoch, prev_bytes_up = p_origin_up, prev_bytes_down = p_origin_down,
         prev_sampled_at = p_created_at, last_classification = 'RESET_BASELINED', updated_at = now()
   WHERE id = cp.id;
  RETURN 'ORIGIN_RESET';
END $$;


--
-- Name: request_full_resync(uuid, uuid, uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.request_full_resync(p_tenant uuid, p_site uuid, p_interface uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  -- The reason vocabulary is closed HERE as well as in edged. A bounded set enforced only in the process that
  -- happens to call today is not a bound; it is a convention that survives until the next caller.
  IF p_reason IS NULL OR p_reason NOT IN
     ('SUSPECTED_STALE_GUEST_LIST','AFTER_PMS_MAINTENANCE','OPERATOR_VERIFICATION','SUPPORT_REQUEST',
      'PMS_ANSWER_TARGET_INVALID') THEN
    RAISE EXCEPTION 'unbounded resync reason' USING ERRCODE = 'check_violation';
  END IF;

  UPDATE iam_v2.pms_interface_runtime rt
     SET resync_command_id            = gen_random_uuid(),
         resync_command_requested_at  = now(),
         resync_command_reason        = p_reason,
         resync_command_generation    = rt.runtime_generation,
         resync_command_claimed_at    = NULL,
         sync_stage                   = 'REQUESTING_FULL_SYNC',
         sync_stage_at                = now(),
         sync_failure_code            = NULL,
         updated_at                   = now()
    FROM iam_v2.pms_interfaces pi
   WHERE pi.tenant_id = rt.tenant_id AND pi.site_id = rt.site_id AND pi.id = rt.pms_interface_id
     AND rt.tenant_id = p_tenant AND rt.site_id = p_site AND rt.pms_interface_id = p_interface
     -- there is a worker with a live socket to receive this
     AND pi.lifecycle_state = 'ACTIVE'
     AND rt.transport_status = 'CONNECTED'
     -- a resync is not already running, and no earlier request is still waiting to be claimed
     AND rt.sync_status <> 'RESYNC_IN_PROGRESS'
     AND rt.resync_command_id IS NULL
  RETURNING rt.resync_command_id INTO v_id;

  RETURN v_id; -- NULL when no row qualified; the caller explains which precondition failed
END;
$$;


--
-- Name: FUNCTION request_full_resync(p_tenant uuid, p_site uuid, p_interface uuid, p_reason text); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.request_full_resync(p_tenant uuid, p_site uuid, p_interface uuid, p_reason text) IS 'Records an operator full-resync request without granting the caller write access to iam_v2.pms_interface_runtime. Writes only the command and stage columns; cannot touch transport, sync, continuity, generations or pins. resync_command_generation is taken from the row own runtime_generation so a caller cannot aim a command at a generation it chose. Returns NULL when the interface is not ACTIVE and CONNECTED, a resync is already running, or a request is already pending.';


--
-- Name: request_register_answer(uuid, uuid, uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.request_register_answer(p_tenant uuid, p_site uuid, p_id uuid, p_actor text, p_status text, p_outcome text, p_note text, p_erasure_ref text, p_assisted_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE q record;
BEGIN
  IF p_actor IS NULL OR length(btrim(p_actor)) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'an operator is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('ANSWERED', 'PARTLY_REFUSED', 'REFUSED', 'WITHDRAWN') THEN
    RAISE EXCEPTION 'the outcome is answered, partly refused, refused or withdrawn' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  -- A refusal, or a part-refusal, names its ground: the person is told it, and told they may complain (Art. 12(4)).
  IF p_status IN ('PARTLY_REFUSED', 'REFUSED') AND COALESCE(p_outcome, 'NONE') = 'NONE' THEN
    RAISE EXCEPTION 'a refusal names its ground' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_note IS NOT NULL AND length(p_note) > 500 THEN
    RAISE EXCEPTION 'the note is at most 500 characters' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT * INTO q FROM guest_data_request_register x WHERE x.id = p_id AND x.tenant_id = p_tenant AND x.site_id = p_site FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'request not found' USING ERRCODE = 'no_data_found'; END IF;
  IF q.status <> 'OPEN' THEN
    RAISE EXCEPTION 'register_refused' USING ERRCODE = 'object_in_use', DETAIL = 'closed';
  END IF;
  UPDATE guest_data_request_register
     SET status = p_status, outcome_code = COALESCE(NULLIF(p_outcome, ''), 'NONE'), answered_by = btrim(p_actor), answered_at = now(),
         erasure_ref = NULLIF(p_erasure_ref, ''), assisted_ref = NULLIF(p_assisted_ref, ''),
         requester_ref = '[removed]', outcome_note = NULL, extension_reason = NULL
   WHERE id = p_id;
  PERFORM ledger_append(p_tenant, p_site, 'request_answered', jsonb_build_object(
    'id', p_id, 'ref', q.ref, 'kind', q.kind, 'received_at', q.received_at, 'due_at', q.due_at, 'extended_until', q.extended_until,
    'status', p_status, 'outcome', COALESCE(NULLIF(p_outcome, ''), 'NONE'), 'erasure_ref', NULLIF(p_erasure_ref, ''),
    'assisted_ref', NULLIF(p_assisted_ref, ''), 'verification_method', q.verification_method, 'answered_at', now()));
  RETURN jsonb_build_object('reference', q.ref, 'kind', q.kind, 'requester', q.requester_ref, 'received_at', q.received_at,
                            'due_at', COALESCE(q.extended_until, q.due_at), 'answered_at', now(), 'status', p_status,
                            'outcome', COALESCE(NULLIF(p_outcome, ''), 'NONE'), 'note', p_note,
                            'verification_method', q.verification_method, 'erasure_ref', NULLIF(p_erasure_ref, ''),
                            'assisted_ref', NULLIF(p_assisted_ref, ''), 'answered_in_time', iam_v2.site_today(p_site) <= COALESCE(q.extended_until, q.due_at));
END $$;


--
-- Name: request_register_extend(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.request_register_extend(p_tenant uuid, p_site uuid, p_id uuid, p_actor text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE q record;
BEGIN
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 4 AND 500 THEN
    RAISE EXCEPTION 'say why the request needs longer (4-500 characters)' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  -- The reason is kept in the register: it names no one (no address, no number).
  IF p_reason ~ '@' OR p_reason ~ '[0-9][^0-9]*[0-9][^0-9]*[0-9][^0-9]*[0-9][^0-9]*[0-9][^0-9]*[0-9]' THEN
    RAISE EXCEPTION 'the reason must not contain an email address or a number that could identify someone' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT * INTO q FROM guest_data_request_register x WHERE x.id = p_id AND x.tenant_id = p_tenant AND x.site_id = p_site FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'request not found' USING ERRCODE = 'no_data_found'; END IF;
  IF q.status <> 'OPEN' OR q.extended_until IS NOT NULL OR iam_v2.site_today(p_site) > q.due_at THEN
    RAISE EXCEPTION 'register_refused' USING ERRCODE = 'object_in_use', DETAIL = 'not_extendable';
  END IF;
  UPDATE guest_data_request_register SET extended_until = (received_at + interval '3 months')::date,
         extension_reason = btrim(p_reason) WHERE id = p_id;
  RETURN jsonb_build_object('id', p_id, 'due_at', (q.received_at + interval '3 months')::date);
END $$;


--
-- Name: request_register_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.request_register_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'a request in the register is never deleted' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.status <> 'OPEN' THEN
    RAISE EXCEPTION 'an answered request does not change' USING ERRCODE = 'restrict_violation';
  END IF;
  IF (NEW.id, NEW.ref, NEW.tenant_id, NEW.site_id, NEW.kind, NEW.received_at, NEW.due_at, NEW.created_by, NEW.created_at)
     IS DISTINCT FROM (OLD.id, OLD.ref, OLD.tenant_id, OLD.site_id, OLD.kind, OLD.received_at, OLD.due_at, OLD.created_by, OLD.created_at) THEN
    RAISE EXCEPTION 'what was received, and when, cannot be edited' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: request_register_list(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.request_register_list(p_tenant uuid, p_site uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', x.id, 'ref', x.ref, 'kind', x.kind, 'received_at', x.received_at, 'due_at', COALESCE(x.extended_until, x.due_at),
      'extended', x.extended_until IS NOT NULL, 'extension_reason', CASE WHEN x.status = 'OPEN' THEN x.extension_reason END,
      'requester', x.requester_ref, 'verification_method', x.verification_method, 'status', x.status, 'outcome', x.outcome_code,
      'erasure_ref', x.erasure_ref, 'assisted_ref', x.assisted_ref, 'created_by', x.created_by, 'answered_by', x.answered_by,
      'answered_at', x.answered_at,
      'days_left', CASE WHEN x.status = 'OPEN' THEN COALESCE(x.extended_until, x.due_at) - iam_v2.site_today(p_site) END,
      'overdue', x.status = 'OPEN' AND iam_v2.site_today(p_site) > COALESCE(x.extended_until, x.due_at))
      ORDER BY (x.status = 'OPEN') DESC, COALESCE(x.extended_until, x.due_at), x.received_at DESC), '[]'::jsonb)
    FROM (SELECT * FROM guest_data_request_register r WHERE r.tenant_id = p_tenant AND r.site_id = p_site
           ORDER BY (r.status = 'OPEN') DESC, r.received_at DESC LIMIT 300) x
$$;


--
-- Name: request_register_open(uuid, uuid, text, text, date, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.request_register_open(p_tenant uuid, p_site uuid, p_actor text, p_kind text, p_received date, p_requester text, p_method text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_ref text := 'RQ-' || upper(encode(public.gen_random_bytes(4), 'hex')); v_id uuid; v_due date;
BEGIN
  IF p_actor IS NULL OR length(btrim(p_actor)) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'an operator is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_received IS NULL OR p_received > iam_v2.site_today(p_site) OR p_received < iam_v2.site_today(p_site) - 366 THEN
    RAISE EXCEPTION 'the request was received on a day up to a year ago, and not in the future' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_requester IS NULL OR length(btrim(p_requester)) NOT BETWEEN 2 AND 120 THEN
    RAISE EXCEPTION 'say who is asking (2-120 characters)' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  v_due := (p_received + interval '1 month')::date;
  INSERT INTO guest_data_request_register (ref, tenant_id, site_id, kind, received_at, due_at, requester_ref, verification_method, created_by)
  VALUES (v_ref, p_tenant, p_site, p_kind, p_received, v_due, btrim(p_requester), NULLIF(p_method, ''), btrim(p_actor))
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'ref', v_ref, 'due_at', v_due);
END $$;


--
-- Name: reserve_device_slot(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.reserve_device_slot(p_ent uuid, p_dev uuid, p_cred text, p_appliance text, p_max integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE t uuid; s uuid; cnt int;
BEGIN
  SELECT tenant_id, site_id INTO t, s FROM iam_v2.entitlements WHERE id=p_ent;
  PERFORM pg_advisory_xact_lock(iam_v2.ns_device_slot(p_cred));   -- 1) device-slot namespace (11), before capacity
  PERFORM pg_advisory_xact_lock(iam_v2.ns_capacity(p_appliance)); -- 2) capacity namespace (7)
  -- reconnect: same device re-authorizes without burning a new slot
  IF EXISTS (SELECT 1 FROM iam_v2.entitlement_devices WHERE entitlement_id=p_ent AND device_id=p_dev) THEN
    UPDATE iam_v2.entitlement_devices SET status='AUTHORIZED', last_authorized=now()
      WHERE entitlement_id=p_ent AND device_id=p_dev;
    RETURN 'RECONNECT';
  END IF;
  SELECT count(*) INTO cnt FROM iam_v2.entitlement_devices WHERE entitlement_id=p_ent AND status='AUTHORIZED';
  IF cnt >= p_max THEN RETURN 'MAX_DEVICES_REACHED'; END IF;
  INSERT INTO iam_v2.entitlement_devices(tenant_id,site_id,entitlement_id,device_id,status,first_authorized,last_authorized)
    VALUES (t,s,p_ent,p_dev,'AUTHORIZED',now(),now());
  RETURN 'AUTHORIZED';
END; $$;


--
-- Name: run_data_retention(uuid, uuid, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.run_data_retention(p_tenant uuid, p_site uuid, p_batch integer) RETURNS TABLE(o_category text, o_cutoff timestamp with time zone, o_anonymised integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE r record; v_cut timestamptz; v_n integer; v_k integer; v_id uuid; v_floor timestamptz;
BEGIN
  IF p_batch IS NULL OR p_batch NOT BETWEEN 1 AND 10000 THEN
    RAISE EXCEPTION 'a batch of 1-10000 is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT * INTO r FROM iam_v2.data_retention_get(p_tenant, p_site);
  SELECT f.since INTO v_floor FROM iam_v2.retention_floor f;
  v_floor := COALESCE(v_floor, now());
  PERFORM set_config('iam_v2.anonymise', 'retention', true);

  -- PMS STAYS: the stay is over (checked out, cancelled or no-show) for longer than the retention, nothing it
  -- granted is still live, and no post-stay access is valid inside the retention. A date is a day in the
  -- hotel's time zone (0144).
  v_cut := now() - make_interval(days => r.pms_stay_days); v_n := 0;
  FOR v_id IN
    SELECT s.id FROM iam_v2.stays s
      LEFT JOIN LATERAL (SELECT max(e.received_at) AS last_event FROM iam_v2.stay_events e WHERE e.stay_id = s.id) le ON true
     WHERE s.tenant_id = p_tenant AND s.site_id = p_site
       AND (s.status IN ('CHECKED_OUT', 'POST_STAY_ACTIVE', 'CANCELLED', 'NO_SHOW')
            -- A stay the PMS never closed (0137, audit B2): its departure is older than the retention.
            OR (s.status IN ('RESERVED', 'IN_HOUSE') AND s.departure IS NOT NULL
                AND iam_v2.site_day_start(p_site, s.departure + 1) < v_cut)
            -- ... or with no departure at all (0143): the PMS's latest full room list no longer has it, and it has
            -- had no PMS message for longer than the retention.
            OR (s.status IN ('RESERVED', 'IN_HOUSE') AND s.departure IS NULL
                AND COALESCE(le.last_event, iam_v2.site_day_start(p_site, s.arrival + 1)) < v_cut
                AND iam_v2.stay_absent_from_published_roster(s.id)))
       AND NOT iam_v2.is_anon_token(s.external_reservation_id)
       AND COALESCE(s.effective_checkout_at, iam_v2.site_day_start(p_site, s.departure + 1),
                    iam_v2.site_day_start(p_site, s.arrival + 1), le.last_event) < v_cut
       AND NOT EXISTS (SELECT 1 FROM iam_v2.entitlements e WHERE e.stay_id = s.id AND e.status <> 'TERMINATED')
       AND NOT EXISTS (SELECT 1 FROM iam_v2.post_stay_profiles p
                        WHERE p.origin_stay_id = s.id AND p.status = 'ACTIVE' AND p.valid_until >= v_cut)
     ORDER BY s.id LIMIT p_batch
  LOOP
    PERFORM iam_v2.anonymise_stay(v_id); v_n := v_n + 1;
  END LOOP;
  -- Processed PMS events that never resolved to a stay carry the same guest data. One still waiting for a staff
  -- decision is first closed as undecided (0144), as 0123's expiry closes one, so it leaves the review queue
  -- instead of staying in it blank. A message whose reservation is still open in the mirror is left alone.
  INSERT INTO iam_v2.pms_case_resolutions
         (tenant_id, site_id, pms_interface_id, stay_event_id, stay_id, disposition,
          evidence_kind, evidence_ref, resolved_by, note)
  SELECT x.tenant_id, x.site_id, x.pms_interface_id, x.id, NULL, 'EXPIRED_UNDECIDED',
         'DATA_RETENTION', 'stay retention ' || r.pms_stay_days::text || ' days', 'data retention', NULL
    FROM iam_v2.stay_events x
   WHERE x.tenant_id = p_tenant AND x.site_id = p_site AND x.stay_id IS NULL
     AND x.processing_status = 'MANUAL_REVIEW' AND x.received_at < v_cut
     AND NOT EXISTS (SELECT 1 FROM iam_v2.pms_case_resolutions c WHERE c.stay_event_id = x.id)
     AND NOT EXISTS (SELECT 1 FROM iam_v2.stays o
                      WHERE o.tenant_id = x.tenant_id AND o.site_id = x.site_id AND o.pms_interface_id = x.pms_interface_id
                        AND o.status IN ('RESERVED', 'IN_HOUSE')
                        AND o.external_reservation_id = btrim(COALESCE(x.payload->>'reservation', '')))
   ORDER BY x.received_at LIMIT p_batch
  ON CONFLICT (stay_event_id) DO NOTHING;
  PERFORM iam_v2.begin_controlled_operation('stay');
  UPDATE iam_v2.stay_events e
     SET payload = '{"anonymised": true}'::jsonb,
         external_event_identity = 'anon-' || encode(public.gen_random_bytes(32), 'hex')
   WHERE e.id IN (SELECT x.id FROM iam_v2.stay_events x
                   WHERE x.tenant_id = p_tenant AND x.site_id = p_site AND x.stay_id IS NULL
                     AND x.processing_status <> 'PENDING' AND x.received_at < v_cut
                     AND x.payload IS DISTINCT FROM '{"anonymised": true}'::jsonb
                     AND (x.processing_status <> 'MANUAL_REVIEW'
                          OR EXISTS (SELECT 1 FROM iam_v2.pms_case_resolutions c WHERE c.stay_event_id = x.id))
                     AND NOT EXISTS (SELECT 1 FROM iam_v2.stays o
                                      WHERE o.tenant_id = x.tenant_id AND o.site_id = x.site_id
                                        AND o.pms_interface_id = x.pms_interface_id
                                        AND o.status IN ('RESERVED', 'IN_HOUSE')
                                        AND o.external_reservation_id = btrim(COALESCE(x.payload->>'reservation', '')))
                   LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;
  -- Events still waiting after the stay retention are given up (0139, D-B2). Rows the stay engine holds are
  -- skipped, never waited for; it finishes them or a later run gives them up.
  v_n := v_n + iam_v2.give_up_waiting_stay_events(p_tenant, p_site, v_cut, NULL, p_batch);
  IF v_n > 0 THEN
    INSERT INTO iam_v2.data_retention_runs (tenant_id, site_id, category, retention_days, cutoff, rows_anonymised)
    VALUES (p_tenant, p_site, 'pms_stays', r.pms_stay_days, v_cut, v_n);
    o_category := 'pms_stays'; o_cutoff := v_cut; o_anonymised := v_n; RETURN NEXT;
  END IF;

  -- CLIENT ACTIVITY: a device unseen for longer than the retention with nothing live on it, and the address
  -- columns of every session that ended before the cutoff. A device never seen is as old as the floor (0144).
  v_cut := now() - make_interval(days => r.client_activity_days); v_n := 0;
  FOR v_id IN
    SELECT d.id FROM iam_v2.devices d
     WHERE d.tenant_id = p_tenant AND d.site_id = p_site
       AND d.mac::text NOT LIKE '03:%'
       AND COALESCE(d.last_seen, d.first_seen, v_floor) < v_cut
       AND NOT EXISTS (SELECT 1 FROM iam_v2.sessions se WHERE se.device_id = d.id AND (se.ended IS NULL OR se.ended >= v_cut))
       AND NOT EXISTS (SELECT 1 FROM iam_v2.entitlement_devices ed WHERE ed.device_id = d.id AND ed.status = 'AUTHORIZED')
       AND NOT EXISTS (SELECT 1 FROM iam_v2.principal_device_credentials c
                        WHERE c.device_id = d.id AND c.revoked_at IS NULL AND c.expires_at > now())
     ORDER BY d.id LIMIT p_batch
  LOOP
    PERFORM iam_v2.anonymise_device(v_id); v_n := v_n + 1;
  END LOOP;
  UPDATE iam_v2.sessions se SET ip = NULL, mac = NULL
   WHERE se.id IN (SELECT x.id FROM iam_v2.sessions x
                    WHERE x.tenant_id = p_tenant AND x.site_id = p_site AND x.ended < v_cut
                      AND (x.ip IS NOT NULL OR x.mac IS NOT NULL)
                    LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;
  IF v_n > 0 THEN
    INSERT INTO iam_v2.data_retention_runs (tenant_id, site_id, category, retention_days, cutoff, rows_anonymised)
    VALUES (p_tenant, p_site, 'client_activity', r.client_activity_days, v_cut, v_n);
    o_category := 'client_activity'; o_cutoff := v_cut; o_anonymised := v_n; RETURN NEXT;
  END IF;

  -- INACTIVE IDENTITIES: no sign-in, verification, access or remembered-device use inside the retention, and
  -- nothing granted to the identity still live.
  v_cut := now() - make_interval(days => r.inactive_identity_days); v_n := 0;
  FOR v_id IN
    SELECT gp.id FROM iam_v2.guest_principals gp
     WHERE gp.tenant_id = p_tenant
       AND (gp.display_name IS NOT NULL
            OR EXISTS (SELECT 1 FROM iam_v2.guest_principal_identities i
                        WHERE i.guest_principal_id = gp.id AND NOT iam_v2.is_anon_token(i.factor_value_norm)))
       AND NOT EXISTS (SELECT 1 FROM iam_v2.guest_principal_identities i
                        WHERE i.guest_principal_id = gp.id AND i.verified_at >= v_cut)
       AND NOT EXISTS (SELECT 1 FROM iam_v2.entitlements e
                        WHERE e.guest_principal_id = gp.id
                          AND (e.status <> 'TERMINATED' OR COALESCE(e.terminated_at, 'infinity') >= v_cut))
       AND NOT EXISTS (SELECT 1 FROM iam_v2.auth_contexts ac
                        WHERE ac.guest_principal_id = gp.id AND COALESCE(ac.consumed_at, ac.expires_at) >= v_cut)
       AND NOT EXISTS (SELECT 1 FROM iam_v2.principal_device_credentials c
                        WHERE c.guest_principal_id = gp.id
                          AND (GREATEST(c.created_at, c.last_used_at) >= v_cut
                               OR (c.revoked_at IS NULL AND c.expires_at > now())))
     ORDER BY gp.id LIMIT p_batch
  LOOP
    PERFORM iam_v2.anonymise_guest_principal(v_id); v_n := v_n + 1;
  END LOOP;
  -- A client account: nothing about it is newer than the cutoff -- not its creation (the floor when 0104 could
  -- not record it), not its start or end of validity, not a verification, sign-in or lock (0144).
  FOR v_id IN
    SELECT a.id FROM iam_v2.guest_access_accounts a
     WHERE a.tenant_id = p_tenant AND a.site_id = p_site
       AND a.username NOT LIKE 'anon-%@anonymised.removed-%'
       AND GREATEST(COALESCE(a.created_at, v_floor), COALESCE(a.valid_from, '-infinity'),
                    COALESCE(a.valid_until, '-infinity'),
                    COALESCE(a.grace_until, '-infinity'), COALESCE(a.email_verified_at, '-infinity'),
                    COALESCE(a.last_login_at, '-infinity'), COALESCE(a.locked_until, '-infinity')) < v_cut
       AND NOT EXISTS (SELECT 1 FROM iam_v2.entitlements e
                        WHERE e.guest_account_id = a.id
                          AND (e.status <> 'TERMINATED' OR COALESCE(e.terminated_at, 'infinity') >= v_cut))
       AND NOT EXISTS (SELECT 1 FROM iam_v2.auth_contexts ac
                        WHERE ac.guest_account_id = a.id AND COALESCE(ac.consumed_at, ac.expires_at) >= v_cut)
     ORDER BY a.id LIMIT p_batch
  LOOP
    PERFORM iam_v2.anonymise_guest_account(v_id); v_n := v_n + 1;
  END LOOP;
  IF v_n > 0 THEN
    INSERT INTO iam_v2.data_retention_runs (tenant_id, site_id, category, retention_days, cutoff, rows_anonymised)
    VALUES (p_tenant, p_site, 'inactive_identities', r.inactive_identity_days, v_cut, v_n);
    o_category := 'inactive_identities'; o_cutoff := v_cut; o_anonymised := v_n; RETURN NEXT;
  END IF;

  -- EXPIRED SINGLE-USE RECORDS (iam_v2 part; public tables are in run_data_retention_public).
  v_cut := now() - make_interval(days => r.expired_record_days); v_n := 0;
  UPDATE iam_v2.verification_access_grants g
     SET device_mac = iam_v2.anonymised_mac(), ip = '0.0.0.0'::inet,
         destination_digest = encode(public.gen_random_bytes(32), 'hex')
   WHERE g.id IN (SELECT x.id FROM iam_v2.verification_access_grants x
                   WHERE x.tenant_id = p_tenant AND x.site_id = p_site AND x.expires_at < v_cut
                     AND x.device_mac::text NOT LIKE '03:%'
                   LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;
  UPDATE iam_v2.guest_signin_restrictions g
     SET device_mac = iam_v2.anonymised_mac(), last_submitted_room = NULL
   WHERE g.id IN (SELECT x.id FROM iam_v2.guest_signin_restrictions x
                   WHERE x.tenant_id = p_tenant AND x.site_id = p_site
                     AND GREATEST(x.updated_at, COALESCE(x.expires_at, '-infinity'), COALESCE(x.released_at, '-infinity')) < v_cut
                     AND x.device_mac::text NOT LIKE '03:%'
                   LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;
  UPDATE iam_v2.account_email_tokens t SET last_send_error = NULL
   WHERE t.id IN (SELECT x.id FROM iam_v2.account_email_tokens x
                   WHERE x.tenant_id = p_tenant AND x.site_id = p_site AND x.expires_at < v_cut
                     AND x.last_send_error IS NOT NULL
                   LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;
  IF v_n > 0 THEN
    INSERT INTO iam_v2.data_retention_runs (tenant_id, site_id, category, retention_days, cutoff, rows_anonymised)
    VALUES (p_tenant, p_site, 'expired_records', r.expired_record_days, v_cut, v_n);
    o_category := 'expired_records'; o_cutoff := v_cut; o_anonymised := v_n; RETURN NEXT;
  END IF;

  PERFORM set_config('iam_v2.anonymise', '', true);
END $$;


--
-- Name: FUNCTION run_data_retention(p_tenant uuid, p_site uuid, p_batch integer); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.run_data_retention(p_tenant uuid, p_site uuid, p_batch integer) IS 'The hourly guest-data retention run for the iam_v2 tables (0127, GDPR plan C1): anonymises, in batches of at most p_batch per category, PMS stays over for longer than the site''s retention, devices and sessions, inactive guest identities and accounts, and expired single-use records. Deletes nothing; records every run that changed something in iam_v2.data_retention_runs.';


--
-- Name: run_staff_note_retention(uuid, uuid, integer); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.run_staff_note_retention(p_tenant uuid, p_site uuid, p_batch integer) RETURNS TABLE(o_category text, o_cutoff timestamp with time zone, o_anonymised integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_days integer; v_cut timestamptz; v_n integer := 0; v_k integer;
        c_removed constant text := 'Removed after the staff-notes period';
BEGIN
  SELECT r.staff_note_days INTO v_days FROM iam_v2.data_retention_get(p_tenant, p_site) r;
  v_cut := now() - make_interval(days => v_days);
  PERFORM set_config('iam_v2.anonymise', 'retention', true);

  UPDATE iam_v2.pms_case_resolutions x SET note = c_removed
   WHERE x.id IN (SELECT y.id FROM iam_v2.pms_case_resolutions y
                   WHERE y.tenant_id = p_tenant AND y.site_id = p_site AND y.resolved_at < v_cut
                     AND y.note IS NOT NULL AND y.note <> c_removed
                   LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;

  UPDATE iam_v2.device_slot_actions x SET reason = c_removed
   WHERE x.id IN (SELECT y.id FROM iam_v2.device_slot_actions y
                   WHERE y.tenant_id = p_tenant AND y.site_id = p_site AND y.acted_at < v_cut
                     AND y.reason IS NOT NULL AND y.reason <> c_removed
                   LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;

  UPDATE iam_v2.post_stay_profiles x SET revoke_reason = c_removed
   WHERE x.id IN (SELECT y.id FROM iam_v2.post_stay_profiles y
                   WHERE y.tenant_id = p_tenant AND y.site_id = p_site AND y.status = 'REVOKED'
                     AND y.revoked_at < v_cut AND y.revoke_reason <> c_removed
                   LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;

  UPDATE iam_v2.stay_posting_blocks x SET note = c_removed
   WHERE x.id IN (SELECT y.id FROM iam_v2.stay_posting_blocks y
                   WHERE y.tenant_id = p_tenant AND y.site_id = p_site AND y.created_at < v_cut
                     AND y.note IS NOT NULL AND y.note <> c_removed
                   LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;

  UPDATE iam_v2.stay_posting_blocks x SET cleared_reason = c_removed
   WHERE x.id IN (SELECT y.id FROM iam_v2.stay_posting_blocks y
                   WHERE y.tenant_id = p_tenant AND y.site_id = p_site AND y.cleared_at < v_cut
                     AND y.cleared_reason IS NOT NULL AND y.cleared_reason <> c_removed
                   LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;

  UPDATE iam_v2.vouchers x SET notes = c_removed
   WHERE x.id IN (SELECT y.id FROM iam_v2.vouchers y
                   WHERE y.tenant_id = p_tenant AND y.site_id = p_site AND y.created_at < v_cut
                     AND y.notes IS NOT NULL AND btrim(y.notes) <> '' AND y.notes <> c_removed
                   LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;

  UPDATE iam_v2.guest_data_erasures x SET erase_reason = c_removed
   WHERE x.erasure_ref IN (SELECT y.erasure_ref FROM iam_v2.guest_data_erasures y
                            WHERE y.tenant_id = p_tenant AND y.site_id = p_site AND y.erased_at < v_cut
                              AND y.erase_reason <> c_removed
                            LIMIT p_batch);
  GET DIAGNOSTICS v_k = ROW_COUNT; v_n := v_n + v_k;

  v_k := iam_v2.scrub_registry_notes(p_tenant, p_site, v_cut, p_batch, c_removed); v_n := v_n + v_k;

  PERFORM set_config('iam_v2.anonymise', '', true);
  IF v_n > 0 THEN
    INSERT INTO iam_v2.data_retention_runs (tenant_id, site_id, category, retention_days, cutoff, rows_anonymised)
    VALUES (p_tenant, p_site, 'staff_notes', v_days, v_cut, v_n);
    o_category := 'staff_notes'; o_cutoff := v_cut; o_anonymised := v_n;
    RETURN NEXT;
  END IF;
END $$;


--
-- Name: FUNCTION run_staff_note_retention(p_tenant uuid, p_site uuid, p_batch integer); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.run_staff_note_retention(p_tenant uuid, p_site uuid, p_batch integer) IS 'Hourly (scd, 0140, GDPR audit C4): replaces staff notes older than the site''s staff_note_days -- PMS case decision notes, device-slot action reasons, post-stay revoke reasons -- with a fixed text, at most p_batch of each per call. The records themselves stay.';


--
-- Name: same_guest(text, text, text, uuid, text, text, text, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.same_guest(a_ext text, a_first text, a_last text, a_iface uuid, b_ext text, b_first text, b_last text, b_iface uuid) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN a_iface IS NOT DISTINCT FROM b_iface
     AND NULLIF(btrim(a_ext), '') IS NOT NULL AND NULLIF(btrim(b_ext), '') IS NOT NULL THEN
      CASE WHEN btrim(a_ext) = btrim(b_ext) THEN 'id' END
    WHEN NULLIF(btrim(a_first), '') IS NOT NULL AND NULLIF(btrim(a_last), '') IS NOT NULL
     AND NULLIF(btrim(b_first), '') IS NOT NULL AND NULLIF(btrim(b_last), '') IS NOT NULL
     AND upper(btrim(a_first)) = upper(btrim(b_first)) AND upper(btrim(a_last)) = upper(btrim(b_last)) THEN 'name'
  END;
$$;


--
-- Name: FUNCTION same_guest(a_ext text, a_first text, a_last text, a_iface uuid, b_ext text, b_first text, b_last text, b_iface uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.same_guest(a_ext text, a_first text, a_last text, a_iface uuid, b_ext text, b_first text, b_last text, b_iface uuid) IS 'Whether two PMS guest rows are one person (0145, D-R4/D-R5): the PMS guest number only within one PMS interface; otherwise the same first AND last name. A number from another interface says nothing.';


--
-- Name: same_guest_rows(uuid[], uuid[]); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.same_guest_rows(p_guests uuid[], p_stays uuid[]) RETURNS uuid[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v uuid[];
BEGIN
  IF EXISTS (
      SELECT 1
        FROM stay_guests a
        JOIN stay_guests b ON b.stay_id = ANY (p_stays) AND b.stay_id <> a.stay_id
       WHERE a.id = ANY (p_guests)
         AND same_guest(a.external_guest_id, a.first_name_norm, a.last_name_norm, a.pms_interface_id,
                        b.external_guest_id, b.first_name_norm, b.last_name_norm, b.pms_interface_id) IS NOT NULL
       -- More than one row of one stay that could be this guest -- by number or by name, an id-less namesake
       -- included -- cannot be told apart: refused, never guessed.
       GROUP BY a.id, b.stay_id HAVING count(*) > 1)
     OR EXISTS (
      SELECT 1
        FROM stay_guests a
        JOIN stay_guests t ON t.stay_id = a.stay_id AND t.id <> a.id
       WHERE a.id = ANY (p_guests) AND NOT t.id = ANY (p_guests)
         AND same_guest(NULL, a.first_name_norm, a.last_name_norm, a.pms_interface_id,
                        NULL, t.first_name_norm, t.last_name_norm, t.pms_interface_id) = 'name'
         AND EXISTS (SELECT 1 FROM stay_guests b
                      WHERE b.stay_id = ANY (p_stays) AND b.stay_id <> a.stay_id
                        AND same_guest(a.external_guest_id, a.first_name_norm, a.last_name_norm, a.pms_interface_id,
                                       b.external_guest_id, b.first_name_norm, b.last_name_norm, b.pms_interface_id) = 'name')) THEN
    RAISE EXCEPTION 'ambiguous guest: more than one guest has this name, so the guest cannot be told apart on a '
                    'linked stay. Choose the guest row from the search.' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT COALESCE(array_agg(DISTINCT b.id), '{}') INTO v
    FROM stay_guests a JOIN stay_guests b ON b.stay_id = ANY (p_stays)
   WHERE a.id = ANY (p_guests)
     AND (b.id = a.id
          OR (b.stay_id <> a.stay_id
              AND same_guest(a.external_guest_id, a.first_name_norm, a.last_name_norm, a.pms_interface_id,
                             b.external_guest_id, b.first_name_norm, b.last_name_norm, b.pms_interface_id) IS NOT NULL));
  RETURN v;
END $$;


--
-- Name: scrub_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.scrub_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE r record; v_o jsonb := to_jsonb(OLD); v_n jsonb := to_jsonb(NEW);
BEGIN
  IF TG_OP <> 'UPDATE'
     OR current_setting('iam_v2.scrub', true) IS DISTINCT FROM 'on'
     OR (current_user <> (SELECT pg_get_userbyid(c.relowner) FROM pg_class c WHERE c.oid = TG_RELID)
         AND NOT COALESCE((SELECT pr.rolsuper FROM pg_roles pr WHERE pr.rolname = current_user), false)) THEN
    RAISE EXCEPTION '% is append-only: % refused', TG_TABLE_NAME, TG_OP USING ERRCODE = 'restrict_violation';
  END IF;
  FOR r IN SELECT x.column_name, x.jsonb_key FROM iam_v2.scrub_registry x WHERE x.table_name = TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME LOOP
    IF r.jsonb_key IS NULL THEN
      v_o := v_o - r.column_name; v_n := v_n - r.column_name;
    ELSE
      IF v_o -> r.column_name IS NOT NULL AND jsonb_typeof(v_o -> r.column_name) = 'object' THEN
        v_o := jsonb_set(v_o, ARRAY[r.column_name], (v_o -> r.column_name) - r.jsonb_key);
      END IF;
      IF v_n -> r.column_name IS NOT NULL AND jsonb_typeof(v_n -> r.column_name) = 'object' THEN
        v_n := jsonb_set(v_n, ARRAY[r.column_name], (v_n -> r.column_name) - r.jsonb_key);
      END IF;
    END IF;
  END LOOP;
  IF v_o IS DISTINCT FROM v_n THEN
    RAISE EXCEPTION '% may be scrubbed only in its registered columns', TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: scrub_registry_notes(uuid, uuid, timestamp with time zone, integer, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.scrub_registry_notes(p_tenant uuid, p_site uuid, p_cut timestamp with time zone, p_batch integer, p_placeholder text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE r record; n integer := 0; k integer;
BEGIN
  PERFORM set_config('iam_v2.scrub', 'on', true);
  FOR r IN SELECT x.* FROM iam_v2.scrub_registry x WHERE x.kind = 'note' AND NOT x.handled LOOP
    IF to_regclass(r.table_name) IS NULL THEN CONTINUE; END IF;
    IF r.jsonb_key IS NULL THEN
      EXECUTE format('UPDATE %1$s x SET %2$I = $1 WHERE x.ctid IN (SELECT y.ctid FROM %1$s y WHERE y.tenant_id = $2 AND y.site_id = $3
                       AND y.%3$I < $4 AND y.%2$I IS NOT NULL AND y.%2$I <> $1 LIMIT $5)', r.table_name, r.column_name, r.ts_column)
        USING p_placeholder, p_tenant, p_site, p_cut, p_batch;
    ELSE
      EXECUTE format('UPDATE %1$s x SET %2$I = jsonb_set(x.%2$I, ARRAY[%4$L], to_jsonb($1::text)) WHERE x.ctid IN (SELECT y.ctid FROM %1$s y
                       WHERE y.tenant_id = $2 AND y.site_id = $3 AND y.%3$I < $4 AND y.%2$I ? %4$L AND y.%2$I ->> %4$L <> $1 LIMIT $5)',
                     r.table_name, r.column_name, r.ts_column, r.jsonb_key)
        USING p_placeholder, p_tenant, p_site, p_cut, p_batch;
    END IF;
    GET DIAGNOSTICS k = ROW_COUNT; n := n + k;
  END LOOP;
  PERFORM set_config('iam_v2.scrub', '', true);
  RETURN n;
END $_$;


--
-- Name: scrub_staff_label(text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.scrub_staff_label(p_old text, p_new text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE r record; n integer := 0; k integer;
BEGIN
  IF p_old IS NULL OR btrim(p_old) = '' OR p_new !~ '^removed-[0-9a-f]{12}@staff[.]invalid$' THEN
    RETURN 0;
  END IF;
  PERFORM set_config('iam_v2.scrub', 'on', true);
  FOR r IN SELECT x.table_name, x.column_name FROM iam_v2.scrub_registry x WHERE x.kind = 'label' AND x.table_name LIKE 'iam_v2.%' LOOP
    IF to_regclass(r.table_name) IS NULL THEN CONTINUE; END IF;
    EXECUTE format('UPDATE %s SET %I = $2 WHERE lower(%I) = lower($1)', r.table_name, r.column_name, r.column_name) USING p_old, p_new;
    GET DIAGNOSTICS k = ROW_COUNT; n := n + k;
  END LOOP;
  PERFORM set_config('iam_v2.scrub', '', true);
  RETURN n;
END $_$;


--
-- Name: selectable_grace_packages(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.selectable_grace_packages(p_tenant uuid, p_site uuid) RETURNS TABLE(package_revision_id uuid, package_code text, revision_no integer, service_plan_revision_id uuid, service_plan_code text, service_plan_revision_no integer, down_kbps integer, up_kbps integer, data_quota_bytes bigint, device_limit integer, device_limit_policy text, time_accounting_mode text, grace_duration_seconds integer, end_mode text, policy_version text, settlement_mode text, is_current boolean, is_active boolean, mismatch_reason text)
    LANGUAGE sql STABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
  WITH candidate AS (
    SELECT ipr.id AS package_revision_id, ip.code AS package_code, ipr.revision_no,
           spr.id AS service_plan_revision_id, sp.code AS service_plan_code, spr.revision_no AS service_plan_revision_no,
           spr.down_kbps, spr.up_kbps, spr.data_quota_bytes,
           spr.max_concurrent_devices AS device_limit, spr.device_limit_policy, spr.time_accounting_mode,
           -- a non-numeric or oversized duration yields NULL, which the validator then rejects for THIS row
           CASE WHEN jsonb_typeof(ipr.duration_policy->'grace_duration_seconds') = 'number'
                     AND (ipr.duration_policy->>'grace_duration_seconds') ~ '^[0-9]{1,9}$'
                THEN (ipr.duration_policy->>'grace_duration_seconds')::int END AS grace_duration_seconds,
           CASE WHEN jsonb_typeof(ipr.duration_policy->'end_mode') = 'string'
                THEN ipr.duration_policy->>'end_mode' END AS end_mode,
           CASE WHEN jsonb_typeof(ipr.duration_policy->'policy_version') = 'string'
                THEN ipr.duration_policy->>'policy_version' END AS policy_version,
           array_to_string(ipr.settlement_methods, ',') AS settlement_mode,
           (ip.current_revision_id = ipr.id) AS is_current, ip.active AS is_active
      FROM iam_v2.internet_package_revisions ipr
      JOIN iam_v2.internet_packages ip
        ON ip.tenant_id = ipr.tenant_id AND ip.site_id = ipr.site_id AND ip.id = ipr.package_id
      JOIN iam_v2.service_plan_revisions spr
        ON spr.tenant_id = ipr.tenant_id AND spr.site_id = ipr.site_id AND spr.id = ipr.service_plan_revision_id
      JOIN iam_v2.service_plans sp
        ON sp.tenant_id = spr.tenant_id AND sp.site_id = spr.site_id AND sp.id = spr.service_plan_id
     WHERE ipr.tenant_id = p_tenant AND ipr.site_id = p_site
       AND ipr.package_type = 'CHECKOUT_GRACE')
  SELECT c.package_revision_id, c.package_code, c.revision_no,
         c.service_plan_revision_id, c.service_plan_code, c.service_plan_revision_no,
         c.down_kbps, c.up_kbps, c.data_quota_bytes,
         c.device_limit, c.device_limit_policy, c.time_accounting_mode,
         c.grace_duration_seconds, c.end_mode, c.policy_version,
         c.settlement_mode, c.is_current, c.is_active,
         -- judged by the SAME function publication uses, against the candidate's OWN values
         iam_v2.grace_package_mismatch_reason(p_tenant, p_site, c.package_revision_id,
             COALESCE(c.grace_duration_seconds, -1), c.down_kbps, c.up_kbps, c.data_quota_bytes,
             c.device_limit, c.device_limit_policy) AS mismatch_reason
    FROM candidate c
   ORDER BY c.package_code, c.revision_no DESC;
$_$;


--
-- Name: self_service_settings_changes_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.self_service_settings_changes_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'iam_v2.self_service_settings_changes is append-only: % refused', TG_OP
    USING ERRCODE = 'restrict_violation';
END $$;


--
-- Name: self_service_settings_get(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.self_service_settings_get(p_tenant uuid, p_site uuid) RETURNS TABLE(verification_required boolean, verification_deadline_hours integer, suspension_policy text, reminder_hours_before integer, resend_cooldown_seconds integer, resend_max_per_day integer, grace_minutes integer, max_grace_extensions integer, registrations_per_device_per_day integer, config_version bigint, updated_at timestamp with time zone, updated_by text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT COALESCE(s.verification_required, true),
         COALESCE(s.verification_deadline_hours, 24),
         COALESCE(s.suspension_policy, 'SUSPEND'),
         COALESCE(s.reminder_hours_before, 4),
         COALESCE(s.resend_cooldown_seconds, 60),
         COALESCE(s.resend_max_per_day, 5),
         COALESCE(s.grace_minutes, 60),
         COALESCE(s.max_grace_extensions, 1),
         COALESCE(s.registrations_per_device_per_day, 3),
         COALESCE(s.config_version, 0),
         s.updated_at,
         s.updated_by
    FROM (SELECT 1) one
    LEFT JOIN iam_v2.site_self_service_settings s
      ON s.tenant_id = p_tenant AND s.site_id = p_site;
$$;


--
-- Name: FUNCTION self_service_settings_get(p_tenant uuid, p_site uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.self_service_settings_get(p_tenant uuid, p_site uuid) IS 'The Email accounts settings in force for a site. config_version 0 with a null updated_at means no row exists and the answer is the contract defaults.';


--
-- Name: self_service_settings_set(uuid, uuid, boolean, integer, text, integer, integer, integer, integer, integer, integer, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.self_service_settings_set(p_tenant uuid, p_site uuid, p_verification_required boolean, p_verification_deadline_hours integer, p_suspension_policy text, p_reminder_hours_before integer, p_resend_cooldown_seconds integer, p_resend_max_per_day integer, p_grace_minutes integer, p_max_grace_extensions integer, p_registrations_per_device_per_day integer, p_operator text, p_reason text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_version bigint; v_old iam_v2.site_self_service_settings%ROWTYPE;
BEGIN
  IF p_operator IS NULL OR btrim(p_operator) = '' THEN
    RAISE EXCEPTION 'an operator label is required: "somebody changed it" is not an audit record'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 4 OR length(btrim(p_reason)) > 500 THEN
    RAISE EXCEPTION 'a reason of 4-500 characters is required to change the Email accounts settings'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_verification_required IS NULL THEN
    RAISE EXCEPTION 'verification_required must be true or false' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_verification_deadline_hours IS NULL OR p_verification_deadline_hours NOT BETWEEN 1 AND 168 THEN
    RAISE EXCEPTION 'verification_deadline_hours must be 1-168 (got %)', p_verification_deadline_hours
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_suspension_policy IS NULL OR p_suspension_policy NOT IN ('SUSPEND','WARN_ONLY') THEN
    RAISE EXCEPTION 'suspension_policy must be SUSPEND or WARN_ONLY (got %)', coalesce(p_suspension_policy,'null')
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_reminder_hours_before IS NULL OR p_reminder_hours_before NOT BETWEEN 0 AND 72
     OR p_reminder_hours_before >= p_verification_deadline_hours THEN
    RAISE EXCEPTION 'reminder_hours_before must be 0-72 and less than the deadline (got %)', p_reminder_hours_before
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_resend_cooldown_seconds IS NULL OR p_resend_cooldown_seconds NOT BETWEEN 30 AND 3600 THEN
    RAISE EXCEPTION 'resend_cooldown_seconds must be 30-3600 (got %)', p_resend_cooldown_seconds
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_resend_max_per_day IS NULL OR p_resend_max_per_day NOT BETWEEN 1 AND 20 THEN
    RAISE EXCEPTION 'resend_max_per_day must be 1-20 (got %)', p_resend_max_per_day
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_grace_minutes IS NULL OR p_grace_minutes NOT BETWEEN 15 AND 240 THEN
    RAISE EXCEPTION 'grace_minutes must be 15-240 (got %)', p_grace_minutes USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_max_grace_extensions IS NULL OR p_max_grace_extensions NOT BETWEEN 0 AND 3 THEN
    RAISE EXCEPTION 'max_grace_extensions must be 0-3 (got %)', p_max_grace_extensions
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_registrations_per_device_per_day IS NULL OR p_registrations_per_device_per_day NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION 'registrations_per_device_per_day must be 1-10 (got %)', p_registrations_per_device_per_day
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('self_service_settings'), hashtext(p_site::text));

  SELECT s.* INTO v_old
    FROM iam_v2.site_self_service_settings s
   WHERE s.tenant_id = p_tenant AND s.site_id = p_site
     FOR UPDATE;

  INSERT INTO iam_v2.site_self_service_settings AS s
    (tenant_id, site_id, verification_required, verification_deadline_hours, suspension_policy,
     reminder_hours_before, resend_cooldown_seconds, resend_max_per_day, grace_minutes, max_grace_extensions,
     registrations_per_device_per_day, updated_by)
  VALUES (p_tenant, p_site, p_verification_required, p_verification_deadline_hours, p_suspension_policy,
          p_reminder_hours_before, p_resend_cooldown_seconds, p_resend_max_per_day, p_grace_minutes,
          p_max_grace_extensions, p_registrations_per_device_per_day, btrim(p_operator))
  ON CONFLICT (tenant_id, site_id) DO UPDATE
     SET verification_required            = EXCLUDED.verification_required,
         verification_deadline_hours      = EXCLUDED.verification_deadline_hours,
         suspension_policy                = EXCLUDED.suspension_policy,
         reminder_hours_before            = EXCLUDED.reminder_hours_before,
         resend_cooldown_seconds          = EXCLUDED.resend_cooldown_seconds,
         resend_max_per_day               = EXCLUDED.resend_max_per_day,
         grace_minutes                    = EXCLUDED.grace_minutes,
         max_grace_extensions             = EXCLUDED.max_grace_extensions,
         registrations_per_device_per_day = EXCLUDED.registrations_per_device_per_day,
         updated_by                       = EXCLUDED.updated_by,
         config_version                   = s.config_version + 1,
         updated_at                       = now()
  RETURNING s.config_version INTO v_version;

  -- v_old is NULL-filled when no row existed: the first change records no "old" values, as in 0104.
  INSERT INTO iam_v2.self_service_settings_changes
    (tenant_id, site_id, changed_by, change_reason,
     old_verification_required, new_verification_required,
     old_verification_deadline_hours, new_verification_deadline_hours,
     old_suspension_policy, new_suspension_policy,
     old_reminder_hours_before, new_reminder_hours_before,
     old_resend_cooldown_seconds, new_resend_cooldown_seconds,
     old_resend_max_per_day, new_resend_max_per_day,
     old_grace_minutes, new_grace_minutes,
     old_max_grace_extensions, new_max_grace_extensions,
     old_registrations_per_device_per_day, new_registrations_per_device_per_day,
     new_config_version)
  VALUES (p_tenant, p_site, btrim(p_operator), btrim(p_reason),
          v_old.verification_required, p_verification_required,
          v_old.verification_deadline_hours, p_verification_deadline_hours,
          v_old.suspension_policy, p_suspension_policy,
          v_old.reminder_hours_before, p_reminder_hours_before,
          v_old.resend_cooldown_seconds, p_resend_cooldown_seconds,
          v_old.resend_max_per_day, p_resend_max_per_day,
          v_old.grace_minutes, p_grace_minutes,
          v_old.max_grace_extensions, p_max_grace_extensions,
          v_old.registrations_per_device_per_day, p_registrations_per_device_per_day,
          v_version);

  RETURN v_version;
END $$;


--
-- Name: FUNCTION self_service_settings_set(p_tenant uuid, p_site uuid, p_verification_required boolean, p_verification_deadline_hours integer, p_suspension_policy text, p_reminder_hours_before integer, p_resend_cooldown_seconds integer, p_resend_max_per_day integer, p_grace_minutes integer, p_max_grace_extensions integer, p_registrations_per_device_per_day integer, p_operator text, p_reason text); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.self_service_settings_set(p_tenant uuid, p_site uuid, p_verification_required boolean, p_verification_deadline_hours integer, p_suspension_policy text, p_reminder_hours_before integer, p_resend_cooldown_seconds integer, p_resend_max_per_day integer, p_grace_minutes integer, p_max_grace_extensions integer, p_registrations_per_device_per_day integer, p_operator text, p_reason text) IS 'Stores validated Email accounts settings and returns the new config_version, recording the old and new values with the operator and the reason. Existing deadlines are not moved: a change applies to accounts registered after it (and to the sweep''s suspension and reminder decisions at once).';


--
-- Name: service_plan_delete_unused(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.service_plan_delete_unused(p_tenant uuid, p_site uuid, p_plan uuid, p_operator uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'public', 'pg_temp'
    AS $$
DECLARE
  v_blockers text;
  v_n integer;
BEGIN
  IF p_operator IS NULL THEN
    RAISE EXCEPTION 'CATALOGUE_DELETE_NEEDS_AN_OPERATOR' USING ERRCODE = 'check_violation';
  END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 4 THEN
    RAISE EXCEPTION 'CATALOGUE_DELETE_NEEDS_A_REASON' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM 1 FROM iam_v2.service_plans
    WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_plan FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PLAN_NOT_FOUND: no plan % for tenant %/site %', p_plan, p_tenant, p_site
      USING ERRCODE = 'no_data_found';
  END IF;

  SELECT string_agg(b.reason || '=' || b.n, ',' ORDER BY b.reason) INTO v_blockers
    FROM iam_v2.service_plan_deletion_blockers(p_tenant, p_site, p_plan) b;
  IF v_blockers IS NOT NULL THEN
    RAISE EXCEPTION 'PLAN_IN_USE: %', v_blockers USING ERRCODE = 'restrict_violation';
  END IF;

  PERFORM set_config('iam_v2.catalogue_purge', 'unused', true);
  UPDATE iam_v2.service_plans SET current_revision_id = NULL
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_plan;
  DELETE FROM iam_v2.service_plan_revisions
   WHERE tenant_id = p_tenant AND site_id = p_site AND service_plan_id = p_plan;
  DELETE FROM iam_v2.service_plans
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_plan;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  PERFORM set_config('iam_v2.catalogue_purge', '', true);
  IF v_n <> 1 THEN
    RAISE EXCEPTION 'PLAN_NOT_DELETED: plan % was not removed', p_plan USING ERRCODE = 'check_violation';
  END IF;
END $$;


--
-- Name: service_plan_deletion_blockers(uuid, uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.service_plan_deletion_blockers(p_tenant uuid, p_site uuid, p_plan uuid) RETURNS TABLE(reason text, n bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'public', 'pg_temp'
    AS $$
DECLARE
  v_plan iam_v2.service_plans%ROWTYPE;
  v_revs uuid[];
BEGIN
  SELECT * INTO v_plan FROM iam_v2.service_plans
   WHERE tenant_id = p_tenant AND site_id = p_site AND id = p_plan;
  IF NOT FOUND THEN
    reason := 'NOT_FOUND'; n := 1; RETURN NEXT; RETURN;
  END IF;
  IF v_plan.code IN ('__sys_emergency_grace_plan__') THEN
    reason := 'SYSTEM_PLAN'; n := 1; RETURN NEXT;
  END IF;

  SELECT coalesce(array_agg(r.id), '{}') INTO v_revs FROM iam_v2.service_plan_revisions r
   WHERE r.tenant_id = p_tenant AND r.site_id = p_site AND r.service_plan_id = p_plan;

  RETURN QUERY
  SELECT x.reason, x.n FROM (
    -- EVERY package revision, current or superseded: a superseded revision is the history of a package that
    -- may have been sold, and it cannot be allowed to point at a plan that no longer exists.
    SELECT 'PACKAGE_REVISIONS' AS reason, (SELECT count(*) FROM iam_v2.internet_package_revisions pr
      WHERE pr.tenant_id = p_tenant AND pr.site_id = p_site AND pr.service_plan_revision_id = ANY (v_revs)) AS n
    UNION ALL SELECT 'ENTITLEMENTS', (SELECT count(*) FROM iam_v2.entitlements e
      WHERE e.tenant_id = p_tenant AND e.site_id = p_site AND e.service_plan_revision_id = ANY (v_revs))
  ) x WHERE x.n > 0;
END $$;


--
-- Name: site_day_start(uuid, date); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.site_day_start(p_site uuid, p_day date) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT p_day::timestamp AT TIME ZONE COALESCE((SELECT s.timezone FROM public.sites s WHERE s.id = p_site), 'UTC');
$$;


--
-- Name: FUNCTION site_day_start(p_site uuid, p_day date); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.site_day_start(p_site uuid, p_day date) IS 'Midnight at the start of a date, in the site''s time zone (public.sites.timezone; UTC if unknown) (0144).';


--
-- Name: site_module_changes_append_only(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.site_module_changes_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'iam_v2.site_module_changes is append-only: % refused', TG_OP
    USING ERRCODE = 'restrict_violation';
END $$;


--
-- Name: site_module_get(uuid, uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.site_module_get(p_tenant uuid, p_site uuid) RETURNS TABLE(module_id text, enabled boolean, config_version bigint, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT m.id, COALESCE(s.enabled, false), COALESCE(s.config_version, 0), s.updated_at
    FROM unnest(ARRAY['hospitality','paid_access','card_payment','room_charge']) AS m(id)
    LEFT JOIN iam_v2.site_module_settings s
      ON s.tenant_id = p_tenant AND s.site_id = p_site AND s.module_id = m.id
   ORDER BY m.id;
$$;


--
-- Name: site_module_set(uuid, uuid, text, boolean, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.site_module_set(p_tenant uuid, p_site uuid, p_module text, p_enabled boolean, p_operator text, p_reason text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_old boolean; v_version bigint;
BEGIN
  IF p_operator IS NULL OR btrim(p_operator) = '' THEN
    RAISE EXCEPTION 'an operator label is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_module IS NULL OR p_module NOT IN ('hospitality','paid_access','card_payment','room_charge') THEN
    RAISE EXCEPTION 'unknown switchable module %', p_module USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_enabled IS NULL THEN
    RAISE EXCEPTION 'enabled must be true or false' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('site_module_settings'), hashtext(p_site::text));
  SELECT s.enabled INTO v_old FROM iam_v2.site_module_settings s
   WHERE s.tenant_id = p_tenant AND s.site_id = p_site AND s.module_id = p_module FOR UPDATE;
  INSERT INTO iam_v2.site_module_settings AS s (tenant_id, site_id, module_id, enabled)
  VALUES (p_tenant, p_site, p_module, p_enabled)
  ON CONFLICT (tenant_id, site_id, module_id) DO UPDATE
     SET enabled = EXCLUDED.enabled, config_version = s.config_version + 1, updated_at = now()
  RETURNING s.config_version INTO v_version;
  INSERT INTO iam_v2.site_module_changes
    (tenant_id, site_id, module_id, changed_by, change_reason, old_enabled, new_enabled, new_config_version)
  VALUES (p_tenant, p_site, p_module, btrim(p_operator), NULLIF(btrim(COALESCE(p_reason,'')),''),
          v_old, p_enabled, v_version);
  RETURN v_version;
END $$;


--
-- Name: FUNCTION site_module_set(p_tenant uuid, p_site uuid, p_module text, p_enabled boolean, p_operator text, p_reason text); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.site_module_set(p_tenant uuid, p_site uuid, p_module text, p_enabled boolean, p_operator text, p_reason text) IS 'Switches a licensed module on or off for a site and records the change. Does not check the licence: enabling an unlicensed module stores the choice but the resolver still refuses it (the licence is a separate gate). Takes effect on the next resolver read; no restart.';


--
-- Name: site_payment_domains_set(uuid, uuid, text[], text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.site_payment_domains_set(p_tenant uuid, p_site uuid, p_domains text[], p_operator text, p_reason text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_old text[]; v_version bigint; d text;
BEGIN
  IF p_operator IS NULL OR btrim(p_operator) = '' THEN
    RAISE EXCEPTION 'an operator label is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_domains IS NULL OR cardinality(p_domains) > 20 THEN
    RAISE EXCEPTION 'at most 20 payment domains' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  FOREACH d IN ARRAY p_domains LOOP
    IF NOT iam_v2.valid_payment_domain(d) THEN
      RAISE EXCEPTION 'PAYMENT_DOMAIN_INVALID: %', d USING ERRCODE = 'invalid_parameter_value';
    END IF;
  END LOOP;
  PERFORM pg_advisory_xact_lock(hashtext('site_payment_domains'), hashtext(p_site::text));
  SELECT domains INTO v_old FROM iam_v2.site_payment_domains
   WHERE tenant_id = p_tenant AND site_id = p_site FOR UPDATE;
  INSERT INTO iam_v2.site_payment_domains AS s (tenant_id, site_id, domains)
  VALUES (p_tenant, p_site, p_domains)
  ON CONFLICT (tenant_id, site_id) DO UPDATE
     SET domains = EXCLUDED.domains, config_version = s.config_version + 1, updated_at = now()
  RETURNING s.config_version INTO v_version;
  INSERT INTO iam_v2.site_payment_domain_changes (tenant_id, site_id, changed_by, change_reason, old_domains, new_domains)
  VALUES (p_tenant, p_site, btrim(p_operator), NULLIF(btrim(coalesce(p_reason,'')),''), v_old, p_domains);
  RETURN v_version;
END $$;


--
-- Name: site_today(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.site_today(p_site uuid) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT (now() AT TIME ZONE COALESCE((SELECT s.timezone FROM public.sites s WHERE s.id = p_site), 'UTC'))::date;
$$;


--
-- Name: staff_release_device_slot(uuid, uuid, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.staff_release_device_slot(p_tenant uuid, p_site uuid, p_entitlement uuid, p_device uuid, p_operator uuid, p_operator_label text, p_reason text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_status text; v_online int; v_out text;
BEGIN
  IF p_operator_label IS NULL OR btrim(p_operator_label) = '' THEN
    RAISE EXCEPTION 'an operator label is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 4 OR length(btrim(p_reason)) > 500 THEN
    RAISE EXCEPTION 'a reason of 4-500 characters is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  PERFORM 1 FROM iam_v2.entitlements e
   WHERE e.id = p_entitlement AND e.tenant_id = p_tenant AND e.site_id = p_site FOR UPDATE;
  IF NOT FOUND THEN
    v_out := 'REFUSED_NO_PACKAGE';
  ELSE
    SELECT ed.status INTO v_status FROM iam_v2.entitlement_devices ed
     WHERE ed.entitlement_id = p_entitlement AND ed.device_id = p_device;
    IF v_status IS NULL THEN v_out := 'REFUSED_NOT_FOUND';
    ELSIF v_status <> 'AUTHORIZED' THEN v_out := 'REFUSED_ALREADY_RELEASED';
    ELSE
      SELECT count(*) INTO v_online FROM iam_v2.sessions s
       WHERE s.entitlement_id = p_entitlement AND s.device_id = p_device
         AND s.state IN ('active','PENDING_ENFORCEMENT');
      IF v_online > 0 THEN v_out := 'REFUSED_ONLINE';
      ELSIF iam_v2.deauthorize_entitlement_device(p_entitlement, p_device, now(), 'STAFF_RELEASED') THEN
        v_out := 'OK';
      ELSE v_out := 'REFUSED_ALREADY_RELEASED';
      END IF;
    END IF;
  END IF;
  INSERT INTO iam_v2.device_slot_actions
    (tenant_id, site_id, entitlement_id, device_id, actor, operator_id, operator_label, action, outcome, reason)
  VALUES (p_tenant, p_site, CASE WHEN v_out <> 'REFUSED_NO_PACKAGE' THEN p_entitlement END, p_device, 'STAFF',
          p_operator, btrim(p_operator_label), 'RELEASE', v_out, btrim(p_reason));
  RETURN v_out;
END $$;


--
-- Name: FUNCTION staff_release_device_slot(p_tenant uuid, p_site uuid, p_entitlement uuid, p_device uuid, p_operator uuid, p_operator_label text, p_reason text); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.staff_release_device_slot(p_tenant uuid, p_site uuid, p_entitlement uuid, p_device uuid, p_operator uuid, p_operator_label text, p_reason text) IS 'Staff free one device''s slot on one package (0118). Offline devices only (edged disconnects first); reason required; recorded in device_slot_actions. The package''s window, consumption and ownership are untouched.';


--
-- Name: staff_require_device_signin(uuid, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.staff_require_device_signin(p_tenant uuid, p_site uuid, p_device uuid, p_operator uuid, p_operator_label text, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_n integer;
BEGIN
  IF p_operator_label IS NULL OR btrim(p_operator_label) = '' THEN
    RAISE EXCEPTION 'an operator label is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 4 OR length(btrim(p_reason)) > 500 THEN
    RAISE EXCEPTION 'a reason of 4-500 characters is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  PERFORM 1 FROM iam_v2.devices d WHERE d.id = p_device AND d.tenant_id = p_tenant AND d.site_id = p_site;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'device % is not at this site', p_device USING ERRCODE = 'foreign_key_violation';
  END IF;
  -- The device-bound remembered sign-in ("Welcome back"). Revoked, never deleted.
  UPDATE iam_v2.principal_device_credentials c SET revoked_at = now()
   WHERE c.tenant_id = p_tenant AND c.site_id = p_site AND c.device_id = p_device AND c.revoked_at IS NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  INSERT INTO iam_v2.device_slot_actions
    (tenant_id, site_id, device_id, actor, operator_id, operator_label, action, outcome, reason, detail)
  VALUES (p_tenant, p_site, p_device, 'STAFF', p_operator, btrim(p_operator_label), 'REQUIRE_SIGNIN', 'OK',
          btrim(p_reason), v_n || ' remembered sign-in(s) revoked');
  RETURN v_n;
END $$;


--
-- Name: FUNCTION staff_require_device_signin(p_tenant uuid, p_site uuid, p_device uuid, p_operator uuid, p_operator_label text, p_reason text); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.staff_require_device_signin(p_tenant uuid, p_site uuid, p_device uuid, p_operator uuid, p_operator_label text, p_reason text) IS 'Staff make a device sign in afresh (0118): its remembered sign-in is revoked (edged also ends its sessions through enforcement). Slots and packages are untouched; recorded in device_slot_actions.';


--
-- Name: stay_absent_from_published_roster(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.stay_absent_from_published_roster(p_stay uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM iam_v2.stays s
      JOIN iam_v2.pms_interface_runtime r
        ON r.tenant_id = s.tenant_id AND r.site_id = s.site_id AND r.pms_interface_id = s.pms_interface_id
       AND r.published_resync_generation > 0
      CROSS JOIN LATERAL (
        SELECT COALESCE(r.last_complete_sync_at, max(se.received_at)) AS sent_at FROM iam_v2.stay_events se
         WHERE se.tenant_id = s.tenant_id AND se.site_id = s.site_id AND se.pms_interface_id = s.pms_interface_id
           AND se.admission_kind = 'RESYNC' AND se.resync_generation = r.published_resync_generation) roster
     WHERE s.id = p_stay
       AND roster.sent_at IS NOT NULL
       AND roster.sent_at > COALESCE((SELECT max(e.received_at) FROM iam_v2.stay_events e WHERE e.stay_id = s.id), 'infinity')
       AND NOT EXISTS (
         SELECT 1 FROM iam_v2.stay_events se
          WHERE se.tenant_id = s.tenant_id AND se.site_id = s.site_id AND se.pms_interface_id = s.pms_interface_id
            AND se.admission_kind = 'RESYNC' AND se.resync_generation = r.published_resync_generation
            AND se.event_type IN ('GI', 'GC')
            AND (btrim(COALESCE(se.payload->>'reservation', '')) = s.external_reservation_id
                 OR (btrim(COALESCE(se.payload->>'reservation', '')) = ''
                     AND upper(btrim(COALESCE(se.payload->>'room', ''))) = s.normalized_room_number))));
$$;


--
-- Name: FUNCTION stay_absent_from_published_roster(p_stay uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.stay_absent_from_published_roster(p_stay uuid) IS 'True only when the stay''s PMS has published a full room list (a resync), that list was published (last_complete_sync_at) after the last message about the stay, and the stay is not in it. False when no list was published, or the stay heard from the PMS since: nothing can be concluded (0143, 0144).';


--
-- Name: stay_guests_as_json(uuid[]); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.stay_guests_as_json(p_guests uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  -- 'rival': someone else on the same stay has this guest's surname, so a surname alone cannot say which of them
  -- a PMS message means.
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', sg.external_guest_id, 'iface', sg.pms_interface_id,
                                               'first', upper(btrim(sg.first_name_norm)),
                                               'last', upper(btrim(sg.last_name_norm)),
                                               'rival', EXISTS (SELECT 1 FROM iam_v2.stay_guests o
                                                                 WHERE o.stay_id = sg.stay_id AND NOT o.id = ANY (p_guests)
                                                                   AND upper(btrim(o.last_name_norm)) = upper(btrim(sg.last_name_norm))))),
                    '[]'::jsonb)
    FROM iam_v2.stay_guests sg WHERE sg.id = ANY (p_guests);
$$;


--
-- Name: stay_named_guests(uuid); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.stay_named_guests(p_stay uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
  SELECT count(*)::integer FROM iam_v2.stay_guests sg
   WHERE sg.stay_id = p_stay AND num_nonnulls(sg.first_name_norm, sg.last_name_norm, sg.display_name, sg.external_guest_id) > 0;
$$;


--
-- Name: FUNCTION stay_named_guests(p_stay uuid); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.stay_named_guests(p_stay uuid) IS 'How many guests are still named on a stay (0141, GDPR audit C3): more than one makes it a shared stay, exported and erased one guest at a time.';


--
-- Name: stay_posting_blocks_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.stay_posting_blocks_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'stay_posting_blocks is not deletable' USING ERRCODE = 'restrict_violation';
  END IF;
  IF current_setting('iam_v2.anonymise', true) = 'retention'
     AND current_user = (SELECT pg_get_userbyid(c.relowner) FROM pg_class c WHERE c.oid = TG_RELID)
     AND (NEW.note IS NOT DISTINCT FROM OLD.note OR NEW.note = 'Removed after the staff-notes period')
     AND (NEW.cleared_reason IS NOT DISTINCT FROM OLD.cleared_reason OR NEW.cleared_reason = 'Removed after the staff-notes period')
     AND (to_jsonb(NEW) - 'note' - 'cleared_reason') = (to_jsonb(OLD) - 'note' - 'cleared_reason') THEN
    RETURN NEW;
  END IF;
  IF ROW(NEW.id, NEW.tenant_id, NEW.site_id, NEW.pms_interface_id, NEW.stay_id, NEW.reason, NEW.source, NEW.posting_id,
         NEW.pa_as_status, NEW.note, NEW.created_by, NEW.created_at)
     IS DISTINCT FROM ROW(OLD.id, OLD.tenant_id, OLD.site_id, OLD.pms_interface_id, OLD.stay_id, OLD.reason, OLD.source,
         OLD.posting_id, OLD.pa_as_status, OLD.note, OLD.created_by, OLD.created_at) THEN
    RAISE EXCEPTION 'stay_posting_blocks identity is immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.cleared_at IS NOT NULL THEN
    RAISE EXCEPTION 'a cleared posting block stays cleared' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: supersede_entitlement_transition(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.supersede_entitlement_transition(p_target uuid, p_to text, p_at timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE v_ent uuid; v_seq bigint; v_new uuid; v_term text; v_head uuid; v_from text;
BEGIN
  IF p_reason IS NOT NULL AND p_reason !~ '^[A-Z][A-Z0-9_]{0,63}$' THEN
    RAISE EXCEPTION 'transition reason must be a bounded machine code';
  END IF;
  IF p_to NOT IN ('PENDING','ACTIVE','SUSPENDED','TERMINATED') THEN
    RAISE EXCEPTION 'invalid target state %', p_to;
  END IF;
  SELECT entitlement_id INTO v_ent
    FROM iam_v2.entitlement_state_transitions WHERE id = p_target AND superseded_by IS NULL;
  IF v_ent IS NULL THEN RAISE EXCEPTION 'transition % not found or already superseded', p_target; END IF;
  -- L3 Entitlement lock before any write (global lock order)
  PERFORM 1 FROM iam_v2.entitlements WHERE id = v_ent FOR UPDATE;
  SELECT id INTO v_head FROM iam_v2.entitlement_state_transitions
    WHERE entitlement_id = v_ent AND superseded_by IS NULL ORDER BY seq DESC LIMIT 1;
  IF v_head IS DISTINCT FROM p_target THEN
    RAISE EXCEPTION 'only the live head transition may be superseded (head is %)', v_head;
  END IF;
  SELECT COALESCE(max(seq),0)+1 INTO v_seq FROM iam_v2.entitlement_state_transitions WHERE entitlement_id = v_ent;
  v_new := gen_random_uuid();
  -- INVALIDATE first, then append: the chain guard must judge the correction against the history that remains.
  UPDATE iam_v2.entitlement_state_transitions SET superseded_by = v_new WHERE id = p_target;
  SELECT to_state INTO v_from FROM iam_v2.entitlement_state_transitions
    WHERE entitlement_id = v_ent AND superseded_by IS NULL ORDER BY seq DESC LIMIT 1;
  v_term := CASE WHEN p_to='TERMINATED' THEN
    (CASE WHEN p_reason IN ('TIME','DATA','HARD_EXPIRY','CHECKOUT','ADMIN','REVOKED','SUPERSEDED','CONVERTED','TRANSFERRED','CANCELLED','OTHER')
          THEN p_reason ELSE 'OTHER' END) ELSE NULL END;
  -- status first, so the INSERT guard's history<->row coherence check sees the corrected state
  UPDATE iam_v2.entitlements SET status = p_to, terminal_reason = v_term WHERE id = v_ent;
  INSERT INTO iam_v2.entitlement_state_transitions
    (id,tenant_id,site_id,entitlement_id,seq,from_state,to_state,effective_at,recorded_at,supersedes,reason)
    SELECT v_new, tenant_id, site_id, id, v_seq, v_from, p_to, p_at, now(), p_target, p_reason
    FROM iam_v2.entitlements WHERE id = v_ent;
  PERFORM iam_v2.p3_rederive_entitlement_times(v_ent);
  RETURN v_new;
END $_$;


--
-- Name: terminate_entitlement_at_boundary(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.terminate_entitlement_at_boundary(p_ent uuid, p_at timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $_$
DECLARE v_status text; v_seq bigint; v_new uuid; v_term text; v_from text; v_head uuid; v_marked int;
BEGIN
  IF p_reason IS NOT NULL AND p_reason !~ '^[A-Z][A-Z0-9_]{0,63}$' THEN
    RAISE EXCEPTION 'transition reason must be a bounded machine code';
  END IF;
  SELECT status INTO v_status FROM iam_v2.entitlements WHERE id = p_ent FOR UPDATE;
  IF v_status IS NULL THEN RAISE EXCEPTION 'entitlement % not found', p_ent; END IF;
  IF v_status = 'TERMINATED' THEN RETURN NULL; END IF;
  SELECT COALESCE(max(seq),0)+1 INTO v_seq FROM iam_v2.entitlement_state_transitions WHERE entitlement_id = p_ent;
  v_new := gen_random_uuid();
  SELECT id INTO v_head FROM iam_v2.entitlement_state_transitions
    WHERE entitlement_id = p_ent AND superseded_by IS NULL AND effective_at > p_at ORDER BY seq DESC LIMIT 1;
  UPDATE iam_v2.entitlement_state_transitions SET superseded_by = v_new
    WHERE entitlement_id = p_ent AND superseded_by IS NULL AND effective_at > p_at;
  GET DIAGNOSTICS v_marked = ROW_COUNT;
  SELECT to_state INTO v_from FROM iam_v2.entitlement_state_transitions
    WHERE entitlement_id = p_ent AND superseded_by IS NULL ORDER BY seq DESC LIMIT 1;
  v_term := CASE WHEN p_reason IN ('TIME','DATA','HARD_EXPIRY','CHECKOUT','ADMIN','REVOKED','SUPERSEDED','CONVERTED','TRANSFERRED','CANCELLED','OTHER')
                 THEN p_reason ELSE 'OTHER' END;
  UPDATE iam_v2.entitlements SET status = 'TERMINATED', terminal_reason = v_term WHERE id = p_ent;
  INSERT INTO iam_v2.entitlement_state_transitions
    (id,tenant_id,site_id,entitlement_id,seq,from_state,to_state,effective_at,recorded_at,supersedes,reason)
    SELECT v_new, tenant_id, site_id, id, v_seq, v_from, 'TERMINATED', p_at, now(),
           CASE WHEN v_marked > 0 THEN v_head ELSE NULL END, p_reason
    FROM iam_v2.entitlements WHERE id = p_ent;
  PERFORM iam_v2.p3_rederive_entitlement_times(p_ent);
  RETURN v_new;
END $_$;


--
-- Name: text_names_any(text, text[]); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.text_names_any(p_text text, p_vals text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT p_text IS NOT NULL AND EXISTS (
    SELECT 1 FROM unnest(p_vals) v
     WHERE length(v) >= 3
       AND (lower(btrim(p_text)) = v
            OR lower(p_text) ~ ('(^|[^[:alnum:]])' || regexp_replace(v, '([.*+?^${}()|\[\]\\-])', '\\\1', 'g')
                                || '($|[^[:alnum:]])')));
$_$;


--
-- Name: trg_catalogue_revision_immutable(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.trg_catalogue_revision_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_owner name;
BEGIN
  IF TG_OP = 'DELETE' AND current_setting('iam_v2.catalogue_purge', true) = 'unused' THEN
    SELECT pg_get_userbyid(c.relowner) INTO v_owner FROM pg_class c WHERE c.oid = TG_RELID;
    IF current_user = v_owner THEN
      RETURN OLD;
    END IF;
  END IF;
  -- Word for word what trg_reject_update_delete() says, so nothing that matches on it changes meaning.
  RAISE EXCEPTION '% is immutable (no UPDATE/DELETE) on %', TG_TABLE_NAME, TG_OP;
END $$;


--
-- Name: trg_entitlement_guard(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.trg_entitlement_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE s_key text; os_key text; v_owner text; v_trusted boolean; v_adj text; v_field text; v_new text;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF OLD.status='TERMINATED' AND NEW.status<>'TERMINATED' THEN
      RAISE EXCEPTION 'no transition out of TERMINATED'; END IF;

    -- WHO IS WRITING. The controlled writers are SECURITY DEFINER functions owned by the owner of
    -- apply_entitlement_transition, so inside them current_user is that owner. A superuser is the maintenance
    -- path. Everybody else -- every runtime role -- is untrusted here. Resolved from the catalog on every call,
    -- like p3_controlled_writer_only, so a re-owned schema is followed rather than hard-coded.
    SELECT pg_get_userbyid(p.proowner) INTO v_owner FROM pg_proc p
     WHERE p.oid = to_regprocedure('iam_v2.apply_entitlement_transition(uuid,text,timestamptz,text)');
    v_trusted := current_user = v_owner
              OR EXISTS (SELECT 1 FROM pg_roles WHERE rolname = current_user AND rolsuper);

    -- AN UNTRUSTED CALLER CHANGES NOTHING BUT STATUS, and status has its own controlled-writer guard
    -- (p3_entitlement_controlled_writer), which refuses it outside apply_entitlement_transition. The window, the
    -- counters, the quota (data_quota_bytes), the pinned plan and package (service_plan_revision_id,
    -- package_revision_id), the policy snapshot, the subject and the scope are the terms the entitlement was
    -- granted on; none is a runtime write.
    IF NOT v_trusted AND (to_jsonb(NEW) - 'status') IS DISTINCT FROM (to_jsonb(OLD) - 'status') THEN
      RAISE EXCEPTION 'entitlements: the terms of a grant are written only by the controlled iam_v2 writers (caller %)',
        current_user USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF ( NEW.consumed_data_bytes < OLD.consumed_data_bytes
      OR NEW.consumed_online_seconds < OLD.consumed_online_seconds
      OR (OLD.window_ends_at IS NOT NULL AND NEW.window_ends_at IS DISTINCT FROM OLD.window_ends_at) ) THEN
      v_adj := current_setting('iam_v2.allow_adjust', true);
      IF v_adj = 'on' AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = current_user AND rolsuper) THEN
        NULL;  -- the superuser maintenance path, as before
      ELSE
        -- The ONE field this statement moves, and the value it moves it to. A statement that moves two of them
        -- matches no single recorded adjustment and is refused.
        IF NEW.consumed_data_bytes < OLD.consumed_data_bytes
           AND NEW.window_ends_at IS NOT DISTINCT FROM OLD.window_ends_at
           AND NEW.consumed_online_seconds >= OLD.consumed_online_seconds THEN
          v_field := 'consumed_data_bytes'; v_new := NEW.consumed_data_bytes::text;
        ELSIF OLD.window_ends_at IS NOT NULL AND NEW.window_ends_at IS DISTINCT FROM OLD.window_ends_at
           AND NEW.consumed_data_bytes >= OLD.consumed_data_bytes
           AND NEW.consumed_online_seconds >= OLD.consumed_online_seconds THEN
          v_field := 'window_ends_at'; v_new := NEW.window_ends_at::text;
        END IF;
        IF v_field IS NULL OR v_adj IS NULL OR v_adj !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR NOT EXISTS (SELECT 1 FROM iam_v2.entitlement_adjustments a
                           WHERE a.id = v_adj::uuid AND a.entitlement_id = NEW.id AND a.field = v_field
                             AND a.created_at = now()
                             AND a.new_value IS NOT DISTINCT FROM v_new) THEN
          RAISE EXCEPTION 'counter decrease / window move only via entitlement_adjustments';
        END IF;
      END IF;
    END IF;
  END IF;
  IF NEW.supersedes_entitlement_id IS NOT NULL THEN
    SELECT CASE WHEN stay_id IS NOT NULL THEN 'stay:'||stay_id WHEN guest_account_id IS NOT NULL THEN 'acct:'||guest_account_id
                WHEN voucher_id IS NOT NULL THEN 'vou:'||voucher_id ELSE 'prin:'||guest_principal_id END
      INTO os_key FROM iam_v2.entitlements WHERE id=NEW.supersedes_entitlement_id;
    s_key := CASE WHEN NEW.stay_id IS NOT NULL THEN 'stay:'||NEW.stay_id WHEN NEW.guest_account_id IS NOT NULL THEN 'acct:'||NEW.guest_account_id
                  WHEN NEW.voucher_id IS NOT NULL THEN 'vou:'||NEW.voucher_id ELSE 'prin:'||NEW.guest_principal_id END;
    IF s_key IS DISTINCT FROM os_key THEN RAISE EXCEPTION 'cross-subject supersession rejected (% vs %)', s_key, os_key; END IF;
  END IF;
  RETURN NEW;
END; $_$;


--
-- Name: FUNCTION trg_entitlement_guard(); Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON FUNCTION iam_v2.trg_entitlement_guard() IS 'Entitlement row guard (0124): no transition out of TERMINATED; a caller that is neither the controlled writers'' owner nor a superuser changes no column but status; a counter decrease or window move needs a superuser with iam_v2.allow_adjust=on or an entitlement_adjustments row recorded in this transaction for this entitlement, field and value, named by iam_v2.allow_adjust; no cross-subject supersession.';


--
-- Name: trg_offer_quote_immutable(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.trg_offer_quote_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.consumed_at IS NOT NULL THEN
    RAISE EXCEPTION 'offer_quote % is already consumed (immutable)', OLD.id USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.consumed_at IS NULL THEN
    RAISE EXCEPTION 'offer_quote consumed_at may not be cleared' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.tenant_id            IS DISTINCT FROM OLD.tenant_id
   OR NEW.site_id             IS DISTINCT FROM OLD.site_id
   OR NEW.auth_context_id     IS DISTINCT FROM OLD.auth_context_id
   OR NEW.package_revision_id IS DISTINCT FROM OLD.package_revision_id
   OR NEW.pms_interface_id    IS DISTINCT FROM OLD.pms_interface_id
   OR NEW.settlement_mapping_id IS DISTINCT FROM OLD.settlement_mapping_id
   OR NEW.price_minor         IS DISTINCT FROM OLD.price_minor
   OR NEW.currency            IS DISTINCT FROM OLD.currency
   OR NEW.currency_exponent   IS DISTINCT FROM OLD.currency_exponent
   OR NEW.tax_code            IS DISTINCT FROM OLD.tax_code
   OR NEW.tax_rate_bp         IS DISTINCT FROM OLD.tax_rate_bp
   OR NEW.tax_amount_minor    IS DISTINCT FROM OLD.tax_amount_minor
   OR NEW.grant_snapshot      IS DISTINCT FROM OLD.grant_snapshot
   OR NEW.expires_at          IS DISTINCT FROM OLD.expires_at THEN
    RAISE EXCEPTION 'offer_quote % is immutable except one-time consumption', OLD.id USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: trg_posting_attempt_oneway(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.trg_posting_attempt_oneway() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'posting_attempts is not deletable'; END IF;
  IF ROW(NEW.p_number,NEW.rn,NEW.g_number,NEW.sent_at,NEW.internal_posting_id,NEW.attempt_no,NEW.pms_interface_id,NEW.ps_sha256)
     IS DISTINCT FROM ROW(OLD.p_number,OLD.rn,OLD.g_number,OLD.sent_at,OLD.internal_posting_id,OLD.attempt_no,OLD.pms_interface_id,OLD.ps_sha256)
  THEN RAISE EXCEPTION 'posting_attempts identity is immutable'; END IF;
  IF OLD.outcome <> 'SENDING' AND NEW.outcome <> OLD.outcome THEN
     RAISE EXCEPTION 'posting_attempts.outcome is terminal (% -> %)', OLD.outcome, NEW.outcome; END IF;
  IF NEW.outcome = 'SENDING' AND OLD.outcome <> 'SENDING' THEN
     RAISE EXCEPTION 'posting_attempts.outcome cannot return to SENDING'; END IF;
  RETURN NEW;
END; $$;


--
-- Name: trg_posting_charge_gate(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.trg_posting_charge_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam_v2', 'pg_temp'
    AS $$
DECLARE v_model text; st record;
BEGIN
  IF NEW.posting_type = 'CHARGE' THEN
    SELECT posting_target_model INTO v_model FROM iam_v2.pms_interface_revisions
      WHERE tenant_id=NEW.tenant_id AND site_id=NEW.site_id AND pms_interface_id=NEW.pms_interface_id AND id=NEW.posting_interface_revision_id;
    IF v_model IS NULL OR v_model = 'UNSET' THEN
      RAISE EXCEPTION 'POSTING_TARGET_UNSET: financial CHARGE blocked fail-closed (interface %, revision %)', NEW.pms_interface_id, NEW.posting_interface_revision_id
        USING ERRCODE='check_violation';
    END IF;
    IF NEW.stay_id IS NULL THEN
      RAISE EXCEPTION 'POSTING_NO_STAY: a CHARGE targets a stay''s reservation' USING ERRCODE='check_violation';
    END IF;
    -- Locking the stay serialises concurrent charges for it, so the one-unresolved check below cannot race.
    SELECT status, posting_allowed, external_reservation_id INTO st FROM iam_v2.stays
      WHERE tenant_id=NEW.tenant_id AND site_id=NEW.site_id AND pms_interface_id=NEW.pms_interface_id AND id=NEW.stay_id
      FOR UPDATE;
    IF st.status IS DISTINCT FROM 'IN_HOUSE' OR st.posting_allowed IS NOT TRUE THEN
      RAISE EXCEPTION 'POSTING_NOT_ALLOWED: stay % not IN_HOUSE/posting_allowed', NEW.stay_id USING ERRCODE='check_violation';
    END IF;
    IF NEW.g_number IS DISTINCT FROM st.external_reservation_id THEN
      RAISE EXCEPTION 'POSTING_RESERVATION_MISMATCH: a CHARGE carries its stay''s reservation number' USING ERRCODE='check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM iam_v2.pms_postings p JOIN iam_v2.settlements se ON se.id = p.settlement_id
                WHERE p.stay_id = NEW.stay_id AND p.posting_type = 'CHARGE'
                  AND se.status IN ('REQUIRED','IN_PROGRESS','MANUAL_REVIEW')) THEN
      RAISE EXCEPTION 'ROOM_CHARGE_UNRESOLVED: stay % already has an unresolved room charge', NEW.stay_id
        USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: trg_purchase_quote_pin_equal(); Type: FUNCTION; Schema: iam_v2; Owner: -
--

CREATE FUNCTION iam_v2.trg_purchase_quote_pin_equal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q iam_v2.offer_quotes%ROWTYPE;
BEGIN
  IF NEW.offer_quote_id IS NULL THEN
    RETURN NEW;  -- non-quote triggers (voucher/account auto-grant etc.) are pinned by their own paths
  END IF;
  SELECT * INTO q FROM iam_v2.offer_quotes WHERE id = NEW.offer_quote_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase references unknown offer_quote %', NEW.offer_quote_id USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF NEW.tenant_id            IS DISTINCT FROM q.tenant_id
   OR NEW.site_id             IS DISTINCT FROM q.site_id
   OR NEW.package_revision_id IS DISTINCT FROM q.package_revision_id
   OR NEW.auth_context_id     IS DISTINCT FROM q.auth_context_id
   OR NEW.pms_interface_id    IS DISTINCT FROM q.pms_interface_id
   OR NEW.settlement_mapping_id IS DISTINCT FROM q.settlement_mapping_id
   OR NEW.amount_minor        IS DISTINCT FROM q.price_minor
   OR NEW.currency            IS DISTINCT FROM q.currency
   OR NEW.currency_exponent   IS DISTINCT FROM q.currency_exponent
   OR NEW.tax_code            IS DISTINCT FROM q.tax_code
   OR NEW.tax_rate_bp         IS DISTINCT FROM q.tax_rate_bp
   OR NEW.tax_amount_minor    IS DISTINCT FROM q.tax_amount_minor THEN
    RAISE EXCEPTION 'purchase money/pin values must match its offer_quote % exactly', NEW.offer_quote_id
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;


