--
-- Name: TABLE appliance_product_settings; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.appliance_product_settings IS 'Per-appliance product settings, read from the site database on the appliance itself. Local-first by construction: no Central Control Plane call is on the read path, so an appliance with no uplink answers exactly as one with an uplink.';


--
-- Name: COLUMN appliance_product_settings.guest_device_self_service; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.appliance_product_settings.guest_device_self_service IS 'OFF by default. When OFF the guest device-management capability is not exposed to the guest at all and ordinary authentication and device-limit behaviour is unchanged. This is the long-term PRODUCT control; the Phase-6 deployment gate is a separate and additionally required control.';


--
-- Name: assisted_guest_request_anchors; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.assisted_guest_request_anchors (
    request_id uuid NOT NULL,
    anchor_kind text NOT NULL,
    anchor_id uuid NOT NULL,
    CONSTRAINT agra_kind CHECK ((anchor_kind = ANY (ARRAY['account'::text, 'principal'::text, 'stay'::text, 'stay_guest'::text])))
);


--
-- Name: TABLE assisted_guest_request_anchors; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.assisted_guest_request_anchors IS 'The reservation, guest, account or identity the requester says the records belong to (0146): a claim, never proof.';


--
-- Name: assisted_guest_request_events; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.assisted_guest_request_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL,
    actor text NOT NULL,
    action text NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT agre_action CHECK ((action = ANY (ARRAY['OPENED'::text, 'EXPORTED'::text, 'ERASED'::text, 'COMPLETED'::text, 'CANCELLED'::text, 'EXPIRED'::text])))
);


--
-- Name: TABLE assisted_guest_request_events; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.assisted_guest_request_events IS 'What happened to an assisted request, in order (0146). Counts and reasons only. Append-only.';


--
-- Name: assisted_guest_request_records; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.assisted_guest_request_records (
    request_id uuid NOT NULL,
    rec_kind text NOT NULL,
    rec_id uuid NOT NULL,
    rec_class text NOT NULL,
    action text NOT NULL,
    done_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agrr_action CHECK ((action = ANY (ARRAY['DISCLOSED'::text, 'ANONYMISED'::text]))),
    CONSTRAINT agrr_class CHECK ((rec_class = ANY (ARRAY['ATTRIBUTABLE'::text, 'CLAIMABLE'::text])))
);


--
-- Name: TABLE assisted_guest_request_records; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.assisted_guest_request_records IS 'Which records a request disclosed or anonymised (0146): kind, id and class only; no personal data.';


--
-- Name: assisted_guest_requests; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.assisted_guest_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ref text NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    purpose text NOT NULL,
    macs macaddr[],
    range_from timestamp with time zone NOT NULL,
    range_to timestamp with time zone NOT NULL,
    pms_interface_id uuid,
    requester_ref text NOT NULL,
    verification_method text NOT NULL,
    evidence_note text NOT NULL,
    attest_identity boolean NOT NULL,
    attest_device boolean NOT NULL,
    attest_sole_use boolean NOT NULL,
    attest_private_address boolean NOT NULL,
    open_reason text NOT NULL,
    status text DEFAULT 'OPEN'::text NOT NULL,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_by text,
    closed_at timestamp with time zone,
    close_reason text,
    result jsonb,
    CONSTRAINT agr_closed CHECK ((((status = 'OPEN'::text) = (closed_at IS NULL)) AND ((closed_at IS NULL) = (closed_by IS NULL)) AND ((closed_at IS NULL) = (close_reason IS NULL)) AND ((closed_at IS NULL) = (result IS NULL)))),
    CONSTRAINT agr_creator CHECK (((length(btrim(created_by)) >= 1) AND (length(btrim(created_by)) <= 200))),
    CONSTRAINT agr_evidence CHECK (((length(btrim(evidence_note)) >= 9) AND (length(btrim(evidence_note)) <= 1000))),
    CONSTRAINT agr_identity CHECK (attest_identity),
    CONSTRAINT agr_macs CHECK ((((status = 'OPEN'::text) = (macs IS NOT NULL)) AND ((macs IS NULL) OR ((cardinality(macs) >= 1) AND (cardinality(macs) <= 5))))),
    CONSTRAINT agr_method CHECK ((verification_method = ANY (ARRAY['ID_CHECKED_IN_PERSON'::text, 'ACCOUNT_CONTROL_SHOWN'::text, 'CALLBACK_TO_KNOWN_CONTACT'::text, 'OTHER_DOCUMENTED'::text]))),
    CONSTRAINT agr_open_reason CHECK (((length(btrim(open_reason)) >= 4) AND (length(btrim(open_reason)) <= 500))),
    CONSTRAINT agr_purpose CHECK ((purpose = ANY (ARRAY['ACCESS'::text, 'ERASURE'::text]))),
    CONSTRAINT agr_range CHECK (((range_to > range_from) AND ((range_to - range_from) <= '366 days'::interval))),
    CONSTRAINT agr_ref CHECK ((ref ~ '^AR-[0-9A-F]{10}$'::text)),
    CONSTRAINT agr_requester CHECK (((length(btrim(requester_ref)) >= 2) AND (length(btrim(requester_ref)) <= 120))),
    CONSTRAINT agr_status CHECK ((status = ANY (ARRAY['OPEN'::text, 'COMPLETED'::text, 'CANCELLED'::text])))
);


--
-- Name: TABLE assisted_guest_requests; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.assisted_guest_requests IS 'A staff-supervised guest data request about records no automatic rule can attribute (0146). While OPEN it holds the addresses, the requester''s reference and the evidence note; closing it scrubs all three. Written only by the definer functions.';


--
-- Name: auth_context_offers; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.auth_context_offers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    auth_context_id uuid NOT NULL,
    package_revision_id uuid NOT NULL,
    matched_tier_order integer,
    evidence_version bigint NOT NULL,
    offered_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT aco_expiry_after_offer CHECK ((expires_at > offered_at)),
    CONSTRAINT auth_context_offers_evidence_version_check CHECK ((evidence_version > 0))
);


--
-- Name: auth_contexts; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.auth_contexts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    method text NOT NULL,
    stay_id uuid,
    guest_account_id uuid,
    voucher_id uuid,
    guest_principal_id uuid,
    post_stay_profile_id uuid,
    pms_interface_id uuid,
    authentication_interface_revision_id uuid,
    device_id uuid NOT NULL,
    guest_network_id uuid NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    pinned_lifecycle_version integer,
    pinned_occupancy_evidence_version bigint,
    resolution_request_id uuid,
    anonymous_subject_id uuid,
    client_group_id uuid,
    client_group_evidence jsonb,
    credential text,
    privacy_notice_version_id uuid,
    privacy_notice_shown_at timestamp with time zone,
    CONSTRAINT ac_credential_label CHECK (((credential IS NULL) OR (credential ~ '^[A-Z0-9_]{1,32}$'::text))),
    CONSTRAINT ac_method_subject CHECK ((((method = 'PMS'::text) AND (stay_id IS NOT NULL)) OR ((method = 'VOUCHER'::text) AND (voucher_id IS NOT NULL)) OR ((method = 'ACCOUNT'::text) AND (guest_account_id IS NOT NULL)) OR ((method = ANY (ARRAY['OTP'::text, 'SOCIAL'::text])) AND (guest_principal_id IS NOT NULL)) OR ((method = 'POST_STAY_PIN'::text) AND (post_stay_profile_id IS NOT NULL)) OR ((method = 'OPEN'::text) AND (anonymous_subject_id IS NOT NULL)))),
    CONSTRAINT ac_one_subject CHECK ((num_nonnulls(stay_id, guest_account_id, voucher_id, guest_principal_id, post_stay_profile_id, anonymous_subject_id) = 1)),
    CONSTRAINT ac_pms_pins CHECK (((method <> 'PMS'::text) OR ((pms_interface_id IS NOT NULL) AND (authentication_interface_revision_id IS NOT NULL)))),
    CONSTRAINT ac_post_stay_pins CHECK (((method <> 'POST_STAY_PIN'::text) OR ((post_stay_profile_id IS NOT NULL) AND (pinned_lifecycle_version IS NOT NULL)))),
    CONSTRAINT auth_contexts_method_check CHECK ((method = ANY (ARRAY['PMS'::text, 'VOUCHER'::text, 'ACCOUNT'::text, 'OTP'::text, 'SOCIAL'::text, 'POST_STAY_PIN'::text, 'OPEN'::text]))),
    CONSTRAINT auth_contexts_pinned_lifecycle_version_check CHECK (((pinned_lifecycle_version IS NULL) OR (pinned_lifecycle_version > 0))),
    CONSTRAINT auth_contexts_pinned_occupancy_evidence_version_check CHECK (((pinned_occupancy_evidence_version IS NULL) OR (pinned_occupancy_evidence_version >= 0)))
);


--
-- Name: COLUMN auth_contexts.client_group_id; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.auth_contexts.client_group_id IS 'The Client Group in force for this sign-in (lowest priority among the matches), decided by scd from the Client''s verified factors and pinned here. NULL = Public, or a group deleted since (the evidence keeps its name). Eligibility reads this pin and never re-derives it.';


--
-- Name: COLUMN auth_contexts.client_group_evidence; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.auth_contexts.client_group_evidence IS 'Why: {group, rule, factor_type, matched[], via} -- rule ids and factor kinds, never an address.';


--
-- Name: COLUMN auth_contexts.credential; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.auth_contexts.credential IS 'How the client proved themselves for THIS context, as a label the operator reads: EMAIL_OTP, SMS_OTP, WHATSAPP_OTP, SOCIAL_<provider>, VOUCHER, ACCOUNT, OPEN. Copied onto sessions.credential_method at activation. NULL = minted before 0109.';


--
-- Name: COLUMN auth_contexts.privacy_notice_version_id; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.auth_contexts.privacy_notice_version_id IS 'The privacy notice in force when this sign-in completed (0130, GDPR plan C6). Set by trigger, never by the writer, and never changed. NULL: before 0130, or the stamp could not be made (the sign-in was not refused).';


--
-- Name: COLUMN auth_contexts.privacy_notice_shown_at; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.auth_contexts.privacy_notice_shown_at IS 'When this sign-in was stamped with its privacy notice (0130, GDPR plan C6): the sign-in time, which the table did not otherwise record. Set by trigger with the stamp, never changed. NULL before 0130.';


--
-- Name: auth_resolutions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.auth_resolutions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    guest_network_id uuid NOT NULL,
    resolved_stay_id uuid,
    outcome_code text NOT NULL,
    resolved_at timestamp with time zone DEFAULT now() NOT NULL,
    resolution_request_id uuid
);


--
-- Name: backfill_0066_identity_text; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.backfill_0066_identity_text (
    kind text NOT NULL,
    row_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    prior_first_name text,
    prior_last_name text,
    prior_room text,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT backfill_0066_identity_text_kind_check CHECK ((kind = ANY (ARRAY['stay_guest'::text, 'stay_room'::text])))
);


--
-- Name: TABLE backfill_0066_identity_text; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.backfill_0066_identity_text IS 'Rollback evidence for migration 0066. Holds guest names and therefore NEVER leaves the appliance: not into Git, a PR body, CI output or a delivery artifact. RETENTION: only until this release''s rollback window is formally closed by the Product Owner, then dropped by the registered cleanup operation (governance/artifact-registry.json :: backfill-0066-pii-retention). Dropped by 0066.down.sql on rollback.';


--
-- Name: card_purchase_sweeps; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.card_purchase_sweeps (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    purchase_id uuid NOT NULL,
    settlement_id uuid NOT NULL,
    swept_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text NOT NULL,
    waited_seconds integer NOT NULL,
    CONSTRAINT card_purchase_sweeps_reason_check CHECK ((reason = 'NO_PAYMENT_TRANSACTION'::text)),
    CONSTRAINT card_purchase_sweeps_waited_seconds_check CHECK ((waited_seconds > 0))
);


--
-- Name: TABLE card_purchase_sweeps; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.card_purchase_sweeps IS 'Card purchases failed because no payment transaction was ever created for them (0121). Append-only.';


--
-- Name: card_reversal_reviews; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.card_reversal_reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    settlement_id uuid NOT NULL,
    charge_transaction_id uuid NOT NULL,
    kind text NOT NULL,
    provider_ref text NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    resolution text,
    resolved_at timestamp with time zone,
    resolved_by text,
    resolution_reason text,
    CONSTRAINT card_reversal_reviews_check CHECK (((resolution IS NULL) = (resolved_at IS NULL))),
    CONSTRAINT card_reversal_reviews_check1 CHECK (((resolution IS NULL) = (resolved_by IS NULL))),
    CONSTRAINT card_reversal_reviews_check2 CHECK (((resolution IS NULL) = (resolution_reason IS NULL))),
    CONSTRAINT card_reversal_reviews_kind_check CHECK ((kind = ANY (ARRAY['DISPUTE'::text, 'CHARGEBACK'::text]))),
    CONSTRAINT card_reversal_reviews_provider_ref_check CHECK (((length(provider_ref) >= 1) AND (length(provider_ref) <= 200))),
    CONSTRAINT card_reversal_reviews_resolution_check CHECK ((resolution = ANY (ARRAY['KEEP_ACCESS'::text, 'END_ACCESS'::text]))),
    CONSTRAINT card_reversal_reviews_resolution_reason_check CHECK (((resolution_reason IS NULL) OR ((length(resolution_reason) >= 1) AND (length(resolution_reason) <= 500)))),
    CONSTRAINT card_reversal_reviews_resolved_by_check CHECK (((resolved_by IS NULL) OR ((length(resolved_by) >= 1) AND (length(resolved_by) <= 200))))
);


--
-- Name: TABLE card_reversal_reviews; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.card_reversal_reviews IS 'Disputes and chargebacks on card charges, each a case an operator resolves explicitly (0115). Never deleted; a resolution is written once.';


--
-- Name: checkout_grace_policy_publications; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.checkout_grace_policy_publications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    config_version integer NOT NULL,
    actor uuid NOT NULL,
    reason_code text,
    grace_package_revision_id uuid,
    policy_snapshot jsonb NOT NULL,
    published_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT checkout_grace_policy_publications_config_version_check CHECK ((config_version >= 1)),
    CONSTRAINT checkout_grace_policy_publications_reason_code_check CHECK (((reason_code IS NULL) OR (reason_code ~ '^[A-Z][A-Z0-9_]{0,63}$'::text)))
);


--
-- Name: client_group_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.client_group_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    group_id uuid NOT NULL,
    action text NOT NULL,
    changed_by text NOT NULL,
    change_reason text DEFAULT ''::text NOT NULL,
    before jsonb,
    after jsonb,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT client_group_changes_action CHECK ((action = ANY (ARRAY['CREATED'::text, 'UPDATED'::text, 'DELETED'::text]))),
    CONSTRAINT client_group_changes_actor CHECK ((length(btrim(changed_by)) > 0))
);


--
-- Name: client_group_rules; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.client_group_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    group_id uuid NOT NULL,
    rule_type text NOT NULL,
    rule_value jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT client_group_rules_type CHECK ((rule_type = ANY (ARRAY['EMAIL_DOMAIN'::text, 'IDP_TENANT'::text, 'IDP_HOSTED_DOMAIN'::text])))
);


--
-- Name: TABLE client_group_rules; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.client_group_rules IS 'OR-ed membership rules of a Client Group. EMAIL_DOMAIN {domains, include_subdomains} needs a verified mailbox; IDP_TENANT {provider, tenant_ids} and IDP_HOSTED_DOMAIN {provider, domains} need the claim from a verified id_token. IDP_GROUP is reserved and refused until a provider emits group claims.';


--
-- Name: client_groups; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.client_groups (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    name text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT client_groups_description CHECK ((length(description) <= 500)),
    CONSTRAINT client_groups_name CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 80))),
    CONSTRAINT client_groups_priority CHECK (((priority >= 1) AND (priority <= 1000)))
);


--
-- Name: TABLE client_groups; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.client_groups IS 'A site''s business groups (Employees, Partners, VIP ...). Membership is decided by the group''s rules against a Client''s VERIFIED identity factors; the lowest priority among the matches is the effective group. The Public group is implicit: a Client who matches no enabled group.';


--
-- Name: compliance_archives; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.compliance_archives (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    manifest_sha256 text NOT NULL,
    receipt_verified boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    purpose text DEFAULT 'CROSS_CUSTOMER_PURGE'::text NOT NULL,
    artifact_path text,
    row_counts jsonb DEFAULT '{}'::jsonb NOT NULL,
    receipt_blocked_reason text,
    receipt_authority text,
    receipt_reference text,
    receipt_verified_at timestamp with time zone,
    CONSTRAINT ca_receipt_evidence_matches_flag CHECK (((receipt_verified = false) OR ((receipt_verified = true) AND (receipt_authority IS NOT NULL) AND (btrim(receipt_authority) <> ''::text) AND (receipt_reference IS NOT NULL) AND (btrim(receipt_reference) <> ''::text) AND (receipt_verified_at IS NOT NULL)))),
    CONSTRAINT compliance_archives_purpose_check CHECK ((purpose = ANY (ARRAY['CROSS_CUSTOMER_PURGE'::text, 'RETENTION_EXPIRY'::text, 'OPERATOR_EXPORT'::text])))
);


--
-- Name: COLUMN compliance_archives.receipt_verified; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.compliance_archives.receipt_verified IS 'TRUE only when an EXTERNAL archival authority has acknowledged custody of the artefact, with the authority and its reference recorded alongside. No such authority exists in this product, so this is false everywhere and cross-customer purge is consequently impossible. That is the intended failure mode: the alternative is letting the appliance that is about to delete the data certify its own copy.';


--
-- Name: controlled_operation_scope; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE UNLOGGED TABLE iam_v2.controlled_operation_scope (
    txid bigint NOT NULL,
    family text NOT NULL,
    token uuid NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE controlled_operation_scope; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.controlled_operation_scope IS 'Transaction-scoped capability tokens for controlled-writer families whose operation is service logic. Written only by iam_v2.begin_controlled_operation().';


--
-- Name: data_crossing_progress; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.data_crossing_progress (
    binding_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    session_id uuid NOT NULL,
    examined_seq bigint DEFAULT 0 NOT NULL,
    counted_bytes bigint DEFAULT 0 NOT NULL,
    final boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dcp_bytes CHECK ((counted_bytes >= 0)),
    CONSTRAINT dcp_seq CHECK ((examined_seq >= 0))
);


--
-- Name: TABLE data_crossing_progress; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.data_crossing_progress IS 'Per session-entitlement binding: the highest accounting sample_seq of the session already examined and the bytes of those samples that fell inside the binding (0122). A derived checkpoint, never evidence: the records stay the authority, and the counted bytes can only overstate (an attribution interval that later shrank), which is answered by the exact derivation. final = the session ended long enough ago that no record can still arrive.';


--
-- Name: data_crossing_state; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.data_crossing_state (
    entitlement_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    quota_bytes bigint NOT NULL,
    crossed_at timestamp with time zone,
    verified_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE data_crossing_state; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.data_crossing_state IS 'The exact data-quota crossing instant of an entitlement, established by the full derivation once the running total reached quota_bytes (0122). Trusted only while the entitlement''s quota is still quota_bytes.';


--
-- Name: data_retention_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.data_retention_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    changed_by text NOT NULL,
    change_reason text NOT NULL,
    old_settings jsonb,
    new_settings jsonb NOT NULL,
    new_config_version bigint NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT drc_actor CHECK ((length(btrim(changed_by)) > 0)),
    CONSTRAINT drc_reason CHECK (((length(btrim(change_reason)) >= 4) AND (length(btrim(change_reason)) <= 500)))
);


--
-- Name: data_retention_checkpoints; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.data_retention_checkpoints (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    category text NOT NULL,
    done_until timestamp with time zone NOT NULL,
    CONSTRAINT drk_category CHECK ((category = 'audit_log'::text))
);


--
-- Name: data_retention_runs; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.data_retention_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    category text NOT NULL,
    retention_days integer NOT NULL,
    cutoff timestamp with time zone NOT NULL,
    rows_anonymised integer NOT NULL,
    ran_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT drr_category CHECK ((category = ANY (ARRAY['pms_stays'::text, 'client_activity'::text, 'inactive_identities'::text, 'expired_records'::text, 'audit_log'::text, 'staff_notes'::text]))),
    CONSTRAINT drr_rows CHECK ((rows_anonymised > 0))
);


--
-- Name: TABLE data_retention_runs; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.data_retention_runs IS 'Every retention run that anonymised something (0127): the category, the retention in force, the cutoff and how many records changed. Append-only. A run that changed nothing writes nothing.';


--
-- Name: delayed_accounting_records; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.delayed_accounting_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    accounting_record_id uuid NOT NULL,
    session_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    watermark_id uuid NOT NULL,
    sampled_at timestamp with time zone NOT NULL,
    bytes_up bigint NOT NULL,
    bytes_down bigint NOT NULL,
    detected_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: device_limit_disconnections; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.device_limit_disconnections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    disconnected_device_id uuid NOT NULL,
    admitted_device_id uuid NOT NULL,
    device_limit integer NOT NULL,
    sessions_ended integer NOT NULL,
    disconnected_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dld_limit CHECK ((device_limit >= 1)),
    CONSTRAINT dld_sessions CHECK ((sessions_ended >= 0))
);


--
-- Name: TABLE device_limit_disconnections; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.device_limit_disconnections IS 'Every device the DISCONNECT_OLDEST device-limit policy disconnected to admit a new one (0122): which device left, which device was admitted, the limit, how many sessions ended. Append-only.';


--
-- Name: device_network_appearances; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.device_network_appearances (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    device_id uuid NOT NULL,
    guest_network_id uuid NOT NULL,
    first_seen timestamp with time zone,
    last_seen timestamp with time zone
);


--
-- Name: device_settings_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.device_settings_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    changed_by text NOT NULL,
    change_reason text NOT NULL,
    old_client_device_changes_per_day integer,
    new_client_device_changes_per_day integer NOT NULL,
    new_config_version bigint NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT device_settings_changes_actor CHECK ((length(btrim(changed_by)) > 0)),
    CONSTRAINT device_settings_changes_reason CHECK ((length(btrim(change_reason)) > 0))
);


--
-- Name: device_slot_actions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.device_slot_actions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    entitlement_id uuid,
    device_id uuid,
    replacement_device_id uuid,
    actor text NOT NULL,
    operator_id uuid,
    operator_label text,
    action text NOT NULL,
    outcome text NOT NULL,
    reason text,
    detail text,
    acted_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dsa_action CHECK ((action = ANY (ARRAY['REPLACE'::text, 'RELEASE'::text, 'REQUIRE_SIGNIN'::text]))),
    CONSTRAINT dsa_actor CHECK ((actor = ANY (ARRAY['CLIENT'::text, 'STAFF'::text]))),
    CONSTRAINT dsa_detail_len CHECK (((detail IS NULL) OR (length(detail) <= 200))),
    CONSTRAINT dsa_outcome CHECK ((outcome = ANY (ARRAY['OK'::text, 'REFUSED_SIGNIN_EXPIRED'::text, 'REFUSED_NO_PACKAGE'::text, 'REFUSED_NOT_FOUND'::text, 'REFUSED_ALREADY_RELEASED'::text, 'REFUSED_ONLINE'::text, 'REFUSED_THROTTLED'::text, 'REFUSED_SAME_DEVICE'::text, 'REFUSED_LIMIT_NOT_REACHED'::text]))),
    CONSTRAINT dsa_reason_len CHECK (((reason IS NULL) OR (length(reason) <= 500))),
    CONSTRAINT dsa_staff_named CHECK (((actor = 'STAFF'::text) = (operator_label IS NOT NULL))),
    CONSTRAINT dsa_staff_reason CHECK (((actor <> 'STAFF'::text) OR (reason IS NOT NULL)))
);


--
-- Name: TABLE device_slot_actions; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.device_slot_actions IS 'Every client or staff attempt to replace or release a device slot, or to forget a device''s remembered sign-in (0118), with its outcome. Append-only; refusals are recorded too.';


--
-- Name: devices; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.devices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    appliance_id uuid NOT NULL,
    mac macaddr NOT NULL,
    first_seen timestamp with time zone,
    last_seen timestamp with time zone,
    last_ip inet
);


--
-- Name: TABLE devices; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.devices IS 'Durable device identity. svc_scd may INSERT (a device appears the first time the appliance sees it) and may UPDATE only mac, last_seen and last_ip. It may not DELETE, and it may not move a device between tenant, site or appliance: those columns are outside its column-level grant.';


--
-- Name: entitlement_adjustments; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.entitlement_adjustments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    field text NOT NULL,
    old_value text,
    new_value text,
    actor uuid,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: entitlement_boundary_watermarks; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.entitlement_boundary_watermarks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    boundary_at timestamp with time zone NOT NULL,
    bytes_up bigint NOT NULL,
    bytes_down bigint NOT NULL,
    records_counted bigint NOT NULL,
    latest_sampled_at timestamp with time zone,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT entitlement_boundary_watermarks_bytes_down_check CHECK ((bytes_down >= 0)),
    CONSTRAINT entitlement_boundary_watermarks_bytes_up_check CHECK ((bytes_up >= 0)),
    CONSTRAINT entitlement_boundary_watermarks_records_counted_check CHECK ((records_counted >= 0))
);


--
-- Name: entitlement_device_authorizations; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.entitlement_device_authorizations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    device_id uuid NOT NULL,
    seq bigint NOT NULL,
    authorized_at timestamp with time zone NOT NULL,
    deauthorized_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT entitlement_device_authorizations_check CHECK (((deauthorized_at IS NULL) OR (deauthorized_at >= authorized_at))),
    CONSTRAINT entitlement_device_authorizations_seq_check CHECK ((seq >= 1))
);


--
-- Name: entitlement_devices; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.entitlement_devices (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    device_id uuid NOT NULL,
    status text DEFAULT 'AUTHORIZED'::text NOT NULL,
    grandfathered boolean DEFAULT false NOT NULL,
    disconnected_reason text,
    first_authorized timestamp with time zone,
    last_authorized timestamp with time zone,
    CONSTRAINT entitlement_devices_status_check CHECK ((status = ANY (ARRAY['AUTHORIZED'::text, 'DISCONNECTED'::text])))
);


--
-- Name: COLUMN entitlement_devices.disconnected_reason; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.entitlement_devices.disconnected_reason IS 'Why the device left this entitlement. Phase 6 adds GUEST_SELF_SERVICE, which is deliberately distinct from ENTITLEMENT_ENDED, CROSS_PMS_TRANSFER and operator-driven reasons: a slot the guest released is a different fact from one the system took back.';


--
-- Name: entitlement_state_transitions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.entitlement_state_transitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    seq bigint NOT NULL,
    from_state text,
    to_state text NOT NULL,
    effective_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    supersedes uuid,
    superseded_by uuid,
    reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT entitlement_state_transitions_from_state_check CHECK (((from_state IS NULL) OR (from_state = ANY (ARRAY['PENDING'::text, 'ACTIVE'::text, 'SUSPENDED'::text, 'TERMINATED'::text])))),
    CONSTRAINT entitlement_state_transitions_reason_check CHECK (((reason IS NULL) OR (reason ~ '^[A-Z][A-Z0-9_]{0,63}$'::text))),
    CONSTRAINT entitlement_state_transitions_seq_check CHECK ((seq >= 1)),
    CONSTRAINT entitlement_state_transitions_to_state_check CHECK ((to_state = ANY (ARRAY['PENDING'::text, 'ACTIVE'::text, 'SUSPENDED'::text, 'TERMINATED'::text]))),
    CONSTRAINT est_no_self_supersede CHECK (((supersedes IS NULL) OR (supersedes <> id))),
    CONSTRAINT est_not_self_superseded CHECK (((superseded_by IS NULL) OR (superseded_by <> id)))
);


--
-- Name: entitlement_termination_evidence; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.entitlement_termination_evidence (
    entitlement_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    terminal_reason text NOT NULL,
    cause_detail text NOT NULL,
    time_mode text NOT NULL,
    budget_seconds bigint,
    consumed_online_seconds bigint,
    window_ends_at timestamp with time zone,
    terminated_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT entitlement_termination_evidence_budget_seconds_check CHECK (((budget_seconds IS NULL) OR (budget_seconds >= 0))),
    CONSTRAINT entitlement_termination_evidence_cause_detail_check CHECK ((cause_detail = ANY (ARRAY['VALIDITY_WINDOW_ELAPSED'::text, 'AGGREGATE_ONLINE_TIME_EXHAUSTED'::text, 'AGGREGATE_OUTER_WINDOW_EXPIRED'::text, 'ONLINE_TIME_ALLOWANCE_EXHAUSTED'::text]))),
    CONSTRAINT entitlement_termination_evidence_consumed_online_seconds_check CHECK (((consumed_online_seconds IS NULL) OR (consumed_online_seconds >= 0))),
    CONSTRAINT entitlement_termination_evidence_terminal_reason_check CHECK ((terminal_reason = 'TIME'::text)),
    CONSTRAINT entitlement_termination_evidence_time_mode_check CHECK ((time_mode = ANY (ARRAY['VALIDITY_WINDOW'::text, 'AGGREGATE_ONLINE_TIME'::text]))),
    CONSTRAINT ete_aggregate_carries_its_budget CHECK (((cause_detail <> ALL (ARRAY['AGGREGATE_ONLINE_TIME_EXHAUSTED'::text, 'AGGREGATE_OUTER_WINDOW_EXPIRED'::text])) OR ((budget_seconds IS NOT NULL) AND (consumed_online_seconds IS NOT NULL)))),
    CONSTRAINT ete_allowance_carries_its_budget CHECK (((cause_detail <> 'ONLINE_TIME_ALLOWANCE_EXHAUSTED'::text) OR ((time_mode = 'VALIDITY_WINDOW'::text) AND (budget_seconds IS NOT NULL) AND (consumed_online_seconds IS NOT NULL) AND (consumed_online_seconds >= budget_seconds)))),
    CONSTRAINT ete_detail_matches_mode CHECK (((cause_detail = ANY (ARRAY['AGGREGATE_ONLINE_TIME_EXHAUSTED'::text, 'AGGREGATE_OUTER_WINDOW_EXPIRED'::text])) = (time_mode = 'AGGREGATE_ONLINE_TIME'::text))),
    CONSTRAINT ete_exhaustion_reached_its_budget CHECK (((cause_detail <> 'AGGREGATE_ONLINE_TIME_EXHAUSTED'::text) OR (consumed_online_seconds >= budget_seconds))),
    CONSTRAINT ete_outer_window_is_distinguishable CHECK (((cause_detail <> 'AGGREGATE_OUTER_WINDOW_EXPIRED'::text) OR ((window_ends_at IS NOT NULL) AND (consumed_online_seconds < budget_seconds))))
);


--
-- Name: TABLE entitlement_termination_evidence; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.entitlement_termination_evidence IS 'Why a time-mode entitlement ended, with the numbers. The contract terminal_reason set is unchanged and is never widened here: an aggregate-budget exhaustion terminates with reason TIME, and THIS row says it was the online-minute budget rather than the wall-clock window, which budget it was, and what had been consumed when it crossed.';


--
-- Name: entitlement_transfers; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.entitlement_transfers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    from_entitlement_id uuid NOT NULL,
    to_entitlement_id uuid NOT NULL,
    from_stay_id uuid NOT NULL,
    to_stay_id uuid NOT NULL,
    reason text DEFAULT 'CROSS_PMS_TRANSFER'::text NOT NULL,
    actor uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT et_no_self CHECK ((from_entitlement_id <> to_entitlement_id)),
    CONSTRAINT et_two_stays CHECK ((from_stay_id <> to_stay_id))
);


--
-- Name: entitlements; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.entitlements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    stay_id uuid,
    guest_account_id uuid,
    voucher_id uuid,
    guest_principal_id uuid,
    pms_interface_id uuid,
    purchase_id uuid NOT NULL,
    policy_snapshot jsonb NOT NULL,
    snapshot_version integer DEFAULT 1 NOT NULL,
    service_plan_revision_id uuid NOT NULL,
    package_revision_id uuid NOT NULL,
    time_accounting_mode text NOT NULL,
    end_mode text NOT NULL,
    window_ends_at timestamp with time zone,
    status text DEFAULT 'PENDING'::text NOT NULL,
    terminal_reason text,
    consumed_data_bytes bigint DEFAULT 0 NOT NULL,
    consumed_online_seconds bigint DEFAULT 0 NOT NULL,
    usage_version bigint DEFAULT 0 NOT NULL,
    renewal_number integer DEFAULT 1 NOT NULL,
    supersedes_entitlement_id uuid,
    is_emergency_grace boolean DEFAULT false NOT NULL,
    activated_at timestamp with time zone,
    terminated_at timestamp with time zone,
    online_time_exhausted_at timestamp with time zone,
    data_quota_bytes bigint,
    anonymous_subject_id uuid,
    CONSTRAINT ent_one_subject CHECK ((num_nonnulls(stay_id, guest_account_id, voucher_id, guest_principal_id, anonymous_subject_id) = 1)),
    CONSTRAINT ent_terminal CHECK (((status = 'TERMINATED'::text) = (terminal_reason IS NOT NULL))),
    CONSTRAINT entitlements_consumed_data_bytes_check CHECK ((consumed_data_bytes >= 0)),
    CONSTRAINT entitlements_consumed_online_seconds_check CHECK ((consumed_online_seconds >= 0)),
    CONSTRAINT entitlements_data_quota_bytes_positive CHECK (((data_quota_bytes IS NULL) OR (data_quota_bytes > 0))),
    CONSTRAINT entitlements_end_mode_check CHECK ((end_mode = ANY (ARRAY['FIXED_AT'::text, 'VALIDITY_WINDOW'::text, 'AT_CHECKOUT'::text, 'EARLIEST_OF_FIXED_AND_CHECKOUT'::text, 'GRACE_AFTER_CHECKOUT'::text, 'MANUAL_END'::text]))),
    CONSTRAINT entitlements_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'ACTIVE'::text, 'SUSPENDED'::text, 'TERMINATED'::text]))),
    CONSTRAINT entitlements_terminal_reason_check CHECK ((terminal_reason = ANY (ARRAY['TIME'::text, 'DATA'::text, 'HARD_EXPIRY'::text, 'CHECKOUT'::text, 'ADMIN'::text, 'REVOKED'::text, 'SUPERSEDED'::text, 'CONVERTED'::text, 'TRANSFERRED'::text, 'CANCELLED'::text, 'OTHER'::text])))
);


--
-- Name: COLUMN entitlements.online_time_exhausted_at; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.entitlements.online_time_exhausted_at IS 'For AGGREGATE_ONLINE_TIME: the instant the online-time budget was exhausted, computed inside the tick that crossed it. Stable across retries -- a re-reported exhaustion carries the original instant, never the clock of the tick that re-reported it.';


--
-- Name: COLUMN entitlements.data_quota_bytes; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.entitlements.data_quota_bytes IS 'The byte allowance THIS entitlement was granted, frozen at grant time. NULL means the allowance is the pinned service plan revision''s data_quota_bytes -- which is what every entitlement granted before PER_STAY_NIGHT existed means, and why nothing was backfilled. A PMS update that lengthens or shortens the stay does not change a value that is already here.';


--
-- Name: erasure_journal; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.erasure_journal (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    erasure_ref text NOT NULL,
    kind text NOT NULL,
    subject_id uuid NOT NULL,
    detail text,
    erased_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ej_assisted_detail CHECK (((kind = 'assisted_record'::text) = (detail IS NOT NULL))),
    CONSTRAINT ej_detail CHECK (((detail IS NULL) OR (detail ~ '^[a-z_]{3,40}$'::text))),
    CONSTRAINT ej_kind CHECK ((kind = ANY (ARRAY['account'::text, 'principal'::text, 'stay'::text, 'stay_guest'::text, 'assisted_record'::text]))),
    CONSTRAINT ej_ref CHECK ((erasure_ref ~ '^ER-[0-9A-F]{12}$'::text))
);


--
-- Name: TABLE erasure_journal; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.erasure_journal IS 'Which records an erasure anonymised (0147): kind and record id only. Replayed after a restore so an older backup does not bring an erased guest back. Holds no personal data. Append-only.';


--
-- Name: financial_epoch; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.financial_epoch (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    epoch integer DEFAULT 1 NOT NULL,
    restore_generation integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: financial_epochs; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.financial_epochs (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    epoch bigint NOT NULL,
    system_identity text NOT NULL,
    entered_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text NOT NULL,
    released_at timestamp with time zone,
    released_by uuid,
    release_note text,
    restore_generation bigint DEFAULT 0 NOT NULL,
    CONSTRAINT financial_epochs_reason_check CHECK ((reason = ANY (ARRAY['INITIAL'::text, 'RESTORE_DETECTED'::text, 'OPERATOR_DECLARED'::text]))),
    CONSTRAINT financial_epochs_release_note_check CHECK (((release_note IS NULL) OR (length(release_note) <= 2000)))
);


--
-- Name: TABLE financial_epochs; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.financial_epochs IS 'One row per run of a site''s financial history. An open row whose reason is RESTORE_DETECTED or OPERATOR_DECLARED means the site is in FINANCIAL_RECOVERY_MODE: money movement is held pending operator reconciliation. Guest access is unaffected.';


--
-- Name: COLUMN financial_epochs.restore_generation; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.financial_epochs.restore_generation IS 'The restore generation this row was written under. It travels WITH the database through a pg_restore, which is what makes comparing it against the management-partition marker a rollback detector.';


--
-- Name: financial_recovery_holds; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.financial_recovery_holds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    epoch bigint NOT NULL,
    work_kind text NOT NULL,
    work_id uuid NOT NULL,
    held_status text NOT NULL,
    amount_minor bigint,
    currency character(3),
    held_at timestamp with time zone DEFAULT now() NOT NULL,
    resolution text,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    resolution_note text,
    CONSTRAINT financial_recovery_holds_held_status_check CHECK ((length(held_status) <= 64)),
    CONSTRAINT financial_recovery_holds_resolution_check CHECK ((resolution = ANY (ARRAY['CONFIRMED_COMPLETED'::text, 'CONFIRMED_NOT_COMPLETED'::text, 'ABANDONED'::text, 'ESCALATED'::text]))),
    CONSTRAINT financial_recovery_holds_resolution_note_check CHECK (((resolution_note IS NULL) OR (length(resolution_note) <= 2000))),
    CONSTRAINT financial_recovery_holds_work_kind_check CHECK ((work_kind = ANY (ARRAY['POSTING_OUTBOX'::text, 'PAYMENT_TRANSACTION'::text, 'SETTLEMENT'::text])))
);


--
-- Name: financial_restore_events; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.financial_restore_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    restore_generation bigint NOT NULL,
    manifest_sha256 text NOT NULL,
    backup_taken_at timestamp with time zone,
    restored_at timestamp with time zone DEFAULT now() NOT NULL,
    restored_by text,
    restore_kind text NOT NULL,
    detected_by text NOT NULL,
    CONSTRAINT financial_restore_events_detected_by_check CHECK ((detected_by = ANY (ARRAY['MANAGEMENT_MARKER'::text, 'SYSTEM_IDENTITY'::text, 'RESTORE_TOOL'::text]))),
    CONSTRAINT financial_restore_events_manifest_sha256_check CHECK ((manifest_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT financial_restore_events_restore_kind_check CHECK ((restore_kind = ANY (ARRAY['SUPPORTED'::text, 'UNSUPPORTED_RAW_SNAPSHOT'::text])))
);


--
-- Name: guest_access_accounts; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.guest_access_accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    username text NOT NULL,
    password_hash text NOT NULL,
    display_name text,
    notes text,
    enabled boolean DEFAULT true NOT NULL,
    valid_from timestamp with time zone,
    valid_until timestamp with time zone,
    assigned_package_id uuid,
    stay_id uuid,
    failed_attempts integer DEFAULT 0 NOT NULL,
    locked_until timestamp with time zone,
    last_login_at timestamp with time zone,
    login_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    self_registered boolean DEFAULT false NOT NULL,
    email_verified_at timestamp with time zone,
    verification_deadline timestamp with time zone,
    verification_reminder_sent_at timestamp with time zone,
    grace_until timestamp with time zone,
    grace_extensions_used integer DEFAULT 0 NOT NULL,
    created_by_device_mac macaddr,
    CONSTRAINT gaa_grace_extensions_used_bounds CHECK (((grace_extensions_used >= 0) AND (grace_extensions_used <= 3))),
    CONSTRAINT gaa_self_registered_username_is_email CHECK (((NOT self_registered) OR ((username = lower(btrim(username))) AND (POSITION(('@'::text) IN (username)) > 1))))
);


--
-- Name: COLUMN guest_access_accounts.created_at; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.guest_access_accounts.created_at IS 'When the account was created. NULL for accounts created before migration 0104, which recorded no creation time; never back-filled with an invented one.';


--
-- Name: COLUMN guest_access_accounts.self_registered; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.guest_access_accounts.self_registered IS 'true: the client created this account on the portal (Email accounts, 0117); its username is the address. false: a Personal account staff created (Client accounts).';


--
-- Name: COLUMN guest_access_accounts.email_verified_at; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.guest_access_accounts.email_verified_at IS 'When the client proved control of the address (a VERIFY or RESET link). NULL = not verified.';


--
-- Name: COLUMN guest_access_accounts.verification_deadline; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.guest_access_accounts.verification_deadline IS 'Until when an unverified self-registered account works normally. NULL = no deadline (verification not required when the account was created).';


--
-- Name: COLUMN guest_access_accounts.grace_until; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.guest_access_accounts.grace_until IS 'End of the one-time grace hour a suspended client asked for with their password. Lifts only the verification gate; no entitlement is created, extended or restored.';


--
-- Name: COLUMN guest_access_accounts.created_by_device_mac; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.guest_access_accounts.created_by_device_mac IS 'The device that registered this self-service account; counted by the per-device daily registration cap.';


--
-- Name: guest_data_erasures; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.guest_data_erasures (
    erasure_ref text NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    subject_kind text NOT NULL,
    erased_by text NOT NULL,
    erase_reason text NOT NULL,
    counts jsonb NOT NULL,
    erased_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT gde_actor CHECK (((length(btrim(erased_by)) >= 1) AND (length(btrim(erased_by)) <= 200))),
    CONSTRAINT gde_kind CHECK ((subject_kind = ANY (ARRAY['account'::text, 'principal'::text, 'stay'::text, 'stay_guest'::text, 'assisted'::text]))),
    CONSTRAINT gde_reason CHECK (((length(btrim(erase_reason)) >= 4) AND (length(btrim(erase_reason)) <= 500))),
    CONSTRAINT gde_ref CHECK ((erasure_ref ~ '^ER-[0-9A-F]{12}$'::text))
);


--
-- Name: TABLE guest_data_erasures; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.guest_data_erasures IS 'Every "erase this guest" that ran (0128, GDPR plan C3): a reference to give the guest, who did it and why, and how many records were anonymised. Holds no personal data and no link back to the erased records. Append-only.';


--
-- Name: guest_data_request_register; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.guest_data_request_register (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ref text NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    kind text NOT NULL,
    received_at date NOT NULL,
    due_at date NOT NULL,
    extended_until date,
    extension_reason text,
    requester_ref text NOT NULL,
    verification_method text,
    status text DEFAULT 'OPEN'::text NOT NULL,
    outcome_code text,
    outcome_note text,
    erasure_ref text,
    assisted_ref text,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    answered_by text,
    answered_at timestamp with time zone,
    CONSTRAINT gdrr_ar CHECK (((assisted_ref IS NULL) OR (assisted_ref ~ '^AR-[0-9A-F]{10}$'::text))),
    CONSTRAINT gdrr_closed CHECK ((((status = 'OPEN'::text) = (answered_at IS NULL)) AND ((answered_at IS NULL) = (answered_by IS NULL)) AND ((status = 'OPEN'::text) OR (outcome_code IS NOT NULL)))),
    CONSTRAINT gdrr_due CHECK (((due_at >= received_at) AND ((extended_until IS NULL) OR (extended_until >= due_at)))),
    CONSTRAINT gdrr_er CHECK (((erasure_ref IS NULL) OR (erasure_ref ~ '^ER-[0-9A-F]{12}$'::text))),
    CONSTRAINT gdrr_kind CHECK ((kind = ANY (ARRAY['ACCESS'::text, 'ERASURE'::text, 'OTHER'::text]))),
    CONSTRAINT gdrr_method CHECK (((verification_method IS NULL) OR (verification_method = ANY (ARRAY['ID_CHECKED_IN_PERSON'::text, 'ACCOUNT_CONTROL_SHOWN'::text, 'CALLBACK_TO_KNOWN_CONTACT'::text, 'OTHER_DOCUMENTED'::text])))),
    CONSTRAINT gdrr_note CHECK (((outcome_note IS NULL) OR (length(outcome_note) <= 500))),
    CONSTRAINT gdrr_outcome CHECK (((outcome_code IS NULL) OR (outcome_code = ANY (ARRAY['NONE'::text, 'LEGAL_RETENTION'::text, 'NOT_IDENTIFIED'::text, 'SHARED_ACCESS'::text, 'THIRD_PARTY_RIGHTS'::text, 'MANIFESTLY_UNFOUNDED'::text, 'OTHER'::text])))),
    CONSTRAINT gdrr_ref CHECK ((ref ~ '^RQ-[0-9A-F]{8}$'::text)),
    CONSTRAINT gdrr_requester CHECK (((length(btrim(requester_ref)) >= 2) AND (length(btrim(requester_ref)) <= 120))),
    CONSTRAINT gdrr_status CHECK ((status = ANY (ARRAY['OPEN'::text, 'ANSWERED'::text, 'PARTLY_REFUSED'::text, 'REFUSED'::text, 'WITHDRAWN'::text])))
);


--
-- Name: TABLE guest_data_request_register; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.guest_data_request_register IS 'A request made under the data-protection rules, its deadline and how it was answered (0147). The requester reference and the note are removed when it is answered; nothing here decides anything.';


--
-- Name: guest_device_actions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.guest_device_actions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    device_id uuid,
    action text NOT NULL,
    outcome text NOT NULL,
    detail text,
    acted_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT guest_device_actions_action_check CHECK ((action = 'RELEASE'::text)),
    CONSTRAINT guest_device_actions_outcome_check CHECK ((outcome = ANY (ARRAY['OK'::text, 'REFUSED_ONLINE'::text, 'REFUSED_NOT_FOUND'::text, 'REFUSED_ALREADY_RELEASED'::text, 'REFUSED_DISABLED'::text, 'REFUSED_THROTTLED'::text])))
);


--
-- Name: TABLE guest_device_actions; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.guest_device_actions IS 'Every guest-initiated action that CHANGES durable device state, refusals included. RELEASE is the only such action: listing reads and changes nothing. An earlier version of this schema also named LIST, which was a standing claim that a guest''s list requests were investigable when no path recorded one -- and after the Phase-6 privilege audit no path can, because the guest surface holds no write on this table.';


--
-- Name: guest_network_replacements; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.guest_network_replacements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    original_network_id uuid NOT NULL,
    successor_network_id uuid,
    state text DEFAULT 'PENDING'::text NOT NULL,
    network_type text NOT NULL,
    parent_interface text NOT NULL,
    vlan_id integer,
    subnet_cidr cidr,
    gateway_ip inet,
    pools jsonb DEFAULT '[]'::jsonb NOT NULL,
    new_name text,
    reason text NOT NULL,
    created_by text NOT NULL,
    revision_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    applied_at timestamp with time zone,
    settled_at timestamp with time zone,
    CONSTRAINT gnr_actor CHECK ((length(btrim(created_by)) > 0)),
    CONSTRAINT gnr_addressing CHECK ((((subnet_cidr IS NULL) AND (gateway_ip IS NULL)) OR ((subnet_cidr IS NOT NULL) AND (gateway_ip IS NOT NULL)))),
    CONSTRAINT gnr_network_type CHECK ((network_type = ANY (ARRAY['untagged'::text, 'vlan'::text]))),
    CONSTRAINT gnr_parent CHECK ((length(btrim(parent_interface)) > 0)),
    CONSTRAINT gnr_reason CHECK ((length(btrim(reason)) >= 4)),
    CONSTRAINT gnr_state CHECK ((state = ANY (ARRAY['PENDING'::text, 'APPLIED'::text, 'CONFIRMED'::text, 'CANCELLED'::text, 'REVERTED'::text]))),
    CONSTRAINT gnr_vlan_consistency CHECK ((((network_type = 'vlan'::text) AND (vlan_id IS NOT NULL)) OR ((network_type = 'untagged'::text) AND (vlan_id IS NULL)))),
    CONSTRAINT gnr_vlan_range CHECK (((vlan_id IS NULL) OR ((vlan_id >= 1) AND (vlan_id <= 4094))))
);


--
-- Name: guest_network_lineage; Type: VIEW; Schema: iam_v2; Owner: -
--

CREATE VIEW iam_v2.guest_network_lineage AS
 WITH RECURSIVE chain AS (
         SELECT r.tenant_id,
            r.site_id,
            r.successor_network_id AS network_id,
            r.original_network_id AS ancestor_id,
            1 AS depth
           FROM iam_v2.guest_network_replacements r
          WHERE ((r.successor_network_id IS NOT NULL) AND (r.state = ANY (ARRAY['APPLIED'::text, 'CONFIRMED'::text])))
        UNION ALL
         SELECT c.tenant_id,
            c.site_id,
            c.network_id,
            r.original_network_id,
            (c.depth + 1)
           FROM (chain c
             JOIN iam_v2.guest_network_replacements r ON (((r.successor_network_id = c.ancestor_id) AND (r.tenant_id = c.tenant_id) AND (r.site_id = c.site_id) AND (r.state = ANY (ARRAY['APPLIED'::text, 'CONFIRMED'::text])))))
          WHERE (c.depth < 32)
        )
 SELECT tenant_id,
    site_id,
    network_id,
    ancestor_id,
    min(depth) AS depth
   FROM chain
  WHERE (ancestor_id <> network_id)
  GROUP BY tenant_id, site_id, network_id, ancestor_id;


--
-- Name: guest_network_pms_map; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.guest_network_pms_map (
