    id uuid DEFAULT gen_random_uuid() NOT NULL,
    pause_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    device_mac macaddr NOT NULL,
    granted_at timestamp with time zone DEFAULT now() NOT NULL,
    granted_by text NOT NULL,
    reason text NOT NULL,
    CONSTRAINT guest_signin_device_passes_granted_by_check CHECK ((length(btrim(granted_by)) > 0))
);


--
-- Name: TABLE guest_signin_device_passes; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.guest_signin_device_passes IS 'A device staff confirmed as a genuine guest during a network pause (0136): it may attempt room sign-in while the pause lasts. A permission to attempt, never access. Removed one day after the pause ends.';


--
-- Name: guest_signin_network_pauses; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.guest_signin_network_pauses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    guest_network_id uuid NOT NULL,
    guest_network_name text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    failure_count integer NOT NULL,
    ended_at timestamp with time zone,
    ended_by text,
    end_reason text,
    CONSTRAINT guest_signin_network_pauses_check CHECK ((expires_at > started_at)),
    CONSTRAINT guest_signin_network_pauses_check1 CHECK (((ended_at IS NULL) = (ended_by IS NULL)))
);


--
-- Name: guest_signin_network_policy_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.guest_signin_network_policy_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    change_reason text,
    old_network_max_failures integer,
    old_network_window_seconds integer,
    old_network_pause_seconds integer,
    new_network_max_failures integer NOT NULL,
    new_network_window_seconds integer NOT NULL,
    new_network_pause_seconds integer NOT NULL,
    new_config_version bigint NOT NULL,
    CONSTRAINT guest_signin_network_policy_changes_changed_by_check CHECK ((length(btrim(changed_by)) > 0))
);


--
-- Name: guest_signin_protection_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.guest_signin_protection_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    change_reason text,
    old_max_failed_attempts integer,
    old_observation_window_seconds integer,
    old_restriction_seconds integer,
    new_max_failed_attempts integer NOT NULL,
    new_observation_window_seconds integer NOT NULL,
    new_restriction_seconds integer NOT NULL,
    new_config_version bigint NOT NULL,
    CONSTRAINT guest_signin_protection_changes_actor CHECK ((length(btrim(changed_by)) > 0))
);


--
-- Name: TABLE guest_signin_protection_changes; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.guest_signin_protection_changes IS 'Append-only history of every change to a site''s guest sign-in protection policy, written in the SAME transaction as the change by iam_v2.guest_signin_protection_set. No runtime role holds UPDATE on the settings table, so a policy cannot move without this record: the audit is mandatory by privilege rather than by convention.';


--
-- Name: guest_signin_restrictions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.guest_signin_restrictions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    device_mac macaddr NOT NULL,
    guest_network_id uuid,
    guest_network_name text,
    last_submitted_room text,
    restricted_at timestamp with time zone,
    expires_at timestamp with time zone,
    failure_count integer,
    reason text,
    counter_reset_at timestamp with time zone DEFAULT '-infinity'::timestamp with time zone NOT NULL,
    released_at timestamp with time zone,
    released_by text,
    release_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT guest_signin_restrictions_all_or_none CHECK ((((restricted_at IS NULL) AND (expires_at IS NULL) AND (failure_count IS NULL) AND (reason IS NULL)) OR ((restricted_at IS NOT NULL) AND (expires_at IS NOT NULL) AND (failure_count IS NOT NULL) AND (reason IS NOT NULL)))),
    CONSTRAINT guest_signin_restrictions_reason_check CHECK (((reason IS NULL) OR (reason = 'FAILED_CREDENTIAL_THRESHOLD'::text)))
);


--
-- Name: TABLE guest_signin_restrictions; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.guest_signin_restrictions IS 'One row per guest device per site. Carries the current restriction when there is one, and always carries counter_reset_at -- the instant before which failures no longer count, which is how expiry, a successful sign-in and a manual release all start a fresh counter through one mechanism. Scoped to the DEVICE, never the room (which would lock out the guest who lives there) and never the address (which on a NATed guest network is a floor).';


--
-- Name: COLUMN guest_signin_restrictions.device_mac; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.guest_signin_restrictions.device_mac IS 'The hardware address the APPLIANCE read from its own neighbour table for the request source -- never a client-supplied value, so no cookie, request id or header can move it. NOT unspoofable: a device on the guest VLAN can change its MAC and obtain a fresh counter.';


--
-- Name: COLUMN guest_signin_restrictions.last_submitted_room; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.guest_signin_restrictions.last_submitted_room IS 'UNVERIFIED INPUT: the room this device last typed. Never treat it as the identity of a person.';


--
-- Name: internet_package_revisions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.internet_package_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    package_id uuid NOT NULL,
    revision_no integer NOT NULL,
    service_plan_revision_id uuid NOT NULL,
    package_type text NOT NULL,
    price_minor bigint DEFAULT 0 NOT NULL,
    currency character(3),
    currency_exponent smallint,
    settlement_methods text[] DEFAULT '{NOT_REQUIRED}'::text[] NOT NULL,
    duration_policy jsonb DEFAULT '{}'::jsonb NOT NULL,
    plan_overrides jsonb,
    renewable boolean DEFAULT false NOT NULL,
    max_purchases_per_stay integer,
    display jsonb,
    visible_from timestamp with time zone,
    visible_until timestamp with time zone,
    data_allocation_policy jsonb,
    CONSTRAINT internet_package_revisions_data_allocation_policy_shape CHECK (((data_allocation_policy IS NULL) OR COALESCE(((jsonb_typeof(data_allocation_policy) = 'object'::text) AND (((data_allocation_policy ->> 'mode'::text) = 'FIXED'::text) OR (((data_allocation_policy ->> 'mode'::text) = 'PER_STAY_NIGHT'::text) AND (jsonb_typeof((data_allocation_policy -> 'gb_per_night'::text)) = 'number'::text) AND (((data_allocation_policy ->> 'gb_per_night'::text))::numeric > (0)::numeric) AND (((data_allocation_policy -> 'min_gb'::text) IS NULL) OR COALESCE(((jsonb_typeof((data_allocation_policy -> 'min_gb'::text)) = 'number'::text) AND (((data_allocation_policy ->> 'min_gb'::text))::numeric >= (0)::numeric)), false)) AND (((data_allocation_policy -> 'max_gb'::text) IS NULL) OR COALESCE(((jsonb_typeof((data_allocation_policy -> 'max_gb'::text)) = 'number'::text) AND (((data_allocation_policy ->> 'max_gb'::text))::numeric > (0)::numeric) AND (((data_allocation_policy ->> 'max_gb'::text))::numeric >= COALESCE(((data_allocation_policy ->> 'min_gb'::text))::numeric, (0)::numeric))), false))))), false))),
    CONSTRAINT internet_package_revisions_package_type_check CHECK ((package_type = ANY (ARRAY['FREE_STAY'::text, 'ONE_DAY'::text, 'REST_OF_STAY'::text, 'POST_STAY'::text, 'GENERAL'::text, 'CHECKOUT_GRACE'::text]))),
    CONSTRAINT internet_package_revisions_price_minor_check CHECK ((price_minor >= 0)),
    CONSTRAINT ipr_acquisition_methods CHECK (((cardinality(settlement_methods) >= 1) AND (settlement_methods <@ ARRAY['NOT_REQUIRED'::text, 'PREPAID'::text, 'ONLINE_PAYMENT'::text, 'PMS_POSTING'::text]) AND ((price_minor <> 0) OR (settlement_methods <@ ARRAY['NOT_REQUIRED'::text, 'PREPAID'::text])) AND ((price_minor = 0) OR (NOT ('NOT_REQUIRED'::text = ANY (settlement_methods))))))
);


--
-- Name: COLUMN internet_package_revisions.data_allocation_policy; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.internet_package_revisions.data_allocation_policy IS 'How this revision turns a stay into a byte allowance. NULL or {"mode":"FIXED"} uses the pinned service plan revision''s data_quota_bytes unchanged. {"mode":"PER_STAY_NIGHT","gb_per_night":N,"min_gb":N,"max_gb":N} computes nights x gb_per_night, raises it to min_gb and caps it at max_gb when set. The computed value is frozen onto the entitlement at grant time and never recomputed.';


--
-- Name: CONSTRAINT ipr_acquisition_methods ON internet_package_revisions; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON CONSTRAINT ipr_acquisition_methods ON iam_v2.internet_package_revisions IS 'How a package may be acquired: NOT_REQUIRED=Free, PREPAID=Voucher, ONLINE_PAYMENT=Card payment, PMS_POSTING=Room charge. Free requires price 0 and a priced package cannot be free. MANUAL_APPROVAL is a dormant settlement method and never a package acquisition method.';


--
-- Name: internet_packages; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.internet_packages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    code text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    is_system boolean DEFAULT false NOT NULL,
