    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone
);


--
-- Name: online_time_skipped_intervals; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.online_time_skipped_intervals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    session_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    skipped_from timestamp with time zone NOT NULL,
    skipped_to timestamp with time zone NOT NULL,
    cause text NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT online_time_skipped_intervals_cause_check CHECK ((cause = 'UNOBSERVED_GAP'::text)),
    CONSTRAINT online_time_skipped_intervals_check CHECK ((skipped_to > skipped_from))
);


--
-- Name: TABLE online_time_skipped_intervals; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.online_time_skipped_intervals IS 'Intervals of apparently-elapsed session time that were deliberately NOT charged to an AGGREGATE_ONLINE_TIME budget because the accounting service was not observing them. Under-charging is the intended failure direction; this table is what makes it visible rather than silent.';


--
-- Name: otp_code_escrow; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.otp_code_escrow (
    challenge_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    key_id text NOT NULL,
    nonce bytea NOT NULL,
    ciphertext bytea NOT NULL,
    cipher_version integer NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT otp_code_escrow_check CHECK ((expires_at > created_at)),
    CONSTRAINT otp_code_escrow_cipher_version_check CHECK ((cipher_version > 0)),
    CONSTRAINT otp_code_escrow_key_id_check CHECK ((key_id ~ '^[0-9a-f]{16}$'::text))
);


--
-- Name: TABLE otp_code_escrow; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.otp_code_escrow IS 'A sealed copy of each live, sent one-time code, readable only by scd for an operator holding the code-reveal permission (contract §6.7). Deleted when the code is used or expires.';


--
-- Name: otp_code_reveals; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.otp_code_reveals (
    challenge_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    revealed_at timestamp with time zone DEFAULT now() NOT NULL,
    revealed_by text NOT NULL,
    CONSTRAINT otp_code_reveals_revealed_by_check CHECK (((length(revealed_by) >= 1) AND (length(revealed_by) <= 200)))
);


--
-- Name: TABLE otp_code_reveals; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.otp_code_reveals IS 'Challenges whose live code an operator revealed (contract §6.7). A verification of such a code is staff-assisted: it may create a new Client marked staff_assisted, never sign in to an existing one.';


--
-- Name: otp_device_bindings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.otp_device_bindings (
    challenge_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    device_mac macaddr NOT NULL,
    issued_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE otp_device_bindings; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.otp_device_bindings IS 'The device (kernel-resolved MAC) a one-time code was issued to. scd writes a row at issue and refuses a verification from any other device (internal/otp VerifyFrom). Rows are pruned a day after issue; the code itself lives ten minutes. MAC identifies the device only -- never a person.';


--
-- Name: package_eligibility_rules; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.package_eligibility_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    package_revision_id uuid NOT NULL,
    rule_type text NOT NULL,
    rule_value jsonb DEFAULT '{}'::jsonb NOT NULL
);


--
-- Name: package_grant_tiers; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.package_grant_tiers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    package_revision_id uuid NOT NULL,
    tier_order integer NOT NULL,
    grant_value jsonb DEFAULT '{}'::jsonb NOT NULL
);


--
-- Name: package_settlement_mappings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.package_settlement_mappings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    package_revision_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    mapping_revision integer NOT NULL,
    posting_code text NOT NULL,
    tax_code text,
    tax_rate_bp integer,
    retired_at timestamp with time zone,
    replaces_mapping_id uuid,
    CONSTRAINT psm_posting_code_wire_safe CHECK ((((length(btrim(posting_code)) >= 1) AND (length(btrim(posting_code)) <= 20)) AND (posting_code !~ '[|\x00-\x1f\x7f]'::text) AND ((tax_rate_bp IS NULL) OR ((tax_rate_bp >= 0) AND (tax_rate_bp <= 10000)))))
);


--
-- Name: payment_account_conversion; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.payment_account_conversion (
    account_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    provider_converts boolean NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    CONSTRAINT payment_account_conversion_changed_by_check CHECK ((length(btrim(changed_by)) > 0))
);


--
-- Name: payment_account_conversion_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.payment_account_conversion_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    account_id uuid NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    change_reason text,
    old_value boolean,
    new_value boolean NOT NULL,
    CONSTRAINT payment_account_conversion_changes_changed_by_check CHECK ((length(btrim(changed_by)) > 0))
);


--
-- Name: payment_checkouts; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.payment_checkouts (
    transaction_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    provider_session_ref text,
    redirect_url text,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    creation_outcome text DEFAULT 'PENDING'::text NOT NULL,
    last_status_at timestamp with time zone,
    last_state text,
    status_checks integer DEFAULT 0 NOT NULL,
    consecutive_failures integer DEFAULT 0 NOT NULL,
    CONSTRAINT payment_checkouts_consecutive_failures_check CHECK ((consecutive_failures >= 0)),
    CONSTRAINT payment_checkouts_creation_outcome_check CHECK ((creation_outcome = ANY (ARRAY['PENDING'::text, 'CREATED'::text, 'NOT_CREATED'::text, 'AMBIGUOUS'::text]))),
    CONSTRAINT payment_checkouts_provider_session_ref_check CHECK (((provider_session_ref IS NULL) OR ((length(provider_session_ref) >= 1) AND (length(provider_session_ref) <= 300)))),
    CONSTRAINT payment_checkouts_redirect_url_check CHECK (((redirect_url IS NULL) OR ((length(redirect_url) <= 2048) AND (redirect_url ~ '^https://'::text)))),
    CONSTRAINT payment_checkouts_status_checks_check CHECK ((status_checks >= 0))
);


--
-- Name: payment_provider_account_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.payment_provider_account_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    account_id uuid NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    change_reason text,
    change_kind text NOT NULL,
    old_values jsonb,
    new_values jsonb NOT NULL,
    CONSTRAINT payment_provider_account_changes_change_kind_check CHECK ((change_kind = ANY (ARRAY['CREATED'::text, 'UPDATED'::text, 'CREDENTIALS_ROTATED'::text]))),
    CONSTRAINT payment_provider_account_changes_changed_by_check CHECK ((length(btrim(changed_by)) > 0))
);


--
-- Name: payment_provider_accounts; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.payment_provider_accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    provider text NOT NULL,
    merchant_account_ref text,
    display_name text,
    currency character(3),
    status text DEFAULT 'DISABLED'::text NOT NULL,
    is_default boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    provenance text DEFAULT 'CONFIGURED'::text NOT NULL,
    mode text DEFAULT 'TEST'::text NOT NULL,
    CONSTRAINT payment_provider_accounts_merchant_account_ref_check CHECK (((btrim(merchant_account_ref) <> ''::text) AND (length(merchant_account_ref) <= 128))),
    CONSTRAINT payment_provider_accounts_provenance_check CHECK ((provenance = ANY (ARRAY['CONFIGURED'::text, 'BACKFILLED_UNVERIFIED'::text]))),
    CONSTRAINT payment_provider_accounts_provider_check CHECK (((provider ~ '^[a-z][a-z0-9_-]{1,31}$'::text) AND (provider <> ALL (ARRAY['none'::text, 'unknown'::text, 'placeholder'::text, 'todo'::text, 'default'::text, 'null'::text, 'na'::text, 'n_a'::text])))),
    CONSTRAINT payment_provider_accounts_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'DISABLED'::text]))),
    CONSTRAINT ppa_default_is_active CHECK (((NOT is_default) OR (status = 'ACTIVE'::text))),
    CONSTRAINT ppa_mode_known CHECK ((mode = ANY (ARRAY['TEST'::text, 'LIVE'::text]))),
    CONSTRAINT ppa_reference_matches_provenance CHECK ((((provenance = 'CONFIGURED'::text) AND (merchant_account_ref IS NOT NULL) AND (btrim(merchant_account_ref) <> ''::text) AND (length(merchant_account_ref) <= 128)) OR ((provenance = 'BACKFILLED_UNVERIFIED'::text) AND (merchant_account_ref IS NULL)))),
    CONSTRAINT ppa_unverified_is_never_live CHECK (((provenance = 'CONFIGURED'::text) OR ((status = 'DISABLED'::text) AND (NOT is_default))))
);


--
-- Name: TABLE payment_provider_accounts; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.payment_provider_accounts IS 'Authoritative per-site payment provider and merchant-account configuration. Identifiers only, never credentials. A payment intent RESOLVES its provider and merchant account from here; no request may supply either.';


--
-- Name: COLUMN payment_provider_accounts.provenance; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.payment_provider_accounts.provenance IS 'CONFIGURED: an operator supplied this account and its external reference is the provider''s own. BACKFILLED_UNVERIFIED: reconstructed by migration 0018 from a payment row that predates this table. Its external reference is UNKNOWN, not invented, and it can never become ACTIVE or default.';


--
-- Name: COLUMN payment_provider_accounts.mode; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.payment_provider_accounts.mode IS 'TEST uses the provider sandbox. LIVE moves real money and is refused by the deployment ceiling unless STAYCONNECT_PAYMENT_LIVE_ALLOWED is set, which requires a separate Product-Owner authorisation.';


--
-- Name: payment_provider_secret_generations; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.payment_provider_secret_generations (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    account_id uuid NOT NULL,
    ciphertext bytea NOT NULL,
    nonce bytea NOT NULL,
    key_id text NOT NULL,
    cipher_version smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text NOT NULL,
    superseded_at timestamp with time zone,
    CONSTRAINT payment_provider_secret_generations_cipher_version_check CHECK ((cipher_version = 1)),
    CONSTRAINT payment_provider_secret_generations_created_by_check CHECK ((length(btrim(created_by)) > 0))
);


--
-- Name: TABLE payment_provider_secret_generations; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.payment_provider_secret_generations IS 'Sealed provider credentials. Only ciphertext is stored; the AEAD key lives in /etc/stayconnect/secrets and the AAD binds each ciphertext to its tenant, site, account and generation. Never returned by any API.';


--
-- Name: payment_settlement_reports; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.payment_settlement_reports (
    transaction_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    presentment_currency text NOT NULL,
    presentment_amount_minor bigint NOT NULL,
    settlement_currency text,
    settlement_amount_minor bigint,
    exchange_rate text,
    fee_minor bigint,
    net_minor bigint,
    provider_balance_ref text,
    converted boolean NOT NULL,
    report_status text NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payment_settlement_reports_exchange_rate_check CHECK (((exchange_rate IS NULL) OR (exchange_rate ~ '^[0-9]+(\.[0-9]+)?([eE][-+]?[0-9]+)?$'::text))),
    CONSTRAINT payment_settlement_reports_presentment_amount_minor_check CHECK ((presentment_amount_minor > 0)),
    CONSTRAINT payment_settlement_reports_presentment_currency_check CHECK ((presentment_currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT payment_settlement_reports_provider_balance_ref_check CHECK (((provider_balance_ref IS NULL) OR (length(provider_balance_ref) <= 200))),
    CONSTRAINT payment_settlement_reports_report_status_check CHECK ((report_status = ANY (ARRAY['REPORTED'::text, 'NOT_REPORTED'::text]))),
    CONSTRAINT payment_settlement_reports_settlement_currency_check CHECK ((settlement_currency ~ '^[A-Z]{3}$'::text))
);


--
-- Name: TABLE payment_settlement_reports; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.payment_settlement_reports IS 'The provider''s own report of a captured card charge''s settlement (contract §9): presentment as quoted, settlement currency/amount, exchange rate as the provider stated it (text, never recomputed), fee and net, and the provider balance-transaction reference. NOT_REPORTED when the provider has not reported it yet.';


--
-- Name: payment_transaction_events; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.payment_transaction_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    payment_transaction_id uuid NOT NULL,
    provider_event_id text NOT NULL,
    event_type text NOT NULL,
    asserted_status text,
    applied boolean DEFAULT false NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    provider text NOT NULL,
    merchant_account_id uuid NOT NULL,
    CONSTRAINT payment_transaction_events_asserted_status_check CHECK (((asserted_status IS NULL) OR (asserted_status = ANY (ARRAY['CREATED'::text, 'PENDING'::text, 'CAPTURED'::text, 'FAILED'::text, 'EXPIRED'::text, 'CANCELLED'::text, 'UNKNOWN'::text])))),
    CONSTRAINT ptx_event_detail_safe CHECK ((iam_v2.p4_callback_evidence_safe(detail) IS NULL)),
    CONSTRAINT ptx_event_ids_bounded CHECK ((((length(provider_event_id) >= 1) AND (length(provider_event_id) <= 200)) AND (provider_event_id !~ '[\x00-\x1f\x7f]'::text) AND ((length(event_type) >= 1) AND (length(event_type) <= 100)) AND (event_type !~ '[\x00-\x1f\x7f]'::text)))
);


--
-- Name: TABLE payment_transaction_events; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.payment_transaction_events IS 'Append-only provider callback ledger. UNIQUE (payment_transaction_id, provider_event_id) is the duplicate-callback defence: a replayed webhook cannot be applied twice, whatever the caller does.';


--
-- Name: payment_transactions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.payment_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    settlement_id uuid NOT NULL,
    merchant_account_id uuid NOT NULL,
    transaction_type text NOT NULL,
    parent_transaction_id uuid,
    provider text NOT NULL,
    provider_ref text NOT NULL,
    idempotency_key text NOT NULL,
    amount_minor bigint NOT NULL,
    currency character(3) NOT NULL,
    currency_exponent smallint NOT NULL,
    status text NOT NULL,
    provider_txn_ref text,
    intent_created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payment_transactions_amount_minor_check CHECK ((amount_minor > 0)),
    CONSTRAINT payment_transactions_status_check CHECK ((status = ANY (ARRAY['CREATED'::text, 'PENDING'::text, 'CAPTURED'::text, 'FAILED'::text, 'EXPIRED'::text, 'CANCELLED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT payment_transactions_transaction_type_check CHECK ((transaction_type = ANY (ARRAY['CHARGE'::text, 'REFUND'::text, 'CHARGEBACK'::text]))),
    CONSTRAINT ptx_local_ref_bounded CHECK ((((length(provider_ref) >= 1) AND (length(provider_ref) <= 200)) AND (provider_ref !~ '[\x00-\x1f\x7f]'::text))),
    CONSTRAINT ptx_parent CHECK (((transaction_type = 'CHARGE'::text) = (parent_transaction_id IS NULL))),
    CONSTRAINT ptx_provider_txn_ref_bounded CHECK (((provider_txn_ref IS NULL) OR (((length(provider_txn_ref) >= 1) AND (length(provider_txn_ref) <= 200)) AND (provider_txn_ref !~ '[\x00-\x1f\x7f]'::text))))
);


--
-- Name: COLUMN payment_transactions.provider_ref; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.payment_transactions.provider_ref IS 'LOCAL durable intent reference, generated before any external call and sent to the provider as the client reference. It is the idempotency root: it exists even if the process dies before the provider answers.';


--
-- Name: COLUMN payment_transactions.provider_txn_ref; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.payment_transactions.provider_txn_ref IS 'The reference the PROVIDER assigned. NULL until the provider answers; write-once thereafter.';


--
-- Name: pms_answer_confirmations; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_answer_confirmations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    as_status text NOT NULL,
    action text NOT NULL,
    evidence text NOT NULL,
    reason text NOT NULL,
    recorded_by uuid NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pms_answer_confirmations_action_check CHECK ((action = ANY (ARRAY['CONFIRM'::text, 'WITHDRAW'::text]))),
    CONSTRAINT pms_answer_confirmations_as_status_check CHECK ((as_status = ANY (ARRAY['NP'::text, 'NG'::text, 'NR'::text, 'NA'::text, 'RY'::text]))),
    CONSTRAINT pms_answer_confirmations_evidence_check CHECK (((length(btrim(evidence)) >= 20) AND (length(btrim(evidence)) <= 2000))),
    CONSTRAINT pms_answer_confirmations_reason_check CHECK (((length(btrim(reason)) >= 4) AND (length(btrim(reason)) <= 500)))
);


--
-- Name: TABLE pms_answer_confirmations; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.pms_answer_confirmations IS 'Append-only record that the PMS vendor confirmed a PA status means "definitely not posted" on this interface (Amendment A1, contract section 9a rule 8). The latest row per code decides. UR can never be confirmed here.';


--
-- Name: pms_case_resolutions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_case_resolutions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    stay_event_id uuid NOT NULL,
    stay_id uuid,
    disposition text NOT NULL,
    evidence_kind text NOT NULL,
    evidence_ref text,
    run_id uuid,
    resolved_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_by text NOT NULL,
    note text,
    CONSTRAINT pms_case_resolutions_disposition_check CHECK ((disposition = ANY (ARRAY['DEPARTED_CONFIRMED_BY_ROSTER'::text, 'NOT_A_DEPARTURE_ROSTER_SNAPSHOT'::text, 'ALREADY_CLOSED'::text, 'NEEDS_PMS_EVIDENCE'::text, 'ACCEPTED_STARTUP_DATA_GAP'::text, 'ACKNOWLEDGED_BY_OPERATOR'::text, 'LINKED_TO_STAY'::text, 'EXPIRED_UNDECIDED'::text]))),
    CONSTRAINT pms_case_resolutions_evidence_kind_check CHECK ((evidence_kind = ANY (ARRAY['PUBLISHED_ROSTER_GENERATION'::text, 'ADMISSION_KIND'::text, 'STAY_STATE'::text, 'NONE'::text, 'OPERATOR_DECISION'::text, 'EXPIRY_SETTING'::text, 'DATA_RETENTION'::text]))),
    CONSTRAINT pms_case_resolutions_evidence_ref_check CHECK (((evidence_ref IS NULL) OR (length(evidence_ref) <= 200))),
    CONSTRAINT pms_case_resolutions_note_check CHECK (((note IS NULL) OR (length(note) <= 500))),
    CONSTRAINT pms_case_resolutions_resolved_by_check CHECK ((length(btrim(resolved_by)) > 0))
);


--
-- Name: pms_connection_settings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_connection_settings (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    backoff_min_ms integer DEFAULT 500 NOT NULL,
    backoff_max_ms integer DEFAULT 30000 NOT NULL,
    stable_reset_seconds integer DEFAULT 60 NOT NULL,
    link_down_alert_seconds integer DEFAULT 900 NOT NULL,
    blocked_after_refusals integer DEFAULT 3 NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pms_interface_id uuid NOT NULL,
    CONSTRAINT pcs_backoff_sane CHECK ((((backoff_min_ms >= 100) AND (backoff_min_ms <= 600000)) AND ((backoff_max_ms >= 100) AND (backoff_max_ms <= 3600000)) AND (backoff_max_ms >= backoff_min_ms))),
    CONSTRAINT pcs_linkdown_sane CHECK (((link_down_alert_seconds >= 30) AND (link_down_alert_seconds <= 604800))),
    CONSTRAINT pcs_refusals_sane CHECK (((blocked_after_refusals >= 1) AND (blocked_after_refusals <= 1000))),
    CONSTRAINT pcs_stable_sane CHECK (((stable_reset_seconds >= 1) AND (stable_reset_seconds <= 86400))),
    CONSTRAINT pcs_version_positive CHECK ((config_version >= 1))
);


--
-- Name: TABLE pms_connection_settings; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.pms_connection_settings IS 'Reconnect and blocker-reporting bounds for the PMS link. The connector retries indefinitely on purpose -- a PMS returning overnight must be picked up unattended -- so these bound the INTERVAL and the reporting, never the number of attempts.';


--
-- Name: COLUMN pms_connection_settings.pms_interface_id; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.pms_connection_settings.pms_interface_id IS 'The ONE interface these bounds govern. Recovery is a property of a link, not of a building: changing one interface must leave every other interface at the same site exactly as it was.';


--
-- Name: pms_connection_settings_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_connection_settings_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    reason text,
    old_values jsonb,
    new_values jsonb NOT NULL,
    new_config_version bigint NOT NULL,
    pms_interface_id uuid,
    CONSTRAINT pms_connection_settings_changes_changed_by_check CHECK ((length(btrim(changed_by)) > 0)),
    CONSTRAINT pms_connection_settings_changes_reason_check CHECK (((reason IS NULL) OR (length(reason) <= 500)))
);


--
-- Name: pms_financial_onboardings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_financial_onboardings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    revision_id uuid NOT NULL,
    previous_revision_id uuid,
    posting_target_model text NOT NULL,
    currency character(3) NOT NULL,
    currency_exponent smallint NOT NULL,
    attestation text NOT NULL,
    reason text NOT NULL,
    approved_by uuid NOT NULL,
    approved_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pms_financial_onboardings_attestation_check CHECK (((length(btrim(attestation)) >= 20) AND (length(btrim(attestation)) <= 2000))),
    CONSTRAINT pms_financial_onboardings_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT pms_financial_onboardings_currency_exponent_check CHECK (((currency_exponent >= 0) AND (currency_exponent <= 4))),
    CONSTRAINT pms_financial_onboardings_posting_target_model_check CHECK ((posting_target_model = 'RESERVATION'::text)),
    CONSTRAINT pms_financial_onboardings_reason_check CHECK (((length(btrim(reason)) >= 4) AND (length(btrim(reason)) <= 500)))
);


--
-- Name: pms_interface_financial_setting_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_interface_financial_setting_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    setting text NOT NULL,
    old_value integer,
    new_value integer NOT NULL,
    reason text NOT NULL,
    changed_by uuid NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pms_interface_financial_setting_changes_reason_check CHECK (((length(btrim(reason)) >= 4) AND (length(btrim(reason)) <= 500))),
    CONSTRAINT pms_interface_financial_setting_changes_setting_check CHECK ((setting = 'mirror_max_age_seconds'::text))
);


--
-- Name: pms_interface_financial_settings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_interface_financial_settings (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    mirror_max_age_seconds integer NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT pms_interface_financial_settings_mirror_max_age_seconds_check CHECK (((mirror_max_age_seconds >= 3600) AND (mirror_max_age_seconds <= 86400)))
);


--
-- Name: pms_interface_pnumber_seq; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_interface_pnumber_seq (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    next_p_number bigint DEFAULT 1 NOT NULL
);


--
-- Name: pms_interface_revisions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_interface_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    revision_no integer NOT NULL,
    source_timezone text NOT NULL,
    posting_target_model text DEFAULT 'UNSET'::text NOT NULL,
    config jsonb NOT NULL,
    normalization_version integer DEFAULT 1 NOT NULL,
    source_fingerprint text,
    financial_base_currency character(3),
    financial_base_currency_exponent smallint,
    CONSTRAINT pms_interface_revisions_posting_target_model_check CHECK ((posting_target_model = ANY (ARRAY['UNSET'::text, 'RESERVATION'::text]))),
    CONSTRAINT pmsrev_financial_currency_exponent_range CHECK (((financial_base_currency_exponent IS NULL) OR ((financial_base_currency_exponent >= 0) AND (financial_base_currency_exponent <= 4)))),
    CONSTRAINT pmsrev_financial_currency_iso CHECK (((financial_base_currency IS NULL) OR (financial_base_currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT pmsrev_financial_currency_pair CHECK (((financial_base_currency IS NULL) = (financial_base_currency_exponent IS NULL)))
);


--
-- Name: COLUMN pms_interface_revisions.posting_target_model; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.pms_interface_revisions.posting_target_model IS 'Fail-closed posting target (Amendment A1, D46). UNSET blocks every financial CHARGE; RESERVATION = a PS targets RN + G#, G# being the vendor-confirmed non-reused reservation number. Recorded by financial onboarding only.';


--
-- Name: COLUMN pms_interface_revisions.financial_base_currency; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.pms_interface_revisions.financial_base_currency IS 'G2/Tier-2: authoritative property financial currency for this revision. NULL = not financially onboarded (fail-closed: no posting may execute). Immutable with the revision; onboarding publishes a new revision.';


--
-- Name: COLUMN pms_interface_revisions.financial_base_currency_exponent; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.pms_interface_revisions.financial_base_currency_exponent IS 'G2: ISO-4217 minor-unit exponent for financial_base_currency. Amounts are integer minor units everywhere.';


--
-- Name: pms_interface_runtime; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_interface_runtime (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    pinned_revision_id uuid,
    pinned_secret_generation_id uuid,
    credential_mode text DEFAULT 'AUTH_KEY'::text NOT NULL,
    runtime_generation bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    transport_status text DEFAULT 'UNKNOWN'::text NOT NULL,
    last_connect_attempt_at timestamp with time zone,
    last_connected_at timestamp with time zone,
    last_heartbeat_at timestamp with time zone,
    disconnected_since timestamp with time zone,
    transport_error_code text,
    continuity_status text DEFAULT 'UNKNOWN'::text NOT NULL,
    last_valid_event_at timestamp with time zone,
    last_event_cursor text,
    discontinuity_detected_at timestamp with time zone,
    last_resync_marker_at timestamp with time zone,
    sync_status text DEFAULT 'UNKNOWN'::text NOT NULL,
    resync_requested_at timestamp with time zone,
    resync_started_at timestamp with time zone,
    last_complete_sync_at timestamp with time zone,
    sync_cursor text,
    last_sync_failure_code text,
    resync_generation_seq bigint DEFAULT 0 NOT NULL,
    published_resync_generation bigint DEFAULT 0 NOT NULL,
    resync_command_id uuid,
    resync_command_requested_at timestamp with time zone,
    resync_command_reason text,
    resync_command_generation bigint,
    resync_command_claimed_at timestamp with time zone,
    sync_stage text,
    sync_stage_at timestamp with time zone,
    sync_records_received bigint DEFAULT 0 NOT NULL,
    sync_records_skipped bigint DEFAULT 0 NOT NULL,
    sync_failure_code text,
    last_sync_in_house_count bigint,
    CONSTRAINT pir_bounded_lengths CHECK ((((transport_error_code IS NULL) OR (length(transport_error_code) <= 200)) AND ((last_sync_failure_code IS NULL) OR (length(last_sync_failure_code) <= 200)) AND ((last_event_cursor IS NULL) OR (length(last_event_cursor) <= 4096)) AND ((sync_cursor IS NULL) OR (length(sync_cursor) <= 4096)))),
    CONSTRAINT pir_connected_pins CHECK (((transport_status <> 'CONNECTED'::text) OR ((pinned_revision_id IS NOT NULL) AND (last_connected_at IS NOT NULL) AND ((credential_mode = 'NONE'::text) OR (pinned_secret_generation_id IS NOT NULL))))),
    CONSTRAINT pir_generation_nonneg CHECK ((runtime_generation >= 0)),
    CONSTRAINT pir_heartbeat_not_future CHECK (((last_heartbeat_at IS NULL) OR (last_heartbeat_at <= updated_at))),
    CONSTRAINT pir_resync_coherent CHECK ((((resync_started_at IS NULL) OR (resync_requested_at IS NOT NULL)) AND ((resync_started_at IS NULL) OR (resync_requested_at IS NULL) OR (resync_started_at >= resync_requested_at)))),
    CONSTRAINT pir_resync_command_coherent CHECK ((((resync_command_id IS NULL) = (resync_command_requested_at IS NULL)) AND ((resync_command_generation IS NULL) = (resync_command_id IS NULL)))),
    CONSTRAINT pir_resync_generation_coherent CHECK (((resync_generation_seq >= 0) AND (published_resync_generation >= 0) AND (published_resync_generation <= resync_generation_seq))),
    CONSTRAINT pir_sync_stage_bounded CHECK (((sync_stage IS NULL) OR (sync_stage = ANY (ARRAY['REQUESTING_FULL_SYNC'::text, 'WAITING_FOR_PMS'::text, 'RECEIVING'::text, 'PUBLISHING'::text, 'COMPLETE'::text, 'FAILED'::text, 'INTERRUPTED'::text])))),
    CONSTRAINT pms_interface_runtime_continuity_status_check CHECK ((continuity_status = ANY (ARRAY['UNKNOWN'::text, 'CONTINUOUS'::text, 'DISCONTINUOUS'::text, 'GAP_DETECTED'::text]))),
    CONSTRAINT pms_interface_runtime_credential_mode_check CHECK ((credential_mode = ANY (ARRAY['NONE'::text, 'AUTH_KEY'::text]))),
    CONSTRAINT pms_interface_runtime_sync_status_check CHECK ((sync_status = ANY (ARRAY['UNKNOWN'::text, 'IN_SYNC'::text, 'RESYNC_REQUIRED'::text, 'RESYNC_IN_PROGRESS'::text, 'SYNC_FAILED'::text]))),
    CONSTRAINT pms_interface_runtime_transport_status_check CHECK ((transport_status = ANY (ARRAY['UNKNOWN'::text, 'CONNECTING'::text, 'CONNECTED'::text, 'DISCONNECTED'::text, 'ERROR'::text])))
);


--
-- Name: COLUMN pms_interface_runtime.resync_command_id; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.pms_interface_runtime.resync_command_id IS 'Operator-requested full resync awaiting execution by the pmsd worker that owns this socket. Written by edged, claimed exactly once by the worker under a runtime_generation CAS, cleared on claim. edged never writes a PMS frame; this row is the whole of the command channel.';


--
-- Name: COLUMN pms_interface_runtime.resync_command_generation; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.pms_interface_runtime.resync_command_generation IS 'The runtime_generation the command was issued against. A worker whose generation has advanced refuses it: the operator asked a specific worker on a specific socket, and a replacement is not that worker.';


--
-- Name: COLUMN pms_interface_runtime.sync_records_received; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.pms_interface_runtime.sync_records_received IS 'Records actually staged under the open resync generation. FIAS provides no total before DE, so this is a real running count and there is deliberately no total, percentage or remaining-count column to pair it with — every such number would be invented.';


--
-- Name: COLUMN pms_interface_runtime.last_sync_in_house_count; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.pms_interface_runtime.last_sync_in_house_count IS 'IN_HOUSE Stays the last COMPLETED sync produced, stamped at publish rather than counted on read, so it reports what that sync delivered instead of what the table holds now.';


--
-- Name: pms_interface_secret_generations; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_interface_secret_generations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
