    CONSTRAINT pms_interfaces_lifecycle_state_check CHECK ((lifecycle_state = ANY (ARRAY['ACTIVE'::text, 'AUTH_DISABLED'::text, 'DRAINING'::text, 'DECOMMISSIONED'::text])))
);


--
-- Name: pms_postings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_postings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    settlement_id uuid NOT NULL,
    purchase_id uuid NOT NULL,
    stay_id uuid,
    posting_interface_revision_id uuid NOT NULL,
    secret_generation_id uuid,
    posting_type text NOT NULL,
    reverses_posting_id uuid,
    amount_minor bigint NOT NULL,
    currency character(3),
    currency_exponent smallint,
    idempotency_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    g_number text NOT NULL,
    CONSTRAINT pms_postings_posting_type_check CHECK ((posting_type = ANY (ARRAY['CHARGE'::text, 'REVERSAL'::text]))),
    CONSTRAINT posting_gnumber_wire_safe CHECK (((btrim(g_number) <> ''::text) AND (length(g_number) <= 32) AND (g_number !~ '[\x00-\x1f\x7f|]'::text))),
    CONSTRAINT posting_reversal_link CHECK (((posting_type = 'REVERSAL'::text) = (reverses_posting_id IS NOT NULL)))
);


--
-- Name: COLUMN pms_postings.g_number; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.pms_postings.g_number IS 'The reservation number (G#) of the pinned stay, snapshotted at creation and immutable. Posting identity is (pms_interface_id, g_number) (Amendment A1).';


--
-- Name: stay_events; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.stay_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    stay_id uuid,
    external_event_identity text NOT NULL,
    event_type text NOT NULL,
    pms_timestamp_raw text,
    pms_timestamp_utc timestamp with time zone,
    source_timezone text,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    sequence_version bigint DEFAULT 0 NOT NULL,
    normalization_version integer DEFAULT 1 NOT NULL,
    clock_suspect boolean DEFAULT false NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    processing_status text DEFAULT 'PENDING'::text NOT NULL,
    processed_at timestamp with time zone,
    review_code text,
    admission_kind text DEFAULT 'LIVE'::text NOT NULL,
    admission_runtime_generation bigint DEFAULT 0 NOT NULL,
    resync_generation bigint DEFAULT 0 NOT NULL,
    fingerprint_key_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT se_admission_coherent CHECK ((((admission_kind = 'LIVE'::text) AND (resync_generation = 0)) OR ((admission_kind = 'RESYNC'::text) AND (resync_generation > 0)))),
    CONSTRAINT stay_events_admission_kind_check CHECK ((admission_kind = ANY (ARRAY['LIVE'::text, 'RESYNC'::text]))),
    CONSTRAINT stay_events_admission_runtime_generation_check CHECK ((admission_runtime_generation >= 0)),
    CONSTRAINT stay_events_fingerprint_key_version_check CHECK ((fingerprint_key_version >= 0)),
    CONSTRAINT stay_events_processing_status_check CHECK ((processing_status = ANY (ARRAY['PENDING'::text, 'APPLIED'::text, 'SKIPPED_DUPLICATE'::text, 'MANUAL_REVIEW'::text, 'FAILED'::text]))),
    CONSTRAINT stay_events_resync_generation_check CHECK ((resync_generation >= 0)),
    CONSTRAINT stay_events_review_code_check CHECK (((review_code IS NULL) OR (length(review_code) <= 200)))
);


--
-- Name: stays; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.stays (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    external_reservation_id text NOT NULL,
    external_stay_identity text NOT NULL,
    normalized_room_number text,
    status text NOT NULL,
    lifecycle_version integer DEFAULT 1 NOT NULL,
    posting_allowed boolean DEFAULT false NOT NULL,
    posting_block_reason text,
    posting_permission_source text,
    posting_checked_at timestamp with time zone,
    last_applied_event_version bigint DEFAULT 0 NOT NULL,
    vip boolean,
    travel_agent text,
    room_type text,
    arrival date,
    departure date,
    effective_checkout_at timestamp with time zone,
    occupancy_evidence_at timestamp with time zone,
    occupancy_ingested_at timestamp with time zone,
    occupancy_revision_id uuid,
    occupancy_normalization_version integer,
    occupancy_clock_suspect boolean,
    occupancy_evidence_version bigint DEFAULT 0 NOT NULL,
    rate_plan text,
    last_applied_event_id uuid,
    CONSTRAINT posting_only_in_house CHECK (((posting_allowed = false) OR (status = 'IN_HOUSE'::text))),
    CONSTRAINT stays_effco_only_after_checkout CHECK (((effective_checkout_at IS NULL) OR (status = ANY (ARRAY['CHECKED_OUT'::text, 'POST_STAY_ACTIVE'::text])))),
    CONSTRAINT stays_evidence_version_coherent CHECK ((((occupancy_evidence_at IS NULL) AND (occupancy_evidence_version = 0)) OR ((occupancy_evidence_at IS NOT NULL) AND (occupancy_evidence_version > 0)))),
    CONSTRAINT stays_occupancy_all_or_none CHECK ((((occupancy_evidence_at IS NULL) AND (occupancy_ingested_at IS NULL) AND (occupancy_revision_id IS NULL) AND (occupancy_normalization_version IS NULL) AND (occupancy_clock_suspect IS NULL)) OR ((occupancy_evidence_at IS NOT NULL) AND (occupancy_ingested_at IS NOT NULL) AND (occupancy_revision_id IS NOT NULL) AND (occupancy_normalization_version IS NOT NULL) AND (occupancy_clock_suspect IS NOT NULL)))),
    CONSTRAINT stays_occupancy_evidence_version_check CHECK ((occupancy_evidence_version >= 0)),
    CONSTRAINT stays_occupancy_norm_pos CHECK (((occupancy_normalization_version IS NULL) OR (occupancy_normalization_version > 0))),
    CONSTRAINT stays_status_check CHECK ((status = ANY (ARRAY['RESERVED'::text, 'IN_HOUSE'::text, 'CHECKED_OUT'::text, 'POST_STAY_ACTIVE'::text, 'CANCELLED'::text, 'NO_SHOW'::text])))
);


--
-- Name: pms_reconciliation_cases; Type: VIEW; Schema: iam_v2; Owner: -
--

CREATE VIEW iam_v2.pms_reconciliation_cases AS
 WITH rt AS (
         SELECT pms_interface_runtime.tenant_id,
            pms_interface_runtime.site_id,
            pms_interface_runtime.pms_interface_id,
            pms_interface_runtime.published_resync_generation,
            pms_interface_runtime.sync_stage,
            pms_interface_runtime.last_complete_sync_at
           FROM iam_v2.pms_interface_runtime
        ), roster AS (
         SELECT se.tenant_id,
            se.site_id,
            se.pms_interface_id,
            btrim(COALESCE((se.payload ->> 'reservation'::text), ''::text)) AS reservation,
            upper(btrim(COALESCE((se.payload ->> 'room'::text), ''::text))) AS room
           FROM (iam_v2.stay_events se
             JOIN rt ON (((rt.tenant_id = se.tenant_id) AND (rt.site_id = se.site_id) AND (rt.pms_interface_id = se.pms_interface_id))))
          WHERE ((se.admission_kind = 'RESYNC'::text) AND (se.resync_generation = rt.published_resync_generation) AND (rt.published_resync_generation > 0) AND (se.event_type = ANY (ARRAY['GI'::text, 'GC'::text])))
        ), ev AS (
         SELECT se.id,
            se.tenant_id,
            se.site_id,
            se.pms_interface_id,
            se.received_at,
            se.pms_timestamp_utc,
            se.clock_suspect,
            se.review_code,
            se.resync_generation,
            btrim(COALESCE((se.payload ->> 'reservation'::text), ''::text)) AS reservation,
            upper(btrim(COALESCE((se.payload ->> 'room'::text), ''::text))) AS room
           FROM iam_v2.stay_events se
          WHERE ((se.event_type = 'GO'::text) AND (se.processing_status = 'MANUAL_REVIEW'::text))
        ), grouped AS (
         SELECT ev.tenant_id,
            ev.site_id,
            ev.pms_interface_id,
                CASE
                    WHEN (ev.reservation <> ''::text) THEN ('reservation:'::text || ev.reservation)
                    ELSE ('room:'::text || ev.room)
                END AS case_key,
            max(ev.reservation) AS reservation,
            max(ev.room) AS room,
            (count(*))::integer AS repeat_count,
            (count(DISTINCT ev.resync_generation))::integer AS generations,
            min(ev.received_at) AS first_seen_at,
            max(ev.received_at) AS last_seen_at,
            (array_agg(ev.id ORDER BY ev.received_at DESC, ev.id DESC))[1] AS latest_event_id,
            (array_agg(ev.review_code ORDER BY ev.received_at DESC, ev.id DESC))[1] AS latest_review_code,
            (array_agg(
                CASE
                    WHEN (ev.clock_suspect OR (ev.pms_timestamp_utc IS NULL)) THEN ev.received_at
                    ELSE ev.pms_timestamp_utc
                END ORDER BY ev.received_at DESC, ev.id DESC))[1] AS event_at
           FROM ev
          GROUP BY ev.tenant_id, ev.site_id, ev.pms_interface_id,
                CASE
                    WHEN (ev.reservation <> ''::text) THEN ('reservation:'::text || ev.reservation)
                    ELSE ('room:'::text || ev.room)
                END
        ), enriched AS (
         SELECT g.tenant_id,
            g.site_id,
            g.pms_interface_id,
            g.case_key,
            g.reservation,
            g.room,
            g.repeat_count,
            g.generations,
            g.first_seen_at,
            g.last_seen_at,
            g.latest_event_id,
            g.latest_review_code,
            g.event_at,
            rt.published_resync_generation,
            rt.sync_stage,
            rt.last_complete_sync_at,
            ( SELECT (count(*))::integer AS count
                   FROM iam_v2.stays s
                  WHERE ((s.tenant_id = g.tenant_id) AND (s.site_id = g.site_id) AND (s.pms_interface_id = g.pms_interface_id) AND (s.status = 'IN_HOUSE'::text) AND (((g.reservation <> ''::text) AND (s.external_reservation_id = g.reservation)) OR ((g.reservation = ''::text) AND (s.normalized_room_number = g.room))))) AS candidate_stays,
            ( SELECT s.id
                   FROM iam_v2.stays s
                  WHERE ((s.tenant_id = g.tenant_id) AND (s.site_id = g.site_id) AND (s.pms_interface_id = g.pms_interface_id) AND (s.status = 'IN_HOUSE'::text) AND (((g.reservation <> ''::text) AND (s.external_reservation_id = g.reservation)) OR ((g.reservation = ''::text) AND (s.normalized_room_number = g.room))))
                  ORDER BY s.id
                 LIMIT 1) AS candidate_stay_id,
            ( SELECT s.arrival
                   FROM iam_v2.stays s
                  WHERE ((s.tenant_id = g.tenant_id) AND (s.site_id = g.site_id) AND (s.pms_interface_id = g.pms_interface_id) AND (s.status = 'IN_HOUSE'::text) AND (((g.reservation <> ''::text) AND (s.external_reservation_id = g.reservation)) OR ((g.reservation = ''::text) AND (s.normalized_room_number = g.room))))
                  ORDER BY s.id
                 LIMIT 1) AS candidate_arrival,
            (EXISTS ( SELECT 1
                   FROM roster ro
                  WHERE ((ro.tenant_id = g.tenant_id) AND (ro.site_id = g.site_id) AND (ro.pms_interface_id = g.pms_interface_id) AND (((g.reservation <> ''::text) AND (ro.reservation = g.reservation)) OR ((g.reservation = ''::text) AND (ro.room = g.room)))))) AS roster_present
           FROM (grouped g
             LEFT JOIN rt ON (((rt.tenant_id = g.tenant_id) AND (rt.site_id = g.site_id) AND (rt.pms_interface_id = g.pms_interface_id))))
        )
 SELECT tenant_id,
    site_id,
    pms_interface_id,
    case_key,
    reservation,
    room,
    repeat_count,
    generations,
    first_seen_at,
    last_seen_at,
    event_at,
    latest_event_id,
    latest_review_code,
    candidate_stays,
    candidate_stay_id,
    candidate_arrival,
    roster_present,
    last_complete_sync_at,
        CASE
            WHEN ((candidate_stays = 0) AND (reservation = ''::text)) THEN 'SUPERSEDED_ROOM_EMPTY'::text
            WHEN (candidate_stays = 0) THEN 'NEEDS_PMS_EVIDENCE'::text
            WHEN (candidate_stays > 1) THEN 'ROOM_SHARED'::text
            WHEN ((reservation = ''::text) AND (candidate_arrival IS NOT NULL) AND (candidate_arrival > ((event_at AT TIME ZONE 'UTC'::text))::date)) THEN 'LATER_OCCUPANT'::text
            WHEN (last_complete_sync_at IS NULL) THEN 'NEEDS_PMS_EVIDENCE'::text
            WHEN roster_present THEN 'ROSTER_CONTRADICTS'::text
            ELSE 'RESOLVABLE'::text
        END AS resolution_state
   FROM enriched e;


--
-- Name: VIEW pms_reconciliation_cases; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON VIEW iam_v2.pms_reconciliation_cases IS 'One row per DISTINCT unresolved PMS departure, with the number of recorded copies beside it and a resolution state computed from current roster and occupancy evidence. READ-ONLY: a departure that went to review is resolved by the PMS sending one that can be applied, never by replaying the old one -- stay_events is one-way and a checkout boundary must be an APPLIED GO event. Collapses copies for counting; deletes and hides nothing.';


--
-- Name: pms_reconciliation_settings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_reconciliation_settings (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    roster_trust_min integer DEFAULT 50 NOT NULL,
    inventory_tolerance integer DEFAULT 2 NOT NULL,
    inventory_lookback integer DEFAULT 10 NOT NULL,
    max_close_per_run integer DEFAULT 500 NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT prs_cap_sane CHECK (((max_close_per_run >= 1) AND (max_close_per_run <= 100000))),
    CONSTRAINT prs_floor_sane CHECK (((roster_trust_min >= 1) AND (roster_trust_min <= 100000))),
    CONSTRAINT prs_lookback_sane CHECK (((inventory_lookback >= 1) AND (inventory_lookback <= 1000))),
    CONSTRAINT prs_tolerance_sane CHECK (((inventory_tolerance >= 0) AND (inventory_tolerance <= 10000))),
    CONSTRAINT prs_version_positive CHECK ((config_version >= 1))
);


--
-- Name: TABLE pms_reconciliation_settings; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.pms_reconciliation_settings IS 'Bounds for roster/mirror reconciliation. inventory_tolerance/inventory_lookback decide when a resync generation counts as a COMPLETE sweep of the property. roster_trust_min is a backstop floor. max_close_per_run is the most stays a single run may close before it stops for a human.';


--
-- Name: pms_reconciliation_settings_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_reconciliation_settings_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    reason text,
    old_values jsonb,
    new_values jsonb NOT NULL,
    new_config_version bigint NOT NULL,
    CONSTRAINT pms_reconciliation_settings_changes_changed_by_check CHECK ((length(btrim(changed_by)) > 0)),
    CONSTRAINT pms_reconciliation_settings_changes_reason_check CHECK (((reason IS NULL) OR (length(reason) <= 500)))
);


--
-- Name: pms_resync_coverage; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_resync_coverage (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    resync_generation bigint NOT NULL,
    rooms_named integer NOT NULL,
    roster_records integer NOT NULL,
    vacant_rooms integer NOT NULL,
    observed_at timestamp with time zone DEFAULT now() NOT NULL,
    rooms text[] DEFAULT '{}'::text[] NOT NULL,
    conflicting_rooms integer DEFAULT 0 NOT NULL,
    CONSTRAINT prc_conflicts_sane CHECK ((conflicting_rooms >= 0)),
    CONSTRAINT prc_counts_sane CHECK (((rooms_named >= 0) AND (roster_records >= 0) AND (vacant_rooms >= 0)))
);


--
-- Name: TABLE pms_resync_coverage; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.pms_resync_coverage IS 'What each completed resync OBSERVED: distinct rooms named, split into occupied (admitted) and vacant (observed but never admitted as departures). Evidence about a sweep, never about a guest.';


--
-- Name: COLUMN pms_resync_coverage.rooms; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.pms_resync_coverage.rooms IS 'The room identities this sweep named, normalized and sorted. Completeness is a set difference against recent sweeps, not a count. Rooms are spaces, not people: no reservation, name, stay or event is stored here.';


--
-- Name: COLUMN pms_resync_coverage.conflicting_rooms; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.pms_resync_coverage.conflicting_rooms IS 'Rooms this sweep reported BOTH occupied and empty. Any value above zero makes the generation unusable for reconciliation.';


--
-- Name: pms_review_expiry_settings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_review_expiry_settings (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    expire_after_days integer DEFAULT 30 NOT NULL,
    applies_from timestamp with time zone,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pres_days_bounded CHECK (((expire_after_days >= 1) AND (expire_after_days <= 365))),
    CONSTRAINT pres_on_has_start CHECK (((NOT enabled) OR (applies_from IS NOT NULL))),
    CONSTRAINT pres_version_positive CHECK ((config_version >= 1))
);


--
-- Name: pms_review_expiry_settings_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_review_expiry_settings_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    reason text NOT NULL,
    old_values jsonb,
    new_values jsonb NOT NULL,
    new_config_version bigint NOT NULL,
    CONSTRAINT pms_review_expiry_settings_changes_changed_by_check CHECK ((length(btrim(changed_by)) > 0)),
    CONSTRAINT pms_review_expiry_settings_changes_reason_check CHECK (((length(btrim(reason)) >= 3) AND (length(btrim(reason)) <= 500)))
);


--
-- Name: pms_room_inventory; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_room_inventory (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    rooms text[] NOT NULL,
    established_at timestamp with time zone DEFAULT now() NOT NULL,
    established_from bigint,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    CONSTRAINT pri_version_positive CHECK ((config_version >= 1))
);


--
-- Name: TABLE pms_room_inventory; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.pms_room_inventory IS 'The rooms this property is known to have. Grows only from sweeps that already passed completeness; shrinks only by an audited operator decision. A feed that stops mentioning rooms must never be able to shrink it.';


--
-- Name: pms_room_inventory_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_room_inventory_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    reason text,
    change_kind text NOT NULL,
    rooms_before integer DEFAULT 0 NOT NULL,
    rooms_after integer DEFAULT 0 NOT NULL,
    removed text[] DEFAULT '{}'::text[] NOT NULL,
    added text[] DEFAULT '{}'::text[] NOT NULL,
    new_config_version bigint NOT NULL,
    CONSTRAINT pms_room_inventory_changes_change_kind_check CHECK ((change_kind = ANY (ARRAY['ESTABLISHED'::text, 'GREW'::text, 'REBASELINED'::text]))),
    CONSTRAINT pms_room_inventory_changes_changed_by_check CHECK ((length(btrim(changed_by)) > 0)),
    CONSTRAINT pms_room_inventory_changes_reason_check CHECK (((reason IS NULL) OR (length(reason) <= 500)))
);


--
-- Name: pms_rooms_multi_occupancy; Type: VIEW; Schema: iam_v2; Owner: -
--

CREATE VIEW iam_v2.pms_rooms_multi_occupancy AS
 SELECT tenant_id,
    site_id,
    pms_interface_id,
    normalized_room_number AS room,
    (count(*))::integer AS stays_in_room,
    min(arrival) AS earliest_arrival,
    max(departure) AS latest_planned_departure,
    array_agg(id ORDER BY arrival, id) AS stay_ids
   FROM iam_v2.stays s
  WHERE ((status = 'IN_HOUSE'::text) AND (COALESCE(normalized_room_number, ''::text) <> ''::text))
  GROUP BY tenant_id, site_id, pms_interface_id, normalized_room_number
 HAVING (count(*) > 1);


--
-- Name: pms_roster_reconciliation_runs; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_roster_reconciliation_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    resync_generation bigint NOT NULL,
    mode text NOT NULL,
    outcome text NOT NULL,
    rooms_enumerated integer DEFAULT 0 NOT NULL,
    rooms_expected integer DEFAULT 0 NOT NULL,
    protected_by_newer_events integer DEFAULT 0 NOT NULL,
    roster_size integer DEFAULT 0 NOT NULL,
    mirror_in_house integer DEFAULT 0 NOT NULL,
    absent_from_roster integer DEFAULT 0 NOT NULL,
    stays_closed integer DEFAULT 0 NOT NULL,
    boundary_at timestamp with time zone,
    run_at timestamp with time zone DEFAULT now() NOT NULL,
    run_by text NOT NULL,
    reason text,
    CONSTRAINT pms_roster_reconciliation_runs_mode_check CHECK ((mode = ANY (ARRAY['DRY_RUN'::text, 'APPLY'::text]))),
    CONSTRAINT pms_roster_reconciliation_runs_outcome_check CHECK ((outcome = ANY (ARRAY['COMPLETED'::text, 'REFUSED_ROSTER_TOO_SMALL'::text, 'REFUSED_GENERATION_UNPUBLISHED'::text, 'REFUSED_CAP_EXCEEDED'::text, 'REFUSED_GENERATION_NOT_LATEST'::text, 'REFUSED_LINK_NOT_HEALTHY'::text, 'REFUSED_ROSTER_INCOMPLETE'::text, 'REFUSED_SCOPE_MISMATCH'::text, 'REFUSED_NO_COVERAGE_EVIDENCE'::text, 'REFUSED_CONFLICTING_OBSERVATIONS'::text]))),
    CONSTRAINT pms_roster_reconciliation_runs_reason_check CHECK (((reason IS NULL) OR (length(reason) <= 500))),
    CONSTRAINT pms_roster_reconciliation_runs_run_by_check CHECK ((length(btrim(run_by)) > 0))
);


--
-- Name: pms_source_conflicts; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.pms_source_conflicts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    interface_a uuid NOT NULL,
    interface_b uuid NOT NULL,
    severity text,
    resolution text,
    CONSTRAINT psc_order CHECK ((interface_a < interface_b))
);


--
-- Name: pms_stays_past_departure; Type: VIEW; Schema: iam_v2; Owner: -
--

CREATE VIEW iam_v2.pms_stays_past_departure AS
 WITH roster AS (
         SELECT se.tenant_id,
            se.site_id,
            se.pms_interface_id,
            btrim(COALESCE((se.payload ->> 'reservation'::text), ''::text)) AS reservation,
            upper(btrim(COALESCE((se.payload ->> 'room'::text), ''::text))) AS room
           FROM (iam_v2.stay_events se
             JOIN iam_v2.pms_interface_runtime r ON (((r.tenant_id = se.tenant_id) AND (r.site_id = se.site_id) AND (r.pms_interface_id = se.pms_interface_id))))
          WHERE ((se.admission_kind = 'RESYNC'::text) AND (se.resync_generation = r.published_resync_generation) AND (r.published_resync_generation > 0) AND (se.event_type = ANY (ARRAY['GI'::text, 'GC'::text])))
        )
 SELECT tenant_id,
    site_id,
    pms_interface_id,
    id AS stay_id,
    normalized_room_number AS room,
    external_reservation_id AS reservation,
    arrival,
    departure,
    (CURRENT_DATE - departure) AS days_past_departure,
    (EXISTS ( SELECT 1
           FROM roster ro
          WHERE ((ro.tenant_id = s.tenant_id) AND (ro.site_id = s.site_id) AND (ro.pms_interface_id = s.pms_interface_id) AND (((COALESCE(s.external_reservation_id, ''::text) <> ''::text) AND (ro.reservation = s.external_reservation_id)) OR ((COALESCE(s.external_reservation_id, ''::text) = ''::text) AND (ro.room = s.normalized_room_number)))))) AS roster_present,
    (EXISTS ( SELECT 1
           FROM roster ro
          WHERE ((ro.tenant_id = s.tenant_id) AND (ro.site_id = s.site_id) AND (ro.pms_interface_id = s.pms_interface_id) AND (ro.room = s.normalized_room_number) AND (ro.reservation IS DISTINCT FROM s.external_reservation_id)))) AS room_now_holds_another_stay
   FROM iam_v2.stays s
  WHERE ((status = 'IN_HOUSE'::text) AND (departure IS NOT NULL) AND (departure < CURRENT_DATE));


--
-- Name: pms_unanswered_review_events; Type: VIEW; Schema: iam_v2; Owner: -
--

CREATE VIEW iam_v2.pms_unanswered_review_events AS
 SELECT id,
    tenant_id,
    site_id,
    pms_interface_id,
    stay_id,
    external_event_identity,
    event_type,
    pms_timestamp_raw,
    pms_timestamp_utc,
    source_timezone,
    received_at,
    sequence_version,
    normalization_version,
    clock_suspect,
    payload,
    processing_status,
    processed_at,
    review_code,
    admission_kind,
    admission_runtime_generation,
    resync_generation,
    fingerprint_key_version
   FROM iam_v2.stay_events e
  WHERE ((processing_status = 'MANUAL_REVIEW'::text) AND (NOT (EXISTS ( SELECT 1
           FROM iam_v2.pms_case_resolutions x
          WHERE (x.stay_event_id = e.id)))));


--
-- Name: VIEW pms_unanswered_review_events; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON VIEW iam_v2.pms_unanswered_review_events IS 'Recorded events that still need an answer: MANUAL_REVIEW with no disposition. THE single definition of outstanding PMS work -- every operator-facing count reads this, so no two screens can disagree about how much there is to do.';


--
-- Name: post_stay_profiles; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.post_stay_profiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    origin_stay_id uuid NOT NULL,
    origin_lifecycle_version integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    pin_hash text NOT NULL,
    pin_generation integer DEFAULT 1 NOT NULL,
    pin_set_at timestamp with time zone DEFAULT now() NOT NULL,
    pin_revealed_at timestamp with time zone,
    valid_until timestamp with time zone NOT NULL,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by uuid,
    revoke_reason text,
    issued_via text NOT NULL,
    issued_by_operator uuid,
    issued_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT post_stay_profiles_issued_via_check CHECK ((issued_via = ANY (ARRAY['GUEST_AUTHENTICATED_SESSION'::text, 'OPERATOR_RESET'::text]))),
    CONSTRAINT post_stay_profiles_pin_generation_check CHECK ((pin_generation > 0)),
    CONSTRAINT post_stay_profiles_pin_hash_check CHECK ((pin_hash ~~ '$argon2id$%'::text)),
    CONSTRAINT post_stay_profiles_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'REVOKED'::text]))),
    CONSTRAINT psp_issuer_coherent CHECK ((((issued_via = 'OPERATOR_RESET'::text) AND (issued_by_operator IS NOT NULL)) OR ((issued_via = 'GUEST_AUTHENTICATED_SESSION'::text) AND (issued_by_operator IS NULL)))),
    CONSTRAINT psp_revoked_coherent CHECK ((((status = 'ACTIVE'::text) AND (revoked_at IS NULL) AND (revoked_by IS NULL) AND (revoke_reason IS NULL)) OR ((status = 'REVOKED'::text) AND (revoked_at IS NOT NULL) AND (revoke_reason IS NOT NULL)))),
    CONSTRAINT psp_validity_window CHECK ((valid_until > created_at))
);


--
-- Name: posting_attempt_events; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.posting_attempt_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    posting_attempt_id uuid NOT NULL,
    event_type text NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: posting_attempts; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.posting_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    internal_posting_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    attempt_no integer NOT NULL,
    p_number text NOT NULL,
    rn text,
    g_number text,
    sent_at timestamp with time zone NOT NULL,
    outcome text DEFAULT 'SENDING'::text NOT NULL,
    response_at timestamp with time zone,
    pa_as_status text,
    ps_sha256 text,
    CONSTRAINT attempt_gnumber_verified CHECK (((g_number IS NOT NULL) AND (btrim(g_number) <> ''::text) AND (length(g_number) <= 32))),
    CONSTRAINT attempt_gnumber_wire_safe CHECK ((g_number !~ '[\x00-\x1f\x7f|]'::text)),
    CONSTRAINT attempt_pnumber_wire_safe CHECK ((p_number ~ '^[0-9]{1,18}$'::text)),
    CONSTRAINT attempt_ps_sha256_shape CHECK (((ps_sha256 IS NULL) OR (ps_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT attempt_rn_verified CHECK (((rn IS NOT NULL) AND (btrim(rn) <> ''::text) AND (length(rn) <= 32))),
    CONSTRAINT attempt_rn_wire_safe CHECK ((rn !~ '[\x00-\x1f\x7f|]'::text)),
    CONSTRAINT posting_attempts_outcome_check CHECK ((outcome = ANY (ARRAY['SENDING'::text, 'ACKED'::text, 'UNKNOWN'::text, 'NOT_SENT'::text]))),
    CONSTRAINT posting_attempts_pa_as_status_check CHECK ((pa_as_status = ANY (ARRAY['OK'::text, 'NG'::text, 'NA'::text, 'NP'::text, 'NR'::text, 'RY'::text, 'UR'::text])))
);


--
-- Name: COLUMN posting_attempts.ps_sha256; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.posting_attempts.ps_sha256 IS 'SHA-256 (lowercase hex) of the exact PS body this attempt authorises. pmsd transmits a PS only when p4_posting_command_authorised confirms a SENDING attempt carrying this hash (decision D45).';


--
-- Name: CONSTRAINT attempt_gnumber_verified ON posting_attempts; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON CONSTRAINT attempt_gnumber_verified ON iam_v2.posting_attempts IS 'G1: G# is mandatory financial targeting evidence on every attempt.';


--
-- Name: CONSTRAINT attempt_rn_verified ON posting_attempts; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON CONSTRAINT attempt_rn_verified ON iam_v2.posting_attempts IS 'G1: RN is mandatory financial TARGETING evidence on every attempt. It is evidence, never the posting identity.';


--
-- Name: posting_outbox; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.posting_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    posting_id uuid NOT NULL,
    state text DEFAULT 'QUEUED'::text NOT NULL,
    enqueued_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT posting_outbox_state_check CHECK ((state = ANY (ARRAY['QUEUED'::text, 'IN_FLIGHT'::text, 'DONE'::text, 'HELD_RECOVERY'::text])))
);


--
-- Name: COLUMN posting_outbox.enqueued_at; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.posting_outbox.enqueued_at IS 'When this work entered the outbox. Rows that predate migration 0020 carry the migration time, so their measured age understates the true wait; no history is invented to hide that.';


--
-- Name: posting_review_state; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.posting_review_state (
    posting_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    review_version integer DEFAULT 0 NOT NULL,
    terminal_action text,
    terminal_action_id uuid,
    retry_authorized_attempt_no integer,
    escalation_count integer DEFAULT 0 NOT NULL,
    decided_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    retry_authorization_consumed_at timestamp with time zone,
    reversal_posting_id uuid,
    CONSTRAINT prs_consumed_needs_authorization CHECK (((retry_authorization_consumed_at IS NULL) OR (terminal_action = 'CONFIRM_NOT_POSTED_RETRY'::text))),
    CONSTRAINT prs_retry_only_for_retry CHECK (((retry_authorized_attempt_no IS NULL) OR (terminal_action = 'CONFIRM_NOT_POSTED_RETRY'::text))),
    CONSTRAINT prs_reversal_needs_action CHECK (((reversal_posting_id IS NULL) OR (terminal_action = 'CREATE_REVERSAL'::text))),
    CONSTRAINT prs_terminal_catalog CHECK (((terminal_action IS NULL) OR (terminal_action = ANY (ARRAY['CONFIRM_POSTED'::text, 'CONFIRM_NOT_POSTED_RETRY'::text, 'CONFIRM_NOT_POSTED_ABANDON'::text, 'CREATE_REVERSAL'::text])))),
    CONSTRAINT prs_terminal_decided CHECK (((terminal_action IS NULL) = (decided_at IS NULL))),
    CONSTRAINT prs_terminal_pair CHECK (((terminal_action IS NULL) = (terminal_action_id IS NULL))),
    CONSTRAINT prs_version_nonneg CHECK ((review_version >= 0))
);


--
-- Name: TABLE posting_review_state; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.posting_review_state IS 'C21: one mutable decision pointer per posting. Serializes concurrent financial reviewers. The review LEDGER (posting_review_actions) remains fully append-only and is the authoritative history.';


--
-- Name: posting_execution_state; Type: VIEW; Schema: iam_v2; Owner: -
--

CREATE VIEW iam_v2.posting_execution_state AS
 SELECT p.id AS posting_id,
    p.tenant_id,
    p.site_id,
    p.pms_interface_id,
    p.posting_type,
    p.amount_minor,
    p.currency,
    p.currency_exponent,
    p.idempotency_key,
    p.created_at,
        CASE
            WHEN (la.attempt_no IS NULL) THEN 'NOT_ATTEMPTED'::text
            WHEN (la.outcome = 'SENDING'::text) THEN 'IN_FLIGHT'::text
            WHEN (la.outcome = 'UNKNOWN'::text) THEN 'UNKNOWN'::text
            WHEN (la.outcome = 'NOT_SENT'::text) THEN 'NOT_SENT'::text
            WHEN ((la.outcome = 'ACKED'::text) AND (la.pa_as_status = 'OK'::text)) THEN 'POSTED'::text
            WHEN (la.outcome = 'ACKED'::text) THEN 'REJECTED'::text
            ELSE NULL::text
        END AS execution_state,
    la.attempt_no AS latest_attempt_no,
    la.p_number AS latest_p_number,
    la.outcome AS latest_attempt_outcome,
    la.pa_as_status AS latest_pa_as_status,
    ac.attempt_count,
    ac.unknown_attempt_count,
    (ac.unknown_attempt_count > 0) AS has_unknown_history,
    ob.state AS outbox_state,
    rs.terminal_action AS terminal_review_action,
    rs.review_version,
    rs.escalation_count,
    rs.retry_authorized_attempt_no,
    (rs.retry_authorization_consumed_at IS NOT NULL) AS retry_authorization_consumed,
    ((la.outcome = 'UNKNOWN'::text) AND (rs.terminal_action IS NULL)) AS awaiting_manual_review,
    iam_v2.p4_interface_freshness_block(p.tenant_id, p.site_id, p.pms_interface_id, p.posting_interface_revision_id, now()) AS freshness_block
   FROM ((((iam_v2.pms_postings p
     LEFT JOIN LATERAL ( SELECT a.attempt_no,
            a.outcome,
            a.p_number,
            a.pa_as_status
           FROM iam_v2.posting_attempts a
          WHERE (a.internal_posting_id = p.id)
          ORDER BY a.attempt_no DESC
         LIMIT 1) la ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS attempt_count,
            count(*) FILTER (WHERE (a.outcome = 'UNKNOWN'::text)) AS unknown_attempt_count
           FROM iam_v2.posting_attempts a
          WHERE (a.internal_posting_id = p.id)) ac ON (true))
     LEFT JOIN LATERAL ( SELECT o.state
           FROM iam_v2.posting_outbox o
          WHERE ((o.posting_id = p.id) AND (o.state = ANY (ARRAY['QUEUED'::text, 'IN_FLIGHT'::text, 'HELD_RECOVERY'::text])))
         LIMIT 1) ob ON (true))
     LEFT JOIN iam_v2.posting_review_state rs ON ((rs.posting_id = p.id)));


--
-- Name: posting_presend_aborts; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.posting_presend_aborts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    posting_id uuid NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT posting_presend_aborts_reason_check CHECK ((reason = ANY (ARRAY['STAY_NOT_IN_HOUSE'::text, 'RESERVATION_MISMATCH'::text, 'STAY_BLOCKED'::text, 'ROOM_UNRESOLVED'::text, 'DATA_STALE'::text])))
);


--
-- Name: posting_review_actions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.posting_review_actions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    posting_id uuid NOT NULL,
    action text NOT NULL,
    actor uuid NOT NULL,
    reason text NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT posting_review_actions_action_check CHECK ((action = ANY (ARRAY['CONFIRM_POSTED'::text, 'CONFIRM_NOT_POSTED_RETRY'::text, 'CONFIRM_NOT_POSTED_ABANDON'::text, 'CREATE_REVERSAL'::text, 'ESCALATE'::text])))
);


--
-- Name: principal_device_credentials; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.principal_device_credentials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    guest_principal_id uuid NOT NULL,
    device_id uuid NOT NULL,
    method text NOT NULL,
    secret_hmac bytea NOT NULL,
    key_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    last_used_at timestamp with time zone,
    revoked_at timestamp with time zone,
    credential text,
    CONSTRAINT principal_device_credentials_label CHECK (((credential IS NULL) OR (credential ~ '^[A-Z0-9_]{1,32}$'::text))),
    CONSTRAINT principal_device_credentials_method CHECK ((method = ANY (ARRAY['OTP'::text, 'SOCIAL'::text])))
);


--
-- Name: TABLE principal_device_credentials; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.principal_device_credentials IS 'A verified Client''s "remember this device" credential: the keyed HMAC of a 256-bit token held only in the portal cookie, bound to ONE device. Usable only from that device (MAC resolved by the kernel on every use), for the site''s Remember-devices period; revoked by sign-out, expiry, or an operator disconnect. It replaces the code on a reconnection, never the eligibility, entitlement or session logic.';


--
-- Name: COLUMN principal_device_credentials.credential; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.principal_device_credentials.credential IS 'The credential the device proved when it was remembered (EMAIL_OTP, SOCIAL_GOOGLE, ...), so a resumed sign-in is reported as what it originally was. NULL = issued before 0109.';


--
-- Name: purchases; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.purchases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    package_revision_id uuid NOT NULL,
    offer_quote_id uuid,
    auth_context_id uuid,
    pms_interface_id uuid,
    stay_id uuid,
    settlement_mapping_id uuid,
    authentication_interface_revision_id uuid,
    trigger text NOT NULL,
    amount_minor bigint DEFAULT 0 NOT NULL,
    currency character(3),
    currency_exponent smallint,
    tax_code text,
    tax_rate_bp integer,
    tax_amount_minor bigint,
    state text DEFAULT 'PENDING'::text NOT NULL,
    purchase_seq integer DEFAULT 1 NOT NULL,
    checkout_episode integer,
    CONSTRAINT purchase_guest_needs_quote CHECK (((trigger <> 'GUEST_SELECTION'::text) OR (offer_quote_id IS NOT NULL))),
    CONSTRAINT purchases_amount_minor_check CHECK ((amount_minor >= 0)),
    CONSTRAINT purchases_state_check CHECK ((state = ANY (ARRAY['PENDING'::text, 'AWAITING_SETTLEMENT'::text, 'MANUAL_REVIEW'::text, 'GRANTED'::text, 'FAILED'::text, 'CANCELLED'::text]))),
    CONSTRAINT purchases_trigger_check CHECK ((trigger = ANY (ARRAY['GUEST_SELECTION'::text, 'VOUCHER_REDEMPTION'::text, 'ACCOUNT_AUTO_GRANT'::text, 'OTP_SOCIAL_DEFAULT'::text, 'CHECKOUT_GRACE'::text, 'EMERGENCY_GRACE'::text, 'POST_STAY_CONVERSION'::text, 'CROSS_PMS_TRANSFER'::text, 'ADMIN_GRANT'::text, 'RENEWAL'::text])))
);


--
-- Name: refund_access_terminations; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.refund_access_terminations (
    entitlement_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    settlement_id uuid NOT NULL,
    charge_transaction_id uuid NOT NULL,
    captured_minor bigint NOT NULL,
    refunded_minor bigint NOT NULL,
    transition_id uuid,
    terminated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT refund_access_terminations_captured_minor_check CHECK ((captured_minor > 0)),
    CONSTRAINT refund_access_terminations_check CHECK ((refunded_minor >= captured_minor))
);


--
-- Name: TABLE refund_access_terminations; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.refund_access_terminations IS 'Evidence: an entitlement ended because the provider fully refunded the charge that funded it (0115). Append-only.';


--
-- Name: retention_floor; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.retention_floor (
    id boolean DEFAULT true NOT NULL,
    since timestamp with time zone NOT NULL,
    CONSTRAINT rf_singleton CHECK (id)
);


--
-- Name: TABLE retention_floor; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.retention_floor IS 'The latest time a row with no recorded creation or sighting time can have been made (0144): when migration 0104 started recording client-account creation, or when this migration ran if 0104 predates the ledger. Retention counts such rows'' age from here, so a row of unknown age is never taken for an old one.';


--
-- Name: scrub_registry; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.scrub_registry (
    table_name text NOT NULL,
    column_name text NOT NULL,
    kind text NOT NULL,
    ts_column text,
    handled boolean DEFAULT false NOT NULL,
    jsonb_key text,
    CONSTRAINT sr_kind CHECK ((kind = ANY (ARRAY['label'::text, 'note'::text, 'secret'::text]))),
    CONSTRAINT sr_note_ts CHECK (((kind = 'note'::text) = (ts_column IS NOT NULL)))
);


--
-- Name: TABLE scrub_registry; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.scrub_registry IS 'Columns that hold what staff typed about a guest (note), who acted (label) or a secret (0147), and may be scrubbed by the retention runs and by erasure.';


--
-- Name: self_service_settings_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.self_service_settings_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    changed_by text NOT NULL,
    change_reason text NOT NULL,
    old_verification_required boolean,
    new_verification_required boolean NOT NULL,
    old_verification_deadline_hours integer,
    new_verification_deadline_hours integer NOT NULL,
    old_suspension_policy text,
    new_suspension_policy text NOT NULL,
    old_reminder_hours_before integer,
    new_reminder_hours_before integer NOT NULL,
    old_resend_cooldown_seconds integer,
    new_resend_cooldown_seconds integer NOT NULL,
    old_resend_max_per_day integer,
    new_resend_max_per_day integer NOT NULL,
    old_grace_minutes integer,
    new_grace_minutes integer NOT NULL,
    old_max_grace_extensions integer,
    new_max_grace_extensions integer NOT NULL,
    old_registrations_per_device_per_day integer,
    new_registrations_per_device_per_day integer NOT NULL,
    new_config_version bigint NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT self_service_settings_changes_actor CHECK ((length(btrim(changed_by)) > 0)),
    CONSTRAINT self_service_settings_changes_reason CHECK ((length(btrim(change_reason)) > 0))
);


--
-- Name: service_plan_revisions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.service_plan_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    service_plan_id uuid NOT NULL,
    revision_no integer NOT NULL,
    name text,
    down_kbps integer,
    up_kbps integer,
    max_concurrent_devices integer DEFAULT 1 NOT NULL,
    device_limit_policy text DEFAULT 'REJECT_NEW_DEVICE'::text NOT NULL,
    idle_timeout_seconds integer,
    max_continuous_session_seconds integer,
    time_accounting_mode text DEFAULT 'VALIDITY_WINDOW'::text NOT NULL,
    time_quota_seconds bigint,
    data_quota_bytes bigint,
    speed_allocation text DEFAULT 'PER_DEVICE'::text NOT NULL,
    CONSTRAINT service_plan_revisions_device_limit_policy_check CHECK ((device_limit_policy = ANY (ARRAY['REJECT_NEW_DEVICE'::text, 'DISCONNECT_OLDEST'::text, 'ADMIN_APPROVAL'::text]))),
    CONSTRAINT service_plan_revisions_max_concurrent_devices_check CHECK ((max_concurrent_devices >= 1)),
    CONSTRAINT service_plan_revisions_time_accounting_mode_check CHECK ((time_accounting_mode = ANY (ARRAY['VALIDITY_WINDOW'::text, 'AGGREGATE_ONLINE_TIME'::text]))),
    CONSTRAINT spr_speed_allocation_check CHECK ((speed_allocation = ANY (ARRAY['PER_DEVICE'::text, 'SHARED'::text])))
);


--
-- Name: COLUMN service_plan_revisions.speed_allocation; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.service_plan_revisions.speed_allocation IS 'PER_DEVICE (default): every authorized device may use down_kbps/up_kbps independently. SHARED: all active sessions under the Entitlement share one aggregate ceiling of down_kbps/up_kbps, allocated dynamically rather than divided into fixed per-device portions. Immutable with the revision it belongs to.';


--
-- Name: service_plans; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.service_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    code text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    current_revision_id uuid
);


--
-- Name: session_counter_watermarks; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.session_counter_watermarks (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    session_id uuid NOT NULL,
    source_epoch integer DEFAULT 1 NOT NULL,
    last_up bigint DEFAULT 0 NOT NULL,
    last_down bigint DEFAULT 0 NOT NULL,
    sample_seq bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: session_entitlement_bindings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.session_entitlement_bindings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    session_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    seq bigint NOT NULL,
    bound_from timestamp with time zone NOT NULL,
    bound_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT seb_interval_ordered CHECK (((bound_until IS NULL) OR (bound_until >= bound_from))),
    CONSTRAINT session_entitlement_bindings_seq_check CHECK ((seq >= 1))
);


--
-- Name: session_online_watermarks; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.session_online_watermarks (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    session_id uuid NOT NULL,
    accounted_through timestamp with time zone NOT NULL,
    accounted_seconds bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT session_online_watermarks_accounted_seconds_check CHECK ((accounted_seconds >= 0))
);


--
-- Name: TABLE session_online_watermarks; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.session_online_watermarks IS 'Per-session durable charged-through instant for AGGREGATE_ONLINE_TIME. Bytes are idempotent because they are cumulative counters compared against a watermark (contract 6.4); wall-clock time has no counter, so it needs this watermark or a replayed tick, a delayed tick or a reboot would each double-charge.';


--
-- Name: sessions; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    device_id uuid NOT NULL,
    credential_method text,
    ip inet,
    mac macaddr,
    state text DEFAULT 'active'::text NOT NULL,
    started timestamp with time zone DEFAULT now() NOT NULL,
    ended timestamp with time zone,
    end_reason text,
    expires_at timestamp with time zone,
    bytes_up bigint DEFAULT 0 NOT NULL,
    bytes_down bigint DEFAULT 0 NOT NULL,
    ingress_interface text
);


--
-- Name: settlements; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.settlements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    purchase_id uuid NOT NULL,
    method text NOT NULL,
    status text NOT NULL,
    CONSTRAINT settlements_method_check CHECK ((method = ANY (ARRAY['NOT_REQUIRED'::text, 'PREPAID'::text, 'PMS_POSTING'::text, 'ONLINE_PAYMENT'::text, 'MANUAL_APPROVAL'::text]))),
    CONSTRAINT settlements_status_check CHECK ((status = ANY (ARRAY['NOT_REQUIRED'::text, 'REQUIRED'::text, 'IN_PROGRESS'::text, 'SETTLED'::text, 'FAILED'::text, 'MANUAL_REVIEW'::text, 'PARTIALLY_REVERSED'::text, 'REVERSED'::text])))
);


--
-- Name: sign_in_attempts; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.sign_in_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    guest_network_id uuid,
    guest_network_name text,
    pms_interface_id uuid,
    request_id uuid,
    submitted_room text,
    verifier_kind text DEFAULT 'UNKNOWN'::text NOT NULL,
    result text NOT NULL,
    matched_field text,
    matched_stay_id uuid,
    matched_guest_id uuid,
    room_in_mirror boolean,
    eligible_stay_candidates integer,
    pms_transport_status text,
    mirror_last_complete_sync_at timestamp with time zone,
    mirror_age_seconds bigint,
    latency_ms bigint,
    entitlement_id uuid,
    session_id uuid,
    device_ip inet,
    device_mac macaddr,
    sensitive_ciphertext bytea,
    sensitive_nonce bytea,
    encryption_key_id uuid,
    cipher_version integer,
    CONSTRAINT sign_in_attempts_matched_field_check CHECK (((matched_field IS NULL) OR (matched_field = ANY (ARRAY['FIRST_NAME'::text, 'FAMILY_NAME'::text, 'RESERVATION_NUMBER'::text])))),
    CONSTRAINT sign_in_attempts_result_check CHECK ((result = ANY (ARRAY['VERIFIED'::text, 'CREDENTIAL_MISMATCH'::text, 'ROOM_NOT_IN_MIRROR'::text, 'STAY_NOT_ELIGIBLE'::text, 'AMBIGUOUS_ROOM_CANDIDATES'::text, 'MIRROR_STALE_OR_MISSING_CHANGE'::text, 'RATE_LIMITED'::text, 'ROUTING_OR_INTERFACE_FAILURE'::text, 'SERVICE_UNAVAILABLE'::text, 'SPENT_REQUEST_ID'::text, 'MALFORMED_SUBMISSION'::text, 'VERIFIED_NO_ELIGIBLE_PACKAGE'::text, 'LICENSE_REFUSED'::text, 'LICENSE_CAPACITY_REACHED'::text]))),
    CONSTRAINT sign_in_attempts_sealed_all_or_none CHECK ((((sensitive_ciphertext IS NULL) AND (sensitive_nonce IS NULL) AND (encryption_key_id IS NULL) AND (cipher_version IS NULL)) OR ((sensitive_ciphertext IS NOT NULL) AND (sensitive_nonce IS NOT NULL) AND (encryption_key_id IS NOT NULL) AND (cipher_version IS NOT NULL)))),
    CONSTRAINT sign_in_attempts_verifier_kind_check CHECK ((verifier_kind = ANY (ARRAY['FULL_NAME'::text, 'RESERVATION_NUMBER_LIKE'::text, 'UNKNOWN'::text])))
);


--
-- Name: TABLE sign_in_attempts; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.sign_in_attempts IS 'One row per deliberate guest Connect submission: the structured result, what the probe saw, the PMS mirror state at that instant, and the guest credential material SEALED with AES-256-GCM under an appliance-local key (internal/signinattempt). RETENTION: 30 days, swept by scd on a ticker; the sweep touches this table and nothing else. The sealed half NEVER leaves the appliance in clear -- not into a log, a journal, CI output, telemetry, an export or a governance artifact. Written by svc_scd; read by svc_edged, which does NOT hold the key and must ask scd to open a sealed row.';


--
-- Name: COLUMN sign_in_attempts.submitted_room; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.sign_in_attempts.submitted_room IS 'The room number as submitted, in clear: it is the operator''s primary filter and is already visible to the same audience on every screen that shows a stay.';


--
-- Name: COLUMN sign_in_attempts.result; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.sign_in_attempts.result IS 'The exact operator-visible reason. Distinct from what the guest is told: internal/signinattempt maps this to one of four coarse guest classes, and several distinct results deliberately share a class so that the portal does not become a way to enumerate which rooms are occupied.';


--
-- Name: COLUMN sign_in_attempts.matched_stay_id; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.sign_in_attempts.matched_stay_id IS 'The stay the evidence was compared against, when one existed. Deliberately NOT a foreign key: the record of a sign-in problem must outlive the stay it describes.';


--
-- Name: COLUMN sign_in_attempts.sensitive_ciphertext; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.sign_in_attempts.sensitive_ciphertext IS 'AES-256-GCM over a JSON envelope holding the submitted verifier (raw and normalized) and the accepted first/family/reservation values. AAD binds it to (tenant, site, attempt id), so a ciphertext moved between rows or sites fails authentication rather than describing the wrong guest.';


--
-- Name: site_account_password_settings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_account_password_settings (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    password_style text DEFAULT 'mixed'::text NOT NULL,
    password_length integer DEFAULT 14 NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by text,
    CONSTRAINT account_password_settings_length CHECK (((password_length <= 32) AND (password_length >=
CASE password_style
    WHEN 'mixed'::text THEN 7
    WHEN 'upper_digits'::text THEN 9
    WHEN 'lower_digits'::text THEN 8
    WHEN 'digits'::text THEN 14
    ELSE NULL::integer
END))),
    CONSTRAINT account_password_settings_style CHECK ((password_style = ANY (ARRAY['mixed'::text, 'upper_digits'::text, 'lower_digits'::text, 'digits'::text]))),
    CONSTRAINT account_password_settings_version CHECK ((config_version >= 1))
);


--
-- Name: TABLE site_account_password_settings; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.site_account_password_settings IS 'Per-site format of GENERATED client-account passwords: which characters, and how many. Read by edged only when it generates a password; operator-typed passwords and existing credentials are unaffected.';


--
-- Name: COLUMN site_account_password_settings.password_style; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.site_account_password_settings.password_style IS 'mixed = upper, lower and digits; upper_digits; lower_digits; digits (2-9). Easily misread characters (0/O, 1/I/l, o) are excluded from every style.';


--
-- Name: COLUMN site_account_password_settings.password_length; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.site_account_password_settings.password_length IS 'Characters in a generated password. At least 40 bits of entropy per style (mixed 7, upper_digits 9, lower_digits 8, digits 14) and at most 32.';


--
-- Name: site_accounting_retention; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_accounting_retention (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    detail_retention_days integer,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by text,
    CONSTRAINT sar_days CHECK (((detail_retention_days IS NULL) OR ((detail_retention_days >= 30) AND (detail_retention_days <= 3650)))),
    CONSTRAINT sar_version CHECK ((config_version >= 1))
);


--
-- Name: TABLE site_accounting_retention; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.site_accounting_retention IS 'How long per-sample accounting detail (iam_v2.accounting_records) is kept (0122). A site with no row keeps iam_v2.accounting_retention_default() days (365, 0131); NULL in a row is the administrator''s choice of UNLIMITED: nothing is purged. Otherwise 30-3650 days. Written only through iam_v2.accounting_retention_set.';


--
-- Name: site_card_payment_setting_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_card_payment_setting_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    change_reason text,
    old_checkout_expiry_minutes integer,
    old_reconcile_grace_minutes integer,
    new_checkout_expiry_minutes integer NOT NULL,
    new_reconcile_grace_minutes integer NOT NULL,
    new_config_version bigint NOT NULL,
    CONSTRAINT site_card_payment_setting_changes_changed_by_check CHECK ((length(btrim(changed_by)) > 0))
);


--
-- Name: site_card_payment_settings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_card_payment_settings (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    checkout_expiry_minutes integer DEFAULT 30 NOT NULL,
    reconcile_grace_minutes integer DEFAULT 60 NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT site_card_payment_settings_bounds CHECK ((((checkout_expiry_minutes >= 30) AND (checkout_expiry_minutes <= 240)) AND ((reconcile_grace_minutes >= 15) AND (reconcile_grace_minutes <= 1440))))
);


--
-- Name: site_checkout_grace_config; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_checkout_grace_config (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    grace_package_revision_id uuid,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    eligibility_window_seconds integer DEFAULT 86400 NOT NULL,
    grace_duration_seconds integer,
    grace_down_kbps integer,
    grace_up_kbps integer,
    grace_data_quota_bytes bigint,
    grace_device_limit integer,
    grace_device_limit_policy text,
    config_version bigint DEFAULT 1 NOT NULL,
    CONSTRAINT grace_all_or_none CHECK ((((grace_duration_seconds IS NULL) AND (grace_down_kbps IS NULL) AND (grace_up_kbps IS NULL) AND (grace_data_quota_bytes IS NULL) AND (grace_device_limit IS NULL) AND (grace_device_limit_policy IS NULL)) OR ((grace_duration_seconds IS NOT NULL) AND (grace_down_kbps IS NOT NULL) AND (grace_up_kbps IS NOT NULL) AND (grace_data_quota_bytes IS NOT NULL) AND (grace_device_limit IS NOT NULL) AND (grace_device_limit_policy = 'REJECT_NEW_DEVICE'::text)))),
    CONSTRAINT grace_bounds CHECK (((eligibility_window_seconds > 0) AND (eligibility_window_seconds <= 604800) AND ((grace_duration_seconds IS NULL) OR ((grace_duration_seconds > 0) AND (grace_duration_seconds <= 604800))) AND ((grace_down_kbps IS NULL) OR ((grace_down_kbps > 0) AND (grace_down_kbps <= 10000000))) AND ((grace_up_kbps IS NULL) OR ((grace_up_kbps > 0) AND (grace_up_kbps <= 10000000))) AND ((grace_data_quota_bytes IS NULL) OR ((grace_data_quota_bytes > 0) AND (grace_data_quota_bytes <= '1099511627776'::bigint))) AND ((grace_device_limit IS NULL) OR ((grace_device_limit > 0) AND (grace_device_limit <= 1000))))),
    CONSTRAINT grace_config_no_dup_policy_keys CHECK ((NOT (config ?| ARRAY['eligibility_window_seconds'::text, 'grace_duration_seconds'::text, 'grace_down_kbps'::text, 'grace_up_kbps'::text, 'grace_data_quota_bytes'::text, 'grace_device_limit'::text, 'grace_device_limit_policy'::text, 'device_limit_policy'::text, 'data_quota_bytes'::text, 'duration_seconds'::text, 'down_kbps'::text, 'up_kbps'::text]))),
    CONSTRAINT site_checkout_grace_config_config_version_check CHECK ((config_version >= 1)),
    CONSTRAINT site_checkout_grace_config_grace_device_limit_policy_check CHECK (((grace_device_limit_policy IS NULL) OR (grace_device_limit_policy = 'REJECT_NEW_DEVICE'::text)))
);


--
-- Name: site_data_retention; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_data_retention (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_stay_days integer NOT NULL,
    client_activity_days integer NOT NULL,
    inactive_identity_days integer NOT NULL,
    expired_record_days integer NOT NULL,
    audit_log_days integer NOT NULL,
    sign_in_attempt_days integer NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by text,
    log_days integer DEFAULT 14 NOT NULL,
    staff_note_days integer DEFAULT 730 NOT NULL,
    CONSTRAINT sdr_audit_log CHECK (((audit_log_days >= 90) AND (audit_log_days <= 3650))),
    CONSTRAINT sdr_client_activity CHECK (((client_activity_days >= 30) AND (client_activity_days <= 3650))),
    CONSTRAINT sdr_expired_record CHECK (((expired_record_days >= 1) AND (expired_record_days <= 365))),
    CONSTRAINT sdr_inactive_identity CHECK (((inactive_identity_days >= 30) AND (inactive_identity_days <= 3650))),
    CONSTRAINT sdr_log CHECK (((log_days >= 1) AND (log_days <= 730))),
    CONSTRAINT sdr_pms_stay CHECK (((pms_stay_days >= 7) AND (pms_stay_days <= 3650))),
    CONSTRAINT sdr_sign_in_attempt CHECK (((sign_in_attempt_days >= 7) AND (sign_in_attempt_days <= 365))),
    CONSTRAINT sdr_staff_note CHECK (((staff_note_days >= 30) AND (staff_note_days <= 3650))),
    CONSTRAINT sdr_version CHECK ((config_version >= 1))
);


--
-- Name: TABLE site_data_retention; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.site_data_retention IS 'How long guest personal data is kept before it is anonymised, per site (0127, GDPR plan C1). A site with no row uses iam_v2.data_retention_defaults(). Written only through iam_v2.data_retention_set.';


--
-- Name: site_device_settings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_device_settings (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    client_device_changes_per_day integer DEFAULT 3 NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by text,
    CONSTRAINT sds_changes_per_day CHECK (((client_device_changes_per_day >= 1) AND (client_device_changes_per_day <= 10))),
    CONSTRAINT sds_version CHECK ((config_version >= 1))
);


--
-- Name: TABLE site_device_settings; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.site_device_settings IS 'Per-site client device management (0118): how many times per package per 24 hours a client may replace or release one of their devices on the portal (default 3, hard bounds 1-10: the protection against passing one package around cannot be switched off). A site with no row reads the default. Written only through iam_v2.device_settings_set.';


--
-- Name: site_guest_signin_network_policy; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_guest_signin_network_policy (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    network_max_failures integer DEFAULT 30 NOT NULL,
    network_window_seconds integer DEFAULT 600 NOT NULL,
    network_pause_seconds integer DEFAULT 900 NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT guest_signin_network_policy_bounds CHECK ((((network_max_failures >= 10) AND (network_max_failures <= 1000)) AND ((network_window_seconds >= 60) AND (network_window_seconds <= 3600)) AND ((network_pause_seconds >= 60) AND (network_pause_seconds <= 3600))))
);


--
-- Name: TABLE site_guest_signin_network_policy; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.site_guest_signin_network_policy IS 'When many wrong room sign-ins on one guest network pause room sign-in there (0136). No row means the approved defaults (30 / 600 s / 900 s), not "off".';


--
-- Name: site_guest_signin_protection; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_guest_signin_protection (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    max_failed_attempts integer DEFAULT 5 NOT NULL,
    observation_window_seconds integer DEFAULT 60 NOT NULL,
    restriction_seconds integer DEFAULT 60 NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT guest_signin_protection_bounds CHECK ((((max_failed_attempts >= 3) AND (max_failed_attempts <= 20)) AND ((observation_window_seconds >= 30) AND (observation_window_seconds <= 3600)) AND ((restriction_seconds >= 30) AND (restriction_seconds <= 3600)))),
    CONSTRAINT guest_signin_protection_version CHECK ((config_version >= 1))
);


--
-- Name: TABLE site_guest_signin_protection; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.site_guest_signin_protection IS 'Per-site guest sign-in protection policy: how many wrong-credential submissions from one device, over what rolling window, are refused for how long. ABSENCE OF A ROW MEANS THE APPROVED DEFAULTS (5 / 60s / 60s), not "disabled" -- there is no enable flag, because a policy that must be switched on is off wherever nobody remembered. Read by the enforcement functions and by the operator API through iam_v2.guest_signin_protection_get, so enforcement, API and UI cannot disagree about the current values.';


--
-- Name: COLUMN site_guest_signin_protection.observation_window_seconds; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.site_guest_signin_protection.observation_window_seconds IS 'The ROLLING window. Failures older than this stop counting continuously, not at a clock boundary: a guest who mistypes twice at 10:00:59 and three times at 10:01:01 is one run of five, not two clean slates.';


--
-- Name: site_module_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_module_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    module_id text NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    change_reason text,
    old_enabled boolean,
    new_enabled boolean NOT NULL,
    new_config_version bigint NOT NULL,
    CONSTRAINT site_module_changes_actor CHECK ((length(btrim(changed_by)) > 0))
);


--
-- Name: site_module_settings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_module_settings (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    module_id text NOT NULL,
    enabled boolean NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT site_module_settings_known CHECK ((module_id = ANY (ARRAY['hospitality'::text, 'paid_access'::text, 'card_payment'::text, 'room_charge'::text]))),
    CONSTRAINT site_module_settings_version CHECK ((config_version >= 1))
);


--
-- Name: TABLE site_module_settings; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.site_module_settings IS 'Local enablement of licensed optional modules, per site. Absence of a row means not enabled. The licence authorises; this row chooses; readiness decides whether anything can execute now. Written only by iam_v2.site_module_set, which records every change in iam_v2.site_module_changes.';


--
-- Name: site_payment_domain_changes; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_payment_domain_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by text NOT NULL,
    change_reason text,
    old_domains text[],
    new_domains text[] NOT NULL,
    CONSTRAINT site_payment_domain_changes_changed_by_check CHECK ((length(btrim(changed_by)) > 0))
);


--
-- Name: site_payment_domains; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_payment_domains (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    domains text[] DEFAULT '{}'::text[] NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT site_payment_domains_bounded CHECK ((cardinality(domains) <= 20))
);


--
-- Name: site_self_service_settings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_self_service_settings (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    verification_required boolean DEFAULT true NOT NULL,
    verification_deadline_hours integer DEFAULT 24 NOT NULL,
    suspension_policy text DEFAULT 'SUSPEND'::text NOT NULL,
    reminder_hours_before integer DEFAULT 4 NOT NULL,
    resend_cooldown_seconds integer DEFAULT 60 NOT NULL,
    resend_max_per_day integer DEFAULT 5 NOT NULL,
    grace_minutes integer DEFAULT 60 NOT NULL,
    max_grace_extensions integer DEFAULT 1 NOT NULL,
    registrations_per_device_per_day integer DEFAULT 3 NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by text,
    CONSTRAINT ssss_deadline CHECK (((verification_deadline_hours >= 1) AND (verification_deadline_hours <= 168))),
    CONSTRAINT ssss_grace_minutes CHECK (((grace_minutes >= 15) AND (grace_minutes <= 240))),
    CONSTRAINT ssss_max_grace CHECK (((max_grace_extensions >= 0) AND (max_grace_extensions <= 3))),
    CONSTRAINT ssss_policy CHECK ((suspension_policy = ANY (ARRAY['SUSPEND'::text, 'WARN_ONLY'::text]))),
    CONSTRAINT ssss_registrations CHECK (((registrations_per_device_per_day >= 1) AND (registrations_per_device_per_day <= 10))),
    CONSTRAINT ssss_reminder CHECK (((reminder_hours_before >= 0) AND (reminder_hours_before <= 72))),
    CONSTRAINT ssss_reminder_before_deadline CHECK ((reminder_hours_before < verification_deadline_hours)),
    CONSTRAINT ssss_resend_cooldown CHECK (((resend_cooldown_seconds >= 30) AND (resend_cooldown_seconds <= 3600))),
    CONSTRAINT ssss_resend_max CHECK (((resend_max_per_day >= 1) AND (resend_max_per_day <= 20))),
    CONSTRAINT ssss_version CHECK ((config_version >= 1))
);


--
-- Name: TABLE site_self_service_settings; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.site_self_service_settings IS 'Per-site Email accounts settings (0117): verification required, deadline, suspension policy, reminder, resend limits, the grace hour and the per-device registration cap. A site with no row reads the defaults. Written only through iam_v2.self_service_settings_set.';


--
-- Name: site_voucher_code_settings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_voucher_code_settings (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    code_mode text DEFAULT 'mixed'::text NOT NULL,
    code_length integer DEFAULT 8 NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT voucher_code_settings_length CHECK (((code_length >= 6) AND (code_length <= 8))),
    CONSTRAINT voucher_code_settings_mode CHECK ((code_mode = ANY (ARRAY['numbers'::text, 'mixed'::text]))),
    CONSTRAINT voucher_code_settings_version CHECK ((config_version >= 1))
);


--
-- Name: TABLE site_voucher_code_settings; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.site_voucher_code_settings IS 'Per-site voucher code format: digits only or digits mixed with letters, and how many characters (6-8). Read at issuance by scd and nowhere else. This is the single source the issuance path, the operator API and the UI all read; it affects codes generated AFTER a change and never a code already printed.';


--
-- Name: COLUMN site_voucher_code_settings.code_mode; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.site_voucher_code_settings.code_mode IS 'numbers = digits only, for keypad entry. mixed = uppercase letters and digits, which reaches the same code space in fewer characters. Characters guests misread from a card are excluded from both.';


--
-- Name: COLUMN site_voucher_code_settings.code_length; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON COLUMN iam_v2.site_voucher_code_settings.code_length IS 'Number of characters in the code, 6 to 8. Eight is the Product-Owner ceiling for both modes; six is the floor the issuance path already enforced. Shorter is easier to read aloud and easier to guess.';


--
-- Name: site_walled_garden_settings; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.site_walled_garden_settings (
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    widest_prefix_len integer DEFAULT 24 NOT NULL,
    config_version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by text,
    CONSTRAINT walled_garden_settings_prefix CHECK (((widest_prefix_len >= 16) AND (widest_prefix_len <= 32))),
    CONSTRAINT walled_garden_settings_version CHECK ((config_version >= 1))
);


--
-- Name: TABLE site_walled_garden_settings; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.site_walled_garden_settings IS 'Per-site walled-garden policy: the widest IPv4 network (smallest prefix length) a rule may name. Read by edged on every rule create and edit.';


--
-- Name: social_provider_secret_generations; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.social_provider_secret_generations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    provider_id uuid NOT NULL,
    generation_no integer NOT NULL,
    ciphertext bytea NOT NULL,
    nonce bytea NOT NULL,
    key_id text NOT NULL,
    cipher_version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    CONSTRAINT spsg_generation CHECK ((generation_no >= 1))
);


--
-- Name: TABLE social_provider_secret_generations; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.social_provider_secret_generations IS 'The client secret (or Apple .p8 key) of a public.social_oauth_providers row, sealed by scd with AES-256-GCM under social_dek.key and AAD bound to (tenant, provider, generation). Exactly one current generation per provider. social_oauth_providers.client_secret is cleared once sealed (0116).';


--
-- Name: stay_guests; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.stay_guests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    stay_id uuid NOT NULL,
    external_guest_id text,
    first_name_norm text,
    last_name_norm text,
    display_name text,
    is_primary boolean DEFAULT false NOT NULL,
    pin_hash text
);


--
-- Name: stay_links; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.stay_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    from_stay uuid NOT NULL,
    to_stay uuid NOT NULL,
    reason text NOT NULL,
    CONSTRAINT stay_links_reason_check CHECK ((reason = ANY (ARRAY['CROSS_PMS_TRANSFER'::text, 'POST_STAY'::text])))
);


--
-- Name: stay_posting_blocks; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.stay_posting_blocks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    pms_interface_id uuid NOT NULL,
    stay_id uuid NOT NULL,
    reason text NOT NULL,
    source text NOT NULL,
    posting_id uuid,
    pa_as_status text,
    note text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    cleared_at timestamp with time zone,
    cleared_by_source text,
    cleared_by uuid,
    cleared_reason text,
    CONSTRAINT stay_posting_block_clearance_fits CHECK ((((cleared_at IS NULL) AND (cleared_by_source IS NULL)) OR ((cleared_at IS NOT NULL) AND (((reason = ANY (ARRAY['PMS_NO_POST'::text, 'PMS_DATA_SUSPECT'::text])) AND (cleared_by_source = 'PMS_FEED'::text)) OR ((reason = 'POSTING_UNRESOLVED'::text) AND (cleared_by_source = 'POSTING_LEDGER'::text)) OR ((reason = 'ADMIN_BLOCK'::text) AND (cleared_by_source = 'OPERATOR'::text) AND (cleared_by IS NOT NULL) AND (cleared_reason IS NOT NULL)))))),
    CONSTRAINT stay_posting_block_source_fits CHECK ((((reason = ANY (ARRAY['PMS_NO_POST'::text, 'PMS_DATA_SUSPECT'::text])) AND (source = 'PMS_ANSWER'::text)) OR ((reason = 'POSTING_UNRESOLVED'::text) AND (source = 'POSTING_LEDGER'::text) AND (posting_id IS NOT NULL)) OR ((reason = 'ADMIN_BLOCK'::text) AND (source = 'OPERATOR'::text) AND (created_by IS NOT NULL) AND (note IS NOT NULL)))),
    CONSTRAINT stay_posting_blocks_cleared_by_source_check CHECK (((cleared_by_source IS NULL) OR (cleared_by_source = ANY (ARRAY['PMS_FEED'::text, 'POSTING_LEDGER'::text, 'OPERATOR'::text])))),
    CONSTRAINT stay_posting_blocks_cleared_reason_check CHECK (((cleared_reason IS NULL) OR ((length(cleared_reason) >= 4) AND (length(cleared_reason) <= 500)))),
    CONSTRAINT stay_posting_blocks_note_check CHECK (((note IS NULL) OR ((length(note) >= 4) AND (length(note) <= 500)))),
    CONSTRAINT stay_posting_blocks_pa_as_status_check CHECK (((pa_as_status IS NULL) OR (pa_as_status = ANY (ARRAY['NG'::text, 'NA'::text, 'NP'::text, 'NR'::text, 'RY'::text, 'UR'::text])))),
    CONSTRAINT stay_posting_blocks_reason_check CHECK ((reason = ANY (ARRAY['PMS_NO_POST'::text, 'PMS_DATA_SUSPECT'::text, 'POSTING_UNRESOLVED'::text, 'ADMIN_BLOCK'::text]))),
    CONSTRAINT stay_posting_blocks_source_check CHECK ((source = ANY (ARRAY['PMS_ANSWER'::text, 'POSTING_LEDGER'::text, 'OPERATOR'::text])))
);


--
-- Name: TABLE stay_posting_blocks; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON TABLE iam_v2.stay_posting_blocks IS 'Reasoned stops on room charging for one stay (Amendment A1, contract section 9a rule 9). Written only by the posting functions; a block is never deleted and is cleared exactly once, by the source its reason allows.';


--
-- Name: v_financial_payments; Type: VIEW; Schema: iam_v2; Owner: -
--

CREATE VIEW iam_v2.v_financial_payments AS
 SELECT tenant_id,
    site_id,
    id AS payment_id,
    settlement_id,
    transaction_type,
    status,
    provider,
    merchant_account_id,
    amount_minor,
    currency,
    currency_exponent,
    parent_transaction_id
   FROM iam_v2.payment_transactions t;


--
-- Name: VIEW v_financial_payments; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON VIEW iam_v2.v_financial_payments IS 'Redacted reporting projection. Deliberately omits provider_ref and idempotency_key: both are correlation handles, and a reporting role has nothing to correlate.';


--
-- Name: v_financial_recovery; Type: VIEW; Schema: iam_v2; Owner: -
--

CREATE VIEW iam_v2.v_financial_recovery AS
 SELECT tenant_id,
    site_id,
    epoch,
    reason,
    entered_at,
    released_at,
    ((released_at IS NULL) AND (reason <> 'INITIAL'::text)) AS recovery_active,
    ( SELECT count(*) AS count
           FROM iam_v2.financial_recovery_holds h
          WHERE ((h.tenant_id = e.tenant_id) AND (h.site_id = e.site_id) AND (h.epoch = e.epoch))) AS held_total,
    ( SELECT count(*) AS count
           FROM iam_v2.financial_recovery_holds h
          WHERE ((h.tenant_id = e.tenant_id) AND (h.site_id = e.site_id) AND (h.epoch = e.epoch) AND (h.resolution IS NULL))) AS held_open
   FROM iam_v2.financial_epochs e;


--
-- Name: v_financial_review_queue; Type: VIEW; Schema: iam_v2; Owner: -
--

CREATE VIEW iam_v2.v_financial_review_queue AS
 SELECT tenant_id,
    site_id,
    posting_id,
    review_version,
    terminal_action,
    escalation_count,
    decided_at
   FROM iam_v2.posting_review_state rs;


--
-- Name: v_financial_settlements; Type: VIEW; Schema: iam_v2; Owner: -
--

CREATE VIEW iam_v2.v_financial_settlements AS
 SELECT se.tenant_id,
    se.site_id,
    se.id AS settlement_id,
    se.purchase_id,
    se.method,
    se.status,
    p.amount_minor,
    p.currency,
    p.currency_exponent,
    p.state AS purchase_state
   FROM (iam_v2.settlements se
     JOIN iam_v2.purchases p ON (((p.tenant_id = se.tenant_id) AND (p.site_id = se.site_id) AND (p.id = se.purchase_id))));


--
-- Name: v_zero_attempt_recovery_queue; Type: VIEW; Schema: iam_v2; Owner: -
--

CREATE VIEW iam_v2.v_zero_attempt_recovery_queue AS
 SELECT o.tenant_id,
    o.site_id,
    o.posting_id,
    o.id AS outbox_id,
    p.pms_interface_id,
    p.amount_minor,
    p.currency,
    p.currency_exponent,
    h.id AS hold_id,
    h.resolution AS hold_resolution,
    h.resolved_at AS hold_resolved_at,
    rs.retry_authorized_attempt_no,
    ((h.resolution = 'CONFIRMED_NOT_COMPLETED'::text) AND (rs.retry_authorized_attempt_no IS NULL)) AS eligible_for_retry_authorization
   FROM (((iam_v2.posting_outbox o
     JOIN iam_v2.pms_postings p ON ((p.id = o.posting_id)))
     LEFT JOIN LATERAL ( SELECT fh.id,
            fh.tenant_id,
            fh.site_id,
            fh.epoch,
            fh.work_kind,
            fh.work_id,
            fh.held_status,
            fh.amount_minor,
            fh.currency,
            fh.held_at,
            fh.resolution,
            fh.resolved_at,
            fh.resolved_by,
            fh.resolution_note
           FROM iam_v2.financial_recovery_holds fh
          WHERE ((fh.work_kind = 'POSTING_OUTBOX'::text) AND (fh.work_id = o.id))
          ORDER BY fh.held_at DESC
         LIMIT 1) h ON (true))
     LEFT JOIN iam_v2.posting_review_state rs ON ((rs.posting_id = o.posting_id)))
  WHERE ((o.state = 'HELD_RECOVERY'::text) AND (NOT (EXISTS ( SELECT 1
           FROM iam_v2.posting_attempts a
          WHERE (a.internal_posting_id = o.posting_id)))));


--
-- Name: VIEW v_zero_attempt_recovery_queue; Type: COMMENT; Schema: iam_v2; Owner: -
--

COMMENT ON VIEW iam_v2.v_zero_attempt_recovery_queue IS 'Postings held by recovery with NO surviving attempts. They cannot appear in the ordinary review queue, which keys on attempts, and before this view the only safe way out of that state was unreachable from any operator surface.';


--
-- Name: verification_access_grants; Type: TABLE; Schema: iam_v2; Owner: -
--

CREATE TABLE iam_v2.verification_access_grants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    site_id uuid NOT NULL,
    guest_network_id uuid,
    device_mac macaddr NOT NULL,
    ip inet NOT NULL,
    bridge text NOT NULL,
    challenge_id uuid,
    destination_digest text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    data_cap_bytes bigint NOT NULL,
    down_kbps integer NOT NULL,
    up_kbps integer NOT NULL,
    used_bytes bigint DEFAULT 0 NOT NULL,
    ended_at timestamp with time zone,
    end_reason text,
    cleared_at timestamp with time zone,
    cleared_by text,
    CONSTRAINT verification_access_cleared_by_bounded CHECK (((cleared_by IS NULL) OR ((length(cleared_by) >= 1) AND (length(cleared_by) <= 200)))),
    CONSTRAINT verification_access_cleared_only_when_ended CHECK (((cleared_at IS NULL) OR (ended_at IS NOT NULL))),
    CONSTRAINT verification_access_cleared_pair CHECK (((cleared_at IS NULL) = (cleared_by IS NULL))),
    CONSTRAINT verification_access_grants_bridge_check CHECK ((bridge ~ '^[A-Za-z0-9_.-]{1,15}$'::text)),
    CONSTRAINT verification_access_grants_check CHECK ((expires_at > started_at)),
    CONSTRAINT verification_access_grants_check1 CHECK (((ended_at IS NULL) = (end_reason IS NULL))),
    CONSTRAINT verification_access_grants_data_cap_bytes_check CHECK ((data_cap_bytes > 0)),
    CONSTRAINT verification_access_grants_destination_digest_check CHECK ((destination_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT verification_access_grants_down_kbps_check CHECK ((down_kbps > 0)),
    CONSTRAINT verification_access_grants_end_reason_check CHECK ((end_reason = ANY (ARRAY['VERIFIED'::text, 'SIGNED_IN'::text, 'EXPIRED'::text, 'DATA_EXHAUSTED'::text, 'CANCELLED'::text, 'ADMIN'::text, 'RESTORE_FAILED'::text]))),
    CONSTRAINT verification_access_grants_up_kbps_check CHECK ((up_kbps > 0)),
    CONSTRAINT verification_access_grants_used_bytes_check CHECK ((used_bytes >= 0))
);


--
